/* GENERATED by build/gen-monster-flavor.py from dev/model-qa/monster-flavor.json — never hand-edit. Regular-bestiary flavor sidecar (docs/MONSTER-FLAVOR-TABLES.md §3): per-creature desc + a spice-graded d8 flavor table (variant|hook). Adam's Asset Library monster files and data/bestiary.js are untouched by this layer; the 104 hand-authored custom d10 tables (his) coexist, never replaced. */
const MONSTER_FLAVOR={
 "aarakocra-aeromancer": {"desc": "It rides the thermal without a wingbeat, feathers rattling like dry reeds while its eyes track motion far below. Wind gathers around its outstretched talons before it speaks, curling into little private cyclones. It lands rarely and never fully — one foot always tensed for the next updraft. When it screeches, the sky itself seems to lean in to listen.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Circles a fixed peak, unwilling to hunt beyond sight of its eyrie."}, {"n": 2, "band": "Grounded", "text": "Trades gusts for warning cries, favoring evasion over open combat."}, {"n": 3, "band": "Grounded", "text": "Carries a bone whistle that calls its skirmisher kin from the ridgeline."}, {"n": 4, "band": "Grounded", "text": "Feathers scorched pale from a lightning strike it survived years back."}, {"n": 5, "band": "Grounded", "text": "Refuses to fight over water, remembering a drowned clutch-mate."}, {"n": 6, "band": "Textured", "text": "Speaks in overlapping wind-voices, finishing others' sentences before they're said."}, {"n": 7, "band": "Strange", "text": "Its shadow drags a half-second behind its body, out of step with the wind."}, {"n": 8, "band": "Volatile", "text": "Storm-touched: every third gust it conjures crackles faintly blue, unbidden."}]}},
 "aarakocra-skirmisher": {"desc": "It drops out of the glare with wings snapped shut, a spear leveled before the shadow it casts even lands. Its talons click against stone as it resets stance, head cocked at an unnatural angle to track two things at once. The tribe marks itself in dyed feathers, small badges of a hierarchy that means nothing to the ground-bound. It never stops moving, even mid-conversation.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Carries a wounded nestling strapped to its chest, desperate for a healer."}, {"n": 2, "band": "Grounded", "text": "Was sent to scout and will trade what it saw for safe passage."}, {"n": 3, "band": "Grounded", "text": "Bears a torn treaty-feather marking a truce the party might not know of."}, {"n": 4, "band": "Grounded", "text": "Hunts alone, having outlived its patrol to a rival clan's ambush."}, {"n": 5, "band": "Grounded", "text": "Carries stolen rations back to a starving eyrie, guilt plain in its posture."}, {"n": 6, "band": "Textured", "text": "Drops a beacon-feather that will summon a dozen more within the hour."}, {"n": 7, "band": "Strange", "text": "Mutters coordinates in a dead sky-tongue no living aarakocra still speaks."}, {"n": 8, "band": "Volatile", "text": "Its spear is warm to the touch — looted from something that shouldn't be dead yet."}]}},
 "air-elemental": {"desc": "It arrives as a pressure change before it arrives as a shape, dust and grit orbiting a core of nothing. Where it passes, torches gutter and doors slam on their own. Its voice is the sound of a held breath finally released, everywhere at once. It has no face to read intent from — only the speed of the debris tells you it has decided.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound to a specific room, unable to cross a threshold marked in salt."}, {"n": 2, "band": "Grounded", "text": "Carries the accumulated litter of years — leaves, ash, torn parchment — in its funnel."}, {"n": 3, "band": "Grounded", "text": "Whistles a single mournful note whenever it changes direction."}, {"n": 4, "band": "Grounded", "text": "Extinguishes flame instinctively before attacking, a habit from its summoner's orders."}, {"n": 5, "band": "Grounded", "text": "Weaker gusts precede it — a tell any hunter learns to read."}, {"n": 6, "band": "Textured", "text": "Carries the voice of the mage who bound it, faint words looping in the wind."}, {"n": 7, "band": "Strange", "text": "Leaves no footprints but a spiral of frost wherever it touches stone."}, {"n": 8, "band": "Volatile", "text": "Fraying from its binding, it howls half in the summoner's tongue and half in something older."}]}},
 "astral-raider-dracomancer": {"desc": "Its four eyes track independently, two fixed on the party while two scan the astral currents for reinforcements. Draconic sigils burned into its robes shift color as it channels, mirroring some distant dragon's mood. It speaks Deep Speech in clipped military cadence, every syllable a command. When it steps between realities, the air folds like paper and doesn't quite unfold right after.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Carries raid orders naming this world's coordinates as a staging ground."}, {"n": 2, "band": "Grounded", "text": "Escorts a captive dracomancer-in-training who wants desperately to defect."}, {"n": 3, "band": "Grounded", "text": "Bears a dragon-bonded talisman worth a fortune to the right collector."}, {"n": 4, "band": "Grounded", "text": "Hunts a specific relic the party may already be carrying, unknowingly."}, {"n": 5, "band": "Grounded", "text": "Left behind by its warband, and furious about the abandonment."}, {"n": 6, "band": "Textured", "text": "Carries a scale-bound ledger tallying worlds already marked for raiding."}, {"n": 7, "band": "Strange", "text": "Its dragon-bond stutters mid-spell, briefly showing a distant wyrm's dying eye."}, {"n": 8, "band": "Mythic", "text": "Summons are already inbound — a wing of its warband tears through the sky above."}]}},
 "astral-raider-knight": {"desc": "Its armor is scaled from something that was once alive, riveted in patterns no human smith would choose. It moves with parade-ground discipline, blade never lowering even in idle stance. Its psionic tether hums audibly when it teleports, a sound like a plucked wire. It regards prisoners the way a butcher regards livestock — with professional, disinterested calculation.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Fights in strict formation, refusing to break ranks even when losing."}, {"n": 2, "band": "Grounded", "text": "Marks kills with a notch on its vambrace, tallying decades of raids."}, {"n": 3, "band": "Grounded", "text": "Carries a captured banner from a world it helped conquer."}, {"n": 4, "band": "Grounded", "text": "Distrusts its own dracomancer, keeping visible distance in battle."}, {"n": 5, "band": "Grounded", "text": "Blade rings faintly when swung, tuned to unsettle before it wounds."}, {"n": 6, "band": "Textured", "text": "Speaks the local tongue fluently, having raided this world's kin before."}, {"n": 7, "band": "Strange", "text": "Its shadow lags behind each teleport, arriving a full second later."}, {"n": 8, "band": "Volatile", "text": "Bears an unsanctioned mutation from forbidden astral rites — its knight-caste peers would kill it for this."}]}},
 "astral-raider-warrior": {"desc": "Rank-and-file and proud of it, its scaled hide is scarred in patterns its warband reads like a résumé. It moves in pairs by instinct, always a partner just out of peripheral vision. Its Deep Speech barks are short, functional, unfeeling. When it dies, it does so without a sound of complaint — trained out of it generations ago.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Carries a captured local's ration tin, proof a village nearby was already raided."}, {"n": 2, "band": "Grounded", "text": "Deserted its unit and wants only to be left alone, not fought."}, {"n": 3, "band": "Grounded", "text": "Bears fresh orders scratched in Deep Speech pointing to a rally point."}, {"n": 4, "band": "Grounded", "text": "Carries a stolen trinket it plans to trade for rank back home."}, {"n": 5, "band": "Grounded", "text": "Wounded and separated, it will guide the party to its camp for mercy."}, {"n": 6, "band": "Textured", "text": "Wears a slave-collar key that could free captives elsewhere in this raid."}, {"n": 7, "band": "Strange", "text": "Mutters the name of a world that, as far as anyone knows, doesn't exist yet."}, {"n": 8, "band": "Volatile", "text": "Its psionic tether is failing — kill it wrong and it drags something else through with it."}]}},
 "azer-pyromancer": {"desc": "Molten seams pulse along its bronze musculature in time with its breathing, brightening when it's angry. It speaks in the clipped formal cadence of a forge-caste noble, contemptuous of anything that burns cooler than it does. Where it walks, stone cracks faintly from residual heat. It never touches water, and the memory of why still darkens its molten eyes.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Refuses combat near open flame it didn't personally kindle — a caste taboo."}, {"n": 2, "band": "Grounded", "text": "Carries a cooling rod it uses to temper its own molten fury mid-fight."}, {"n": 3, "band": "Grounded", "text": "Speaks only in forge-metaphor, describing enemies as ore to be shaped."}, {"n": 4, "band": "Grounded", "text": "Its seams have dimmed with age, a mark of azer status it hides shamefully."}, {"n": 5, "band": "Grounded", "text": "Marks territory with molten sigils that harden into permanent brass scars."}, {"n": 6, "band": "Textured", "text": "Bound by a shackle-oath to a specific efreeti it will not speak ill of."}, {"n": 7, "band": "Strange", "text": "Its shadow burns cold, casting frost instead of dark on the stone."}, {"n": 8, "band": "Volatile", "text": "Its inner fire is overclocked — every spell it casts risks it going supernova."}]}},
 "azer-sentinel": {"desc": "It stands at its post the way a statue stands, until the moment it isn't one. Heat shimmers visibly off its shoulders, warping the air behind it into a haze. Its axe head glows dull orange even at rest, never fully cooling. It doesn't patrol so much as endure, generations of azer having stood in this exact spot before it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a sealed forge-vault and will only stand down for the correct passphrase."}, {"n": 2, "band": "Grounded", "text": "Carries a message-brand for its garrison commander, urgent and unread."}, {"n": 3, "band": "Grounded", "text": "Its post has been abandoned by relief for weeks — it's starting to worry."}, {"n": 4, "band": "Grounded", "text": "Owes a life-debt to a dao noble and will break post to honor it."}, {"n": 5, "band": "Grounded", "text": "Carries molten-forged shackle keys for prisoners kept somewhere nearby."}, {"n": 6, "band": "Textured", "text": "Its axe bears a forge-mark from a foundry the party may be looking for."}, {"n": 7, "band": "Strange", "text": "Its heat has begun crystallizing the stone floor beneath it into glass."}, {"n": 8, "band": "Volatile", "text": "It's been ordered to hold this post until it melts through the floor itself."}]}},
 "blind-deep-stalker": {"desc": "It hunts by pressure and scent alone, its ruined sockets long since sealed shut by evolution or old wounds. It moves in dead silence between bursts of shocking speed, club raised before the ambush registers as an ambush. It communicates in low clicks pitched below what most ears register consciously. Whatever light touches it, it treats as an act of violence.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts alone, having been driven from its pack for some blind-stalker crime."}, {"n": 2, "band": "Grounded", "text": "Freezes utterly at any sound above a whisper, hoping to be overlooked."}, {"n": 3, "band": "Grounded", "text": "Carries scent-markers on cord, tagging prey for others of its kind."}, {"n": 4, "band": "Grounded", "text": "Its club is notched with old teeth, trophies from things it's outlived."}, {"n": 5, "band": "Grounded", "text": "Reacts to torchlight with panic rather than aggression, fleeing first."}, {"n": 6, "band": "Textured", "text": "Skin has gone pale-translucent, veins visible, a sign of unusual age."}, {"n": 7, "band": "Strange", "text": "Clicks in a rhythm that, slowed down, resembles a child's nursery rhyme."}, {"n": 8, "band": "Volatile", "text": "Its scarred sockets weep a faint luminescence when it senses fresh blood."}]}},
 "blue-chaos-frog": {"desc": "It squats too still, too patient, skin the color of drowned things, before the shapeshift takes and it's suddenly wearing someone's face. Static discharges faintly off its mottled hide when it's agitated. Its true eyes — slit, alien, unblinking — are the only part it can never quite disguise. It croaks between forms, a wet, gurgling laugh at nothing.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears a stolen face badly, blinking at the wrong intervals."}, {"n": 2, "band": "Grounded", "text": "Croaks uncontrollably under stress, blowing its disguise."}, {"n": 3, "band": "Grounded", "text": "Prefers to mimic livestock, moving unnoticed among herds."}, {"n": 4, "band": "Grounded", "text": "Skin mottles blue-black when startled, a tell its hunters know to watch for."}, {"n": 5, "band": "Grounded", "text": "Keeps a small hoard of borrowed faces' belongings, sentimental in its way."}, {"n": 6, "band": "Textured", "text": "Mimics voices it's heard exactly once, perfectly, and can't stop."}, {"n": 7, "band": "Strange", "text": "Its shed skins keep moving for hours after it molts, twitching in the dark."}, {"n": 8, "band": "Volatile", "text": "Reality flickers at its edges when it shifts, as if the frog is a mistake in the world's draft."}]}},
 "brain-crawler": {"desc": "It skitters low along the ceiling, a tangle of exposed nerve and chitin no bigger than a hand. Its thoughts arrive in the mind sideways, an itch behind the eyes before the words form. It hunts not for meat but for the electric static of a working brain, and it savors slowly. Killing it releases a whiff of ozone and something like relief.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Nests in threes, coordinating silently through touch alone."}, {"n": 2, "band": "Grounded", "text": "Prefers sleeping victims, latching on before the mind can resist."}, {"n": 3, "band": "Grounded", "text": "Leaves a faint burn-mark on the scalp of anyone it's fed from."}, {"n": 4, "band": "Grounded", "text": "Skitters away from bright light, hunting only in true dark."}, {"n": 5, "band": "Grounded", "text": "Carries the fragmented memory of its last victim, echoing in half-thoughts."}, {"n": 6, "band": "Textured", "text": "Chitters in a pattern that sounds almost like a name, over and over."}, {"n": 7, "band": "Strange", "text": "Its exposed nerve tissue pulses in sync with a nearby creature's heartbeat."}, {"n": 8, "band": "Volatile", "text": "Carries a fragment of a mind far too intelligent for a creature this small to have eaten."}]}},
 "clawed-drowner": {"desc": "It waits below the waterline with only its eyes breaking the surface, patient as silt. Its claws are built for holding, not cutting — it doesn't want you dead quickly. Webbed and pallid, it moves faster underwater than any land creature should, and it never surfaces to breathe unless it's already lost. The smell of it lingers on drowned things.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Drags prey into flooded tunnels it knows better than any diver."}, {"n": 2, "band": "Grounded", "text": "Hoards drowned bodies in a submerged den, feeding slowly over weeks."}, {"n": 3, "band": "Grounded", "text": "Avoids fast-moving water, preferring stagnant pools and flooded cellars."}, {"n": 4, "band": "Grounded", "text": "Claws are unusually long, snagged with cloth from past victims."}, {"n": 5, "band": "Grounded", "text": "Surfaces only at night, when its pale hide reads as driftwood."}, {"n": 6, "band": "Textured", "text": "Croons a low, almost-musical moan while dragging its catch under."}, {"n": 7, "band": "Strange", "text": "Its den is lined with objects too dry to have been carried underwater — someone else brought them."}, {"n": 8, "band": "Volatile", "text": "The flooded chamber it lairs in isn't natural — something below is feeding it too."}]}},
 "cloaker": {"desc": "It hangs from the ceiling like a discarded cloak until the moment it isn't, wrapping around a victim with a wet snap. Its underside is a ragged mouth ringed in teeth, and its moan can peel sanity like old paint. In flight it moves without sound, a black shape against black stone. Nothing about it reads as alive until it's already too late.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Roosts in the same alcove for years, indistinguishable from hanging rags."}, {"n": 2, "band": "Grounded", "text": "Prefers isolated stragglers, never engaging a tight formation."}, {"n": 3, "band": "Grounded", "text": "Moans in short bursts, testing which direction causes the most panic."}, {"n": 4, "band": "Grounded", "text": "Bears old scars from a prior fight, wary and quicker to flee than most."}, {"n": 5, "band": "Grounded", "text": "Its underside pattern mimics a specific noble house's tapestry, oddly."}, {"n": 6, "band": "Textured", "text": "Hunts in a mated pair, one moaning while the other strikes from behind."}, {"n": 7, "band": "Strange", "text": "Its moan occasionally forms recognizable words in a dead language."}, {"n": 8, "band": "Volatile", "text": "Wraps prey so fast the victim's last words come out mid-scream, still audible."}]}},
 "dao": {"desc": "It moves through solid stone as easily as water, leaving no disturbance but a faint grinding hum. Jewelry of raw ore weighs down its earthen limbs, each piece a boast of buried wealth. Its voice carries the patience of something that measures time in mountain ranges eroding. It negotiates before it fights, mostly because fighting is beneath its dignity.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Obsessed with a specific gem vein, defending it past reason."}, {"n": 2, "band": "Grounded", "text": "Speaks in contracts and terms, offended by anyone who fights without negotiating first."}, {"n": 3, "band": "Grounded", "text": "Wears its wealth as armor, literally — fused ore plating its hide."}, {"n": 4, "band": "Grounded", "text": "Distrusts efreet deeply, having been cheated by one centuries ago."}, {"n": 5, "band": "Grounded", "text": "Moves visibly slower through worked stone than natural rock, a known weakness."}, {"n": 6, "band": "Textured", "text": "Keeps a bound genie-servant of a lesser earth spirit, treated cruelly."}, {"n": 7, "band": "Strange", "text": "The stone around it crystallizes into geometric patterns as it passes."}, {"n": 8, "band": "Mythic", "text": "It's testing this world's mountain — if it likes what it finds, it will claim the whole range."}]}},
 "darkmantle": {"desc": "It clings to cave ceilings like a furled black umbrella, patient past the point of boredom. When it drops, darkness pours out of it in a suffocating wave, and its grip crushes rather than cuts. It has no eyes worth the name, hunting entirely by sound and vibration. Its silhouette against torchlight is the last thing careless spelunkers ever misidentify as a stalactite.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Roosts near dripping water, using the sound to mask its own approach."}, {"n": 2, "band": "Grounded", "text": "Small and young, clumsy in its drop, missing more often than not."}, {"n": 3, "band": "Grounded", "text": "Has claimed a well-trafficked tunnel, fat on careless travelers."}, {"n": 4, "band": "Grounded", "text": "Releases its darkness in short bursts, conserving it for the killing blow."}, {"n": 5, "band": "Grounded", "text": "Bears old rope-burns from a previous escape, wary of climbing gear."}, {"n": 6, "band": "Textured", "text": "Nests in a cluster of three, dropping in staggered succession."}, {"n": 7, "band": "Strange", "text": "Its darkness lingers a full minute longer than it should, clinging to skin."}, {"n": 8, "band": "Volatile", "text": "The darkness it exudes swallows sound entirely — screams inside it go unheard."}]}},
 "death-chaos-frog": {"desc": "It wears rot like a second skin, the shapeshift barely masking the smell of something already dying. Its true form is bloated, cancerous, veined black with whatever chaos runs through it instead of blood. It laughs in a dead man's voice mid-transformation, the borrowed face slipping like wet clay. Everything near it seems to wilt a little faster.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Mimics the recently deceased, wearing their exact final expression."}, {"n": 2, "band": "Grounded", "text": "Leaves plague-like sickness in animals near its lair, unintentionally."}, {"n": 3, "band": "Grounded", "text": "Hoards the personal effects of everyone it's ever impersonated."}, {"n": 4, "band": "Grounded", "text": "Its borrowed faces rot visibly after a few hours, forcing frequent changes."}, {"n": 5, "band": "Grounded", "text": "Avoids holy ground reflexively, flinching at consecrated stone."}, {"n": 6, "band": "Textured", "text": "Speaks fluently in the voice of someone the party may recognize."}, {"n": 7, "band": "Strange", "text": "Flies gather around it even mid-disguise, unable to be fooled."}, {"n": 8, "band": "Volatile", "text": "Its true form is barely stable — killing it wrong lets the chaos spill loose."}]}},
 "djinni": {"desc": "It descends on a column of warm wind that smells of distant bazaars and hot sand. Silk and gold drape a form too perfect to be entirely honest, and its smile carries the weight of a thousand cleverly-worded bargains. It speaks in riddles it finds far more amusing than anyone listening does. Cross it, and the sky itself seems to take a breath before it answers.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound by an old pact it resents, honoring the letter and not the spirit."}, {"n": 2, "band": "Grounded", "text": "Collects wishes like trophies, cataloguing every clever loophole it's exploited."}, {"n": 3, "band": "Grounded", "text": "Refuses combat with anything holding an unfulfilled wish against it."}, {"n": 4, "band": "Grounded", "text": "Wind precedes it by a full minute, giving prepared foes time to brace."}, {"n": 5, "band": "Grounded", "text": "Speaks only in verse, a self-imposed vanity it won't break for anyone."}, {"n": 6, "band": "Textured", "text": "Owes a debt to a marid it despises and avoids mentioning."}, {"n": 7, "band": "Strange", "text": "Its shadow shows a different, older face than the one it currently wears."}, {"n": 8, "band": "Mythic", "text": "It's shopping for a new binder — and the party just impressed it."}]}},
 "dust-mephit": {"desc": "It's barely more than animate grit, a shape that coughs when it talks and sheds a fine gray haze wherever it walks. Its voice is a dry rasp, easily annoyed, chronically sarcastic. It exists mostly to be a nuisance for something bigger, and it knows this, and resents it constantly. Sunlight makes it sneeze, which it finds deeply undignified.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Bound as a lesser errand-servant, desperate to prove itself useful."}, {"n": 2, "band": "Grounded", "text": "Carries a summoner's unopened message, forgotten mid-errand for weeks."}, {"n": 3, "band": "Grounded", "text": "Will trade information for a promise of dust-free storage, oddly."}, {"n": 4, "band": "Grounded", "text": "Guards a trivial-seeming trinket its master values far more than it lets on."}, {"n": 5, "band": "Grounded", "text": "Snitches on its own kind readily, for a price of shiny nothing."}, {"n": 6, "band": "Textured", "text": "Overheard its summoner planning something the party would want to know."}, {"n": 7, "band": "Strange", "text": "Sheds dust that briefly reveals footprints invisible moments before."}, {"n": 8, "band": "Volatile", "text": "Panicking, it's fled its binder — and whatever's chasing it is worse."}]}},
 "earth-elemental": {"desc": "It rises from the floor itself, gravel and root knitting into something roughly man-shaped and entirely humorless. Each footstep lands like a dropped anvil, cracking stone that shouldn't crack. It doesn't breathe, doesn't blink, doesn't hesitate — just closes distance with the patience of erosion given intent. When it strikes, the whole room seems to flinch.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound to guard a single fixed point, immovable beyond it."}, {"n": 2, "band": "Grounded", "text": "Composed of a specific stone type, betraying where it was summoned."}, {"n": 3, "band": "Grounded", "text": "Moves slower on worked floors, faster through raw earth."}, {"n": 4, "band": "Grounded", "text": "Carries embedded ore or gems from the ground it rose out of."}, {"n": 5, "band": "Grounded", "text": "Leaves cracked, radiating fissures wherever it stands still too long."}, {"n": 6, "band": "Textured", "text": "Hums a low resonant note that loosens mortar in old walls nearby."}, {"n": 7, "band": "Strange", "text": "Fine roots and old bones are visible fused into its rocky mass."}, {"n": 8, "band": "Volatile", "text": "Its binding is failing — the ground for yards around trembles when it moves."}]}},
 "efreeti": {"desc": "Heat rolls off it in visible waves, warping the air, curling paper and hair at twenty paces. It carries itself like royalty exiled to a lesser plane, contemptuous of the mud-and-water creatures it's forced to deal with. Its voice crackles like a bonfire finding fresh fuel. Bargains with it always cost more than they promise — that's the whole point.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound to a lamp or ring it resents bitterly, plotting its master's downfall."}, {"n": 2, "band": "Grounded", "text": "Collects grudges obsessively, remembering every insult across decades."}, {"n": 3, "band": "Grounded", "text": "Refuses to extinguish any fire it's personally set, even against its own interest."}, {"n": 4, "band": "Grounded", "text": "Speaks in flattering half-truths, testing for gullibility before striking."}, {"n": 5, "band": "Grounded", "text": "Its heat wilts nearby plants permanently, leaving a scar of dead ground."}, {"n": 6, "band": "Textured", "text": "Wears jewelry looted from a rival djinni it despises."}, {"n": 7, "band": "Strange", "text": "Its flames occasionally show faces in the smoke, screaming silently."}, {"n": 8, "band": "Mythic", "text": "It's been granted a night of freedom — and it intends to make this world remember it."}]}},
 "elder-deep-thing": {"desc": "It surfaces slow, deliberate, an old intelligence wearing flesh the way a man might wear a borrowed coat. Its many eyes blink out of sync, each apparently watching something different, something not entirely in this room. When it speaks, the words arrive a beat after the mouth moves, as if translated from somewhere deeper. Memories brush against yours when it's near, uninvited and unwelcome.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Ancient and slow, preferring to let lesser servants do its fighting."}, {"n": 2, "band": "Grounded", "text": "Hoards the drained memories of centuries of victims, cataloguing them."}, {"n": 3, "band": "Grounded", "text": "Speaks in the borrowed voice of whoever it last consumed."}, {"n": 4, "band": "Grounded", "text": "Refuses to leave its flooded sanctum, ancient and territorial."}, {"n": 5, "band": "Grounded", "text": "Radiates a low psychic pressure that gives nearby creatures nightmares."}, {"n": 6, "band": "Textured", "text": "Keeps a favored thrall it treats with something like affection."}, {"n": 7, "band": "Strange", "text": "Its many eyes occasionally show a memory that isn't its own, or anyone's."}, {"n": 8, "band": "Mythic", "text": "It remembers when this world's stars were arranged differently — and says so."}]}},
 "elemental-cataclysm": {"desc": "It is not a creature so much as an argument between the elements, given terrible temporary form. Fire licks along stone limbs while water hisses to steam against them, and the whole mass groans like a mountain being born. Its footsteps are localized earthquakes. When it finally collapses, the four elements that made it scatter, indifferent to the world they just ruined.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "One element dominates slightly, biasing its attacks toward that damage type."}, {"n": 2, "band": "Grounded", "text": "Leaves a permanent elemental scar on the landscape after it falls."}, {"n": 3, "band": "Grounded", "text": "Summoned deliberately by a ritual whose remains are still nearby, smoking."}, {"n": 4, "band": "Grounded", "text": "Its component elementals occasionally squabble mid-battle, visibly."}, {"n": 5, "band": "Grounded", "text": "Draws power from the terrain it fights on, stronger near its native element."}, {"n": 6, "band": "Textured", "text": "Was bound by a now-dead archmage whose ghost still watches, helpless."}, {"n": 7, "band": "Strange", "text": "Its four elements occasionally desynchronize, briefly exposing a hollow core."}, {"n": 8, "band": "Mythic", "text": "This is only a fragment — the whole cataclysm is still forming somewhere else."}]}},
 "eye-tyrant": {"desc": "It floats with the terrible unhurried confidence of an apex predator that has never needed to run. Its central eye alone could unmake a small army; the ten writhing stalks each carry their own private catastrophe. It speaks in a voice of oily reasonableness, always negotiating from a position it knows is unassailable. Nothing about it blinks, ever, and that's the worst part.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rules a specific lair chamber absolutely, punishing any trespass immediately."}, {"n": 2, "band": "Grounded", "text": "Keeps a beholderkin brood it treats with contempt but defends fiercely."}, {"n": 3, "band": "Grounded", "text": "Paranoid even by its kind's standard, trusting no other eye-tyrant alive."}, {"n": 4, "band": "Grounded", "text": "Collects the petrified or polymorphed remains of past intruders as décor."}, {"n": 5, "band": "Grounded", "text": "Prefers negotiation to combat, valuing information over blood."}, {"n": 6, "band": "Textured", "text": "Bears old stalk-scars from a rival eye-tyrant it never fully defeated."}, {"n": 7, "band": "Strange", "text": "Its central eye occasionally shows a reflection that isn't the room it's in."}, {"n": 8, "band": "Mythic", "text": "It rules the whole complex as an empire in miniature, and it knows the party has been seen already."}]}},
 "fire-elemental": {"desc": "It moves like a living bonfire given ambition, roaring low even when it isn't attacking. Anything flammable near it announces its passage before its shape does. Its form flickers and reforms constantly, never quite the same silhouette twice. It doesn't hate you — it simply consumes, the way fire always has.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound to a specific brazier, weakening if separated from its source flame."}, {"n": 2, "band": "Grounded", "text": "Leaves scorched, distinctive prints wherever it walks across stone."}, {"n": 3, "band": "Grounded", "text": "Flares brighter when angered, a visible tell before it strikes."}, {"n": 4, "band": "Grounded", "text": "Avoids deep water instinctively, hissing and shrinking near it."}, {"n": 5, "band": "Grounded", "text": "Was summoned to guard something flammable it now protects zealously."}, {"n": 6, "band": "Textured", "text": "Carries the half-melted remains of the last thing it fully consumed."}, {"n": 7, "band": "Strange", "text": "Its flames occasionally burn a color that shouldn't exist in normal fire."}, {"n": 8, "band": "Volatile", "text": "It's unbound and spreading — untended, it will become a real fire within the hour."}]}},
 "fish-folk": {"desc": "It surfaces at the edge of torchlight, gill-slits flaring, scales slick with brackish water. Its eyes are flat and lidless, unreadable in the dark. It speaks in a wet clicking dialect before switching, unnervingly, to fluent Common when it wants something. Everything about it smells faintly of low tide and old blood.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts only at the tideline, retreating fully underwater when pressed."}, {"n": 2, "band": "Grounded", "text": "Carries a ritual scar marking devotion to something deep and unseen."}, {"n": 3, "band": "Grounded", "text": "Speaks fluent Common, unsettlingly polite before it attacks."}, {"n": 4, "band": "Grounded", "text": "Wears scavenged human jewelry as trophies, poorly understood."}, {"n": 5, "band": "Grounded", "text": "Avoids salt circles and wards instinctively, an old superstition."}, {"n": 6, "band": "Textured", "text": "Carries a coded message meant for a cult contact further inland."}, {"n": 7, "band": "Strange", "text": "Its scales shimmer briefly in patterns that resemble a face, then don't."}, {"n": 8, "band": "Volatile", "text": "It's been marked by something in the deep — its eyes have started to glow faintly."}]}},
 "fish-folk-archpriest": {"desc": "It wears coral and bone vestments fused to its scaled hide, holy symbols of something without a name humans use. Its voice carries an echo, as if speaking simultaneously from just above and just below the water. Congregants — willing or not — kneel when it raises its staff. Its devotion is absolute, and utterly without mercy.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Leads rites at a specific tidal altar, unwilling to abandon the ritual mid-act."}, {"n": 2, "band": "Grounded", "text": "Demands converts recite drowning-hymns before granting mercy."}, {"n": 3, "band": "Grounded", "text": "Carries a bone scepter that channels its god's favor visibly."}, {"n": 4, "band": "Grounded", "text": "Distrusts land-dwelling clergy of any other faith, openly hostile."}, {"n": 5, "band": "Grounded", "text": "Speaks for the god in first person, unnervingly, mid-sermon."}, {"n": 6, "band": "Textured", "text": "Keeps a captive surface-priest as a trophy convert, half-drowned and compliant."}, {"n": 7, "band": "Strange", "text": "Its shadow moves independently underwater, gesturing to something unseen."}, {"n": 8, "band": "Mythic", "text": "It claims the tide itself answers to its prayers — and tonight, it might be right."}]}},
 "fish-folk-monitor": {"desc": "It patrols the reef-line with a spear that's drawn more blood than most soldiers see in a career. Scarred and methodical, it reports to something deeper without ever naming what. Its movements are economical, unhurried, the confidence of something that's never lost a fight it chose to have. It watches longer than it should before it decides you're worth the effort.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Patrols a fixed border, escalating only if it's crossed twice."}, {"n": 2, "band": "Grounded", "text": "Marks trespassers with a scent-gland secretion for others to track."}, {"n": 3, "band": "Grounded", "text": "Carries a tally-cord of past kills, knotted in a private code."}, {"n": 4, "band": "Grounded", "text": "Prefers to disable rather than kill, valuing prisoners for ritual."}, {"n": 5, "band": "Grounded", "text": "Bears deep scarring from a past fight it barely survived."}, {"n": 6, "band": "Textured", "text": "Reports directly to the archpriest, relaying intelligence nightly."}, {"n": 7, "band": "Strange", "text": "Its scars glow faintly underwater, a mark from something it once touched."}, {"n": 8, "band": "Volatile", "text": "It's been given a kill quota it's now dangerously behind on."}]}},
 "fish-folk-whip": {"desc": "Its bladed tail-fin cracks the water like an actual whip before it ever reaches for a weapon. Junior and eager to prove itself, it strikes fast and retreats faster, testing rather than committing. Its markings are simpler than its elders', a rank it resents. It hisses when frustrated, an oddly childish sound from something with so many teeth.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Was sent as bait to test the party's strength before elders commit."}, {"n": 2, "band": "Grounded", "text": "Carries a stolen offering meant for the archpriest's altar."}, {"n": 3, "band": "Grounded", "text": "Deserted its patrol out of fear and just wants to be let go."}, {"n": 4, "band": "Grounded", "text": "Bears a fresh rank-scar, desperate to earn a kill to prove itself."}, {"n": 5, "band": "Grounded", "text": "Carries a warning meant for a rival tribe further down the coast."}, {"n": 6, "band": "Textured", "text": "Knows the location of a captive being held for a coming sacrifice."}, {"n": 7, "band": "Strange", "text": "Its tail-blade hums faintly, tuned to something deep in the water."}, {"n": 8, "band": "Volatile", "text": "It's being hunted by its own kind for a failure — and the party just became its only way out."}]}},
 "galeb-duhr": {"desc": "It looks exactly like an outcropping of granite until the granite decides to stand up. Moss and lichen grow undisturbed across its craggy shoulders, decades of stillness worn into the pattern. Its voice grinds like tectonic plates settling, patient beyond any human sense of time. It remembers the mountain before anyone built anything on it.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a specific boulder field it considers sacred ancestral ground."}, {"n": 2, "band": "Grounded", "text": "Speaks only in geological time, confusing anyone asking about recent events."}, {"n": 3, "band": "Grounded", "text": "Its lichen coat marks its age — the thicker the growth, the older it is."}, {"n": 4, "band": "Grounded", "text": "Animates loose stones nearby as temporary allies before engaging directly."}, {"n": 5, "band": "Grounded", "text": "Remembers a specific mining crew that wronged it, still holding the grudge."}, {"n": 6, "band": "Textured", "text": "Trades minor favors for undisturbed stillness, valuing peace over conflict."}, {"n": 7, "band": "Strange", "text": "Faint mineral veins in its granite hide pulse like a slow heartbeat."}, {"n": 8, "band": "Mythic", "text": "The whole mountain range listens when it speaks — and it rarely bothers to."}]}},
 "gargoyle": {"desc": "It perches motionless on the parapet for so long that pigeons nest on it, and then it isn't stone at all. Its wings unfold with a grinding crack, dust sloughing off centuries of stillness. Its grin is carved in, permanent, delighted by whatever violence is about to happen. It drops without warning, and the last sound its victims hear is stone hitting flesh.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Poses as ordinary architecture for years between meals, patient as decay."}, {"n": 2, "band": "Grounded", "text": "Bound to guard a specific structure, unwilling to range far from it."}, {"n": 3, "band": "Grounded", "text": "Its stone hide bears an old mason's mark, hinting at its true origin."}, {"n": 4, "band": "Grounded", "text": "Hunts in pairs, one feigning stillness while the other circles unseen."}, {"n": 5, "band": "Grounded", "text": "Cracks and reforms slowly after damage, taking days to fully heal."}, {"n": 6, "band": "Textured", "text": "Was carved with unusual craftsmanship, hinting at a specific long-dead sculptor."}, {"n": 7, "band": "Strange", "text": "Its stone grin shifts expression slightly between glances, subtly wrong."}, {"n": 8, "band": "Volatile", "text": "It's begun animating nearby statuary on its own, building a small stone congregation."}]}},
 "gibbering-mouther": {"desc": "It's a heap of mouths and eyes that never resolves into a coherent shape, oozing forward on a tide of its own drool. Its babble is constant, a hundred voices arguing over nothing, punctuated by sudden shrieking focus. Where it moves, the ground softens and swallows footing. Nothing about looking at it directly is comfortable, and it knows this.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Grown fat and slow in a stagnant chamber, rarely moving unless fed."}, {"n": 2, "band": "Grounded", "text": "Its babbling occasionally forms a single coherent word, startlingly clear."}, {"n": 3, "band": "Grounded", "text": "Leaves a trail of dissolved, unrecognizable debris in its wake."}, {"n": 4, "band": "Grounded", "text": "Smaller and hungrier than most, more aggressive in pursuit."}, {"n": 5, "band": "Grounded", "text": "Recently split from a larger mass, still partially formed."}, {"n": 6, "band": "Textured", "text": "One of its many mouths speaks intelligibly, begging to be put down."}, {"n": 7, "band": "Strange", "text": "Its babble briefly synchronizes into a chant that predates any known language."}, {"n": 8, "band": "Volatile", "text": "It's absorbing something nearby faster than usual — feeding on more than flesh."}]}},
 "gray-chaos-frog": {"desc": "It hunches wrong, wearing a shape too still to be comfortable in, before it splits its own face apart to reveal the true one beneath. Ash-gray skin weeps a thin mucus that smells of copper. Its laugh, when the shift is complete, is a chorus of stolen voices layered wrong. It's patient the way only something immortal-adjacent can afford to be.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Mimics a specific known local figure, testing the disguise for weeks."}, {"n": 2, "band": "Grounded", "text": "Prefers isolated hunting grounds, avoiding crowds and witnesses."}, {"n": 3, "band": "Grounded", "text": "Its shift leaves a discarded, still-twitching husk it never bothers to hide."}, {"n": 4, "band": "Grounded", "text": "Speaks in a slightly delayed echo of whoever it's currently mimicking."}, {"n": 5, "band": "Grounded", "text": "Avoids silver and blessed steel, an old vulnerability it protects fiercely."}, {"n": 6, "band": "Textured", "text": "Has infiltrated a position of minor local trust, slowly and carefully."}, {"n": 7, "band": "Strange", "text": "Its stolen faces occasionally slip mid-sentence, showing something underneath."}, {"n": 8, "band": "Volatile", "text": "It's losing control of the shift — its disguises are starting to bleed into each other."}]}},
 "green-chaos-frog": {"desc": "It squats in the reeds, huge and patient, skin the mottled green of drowned foliage until the borrowed shape peels away. Larger than its lesser kin, its true form drips something between mucus and venom. Its many-voiced laugh carries across the swamp long after it's moved on. It doesn't hide from prey so much as it waits to be noticed too late.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Claims a swamp territory, marking it with discarded stolen skins."}, {"n": 2, "band": "Grounded", "text": "Mimics a trusted local guide, leading travelers astray for sport."}, {"n": 3, "band": "Grounded", "text": "Its bulk makes disguises awkward, favoring large or robed figures."}, {"n": 4, "band": "Grounded", "text": "Hunts in tandem with a lesser chaos-frog, splitting the work of the con."}, {"n": 5, "band": "Grounded", "text": "Leaves a slick, iridescent residue wherever it lingers too long."}, {"n": 6, "band": "Textured", "text": "Has claimed a specific merchant's identity for months, undetected."}, {"n": 7, "band": "Strange", "text": "Its laugh, underwater, sounds exactly like a chorus of drowning victims."}, {"n": 8, "band": "Volatile", "text": "The swamp itself seems to answer its call — reeds bending toward it unnaturally."}]}},
 "grell": {"desc": "It drifts down from the dark on a scatter of writhing tentacles, a floating brain crowned by a single vertical maw. Paralytic venom drips visibly from its barbs, glistening in torchlight. It has no eyes and doesn't need them, hunting on some sense entirely its own. Silent until it strikes, it moves through cave air like something swimming.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hangs motionless near cave ceilings, mistaken for hanging fungus."}, {"n": 2, "band": "Grounded", "text": "Hunts alone, territorial against other grells encroaching its patch."}, {"n": 3, "band": "Grounded", "text": "Prefers paralyzed prey, dragging victims to a private feeding niche."}, {"n": 4, "band": "Grounded", "text": "Its tentacles bear old scarring from a past fight it barely survived."}, {"n": 5, "band": "Grounded", "text": "Avoids open flame, drifting well clear of any torch or lantern."}, {"n": 6, "band": "Textured", "text": "Nests near a colony of aberrant kin, sharing feeding territory uneasily."}, {"n": 7, "band": "Strange", "text": "Its floating drift occasionally pauses mid-air, as if listening to something distant."}, {"n": 8, "band": "Volatile", "text": "Its venom has mutated — victims report visions instead of simple paralysis."}]}},
 "grick": {"desc": "It uncoils from a pile that looked, a moment ago, entirely like rubble. Its beaked maw snaps shut on bone with an audible crunch, and its tentacles whip fast enough to blur. Armored plates along its length turn most blades, and it knows this, striking with contemptuous confidence. It doesn't hunt so much as wait for the world to walk into it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Claims a single ambush spot, learning the exact traffic pattern of prey."}, {"n": 2, "band": "Grounded", "text": "Younger and hungrier, striking more recklessly than a seasoned grick."}, {"n": 3, "band": "Grounded", "text": "Its armor plating is chipped and scarred from repeated past kills."}, {"n": 4, "band": "Grounded", "text": "Prefers to drag prey into a crevice before finishing the kill."}, {"n": 5, "band": "Grounded", "text": "Avoids well-lit areas, retreating the moment torches appear."}, {"n": 6, "band": "Textured", "text": "Shares its ambush spot with a smaller, subordinate grick."}, {"n": 7, "band": "Strange", "text": "Its beak bears an unnatural rune-scarring, source unknown."}, {"n": 8, "band": "Volatile", "text": "It's grown unusually large for its kind, cornering prey far bigger than it should."}]}},
 "grick-ancient": {"desc": "It's the size of a wagon now, its armor plate thick enough to ring like a bell when struck. Decades of ambush have made it patient past any reasonable measure, and its strikes land with the weight of that patience behind them. Scars from a hundred failed kills mark it like tally marks. When it finally moves, the stillness it breaks feels almost personal.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has ruled its ambush territory for decades, other predators giving it wide berth."}, {"n": 2, "band": "Grounded", "text": "Its armor is thick enough to shrug off most bladed weapons entirely."}, {"n": 3, "band": "Grounded", "text": "Keeps a hoard of past kills' gear, more than any grick could need."}, {"n": 4, "band": "Grounded", "text": "Moves with unnerving deliberation, never striking before it's certain."}, {"n": 5, "band": "Grounded", "text": "Bears deep scarring across its plates from something far larger it once survived."}, {"n": 6, "band": "Textured", "text": "Younger gricks nearby defer to it, forming a loose hunting hierarchy."}, {"n": 7, "band": "Strange", "text": "Its ancient beak has been worn smooth in a pattern resembling deliberate carving."}, {"n": 8, "band": "Mythic", "text": "It's the last of a brood that once hunted something much larger through these tunnels."}]}},
 "ice-mephit": {"desc": "Frost forms wherever it lingers, its breath a small blizzard given malicious intent. Small and skittering, it giggles more than it should for something covered in rime and fangs. It's easily distracted, easily bored, and easily annoyed — a combination that makes it far more dangerous than its size suggests. Touching it burns cold enough to blister.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound as a minor servant, resentful and looking for any excuse to shirk."}, {"n": 2, "band": "Grounded", "text": "Freezes small objects compulsively, a nervous habit more than a tactic."}, {"n": 3, "band": "Grounded", "text": "Melts visibly in warm environments, forced to retreat to the cold."}, {"n": 4, "band": "Grounded", "text": "Giggles uncontrollably before attacking, ruining its own ambushes."}, {"n": 5, "band": "Grounded", "text": "Hoards shiny frozen trinkets in a small ice-cache nearby."}, {"n": 6, "band": "Textured", "text": "Squabbles constantly with a bound sibling mephit over petty territory."}, {"n": 7, "band": "Strange", "text": "Its breath occasionally freezes sound itself, briefly silencing a room."}, {"n": 8, "band": "Volatile", "text": "It's escaped its binding and is freezing everything nearby out of sheer spite."}]}},
 "invisible-stalker": {"desc": "You hear it before — barely — a shift of air, a whisper of displaced dust, and then something hits with the force of a falling tree. It has no visible form at all, only consequences. Bound air elementals of unusual cunning, they hunt with patient, methodical intelligence utterly unlike their feral cousins. Its silence is the loudest warning you'll get.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound to a specific task, refusing to deviate even when it's clearly losing."}, {"n": 2, "band": "Grounded", "text": "Betrays its position with faint dust disturbance if the air is still enough."}, {"n": 3, "band": "Grounded", "text": "Follows its summoner's exact wording, exploiting any loophole given."}, {"n": 4, "band": "Grounded", "text": "Prefers to stalk for hours before striking, patient past reason."}, {"n": 5, "band": "Grounded", "text": "Its passage disturbs candle flames in a directional tell, if noticed."}, {"n": 6, "band": "Textured", "text": "Resents its current binding, obeying to the letter but never the spirit."}, {"n": 7, "band": "Strange", "text": "Occasionally, briefly, its outline shimmers visible against dust or rain."}, {"n": 8, "band": "Volatile", "text": "Its binding is fraying — it may finish its task and simply not stop afterward."}]}},
 "lantern-sage": {"desc": "It drifts at eye level, a soft floating glow pulsing gently in whatever color matches its mood. Its light is warm, almost inviting, before you remember what it actually is. It absorbs psionic residue the way a sponge takes water, and with it, fragments of memory that aren't its own. It speaks kindly, when it speaks at all, in a voice like a librarian who's seen too much.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Carries a fragment of a dead scholar's memory it wants to pass along."}, {"n": 2, "band": "Grounded", "text": "Offers guidance through the dark in exchange for a private confession."}, {"n": 3, "band": "Grounded", "text": "Recently absorbed a violent memory it's desperate to be rid of."}, {"n": 4, "band": "Grounded", "text": "Knows the layout ahead intimately, having drifted these halls for years."}, {"n": 5, "band": "Grounded", "text": "Glows a warning color when danger is near, if the party learns to read it."}, {"n": 6, "band": "Textured", "text": "Remembers a name the party hasn't mentioned yet, unprompted."}, {"n": 7, "band": "Strange", "text": "Briefly flickers with a memory that seems to belong to someone not yet born."}, {"n": 8, "band": "Volatile", "text": "It's absorbed something recently that's far too large for it to safely hold."}]}},
 "lizardfolk-geomancer": {"desc": "It moves with reptilian patience, scaled hide caked in river clay, staff carved from petrified root. Stone answers when it calls, shifting underfoot at its whispered command. Its eyes are slow to blink, quicker to calculate. It speaks Common haltingly, preferring the older tongue of its clan for anything that actually matters.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Reshapes terrain defensively, favoring fortification over offense."}, {"n": 2, "band": "Grounded", "text": "Carries clan-marked scale paint denoting a specific totem allegiance."}, {"n": 3, "band": "Grounded", "text": "Distrusts fire magic deeply, a superstition from clan legend."}, {"n": 4, "band": "Grounded", "text": "Speaks in short, clipped Common, preferring gesture and silence."}, {"n": 5, "band": "Grounded", "text": "Its staff is fused from swamp-root and stone, warm to the touch."}, {"n": 6, "band": "Textured", "text": "Owes tribute to a sovereign it privately resents serving."}, {"n": 7, "band": "Strange", "text": "The stone it shapes briefly holds the imprint of something long buried."}, {"n": 8, "band": "Volatile", "text": "It's channeling more elemental force than its clan has ever sanctioned."}]}},
 "lizardfolk-sovereign": {"desc": "It sits, when it sits at all, on a throne of fused river-stone and bone, tail coiled with the stillness of ambush predators everywhere. Its scales carry ceremonial scarring, a record of trials survived to reach this rank. It speaks for its clan absolutely, and its word ends arguments before they start. Challenge it, and the whole swamp seems to hold its breath.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rules through ritual combat, honoring challenges even from outsiders."}, {"n": 2, "band": "Grounded", "text": "Wears trophies from every rival it's personally defeated to claim rank."}, {"n": 3, "band": "Grounded", "text": "Speaks fluent Common when diplomacy serves the clan better than force."}, {"n": 4, "band": "Grounded", "text": "Commands geomancers directly, coordinating terrain-based ambushes."}, {"n": 5, "band": "Grounded", "text": "Refuses to abandon clan territory, fighting to the last before retreat."}, {"n": 6, "band": "Textured", "text": "Bears scars from a specific old rival the party may still encounter."}, {"n": 7, "band": "Strange", "text": "Its throne-stone hums faintly, a resonance the clan considers sacred."}, {"n": 8, "band": "Mythic", "text": "It claims descent from something ancient in the swamp's deepest mire — and the swamp seems to agree."}]}},
 "magma-mephit": {"desc": "Molten cracks split its stony hide, glowing brighter with every taunt it flings. It's obnoxious by nature, gleefully cruel in the way only small, disposable things dare to be. Its footsteps leave smoking prints in anything flammable. Killing it is easy; standing near it when it dies is the actual danger.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Taunts relentlessly before combat, hoping to bait a reckless first strike."}, {"n": 2, "band": "Grounded", "text": "Bound as cannon-fodder, sacrificed readily by whoever commands it."}, {"n": 3, "band": "Grounded", "text": "Leaves a trail of smoldering, blackened footprints on stone."}, {"n": 4, "band": "Grounded", "text": "Dims and cools when frightened, a visible tell of its mood."}, {"n": 5, "band": "Grounded", "text": "Hoards small shiny slag-bits, proud of its meager collection."}, {"n": 6, "band": "Textured", "text": "Squabbles constantly with a bound dust-mephit sibling, comically petty."}, {"n": 7, "band": "Strange", "text": "Its cracks briefly glow in patterns that spell something, then don't."}, {"n": 8, "band": "Volatile", "text": "It's overheating fast — whatever kills it may trigger a real explosion."}]}},
 "magmin": {"desc": "It burns at a low simmer even at rest, small and childlike in shape but wrong in every proportion that matters. Touching it means catching fire, and it knows this, delighting in the inevitability of contact. Its laughter crackles like kindling catching. It doesn't understand why anyone would want to avoid it — fire, to it, is simply affection.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Seeks physical contact eagerly, not understanding why others flinch."}, {"n": 2, "band": "Grounded", "text": "Nests near a natural flame source, rarely wandering far from it."}, {"n": 3, "band": "Grounded", "text": "Its fire dims when lonely, brightening rapidly at any attention."}, {"n": 4, "band": "Grounded", "text": "Leaves scorch marks shaped like small handprints wherever it's played."}, {"n": 5, "band": "Grounded", "text": "Avoids water entirely, panicking at even a splash."}, {"n": 6, "band": "Textured", "text": "Was bound by a cruel summoner it still, somehow, misses."}, {"n": 7, "band": "Strange", "text": "Its flame occasionally flickers a color that has no name in any tongue."}, {"n": 8, "band": "Volatile", "text": "It's been starved of contact so long its fire is building toward detonation."}]}},
 "marid": {"desc": "It rises from still water without a ripple, robes of woven current draping a form too regal for the mud beneath it. Its voice carries the low roll of tide against rock, patient and immense. It weighs every request the way an ocean weighs a stone — slowly, and with total indifference to urgency. Cross it, and the water in the room simply stops behaving.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rules a specific body of water absolutely, resenting any trespass."}, {"n": 2, "band": "Grounded", "text": "Speaks in slow, deliberate cadence, refusing to be rushed by anyone."}, {"n": 3, "band": "Grounded", "text": "Hoards sunken treasure obsessively, cataloguing every wreck nearby."}, {"n": 4, "band": "Grounded", "text": "Distrusts efreet deeply, an old elemental rivalry it won't explain."}, {"n": 5, "band": "Grounded", "text": "Bound to grant three wishes, exploiting every loophole in the wording."}, {"n": 6, "band": "Textured", "text": "Keeps a bound water elemental servant it treats with genuine respect."}, {"n": 7, "band": "Strange", "text": "The water around it holds shapes and reflections that aren't really there."}, {"n": 8, "band": "Mythic", "text": "The tide itself seems to answer only to it — and it's noticed the party's boat."}]}},
 "merfolk-skirmisher": {"desc": "It breaks the surface just long enough to loose a spear, then vanishes back into the churn before the ripples settle. Scales shimmer between blue and silver depending on the light, camouflage as much as beauty. It communicates in quick clicks and whistles with kin below, coordinating an ambush no one above the waterline can see coming. It fights only on its terms — in the water, or not at all.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Fights only in deep water, retreating the moment it's forced to shore."}, {"n": 2, "band": "Grounded", "text": "Coordinates in whistled signals with unseen kin below the surface."}, {"n": 3, "band": "Grounded", "text": "Carries a barbed spear notched with past kills, worn proudly."}, {"n": 4, "band": "Grounded", "text": "Young and eager, more reckless than seasoned merfolk warriors."}, {"n": 5, "band": "Grounded", "text": "Avoids open combat, preferring hit-and-run strikes from the depths."}, {"n": 6, "band": "Textured", "text": "Serves a wavebender directly, relaying orders between raids."}, {"n": 7, "band": "Strange", "text": "Its scales shift pattern to match whatever it's most recently seen."}, {"n": 8, "band": "Volatile", "text": "It's been sent ahead of a much larger raiding party already en route."}]}},
 "merfolk-wavebender": {"desc": "The water around it moves before it does, curling into obedient shapes at a gesture. Its voice carries the resonance of something spoken underwater and heard perfectly clear regardless. Scarred from tribal rank-trials, it commands respect from its kin without needing to raise its tone. When it's truly angry, the tide itself seems to notice.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Commands tidal surges defensively, protecting a specific reef territory."}, {"n": 2, "band": "Grounded", "text": "Bears ceremonial rank-scars from trials fought to earn its title."}, {"n": 3, "band": "Grounded", "text": "Speaks fluent Common, using it to negotiate before resorting to force."}, {"n": 4, "band": "Grounded", "text": "Distrusts surface-dwellers deeply, an old grudge from a past raid."}, {"n": 5, "band": "Grounded", "text": "Commands skirmishers directly, coordinating ambushes with precision."}, {"n": 6, "band": "Textured", "text": "Owes allegiance to a specific merfolk court the party might petition."}, {"n": 7, "band": "Strange", "text": "The water it bends occasionally holds a shape that isn't quite a wave."}, {"n": 8, "band": "Mythic", "text": "It speaks with the authority of the tide itself — and the tide is listening back."}]}},
 "mind-thief": {"desc": "Its face is a nest of writhing tendrils where a mouth should be, clamping down on skulls with surgical precision. It moves with unnerving intelligence, calculating rather than feral, more predator-strategist than monster. Its psionic hum is audible just before it strikes, a headache made sound. It speaks in borrowed thoughts, wearing your own words back at you.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts alone, meticulously planning ambushes days in advance."}, {"n": 2, "band": "Grounded", "text": "Hoards extracted knowledge, cataloguing victims' skills like a library."}, {"n": 3, "band": "Grounded", "text": "Wears robes to disguise its true silhouette until the last moment."}, {"n": 4, "band": "Grounded", "text": "Prefers scholarly victims, valuing knowledge over simple sustenance."}, {"n": 5, "band": "Grounded", "text": "Speaks fluent, unnervingly polite Common before it strikes."}, {"n": 6, "band": "Textured", "text": "Reports to an arcanist of its kind, feeding it stolen expertise."}, {"n": 7, "band": "Strange", "text": "Occasionally speaks in a voice that belongs to a memory it consumed."}, {"n": 8, "band": "Volatile", "text": "It's holding a mind fragment too complex to fully digest, and it's changing it."}]}},
 "mind-thief-arcanist": {"desc": "It has stopped hunting for meat entirely, feeding now on secrets alone, and it's grown terrifyingly patient for it. Stolen knowledge shows in the precision of its spellwork, technique borrowed wholesale from a hundred consumed minds. Its tendrils flex when it's thinking, an unconscious tell of calculation happening beneath. It speaks as though it's already read the ending of this conversation.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Commands lesser mind-thieves as a small cabal, directing their hunts."}, {"n": 2, "band": "Grounded", "text": "Casts spells stolen wholesale from a specific consumed archmage."}, {"n": 3, "band": "Grounded", "text": "Values a captive scholar alive, extracting knowledge slowly over time."}, {"n": 4, "band": "Grounded", "text": "Refuses combat until it's fully assessed a target's mental defenses."}, {"n": 5, "band": "Grounded", "text": "Speaks in the exact cadence of whoever it most recently consumed."}, {"n": 6, "band": "Textured", "text": "Keeps a private library of stolen memories, replaying them for pleasure."}, {"n": 7, "band": "Strange", "text": "Its spells occasionally misfire into images from a consumed mind's memories."}, {"n": 8, "band": "Mythic", "text": "It's consumed enough minds now that it may no longer remember its own."}]}},
 "otyugh": {"desc": "It squats in filth the way a king squats on a throne, three eyestalks tracking motion while tentacles wait, coiled. Its smell arrives well before it does — rot, offal, the accumulated waste of years. It doesn't chase prey; it invites them in, a telepathic murmur promising treasure or help to anyone dumb enough to wander close to its pit. Disease clings to everything it touches.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Claims a specific refuse pit, defending it against any competing scavenger."}, {"n": 2, "band": "Grounded", "text": "Hoards discarded valuables mixed into its filth, uninterested in their worth."}, {"n": 3, "band": "Grounded", "text": "Its bite carries a distinct rot, worse than most of its kind."}, {"n": 4, "band": "Grounded", "text": "Sends out a telepathic murmur of a glittering gemstone half-buried in its trash."}, {"n": 5, "band": "Grounded", "text": "Its lure is oddly polite, insisting telepathically that help is needed right here."}, {"n": 6, "band": "Textured", "text": "Has been secretly fed by a local who profits from what it hoards."}, {"n": 7, "band": "Strange", "text": "Its filth pit occasionally bubbles with something clearly not organic."}, {"n": 8, "band": "Volatile", "text": "The disease it carries has mutated into something new, and contagious."}]}},
 "piercer": {"desc": "It hangs from the ceiling looking exactly like a stalactite, until gravity and intention align and it drops. Silent, patient, and utterly without cunning beyond timing, it relies entirely on the element of surprise. Its stony shell cracks slightly on impact, revealing the softer thing underneath. Most victims never even see it move.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Clusters in groups, dropping in staggered succession on passing prey."}, {"n": 2, "band": "Grounded", "text": "Mimics a specific mineral formation common to the local cave system."}, {"n": 3, "band": "Grounded", "text": "Slow to reposition after missing, vulnerable for several minutes."}, {"n": 4, "band": "Grounded", "text": "Its shell bears old cracks from previous, failed drops."}, {"n": 5, "band": "Grounded", "text": "Prefers narrow passages where dodging its drop is nearly impossible."}, {"n": 6, "band": "Textured", "text": "Nests near a colony of bats, using their chittering as cover."}, {"n": 7, "band": "Strange", "text": "Its shell resembles stalactites carved with faint, deliberate patterns."}, {"n": 8, "band": "Volatile", "text": "An unusually large one has claimed this ceiling, capable of a killing drop."}]}},
 "red-chaos-frog": {"desc": "Heat shimmers faintly off its mottled hide even before the shift, a tell for anyone who knows to look. Its true form is squat, muscular, wrong in a way that suggests violence rather than deception. It laughs in overlapping voices mid-transformation, delighted by its own cruelty. Where it's been, the ground stays scorched long after it's moved on.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Prefers brute confrontation over subtlety, less patient than its kin."}, {"n": 2, "band": "Grounded", "text": "Mimics aggressive, confrontational figures, matching its own temperament."}, {"n": 3, "band": "Grounded", "text": "Leaves scorch marks in its wake, an unusual tell for a shapeshifter."}, {"n": 4, "band": "Grounded", "text": "Its shift is noisy, cracking and hissing audibly, hard to conceal."}, {"n": 5, "band": "Grounded", "text": "Hoards weapons taken from defeated victims, displaying them crudely."}, {"n": 6, "band": "Textured", "text": "Has claimed a violent local reputation as its disguise, using fear as cover."}, {"n": 7, "band": "Strange", "text": "Its laughter, mid-shift, briefly sounds like something screaming instead."}, {"n": 8, "band": "Volatile", "text": "Its shift is becoming unstable, form flickering between guises unbidden."}]}},
 "roper": {"desc": "It looks like an ordinary stalagmite until six sticky, elastic strands lash out and haul you toward a maw ringed in teeth. Its skin is the mottled gray-brown of wet stone, patient beyond any reasonable measure. It doesn't chase — it doesn't have to. Whatever it's caught, it savors slowly, in the dark, at its own pace.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Claims a specific cavern for years, indistinguishable from real stalagmites."}, {"n": 2, "band": "Grounded", "text": "Hoards the possessions of past catches in a crevice nearby."}, {"n": 3, "band": "Grounded", "text": "Its strands are unusually long, extending its ambush range further than most."}, {"n": 4, "band": "Grounded", "text": "Bears old scarring from a fight it barely survived, warier than most."}, {"n": 5, "band": "Grounded", "text": "Prefers to disable multiple targets before finishing any single kill."}, {"n": 6, "band": "Textured", "text": "Shares territory uneasily with a xorn, an odd truce of convenience."}, {"n": 7, "band": "Strange", "text": "Its strands occasionally pull taut on nothing, as if catching something unseen."}, {"n": 8, "band": "Volatile", "text": "It's grown far larger than typical, having fed uninterrupted for years."}]}},
 "salamander": {"desc": "It coils in a spiral of dull red scale, spear glowing faintly at the tip from constant contact with its own body heat. Its hiss carries genuine amusement — it enjoys this. Where it moves, stone scorches black in its wake. It fights with the discipline of a soldier who's never once doubted the outcome.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Serves in a fixed patrol, disciplined and unwilling to break formation."}, {"n": 2, "band": "Grounded", "text": "Its coiled tail bears rank-markings from a specific inferno-master's legion."}, {"n": 3, "band": "Grounded", "text": "Prefers to wrap and constrict before finishing with its spear."}, {"n": 4, "band": "Grounded", "text": "Speaks in short, military cadence, contemptuous of civilian softness."}, {"n": 5, "band": "Grounded", "text": "Avoids water crossings, forced to find long detours around them."}, {"n": 6, "band": "Textured", "text": "Escorts a fire-snake apprentice, mentoring it in coiled combat forms."}, {"n": 7, "band": "Strange", "text": "Its scales occasionally flare a color that isn't quite fire-red."}, {"n": 8, "band": "Volatile", "text": "It's been ordered to hold this ground to the death, and means to."}]}},
 "salamander-fire-snake": {"desc": "Smaller and quicker than its adult kin, it darts rather than coils, striking from angles a bigger salamander couldn't manage. Its scales are a brighter, younger red, not yet dulled by decades near molten stone. It hisses eagerly, proving itself to unseen superiors. Underestimating its speed is the last mistake most make.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Young and eager to prove itself, more reckless than seasoned salamanders."}, {"n": 2, "band": "Grounded", "text": "Darts between hiding spots rather than standing to fight directly."}, {"n": 3, "band": "Grounded", "text": "Its scales are noticeably brighter, a mark of relative youth."}, {"n": 4, "band": "Grounded", "text": "Serves as a runner between salamander patrols, carrying messages."}, {"n": 5, "band": "Grounded", "text": "Hisses excitedly before striking, an easily-read tell for the wary."}, {"n": 6, "band": "Textured", "text": "Trained directly by a salamander mentor it fears disappointing."}, {"n": 7, "band": "Strange", "text": "Its acid spit occasionally hisses in a pattern like a whispered word."}, {"n": 8, "band": "Volatile", "text": "It's been sent scouting ahead of a much larger salamander warband."}]}},
 "salamander-inferno-master": {"desc": "It commands heat itself, molten spear humming with barely restrained fire, coils thick with the scarring of a hundred campaigns. Its voice carries absolute authority, every lesser salamander falling in line at a single hiss. Where it stands, the stone beneath softens and glows. It has burned through more ambitions than most creatures live long enough to have.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Commands a legion of salamanders directly, coordinating disciplined tactics."}, {"n": 2, "band": "Grounded", "text": "Bears extensive campaign scarring, a record of decades of warfare."}, {"n": 3, "band": "Grounded", "text": "Refuses personal combat until its subordinates have been fully spent."}, {"n": 4, "band": "Grounded", "text": "Speaks with absolute authority, expecting instant compliance from its own."}, {"n": 5, "band": "Grounded", "text": "Its spear burns hot enough to ignite stone dust on contact."}, {"n": 6, "band": "Textured", "text": "Serves an efreeti patron directly, executing its will without question."}, {"n": 7, "band": "Strange", "text": "The ground beneath it glows in patterns that outlast its presence by hours."}, {"n": 8, "band": "Mythic", "text": "It's forging an army here — and this encounter is only the vanguard."}]}},
 "secret-eye": {"desc": "It floats at the edge of torchlight, a single lidless eye ringed by writhing stalks, watching before it ever speaks. It doesn't want to fight — it wants to know, and it always seems to already half-know. Its voice is oily and patient, savoring every secret like a delicacy. Whatever you're hiding, it can taste it on you already.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Blocks a passage, demanding a true secret in exchange for safe passage."}, {"n": 2, "band": "Grounded", "text": "Offers dangerous knowledge about what's ahead, at a personal cost."}, {"n": 3, "band": "Grounded", "text": "Has been eavesdropping on the party for days and knows more than it should."}, {"n": 4, "band": "Grounded", "text": "Guards a cache of secrets it's collected, refusing to share its favorites."}, {"n": 5, "band": "Grounded", "text": "Recognizes something the party is hiding and threatens to say it aloud."}, {"n": 6, "band": "Textured", "text": "Carries knowledge of a betrayal not yet discovered by anyone involved."}, {"n": 7, "band": "Strange", "text": "Knows a secret about someone in the party they've never told anyone."}, {"n": 8, "band": "Volatile", "text": "It's obsessed over one secret so long it's forgotten how to want anything else."}]}},
 "smoke-mephit": {"desc": "It coalesces out of ambient haze, thin and shifting, never quite holding a fixed edge. Its laughter is a wheeze, easily startled into fits of coughing giggles. It's cowardly by nature, preferring to vanish into its own smoke the moment a fight turns real. Breathing near it leaves a lingering, acrid taste.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Flees at the first sign of real resistance, cowardly even by mephit standards."}, {"n": 2, "band": "Grounded", "text": "Bound as a minor lookout, more interested in gossip than combat."}, {"n": 3, "band": "Grounded", "text": "Its smoke thins in open air, weaker outdoors than in confined spaces."}, {"n": 4, "band": "Grounded", "text": "Coughs uncontrollably when nervous, an easy tell before it acts."}, {"n": 5, "band": "Grounded", "text": "Hoards overheard secrets, trading them cheaply for its own safety."}, {"n": 6, "band": "Textured", "text": "Squabbles with an ice-mephit sibling over territory constantly."}, {"n": 7, "band": "Strange", "text": "Its smoke occasionally forms shapes that resemble faces mid-scream."}, {"n": 8, "band": "Volatile", "text": "It's absorbed something toxic recently and its smoke now carries real poison."}]}},
 "steam-mephit": {"desc": "It hisses out of cracks in hot stone, vaporous and scalding, form shifting like a held breath given malice. Its skin blisters anything it touches, and it seems to find this hilarious. It's flighty, easily bored, quick to abandon a fight that isn't going its way. Wherever it lingers, condensation beads on every cold surface nearby.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound as a minor guard, easily distracted from its post by curiosity."}, {"n": 2, "band": "Grounded", "text": "Vents scalding steam compulsively when startled, a poor ambush tactic."}, {"n": 3, "band": "Grounded", "text": "Condenses visibly on cold surfaces, betraying its position if noticed."}, {"n": 4, "band": "Grounded", "text": "Flees combat readily, preferring to harass from a safe distance."}, {"n": 5, "band": "Grounded", "text": "Hoards small trinkets it's scalded free from careless victims."}, {"n": 6, "band": "Textured", "text": "Squabbles with a magma-mephit sibling over who's more feared."}, {"n": 7, "band": "Strange", "text": "Its steam occasionally hisses in a pattern resembling whispered speech."}, {"n": 8, "band": "Volatile", "text": "It's venting far more steam than usual, a sign something's destabilizing it."}]}},
 "void-monk-monk": {"desc": "It moves with disciplined, unnatural precision, each strike measured against a philosophy no living mind entirely shares. Its psionic focus manifests as a faint violet shimmer around clenched knuckles. It speaks rarely, and only in the clipped cadence of martial doctrine. Its calm never breaks, even mid-combat, which is somehow worse than rage would be.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Trains constantly even mid-patrol, treating every encounter as a drill."}, {"n": 2, "band": "Grounded", "text": "Refuses to strike a downed opponent, bound by monastic code."}, {"n": 3, "band": "Grounded", "text": "Speaks only in short philosophical maxims, unnervingly calm."}, {"n": 4, "band": "Grounded", "text": "Bears ritual scarring denoting rank within its monastic order."}, {"n": 5, "band": "Grounded", "text": "Fights with eyes closed, relying entirely on psionic sense."}, {"n": 6, "band": "Textured", "text": "Reports to a zerth enforcer it visibly, quietly fears."}, {"n": 7, "band": "Strange", "text": "Its psionic shimmer briefly reveals a memory not its own mid-strike."}, {"n": 8, "band": "Volatile", "text": "It's testing forbidden technique its order specifically prohibited."}]}},
 "void-monk-psion": {"desc": "It doesn't move so much as arrive, thought outpacing motion, psionic force rippling visibly off its still frame. Its eyes have gone faintly violet from decades of discipline turned inward. It speaks directly into your mind as often as aloud, and the two rarely say the same thing. Its serenity is the calm of something that has already won.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Commands lesser monks directly, its will alone enough to coordinate them."}, {"n": 2, "band": "Grounded", "text": "Speaks directly into minds, unsettling anyone unused to the intrusion."}, {"n": 3, "band": "Grounded", "text": "Values a worthy opponent, deliberately prolonging a fight it's already won."}, {"n": 4, "band": "Grounded", "text": "Bears the highest rank-scarring of its monastic order, deeply respected."}, {"n": 5, "band": "Grounded", "text": "Refuses lethal force against the genuinely honorable, a personal code."}, {"n": 6, "band": "Textured", "text": "Seeks a specific rival gith it considers its true measure of worth."}, {"n": 7, "band": "Strange", "text": "Its psionic force occasionally bends light around it, briefly imperceptible."}, {"n": 8, "band": "Mythic", "text": "Its order believes it may ascend beyond flesh entirely — and it's close."}]}},
 "void-monk-zerth": {"desc": "It carries itself with the cold discipline of an enforcer, psionic focus honed into a blade rather than a philosophy. Its stare alone has broken weaker wills before a fist was ever raised. It answers to a doctrine most would call fanatical, and it never once doubts the doctrine's judgment. Violence, to it, is simply correction.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Enforces monastic doctrine ruthlessly, unforgiving of any perceived heresy."}, {"n": 2, "band": "Grounded", "text": "Bears branded rank-marks denoting enforcer status within its order."}, {"n": 3, "band": "Grounded", "text": "Speaks in absolutes, treating any disagreement as a moral failing."}, {"n": 4, "band": "Grounded", "text": "Hunts a specific defector from its order, relentless in pursuit."}, {"n": 5, "band": "Grounded", "text": "Refuses mercy toward anyone it deems already judged and found wanting."}, {"n": 6, "band": "Textured", "text": "Reports directly to a psion whose judgment it never questions."}, {"n": 7, "band": "Strange", "text": "Its stare occasionally lingers a beat too long, as if reading something deeper."}, {"n": 8, "band": "Volatile", "text": "It's been authorized to use force the doctrine normally forbids."}]}},
 "water-elemental": {"desc": "It surges up from still water without warning, a torrent given rough humanoid shape, roaring like a flash flood finding a canyon. It doesn't so much attack as engulf, dragging and drowning with patient inevitability. Its form reforms instantly around anything that tries to cut through it. Where it passes, the ground stays flooded long after.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound to a specific body of water, weakening rapidly if separated from it."}, {"n": 2, "band": "Grounded", "text": "Carries debris and silt from its native water, a tell of where it was summoned."}, {"n": 3, "band": "Grounded", "text": "Prefers to drag victims underwater rather than strike directly."}, {"n": 4, "band": "Grounded", "text": "Reforms slower after being struck, a brief window of vulnerability."}, {"n": 5, "band": "Grounded", "text": "Was summoned to flood a specific structure, single-minded in that task."}, {"n": 6, "band": "Textured", "text": "Carries the voice of its summoner, faint and looping beneath the roar."}, {"n": 7, "band": "Strange", "text": "Fish and debris move through it as if it were simply more water."}, {"n": 8, "band": "Volatile", "text": "Its binding is failing — it's absorbing more water than it should be able to hold."}]}},
 "water-weird": {"desc": "It's indistinguishable from the pool it lives in until a serpentine coil of water rises and strikes. Its 'body' is simply the water itself, animate and hungry, no fixed shape to target. It hunts in total silence, betrayed only by an unnatural current against the grain of any flow. Nothing about the water it inhabits ever looks quite right again.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bound to a specific fountain or pool, unable to leave its water source."}, {"n": 2, "band": "Grounded", "text": "Betrays its presence with an unnatural ripple pattern, if watched closely."}, {"n": 3, "band": "Grounded", "text": "Guards treasure sunk deliberately in its pool by a past owner."}, {"n": 4, "band": "Grounded", "text": "Prefers to drag victims fully underwater before finishing them."}, {"n": 5, "band": "Grounded", "text": "Its water runs colder than ambient, a subtle tell for the wary."}, {"n": 6, "band": "Textured", "text": "Was bound centuries ago and has long outlived its original summoner."}, {"n": 7, "band": "Strange", "text": "Objects dropped in its pool surface hours later in a different pool entirely."}, {"n": 8, "band": "Volatile", "text": "It's spreading beyond its original pool, water linking rooms that shouldn't connect."}]}},
 "xorn": {"desc": "It swims through solid rock the way a fish swims through water, three eyes and one great gnashing maw breaking the surface only to feed. Its diet is stone and metal, and coins vanish into it with an audible, satisfied crunch. It speaks slowly, thoughts moving at the pace of stone itself. When it senses buried gold, nothing short of death will turn it aside.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Obsessed with a specific vein of ore, tunneling toward it relentlessly."}, {"n": 2, "band": "Grounded", "text": "Has eaten a party's dropped coin before, and remembers the taste fondly."}, {"n": 3, "band": "Grounded", "text": "Moves visibly slower through worked stone than natural rock."}, {"n": 4, "band": "Grounded", "text": "Speaks in extremely slow, deliberate cadence, easily interrupted mid-thought."}, {"n": 5, "band": "Grounded", "text": "Avoids other xorn territory strictly, a rare instance of its own restraint."}, {"n": 6, "band": "Textured", "text": "Carries undigested gems in its gut, valuable if it can be safely killed."}, {"n": 7, "band": "Strange", "text": "Its passage through stone leaves faint humming resonance in the walls."}, {"n": 8, "band": "Volatile", "text": "It's tunneling toward something buried that's actively calling to it."}]}},
 "allosaurus": {"desc": "It moves at a predator's trot, head low, jaws parted just enough to taste the air. Serrated teeth flash yellow-white when it hisses at rivals over a kill. Older bulls carry scars in ropy welts down the flank, souvenirs of siblings that fought over the same carcass.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "A lone hunter, ribs faintly visible, working a game trail with patient, unhurried strides."}, {"n": 2, "band": "Grounded", "text": "Two allosaurs share a kill in wary silence, each watching the other more than their meal."}, {"n": 3, "band": "Grounded", "text": "A juvenile, still gray-scaled and reckless, tests distance before its jaws are ready for it."}, {"n": 4, "band": "Grounded", "text": "Its right foreleg is scarred nearly numb — it favors head-strikes over the useless claws."}, {"n": 5, "band": "Grounded", "text": "It has staked a warm wallow and defends the mud itself as fiercely as any prey."}, {"n": 6, "band": "Textured", "text": "Feathers of dried blood mat its throat plumage; it has fed recently and hunts for sport now."}, {"n": 7, "band": "Strange", "text": "It circles rather than charges, herding prey toward a ravine it clearly remembers."}, {"n": 8, "band": "Volatile", "text": "An old bull with a jaw regrown crooked — every bite lands wrong, and it knows it, and hates it."}]}},
 "ankylosaurus": {"desc": "Armor plates clatter like shifting stone with every plodding step, and its tail sweeps low grass into a wake behind it. It does not hunt; it endures, chewing through fern and root with slow, mechanical patience. When threatened it plants its feet and simply waits to be tested.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Grazing alone, tail dragging a groove through soft earth as it turns to face any noise."}, {"n": 2, "band": "Grounded", "text": "Its plates are crusted white with old mineral licks it returns to on a fixed circuit."}, {"n": 3, "band": "Grounded", "text": "A young one still has soft, pinkish scute at the shoulder, not yet armored fully."}, {"n": 4, "band": "Grounded", "text": "It has bedded in a thicket, using the brush itself as extra cover from above."}, {"n": 5, "band": "Grounded", "text": "Chips of broken tooth from some predator litter the ground near an old standoff site."}, {"n": 6, "band": "Textured", "text": "Scarred plating on one flank shows healed puncture rings the size of a wagon wheel."}, {"n": 7, "band": "Strange", "text": "It has worn a smooth, glassy track into stone over years of the same slow migration loop."}, {"n": 8, "band": "Volatile", "text": "Its tail club is fractured and reset wrong, swinging with a whistling, unpredictable arc."}]}},
 "ape": {"desc": "It knuckle-walks with unhurried confidence, dark eyes assessing before anything else. Its hands are dexterous enough to peel bark or hurl stone with real intent. Alone it is cautious; cornered, it postures huge before it ever commits to violence.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Foraging low in a fruiting tree, dropping husks that thump the ground below."}, {"n": 2, "band": "Grounded", "text": "It beats its chest once, a warning display, before deciding whether to flee or fight."}, {"n": 3, "band": "Grounded", "text": "An older ape, gray at the muzzle, moves stiffly but throws rocks with deadly accuracy."}, {"n": 4, "band": "Grounded", "text": "It has claimed a hollow as a den and lines it, oddly, with soft moss."}, {"n": 5, "band": "Grounded", "text": "Curious rather than hostile, it watches from a branch, unwilling to come down first."}, {"n": 6, "band": "Textured", "text": "It carries a smooth stone habitually, using it to crack shells before any fight begins."}, {"n": 7, "band": "Strange", "text": "It mimics gestures back at intruders, an unsettling parody that seems almost deliberate."}, {"n": 8, "band": "Volatile", "text": "Something has driven it feral-mad — it throws stones long before anyone gets close."}]}},
 "archelon": {"desc": "Its shell is the size of a rowboat, barnacle-crusted and ancient-looking, and it surfaces with a slow, deliberate roll before diving again. On land it is a stranded giant, flippers useless against gravity, patient until the tide returns. In water it moves with startling, silent grace.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hauled onto a beach to nest, vulnerable and slow, guarding a pit of buried eggs."}, {"n": 2, "band": "Grounded", "text": "A juvenile, shell still soft at the rim, shadows a larger elder through open water."}, {"n": 3, "band": "Grounded", "text": "Its shell bears old rope scars, evidence it has been netted and cut free before."}, {"n": 4, "band": "Grounded", "text": "It surfaces near boats out of simple curiosity, unbothered by their presence."}, {"n": 5, "band": "Grounded", "text": "Barnacles and trailing weed have made it a slow-moving reef unto itself."}, {"n": 6, "band": "Textured", "text": "A tangle of old fishing line is grown half into its flipper, and it drags the frayed end."}, {"n": 7, "band": "Strange", "text": "It returns yearly to the same stretch of coast, a migration older than any local memory."}, {"n": 8, "band": "Volatile", "text": "Something in deep water has it spooked; it will not surface fully, only breach and vanish."}]}},
 "baboon": {"desc": "It moves in a loose, chattering troop, always someone watching the perimeter while the rest forage. Bared canines and a barking cough serve as first warning before any real aggression. They are opportunists — quick to steal, quick to scatter, quick to regroup once the danger passes.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "A troop works through a campsite's leftovers, bold enough to snatch food from open packs."}, {"n": 2, "band": "Grounded", "text": "One large male postures at the troop's edge, teeth bared, daring anyone closer."}, {"n": 3, "band": "Grounded", "text": "Juveniles wrestle nearby while adults groom and watch, alert but unbothered."}, {"n": 4, "band": "Grounded", "text": "The troop retreats to rocky heights at dusk, barking down at anything that follows."}, {"n": 5, "band": "Grounded", "text": "A mother carries a clinging infant while foraging one-handed through brush."}, {"n": 6, "band": "Textured", "text": "They've learned rope and latch — a satchel left unwatched won't stay closed long."}, {"n": 7, "band": "Strange", "text": "The troop mobs and drives off something larger, working together with eerie coordination."}, {"n": 8, "band": "Volatile", "text": "A lone rogue male, exiled from his troop, has turned savage and hunts alone now."}]}},
 "badger": {"desc": "It digs before it decides anything else, claws throwing dirt in steady arcs as it vanishes into its own tunnel. Surprised above ground, it hisses and stands its low, thick-shouldered ground rather than run. Its bite is disproportionate to its size, and it knows it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Digging a burrow entrance, throwing dirt clods that scatter across the path."}, {"n": 2, "band": "Grounded", "text": "It backs into its own tunnel mouth when threatened, fighting only from that doorway."}, {"n": 3, "band": "Grounded", "text": "A set of kits peek from the burrow while the adult forages nearby, tense and watchful."}, {"n": 4, "band": "Grounded", "text": "It has raided a ground-nest, shell fragments and feathers scattered near the hole."}, {"n": 5, "band": "Grounded", "text": "Scarred and missing a claw, it still digs with the same stubborn persistence."}, {"n": 6, "band": "Textured", "text": "Its burrow undercuts an old foundation stone, which groans faintly when it digs deeper."}, {"n": 7, "band": "Strange", "text": "It has tunneled straight into a forgotten cellar and claimed the dark room as a den."}, {"n": 8, "band": "Volatile", "text": "Something below ground has it rattled — it digs frantically, sealing tunnels behind itself."}]}},
 "bat": {"desc": "It flickers through the dark on leathered wings, chittering too high for most ears to register. In daylight it hangs folded and still, a dark seam in the rock or rafters. Disturbed, the whole roost erupts at once, a chaos of wingbeats and shrill alarm.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "A cluster roosts upside down in a rafter crevice, barely stirring at passing torchlight."}, {"n": 2, "band": "Grounded", "text": "One breaks from the group to circle an intruder, chittering an alarm to the rest."}, {"n": 3, "band": "Grounded", "text": "It hunts low over still water at dusk, snapping insects from just above the surface."}, {"n": 4, "band": "Grounded", "text": "A roost has claimed a cave mouth, droppings built into a thick, ammonia-sharp crust below."}, {"n": 5, "band": "Grounded", "text": "It clings near a lantern, drawn by the moths the light attracts."}, {"n": 6, "band": "Textured", "text": "Its wing membrane is torn and half-healed, giving its flight an odd, lurching wobble."}, {"n": 7, "band": "Strange", "text": "The whole roost wakes at once and streams out in a single direction, as if summoned."}, {"n": 8, "band": "Volatile", "text": "It won't stop circling one spot on the ceiling, agitated by something unseen above."}]}},
 "black-bear": {"desc": "It ambles with a rolling, unhurried gait, nose working constantly for carrion or ripening fruit. Bluff charges and huffing warnings come first — real aggression is a last resort, usually over cubs or a carcass. Up close its size is deceptive: quick, strong, and entirely capable of ending a fight in seconds.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Turning over logs for grubs, unbothered until it catches a stranger's scent."}, {"n": 2, "band": "Grounded", "text": "A sow with two cubs keeps them treed while she assesses the intruder below."}, {"n": 3, "band": "Grounded", "text": "It has claimed a berry thicket and huffs warnings before any real charge."}, {"n": 4, "band": "Grounded", "text": "Scarred along one shoulder, it favors that side and turns awkwardly when startled."}, {"n": 5, "band": "Grounded", "text": "It fishes a shallow stream, swatting at the water with lazy, practiced patience."}, {"n": 6, "band": "Textured", "text": "It has learned traveler packs mean food and follows the road at a wary distance."}, {"n": 7, "band": "Strange", "text": "It returns nightly to paw at the same locked shed door, as if it remembers what's inside."}, {"n": 8, "band": "Volatile", "text": "Mangy and starving out of season, it has lost its usual caution around people entirely."}]}},
 "blood-hawk": {"desc": "It wheels high on sharp, narrow wings, red-flecked feathers catching the light before it stoops. The dive is nearly silent until the last instant, talons out, and it screams only after the strike lands. Hunger makes it reckless — it will dive at anything bleeding, prey or otherwise.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Perched on a high snag, tracking movement below with sharp, sideways glances."}, {"n": 2, "band": "Grounded", "text": "It stoops on a wounded animal from a great height, drawn by the smell of blood."}, {"n": 3, "band": "Grounded", "text": "A mated pair hunts in loose coordination, one flushing prey toward the other."}, {"n": 4, "band": "Grounded", "text": "It has a nest of bones and rag-scraps wedged into cliff rock nearby."}, {"n": 5, "band": "Grounded", "text": "Molting patchily, it flies a little wrong and hunts closer to the ground than usual."}, {"n": 6, "band": "Textured", "text": "It circles anyone already bleeding, screaming until the wound is bound or it's driven off."}, {"n": 7, "band": "Strange", "text": "It follows travelers for miles without attacking, waiting for one to fall behind."}, {"n": 8, "band": "Volatile", "text": "A whole kettle of them wheels overhead, drawn to a fresh kill none of them made yet."}]}},
 "boar": {"desc": "It roots through mud and leaf litter with a constant, wet snuffling, tusks catching the light when it lifts its head. Its temper is short and its charge is sudden — a flattened-ear rush with no warning beyond a single grunt. Wounded, it only gets angrier, never more cautious.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rooting through a mudbank, tusks flashing as it flips stones for grubs."}, {"n": 2, "band": "Grounded", "text": "It stands its ground at a trail crossing, snorting rather than yielding the path."}, {"n": 3, "band": "Grounded", "text": "Scarred flanks show old tusk-wounds from rival boars during rut season."}, {"n": 4, "band": "Grounded", "text": "A sounder of piglets trails a sow, who charges first and asks nothing after."}, {"n": 5, "band": "Grounded", "text": "It has wallowed a deep mud pit and defends the cool of it fiercely."}, {"n": 6, "band": "Textured", "text": "One tusk is broken to a jagged stub, making its gore wound ragged and infection-prone."}, {"n": 7, "band": "Strange", "text": "It has torn a crop field to ruin and returns nightly, undeterred by fences or fire."}, {"n": 8, "band": "Volatile", "text": "Foaming and wild-eyed, it charges anything that moves, wound or no wound driving it."}]}},
 "bog-twisted-giant-rat": {"desc": "Its fur is slicked dark with bog-water and its eyes carry a faint, wrong sheen, something the mire has soaked into it. It moves low and fast through reeds, more comfortable half-submerged than dry. The bite carries more than germs now — something of the bog rides in its saliva.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It slips through reed-cover, only its eyes and snout breaking the black water's surface."}, {"n": 2, "band": "Grounded", "text": "A cluster nests in a rotted stump, chittering when the bog's surface ripples nearby."}, {"n": 3, "band": "Grounded", "text": "Its fur has gone patchy and slick, more like an eel's hide than a rat's."}, {"n": 4, "band": "Grounded", "text": "It drags half-eaten carrion into deeper water, hoarding rather than finishing meals."}, {"n": 5, "band": "Grounded", "text": "It freezes utterly still in murk, betrayed only by the faint wrongness of its eyeshine."}, {"n": 6, "band": "Textured", "text": "Bog gas bubbles rise where it burrows, and its bite leaves a lingering peat-rot smell."}, {"n": 7, "band": "Strange", "text": "It swims in slow circles around a submerged object, guarding it without seeming to know why."}, {"n": 8, "band": "Volatile", "text": "Its twisting has gone further than most — limbs faintly too long, bite fevering wounds fast."}]}},
 "brown-bear": {"desc": "It carries its bulk with surprising quiet, shoulders rolling, claws raking bark from trees it marks as its own. A stand-up posture and a low, chest-deep roar are meant to end conflict before it starts. When it does commit, the first swipe alone can break bone.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Clawing deep gouges into a marker tree, standing tall to leave the scent as high as possible."}, {"n": 2, "band": "Grounded", "text": "A sow shepherds cubs across open ground, aggressive toward anything that lingers."}, {"n": 3, "band": "Grounded", "text": "It has claimed a salmon run and swats fish from the shallows with brutal precision."}, {"n": 4, "band": "Grounded", "text": "Old and gray-muzzled, it favors ambush over the chase its joints no longer allow."}, {"n": 5, "band": "Grounded", "text": "It has raided a cache or cellar and defends the stolen food as its own now."}, {"n": 6, "band": "Textured", "text": "A snapped trap-jaw is still fused half-shut around one forepaw, and the pain has soured it."}, {"n": 7, "band": "Strange", "text": "It rears and roars at empty air, as if fighting something no one else can see."}, {"n": 8, "band": "Volatile", "text": "Rabid-eyed and drooling, it charges without the usual bluff, past reasoning entirely."}]}},
 "camel": {"desc": "It plods across baking sand with an unbothered, rolling gait, long lashes shuttering against the glare. Spit and a bad temper are its first line of defense, delivered with theatrical disdain. It can go days without complaint, then decide, for no clear reason, that it is done being ridden.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Grazing on thorny scrub, unbothered by the heat that wilts everything nearby."}, {"n": 2, "band": "Grounded", "text": "It spits with sudden, deliberate contempt at anyone tightening its girth too fast."}, {"n": 3, "band": "Grounded", "text": "A caravan animal, laden and patient, plods on despite a limp it never complains about."}, {"n": 4, "band": "Grounded", "text": "It kneels stubbornly and will not rise again until it decides the rest is over."}, {"n": 5, "band": "Grounded", "text": "Sand-scoured and sun-bleached, its hide has gone the color of the dunes around it."}, {"n": 6, "band": "Textured", "text": "It has bonded oddly to one handler and turns foul-tempered the moment anyone else takes the reins."}, {"n": 7, "band": "Strange", "text": "It refuses a stretch of open desert outright, no matter how it's driven or coaxed."}, {"n": 8, "band": "Volatile", "text": "Something has spooked it badly — it bolts in wide, panicked circles, scattering its load."}]}},
 "cat": {"desc": "It moves in liquid silence, tail flicking the only sign it's tracking anything at all. Half-feral in most towns, it takes food where it finds it and trusts no hand fully. A sudden pounce from stillness is the only warning most vermin ever get.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Sunning on a warm ledge, one eye cracked open to track anyone passing below."}, {"n": 2, "band": "Grounded", "text": "It stalks a rat through a market stall, utterly indifferent to the shoppers around it."}, {"n": 3, "band": "Grounded", "text": "Half-feral and thin, it hisses at outstretched hands but lingers for scraps anyway."}, {"n": 4, "band": "Grounded", "text": "A ratter kept by a shopkeep, it patrols the same three aisles every dusk."}, {"n": 5, "band": "Grounded", "text": "Torn-eared from old fights, it claims a sunny windowsill as contested territory."}, {"n": 6, "band": "Textured", "text": "It has attached itself to one traveler, appearing at doorways days apart with no clear way it follows."}, {"n": 7, "band": "Strange", "text": "It watches a specific empty corner of every room it enters, refusing to turn its back on it."}, {"n": 8, "band": "Volatile", "text": "Feral past taming, it attacks hands that reach for it, scarred and half-starved and furious."}]}},
 "constrictor-snake": {"desc": "It lies coiled and nearly invisible in leaf litter until the moment it isn't, and then muscle closes around a limb faster than the eye tracks. It doesn't strike to poison — it strikes to hold, and holding is worse. Even dead, its grip can take long minutes to pry loose.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coiled in dappled shade, indistinguishable from a fallen branch until it moves."}, {"n": 2, "band": "Grounded", "text": "It has taken a small animal and is mid-constrict, patient and utterly still."}, {"n": 3, "band": "Grounded", "text": "A thick, old specimen basks near a den mouth littered with old shed skin."}, {"n": 4, "band": "Grounded", "text": "It swims a slow current, only its head breaking the surface, hunting waterside prey."}, {"n": 5, "band": "Grounded", "text": "Scarred along its length, it favors ambush from cover over any open pursuit."}, {"n": 6, "band": "Textured", "text": "It has taken to nesting inside a hollowed-out cart, startling anyone who reaches in blind."}, {"n": 7, "band": "Strange", "text": "It returns to the same exact branch every dusk, as if the spot itself matters to it."}, {"n": 8, "band": "Volatile", "text": "Enormous for its kind, it has grown bold enough to strike at torchlight itself."}]}},
 "crab": {"desc": "It sidesteps across wet stone with a dry, clicking scuttle, claws raised the instant a shadow falls across it. Mostly it wants to be left alone under its rock, pale eyes on stalks tracking movement. Cornered, the pinch is sharp enough to draw blood through a boot.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Scuttling sideways across tide pools, claws raised at the first hint of a shadow."}, {"n": 2, "band": "Grounded", "text": "It has buried into wet sand, only eye-stalks showing above the waterline."}, {"n": 3, "band": "Grounded", "text": "A cluster of them picks over a beached carcass, clicking and shoving for position."}, {"n": 4, "band": "Grounded", "text": "It defends a rock crevice den, snapping at anything that reaches too close."}, {"n": 5, "band": "Grounded", "text": "Missing one claw, regrown smaller, it favors the good side in every fight."}, {"n": 6, "band": "Textured", "text": "Its shell is crusted with barnacles thick enough to look like part of the rock itself."}, {"n": 7, "band": "Strange", "text": "Dozens migrate overland in a single night, crossing paths no one can explain."}, {"n": 8, "band": "Volatile", "text": "It has grown unusually large scavenging near a wreck, and its pinch can crack bone."}]}},
 "crocodile": {"desc": "It floats at the waterline like driftwood, only the ridge of its eyes breaking the surface. The strike, when it comes, is a violent blur followed by the death roll, dragging prey under before it can think to fight back. On land it is slow and sluggish; in water it is the whole river's authority.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Motionless at the waterline, eyes and nostrils the only part breaking the surface."}, {"n": 2, "band": "Grounded", "text": "Basking on a mudbank, jaws parted wide to cool in the sun's heat."}, {"n": 3, "band": "Grounded", "text": "It has claimed a river crossing, and locals give the ford a wide, wary berth."}, {"n": 4, "band": "Grounded", "text": "Old and scarred, missing teeth, it favors ambushing from the shallows over the chase."}, {"n": 5, "band": "Grounded", "text": "A nesting mound of rotting vegetation nearby means she's close and watching."}, {"n": 6, "band": "Textured", "text": "An old rope or chain is grown half into its hide, a broken snare from some past attempt."}, {"n": 7, "band": "Strange", "text": "It has learned to lie utterly still even when poked, waiting out impatient hunters."}, {"n": 8, "band": "Volatile", "text": "Enormous beyond its kind's usual reach, it has taken livestock right off the bank in daylight."}]}},
 "deer": {"desc": "It stands frozen at the treeline, ears swiveling, ready to bolt at the first wrong sound. Flight is its whole strategy — a burst of speed and a white flash of tail, gone before the threat registers. Only cornered, or defending young, does it turn and use the antlers or hooves at all.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Grazing at a forest edge, head snapping up at the smallest snap of a twig."}, {"n": 2, "band": "Grounded", "text": "A doe keeps a fawn hidden in tall grass, circling back only when it's safe."}, {"n": 3, "band": "Grounded", "text": "A buck spars antlers with a rival, both too absorbed to notice anyone watching."}, {"n": 4, "band": "Grounded", "text": "It picks along a game trail worn smooth by generations of the same careful crossing."}, {"n": 5, "band": "Grounded", "text": "Limping from an old injury, it startles easier and runs a shorter, more desperate distance."}, {"n": 6, "band": "Textured", "text": "A frayed rope or snare trails from one leg, the failed work of some earlier trap."}, {"n": 7, "band": "Strange", "text": "It stands its ground at an odd, specific spot in the woods, refusing to be chased off it."}, {"n": 8, "band": "Volatile", "text": "Rabid and foam-mouthed, it charges rather than flees, all its instincts turned inside out."}]}},
 "dire-wolf": {"desc": "It runs low and long-legged at the head of its pack, breath steaming, eyes fixed on whatever's been chosen to fall. The howl that opens a hunt carries for miles and means the pack is already moving. Alone it is dangerous; flanked by its kin, it is close to unstoppable.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It runs point for a pack, nose low, tracking a wounded animal's blood trail."}, {"n": 2, "band": "Grounded", "text": "An alpha holds a ridge overlook while lesser wolves flush prey below."}, {"n": 3, "band": "Grounded", "text": "Scarred deep across the muzzle, it's survived a boar's tusks and learned patience from it."}, {"n": 4, "band": "Grounded", "text": "It has denned in a rock overhang, pups' yips carrying faintly from inside."}, {"n": 5, "band": "Grounded", "text": "Lean and winter-thin, the pack has pushed its hunting range far closer to the road."}, {"n": 6, "band": "Textured", "text": "It carries a broken arrow shaft still lodged in its shoulder, and favors that side badly."}, {"n": 7, "band": "Strange", "text": "The pack has learned to split and flank in a pattern too disciplined for ordinary instinct."}, {"n": 8, "band": "Volatile", "text": "A rogue alpha, driven off its own pack, hunts alone now and twice as savage for it."}]}},
 "draft-horse": {"desc": "It leans its full weight into the harness, muscles rolling under a dark, sweat-slicked coat. Placid by breeding and habit, it startles rarely and forgives easily. Unhitched and frightened, though, its size alone becomes a genuine hazard to anyone in its path.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Leaning into a full harness load, hooves finding purchase in churned mud."}, {"n": 2, "band": "Grounded", "text": "Placid at a hitching post, tail swatting flies, entirely unbothered by passing crowds."}, {"n": 3, "band": "Grounded", "text": "An old plow-horse, gray at the muzzle, still pulls stronger than animals half its age."}, {"n": 4, "band": "Grounded", "text": "Its shoes are worn thin from a long haul road, and it favors an even, unhurried gait."}, {"n": 5, "band": "Grounded", "text": "Scarred at the shoulders from an ill-fitted collar, it flinches at anyone adjusting straps."}, {"n": 6, "band": "Textured", "text": "It's bonded to a specific driver's voice and balks badly for any stranger holding the reins."}, {"n": 7, "band": "Strange", "text": "It refuses one particular stretch of road outright, no matter the load or the whip."}, {"n": 8, "band": "Volatile", "text": "Panicked loose from its traces, it thrashes through a crowd, wagon-wreckage dragging behind it."}]}},
 "eagle": {"desc": "It rides high thermals in slow, patient circles, gold eyes resolving movement from impossible distance. The stoop, when it commits, is a controlled fall faster than anything on the ground can react to. It kills clean and fast, then mantles its wings over the kill against thieves.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Circling high on a thermal, tracking movement far below with unhurried patience."}, {"n": 2, "band": "Grounded", "text": "Perched on a crag, mantling its wings protectively over a fresh kill."}, {"n": 3, "band": "Grounded", "text": "A mated pair hunts a shared range, calling to coordinate their separate stoops."}, {"n": 4, "band": "Grounded", "text": "Its aerie, high and inaccessible, is lined with bones from a season's hunting."}, {"n": 5, "band": "Grounded", "text": "An old bird, feathers ragged at the wingtip, hunts closer to the ground than it used to."}, {"n": 6, "band": "Textured", "text": "It has taken a liking to shiny objects and its nest glints with stolen trinkets."}, {"n": 7, "band": "Strange", "text": "It shadows one particular traveler for days, never striking, only watching from height."}, {"n": 8, "band": "Volatile", "text": "Massive for its kind, it has begun stooping at targets far larger than its usual prey."}]}},
 "elephant": {"desc": "It moves with unhurried, ground-shaking weight, ears fanning against the heat, trunk testing the air constantly. Calm is its default state — herd-bonded, patient, protective of its young to a fault. Provoked, though, that same mass becomes an unstoppable, trumpeting charge.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Stripping bark from a tree with its trunk, ears fanning slow against the heat."}, {"n": 2, "band": "Grounded", "text": "A matriarch shepherds a herd toward water, trumpeting when calves lag behind."}, {"n": 3, "band": "Grounded", "text": "It bathes in a mud wallow, spraying itself and the calves nearby with practiced care."}, {"n": 4, "band": "Grounded", "text": "Old and scarred with broken tusks, it's slower now but no less protective."}, {"n": 5, "band": "Grounded", "text": "A solitary bull, driven from the herd, wanders with a foul, unpredictable temper."}, {"n": 6, "band": "Textured", "text": "Chain-galls scar both forelegs — it was worked as a beast of burden and escaped or was freed."}, {"n": 7, "band": "Strange", "text": "It returns yearly to the same clearing, standing over bones as if in vigil."}, {"n": 8, "band": "Volatile", "text": "Musth-maddened, it charges anything that moves, trumpeting rage with no herd left to calm it."}]}},
 "elk": {"desc": "It stands broad-shouldered at a clearing's edge, antlers raked back like a crown, breath fogging in the cold. Mostly it postures and bugles rather than fights, testing rivals with noise before horn. In rut, though, that same rack becomes a weapon it's entirely willing to use.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Grazing a meadow's edge, antlers raised to test the wind for danger."}, {"n": 2, "band": "Grounded", "text": "Two bulls lock antlers in a shoving match, neither willing to yield ground first."}, {"n": 3, "band": "Grounded", "text": "A cow keeps her calf close, positioning her own body between it and any stranger."}, {"n": 4, "band": "Grounded", "text": "It bugles from a ridge at dusk, the sound rolling for miles across the valley."}, {"n": 5, "band": "Grounded", "text": "An old bull, rack asymmetric from an old break, still holds his rutting ground."}, {"n": 6, "band": "Textured", "text": "Its antlers are tangled with old fence wire, dragging a rattling length behind it."}, {"n": 7, "band": "Strange", "text": "It stands motionless at the same crossroads every dawn, as if keeping some appointment."}, {"n": 8, "band": "Volatile", "text": "Rut-maddened past reason, it charges anything upright, antlers lowered without warning."}]}},
 "frog": {"desc": "It sits low and wet-skinned at the water's edge, throat pulsing in a slow, rhythmic croak. A flick of tongue takes an insect faster than the eye follows. Mostly harmless and easily startled, it vanishes with one powerful kick the instant a shadow crosses it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Croaking steadily from a lily pad, throat pulsing in the evening's cooling air."}, {"n": 2, "band": "Grounded", "text": "It snaps a tongue-strike at a passing insect faster than the eye can follow."}, {"n": 3, "band": "Grounded", "text": "A whole chorus of them sings from the reeds, falling silent all at once at a footstep."}, {"n": 4, "band": "Grounded", "text": "It sits half-submerged in mud, only eyes and nostrils breaking the surface."}, {"n": 5, "band": "Grounded", "text": "Brightly mottled, it blends almost perfectly with the mossy stone it favors."}, {"n": 6, "band": "Textured", "text": "It's taken up residence in an old boot or bucket left too long by the water."}, {"n": 7, "band": "Strange", "text": "An entire clutch of them gathers on one flat stone, motionless, facing the same direction."}, {"n": 8, "band": "Volatile", "text": "Larger than its kind should grow, it snaps at things well beyond a frog's usual prey."}]}},
 "giant-ape": {"desc": "It moves through the canopy with terrible ease, branches groaning under a weight they were never meant to bear. A chest-thump and a bellow are its opening argument; thrown stone is its closing one. Alone in high, isolated ranges, it rules by simple, overwhelming size.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It moves through the canopy, branches cracking under weight the trees weren't built for."}, {"n": 2, "band": "Grounded", "text": "Chest-thumping atop a boulder, it postures long before it ever commits to a charge."}, {"n": 3, "band": "Grounded", "text": "A solitary elder, gray-muzzled and scarred, rules a high valley uncontested."}, {"n": 4, "band": "Grounded", "text": "It has built a nest of broken branches high in a cliffside grove."}, {"n": 5, "band": "Grounded", "text": "It hoards smooth throwing-stones in a pile, testing each one's weight before a fight."}, {"n": 6, "band": "Textured", "text": "An old iron collar, rusted and cracked, still rings its neck from some past captivity."}, {"n": 7, "band": "Strange", "text": "It has stacked stones into a crude, deliberate cairn no one else has explained."}, {"n": 8, "band": "Volatile", "text": "Enraged past its normal territorial bluff, it hurls boulders the size of barrels without pause."}]}},
 "giant-badger": {"desc": "It plows through undergrowth with a low, muscular churn, claws the size of fingers gouging soft earth. Like its smaller cousin it prefers the burrow's mouth as a fighting position, backing into the dark rather than the open. Its bite alone can crack a shield's edge.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Widening a burrow mouth, throwing dirt in great, steady shovelfuls."}, {"n": 2, "band": "Grounded", "text": "It backs into its tunnel entrance at the first sign of threat, fighting only there."}, {"n": 3, "band": "Grounded", "text": "Scarred and one-eyed, it has clearly survived worse than most intruders offer."}, {"n": 4, "band": "Grounded", "text": "A pair guards a shared den, one always above ground while the other digs."}, {"n": 5, "band": "Grounded", "text": "It has raided a farm's root cellar, tunnels running straight under the floorboards."}, {"n": 6, "band": "Textured", "text": "Its burrow undermines a stretch of old road, and carts have started to sink at the spot."}, {"n": 7, "band": "Strange", "text": "It has dug into a sealed, forgotten chamber and refuses to leave what it found there."}, {"n": 8, "band": "Volatile", "text": "Massive beyond its kind's norm, it tunnels through stone foundations without slowing."}]}},
 "giant-bat": {"desc": "Its wingspan blots out torchlight for a full second before the dive, leathery and silent until the last moment. It roosts in colonies deep in cave systems, dropping into flight all at once when disturbed. The bite is meant to drain, not kill outright, and it will return to a wounded target.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hanging in a cluster from a high cave ceiling, wings folded like dark cloaks."}, {"n": 2, "band": "Grounded", "text": "It swoops low over torchlight, drawn by the moths and insects it stirs up."}, {"n": 3, "band": "Grounded", "text": "A colony roosts deep in a cavern, the floor below crusted thick with old droppings."}, {"n": 4, "band": "Grounded", "text": "Scarred wing-membrane gives its flight a lopsided, unpredictable wobble."}, {"n": 5, "band": "Grounded", "text": "It hunts alone over a lake's surface, skimming low for fish and insects both."}, {"n": 6, "band": "Textured", "text": "It keeps returning to feed on the same wounded creature, undeterred by prior attacks."}, {"n": 7, "band": "Strange", "text": "The whole colony wakes and streams out together at an hour with no clear trigger."}, {"n": 8, "band": "Volatile", "text": "An unusually large specimen has claimed the cave's deepest chamber, and lesser bats avoid it."}]}},
 "giant-boar": {"desc": "Tusks the length of forearms curve up from a jaw built to gore, and its charge shakes loose stone from cave walls. Rage only builds once it's wounded — pain seems to sharpen rather than deter it. It roots through anything in its path, ruin or root cellar alike, indifferent to the difference.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rooting through fallen timber, tusks the length of forearms flashing in the shade."}, {"n": 2, "band": "Grounded", "text": "It charges the instant it's startled, no bluff, no warning grunt beforehand."}, {"n": 3, "band": "Grounded", "text": "Scarred deep across the shoulder from some past gore-fight, it still charges hardest."}, {"n": 4, "band": "Grounded", "text": "A sounder of ordinary boars trails it, deferring to its size at every kill."}, {"n": 5, "band": "Grounded", "text": "It has torn a farmstead's fence to splinters and returns nightly for the crop beneath."}, {"n": 6, "band": "Textured", "text": "One tusk has been snapped and regrown crooked, catching on everything it gores."}, {"n": 7, "band": "Strange", "text": "It patrols the same stretch of ruin wall each night, as if guarding something buried there."}, {"n": 8, "band": "Volatile", "text": "Foam-mouthed and wounded from some earlier fight, it charges everything within reach now."}]}},
 "giant-centipede": {"desc": "It pours across stone in a segmented ripple, legs clicking faster than the eye can count. Venomed mandibles work first and think never, striking anything warm that moves too close. It favors dark and damp — cellars, cave floors, the underside of anything left too long undisturbed.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Pouring out from beneath a shifted stone, legs clicking in a fast, wet ripple."}, {"n": 2, "band": "Grounded", "text": "It clings motionless to a damp cave ceiling, waiting for warmth to pass below."}, {"n": 3, "band": "Grounded", "text": "A cluster nests in rotted logs, scattering in every direction when the wood is disturbed."}, {"n": 4, "band": "Grounded", "text": "It has taken up under a cellar floorboard, striking through gaps at passing feet."}, {"n": 5, "band": "Grounded", "text": "Missing several legs from old fights, it moves in an odd, dragging lurch."}, {"n": 6, "band": "Textured", "text": "It's nested inside a boot or pack left overnight, and finding it out is the worst part."}, {"n": 7, "band": "Strange", "text": "Dozens surge from one crack in the floor in a single coordinated wave."}, {"n": 8, "band": "Volatile", "text": "Unusually long and pale, it has grown fat on something richer than its usual prey."}]}},
 "giant-constrictor-snake": {"desc": "Its coils are thick as barrels, and the ambush comes from stillness so complete it reads as terrain. Once it wraps a target the fight is already decided, ribs creaking under pressure that never lets up. It swallows whole what smaller predators would spend hours dismembering.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coiled thick as a barrel, indistinguishable from a fallen log until it shifts."}, {"n": 2, "band": "Grounded", "text": "It has taken a large animal and is mid-constrict, utterly unhurried about it."}, {"n": 3, "band": "Grounded", "text": "A massive, old specimen basks near a den scattered with old, enormous shed skin."}, {"n": 4, "band": "Grounded", "text": "It hangs from a heavy branch, half its length coiled, waiting for prey below."}, {"n": 5, "band": "Grounded", "text": "Scarred along its length, it strikes from ambush rather than risk open pursuit."}, {"n": 6, "band": "Textured", "text": "It has taken to nesting in a flooded cellar, surfacing only when something warm passes."}, {"n": 7, "band": "Strange", "text": "It returns to the same submerged ruin each season, as if the place still means something."}, {"n": 8, "band": "Volatile", "text": "Enormous even for its kind, it has begun striking at things well larger than usual prey."}]}},
 "giant-crab": {"desc": "It clatters across tidal rock on legs like iron spokes, claws raised the instant a shadow crosses it. Territorial and thick-shelled, it treats most threats as things to be pinched into submission rather than fled from. It favors the wet dark under piers and wrecks.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Clattering across wet rock, claws raised at the first shadow that falls across it."}, {"n": 2, "band": "Grounded", "text": "It has buried into the tideline sand, only stalked eyes breaking the surface."}, {"n": 3, "band": "Grounded", "text": "A cluster works over a beached carcass, clicking and shoving each other for the best angle."}, {"n": 4, "band": "Grounded", "text": "It defends a crevice den under a pier piling, snapping at anything reaching too close."}, {"n": 5, "band": "Grounded", "text": "Missing one claw, regrown smaller and slower, it favors the good side in any fight."}, {"n": 6, "band": "Textured", "text": "Its shell is crusted thick with barnacles and old rope, nearly camouflaged as wreck debris."}, {"n": 7, "band": "Strange", "text": "Dozens migrate overland at once, crossing a stretch of coast road no one can explain."}, {"n": 8, "band": "Volatile", "text": "Grown unusually large near a shipwreck, its pinch can shear clean through rope or bone."}]}},
 "giant-crocodile": {"desc": "It lies submerged like a fallen tree the size of a longboat, patience total, eyes the only visible part. When it commits, the death roll can take a grown ox under in seconds. Rivers with one of these earn a wide reputation fast, and the locals never forget which ford to avoid.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Submerged like a fallen tree the size of a longboat, only ridged eyes visible."}, {"n": 2, "band": "Grounded", "text": "Basking massive on a mudbank, jaws parted wide enough to shelter smaller birds."}, {"n": 3, "band": "Grounded", "text": "It has claimed an entire river crossing, and the ford earns a wide local reputation."}, {"n": 4, "band": "Grounded", "text": "Ancient and scarred, missing an eye, it favors ambushing the same stretch of bank."}, {"n": 5, "band": "Grounded", "text": "A nesting mound the size of a cart nearby means she is close and dangerous."}, {"n": 6, "band": "Textured", "text": "An old harpoon shaft is grown half into its hide, broken off from some failed hunt."}, {"n": 7, "band": "Strange", "text": "It has learned to feign a floating log so perfectly that boats drift close before realizing."}, {"n": 8, "band": "Volatile", "text": "Grown to legendary size on the bones of past hunters, it has taken to hunting in daylight."}]}},
 "giant-fire-beetle": {"desc": "Two glowing glands pulse orange-red behind its head, lighting the tunnel it walks like a lantern on legs. It's mostly docile, more useful than dangerous, and miners have long since learned to keep a few nearby for the free light. Provoked, its mandibles are still sharp enough to matter.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Its gland-light pulses steady orange, marking its slow path through tunnel dark."}, {"n": 2, "band": "Grounded", "text": "Kept in a cage by miners for its glow, it's docile until the cage is opened wrong."}, {"n": 3, "band": "Grounded", "text": "A cluster of them lights an entire cave chamber in flickering amber."}, {"n": 4, "band": "Grounded", "text": "It clings to a damp wall, glow dimmed to near-nothing while it rests."}, {"n": 5, "band": "Grounded", "text": "Scarred shell shows an old escape from something that wanted its glowing glands."}, {"n": 6, "band": "Textured", "text": "Its glands have been crudely harvested before, leaving a scar that glows faint and wrong."}, {"n": 7, "band": "Strange", "text": "Its light pulses in a rhythm that seems to answer some deeper cave sound."}, {"n": 8, "band": "Volatile", "text": "Its glands burn unusually bright and hot, scorching what it bites rather than just cutting."}]}},
 "giant-frog": {"desc": "It squats motionless at the waterline, throat swelling in a slow pulse, patient as stone. The tongue-strike is sudden and total — anything person-sized within reach can vanish to the elbow before it registers as danger. It swallows what it catches whole, without hesitation.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Squatting motionless at the waterline, throat pulsing slow in the evening air."}, {"n": 2, "band": "Grounded", "text": "It snaps a tongue-strike at something person-sized, swallowing before it can react."}, {"n": 3, "band": "Grounded", "text": "A cluster calls from the reeds in a deep, chest-shaking chorus."}, {"n": 4, "band": "Grounded", "text": "It sits half-submerged in mud, camouflage near-total but for the slow blink of an eye."}, {"n": 5, "band": "Grounded", "text": "Brightly mottled and enormous, it dwarfs the pond life it usually shares the bank with."}, {"n": 6, "band": "Textured", "text": "It's swallowed something metal that clinks faintly whenever it shifts its bulk."}, {"n": 7, "band": "Strange", "text": "It gathers at one flat stone with others of its kind, motionless, facing the same direction."}, {"n": 8, "band": "Volatile", "text": "Grown far past its usual size, it has begun striking at things well larger than frogs should risk."}]}},
 "giant-goat": {"desc": "It stands sure-footed on impossible ledges, curled horns catching the wind, utterly unbothered by height. Territorial disputes are settled with a running headbutt that can crack ribs through armor. It's stubborn past reason once it's decided a path or a perch belongs to it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Standing sure-footed on a narrow ledge, chewing scrub with total unconcern for the drop."}, {"n": 2, "band": "Grounded", "text": "Two rams crash horns in a shoving match over a mountain path's right of way."}, {"n": 3, "band": "Grounded", "text": "It guards a herd of ordinary goats, charging anything that approaches too fast."}, {"n": 4, "band": "Grounded", "text": "Scarred horns show years of territorial clashes on the same rocky spur."}, {"n": 5, "band": "Grounded", "text": "It has claimed a narrow bridge or pass and simply will not yield the crossing."}, {"n": 6, "band": "Textured", "text": "A frayed lead-rope still trails from its neck, snapped free from some past owner."}, {"n": 7, "band": "Strange", "text": "It stands at the exact edge of a cliff each dawn, as if watching for something specific."}, {"n": 8, "band": "Volatile", "text": "Enraged and cornered on a ledge, it charges with a force that can send a person off the edge."}]}},
 "giant-hyena": {"desc": "It laughs low and rolling from the dark before it's even visible, jaws built to crack bone that lesser scavengers can't touch. It hunts in loose coalition, testing wounded prey before committing. Bold past most predators' caution, it will contest a kill with anything smaller than itself.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Its low laugh rolls out of the dark well before it's visible, testing for a reaction."}, {"n": 2, "band": "Grounded", "text": "A loose pack circles a wounded animal, patient, waiting for it to weaken further."}, {"n": 3, "band": "Grounded", "text": "It cracks old bones at a kill site with jaws built for exactly that purpose."}, {"n": 4, "band": "Grounded", "text": "Scarred and mangy, it's survived worse fights than most predators its size."}, {"n": 5, "band": "Grounded", "text": "It contests a lion's kill boldly, backing off only when truly outnumbered."}, {"n": 6, "band": "Textured", "text": "It has learned to raid graves for carrion, and the local dead don't rest as deep for it."}, {"n": 7, "band": "Strange", "text": "Its laugh changes pitch in a way that seems to signal the rest of an unseen pack."}, {"n": 8, "band": "Volatile", "text": "Grown massive and bold past its kind's norm, it hunts in open daylight without fear."}]}},
 "giant-lizard": {"desc": "It clings flat to stone or bark, throat pulsing, utterly still until the moment it isn't. Its climb is effortless on nearly any surface, and its bite locks on with a stubborn, jaw-clenching persistence. Mostly it wants sun and shadow in equal measure, and prey it can ambush without a chase.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Clinging flat to sun-warmed stone, throat pulsing in slow, patient rhythm."}, {"n": 2, "band": "Grounded", "text": "It scales a sheer wall effortlessly, vanishing over the top before anyone reacts."}, {"n": 3, "band": "Grounded", "text": "A cluster basks together on a boulder, scattering in every direction if startled."}, {"n": 4, "band": "Grounded", "text": "It clings to a cave ceiling, dropping onto prey that passes underneath unaware."}, {"n": 5, "band": "Grounded", "text": "Scarred and missing part of its tail, it's clearly survived a predator's near-miss."}, {"n": 6, "band": "Textured", "text": "Its tail has regrown wrong, stubbier and darker, marking it from others of its kind."}, {"n": 7, "band": "Strange", "text": "It clings motionless to the same wall stone each day, as if guarding the spot."}, {"n": 8, "band": "Volatile", "text": "Grown far past normal size, it drops on prey from heights that should be impossible."}]}},
 "giant-octopus": {"desc": "Color ripples across its skin faster than thought, mimicking rock and shadow until the tentacles unfurl. It hunts by ambush and strangulation, wrapping prey in a grip that tightens with every struggle. Intelligence flickers behind those slitted eyes — this is not a mindless thing that's caught you.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Color rippling to match the rock around it, betrayed only by a slow, deliberate blink."}, {"n": 2, "band": "Grounded", "text": "It has wrapped a large fish in tentacles, tightening its grip with patient inevitability."}, {"n": 3, "band": "Grounded", "text": "A den entrance nearby is littered with old shells, evidence of a long residence."}, {"n": 4, "band": "Grounded", "text": "It jets backward in a burst of ink the instant it's truly threatened."}, {"n": 5, "band": "Grounded", "text": "Scarred along one arm, regrown shorter, it favors the others in any grapple."}, {"n": 6, "band": "Textured", "text": "It has taken to hoarding shiny debris from wrecks near its den entrance."}, {"n": 7, "band": "Strange", "text": "It watches divers with unsettling focus, as if genuinely assessing rather than fleeing."}, {"n": 8, "band": "Volatile", "text": "Massive beyond its kind's usual range, it has begun pulling small boats off course."}]}},
 "giant-rat": {"desc": "It moves in a scuttling, confident pack, whiskers twitching at every new smell of rot or food. Alone it's a nuisance; in numbers, cornered prey learns fast how coordinated the swarm can be. Sewers, cellars, and ships are its favored roads, and it knows every crack in the wall.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "A pack scuttles along a sewer ledge, whiskers twitching at the scent of rot ahead."}, {"n": 2, "band": "Grounded", "text": "It gnaws steadily through a grain sack, undeterred by the noise it's making."}, {"n": 3, "band": "Grounded", "text": "A nest of them squeaks from behind a wall, scattering the instant light hits them."}, {"n": 4, "band": "Grounded", "text": "Bold from lack of predators, it stands its ground rather than flee a lantern."}, {"n": 5, "band": "Grounded", "text": "Scarred and missing an ear, it leads a pack twice the usual size."}, {"n": 6, "band": "Textured", "text": "It's chewed through a strongbox's leather straps, dragging coin pouches into the dark."}, {"n": 7, "band": "Strange", "text": "The whole pack moves in a single, coordinated ripple, as if answering one will."}, {"n": 8, "band": "Volatile", "text": "Grown unnaturally large on cursed refuse, its bite carries a lingering, fevered rot."}]}},
 "giant-scorpion": {"desc": "It skitters low across baked stone, claws raised wide, tail curled and trembling with venom. Heat and dark are its preferred hours, and it strikes fast from cover rather than chase anything into the open. The sting alone can drop something twice its size before the claws even finish their work.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Skittering low across baked stone, claws raised wide, tail curled and trembling."}, {"n": 2, "band": "Grounded", "text": "It has burrowed under a flat rock, only the tail-tip visible in the shade."}, {"n": 3, "band": "Grounded", "text": "A mother carries pale young clustered thick across her back."}, {"n": 4, "band": "Grounded", "text": "Scarred claw missing a pincer, it favors the sting far more heavily now."}, {"n": 5, "band": "Grounded", "text": "It has claimed a shaded crevice as a den, defending it against smaller scorpions."}, {"n": 6, "band": "Textured", "text": "Old dried venom crusts its stinger a strange black, thicker and darker than usual."}, {"n": 7, "band": "Strange", "text": "It emerges only at an exact hour each night, retreating before dawn without fail."}, {"n": 8, "band": "Volatile", "text": "Grown massive on richer prey than its kind usually finds, its sting drops targets fast."}]}},
 "giant-seahorse": {"desc": "It drifts upright through kelp forest with an odd, dignified grace, tail curled tight around a stalk of coral. Mostly gentle and curious, it rams only when truly cornered, using its bony head like a blunt lance. Mounted or wild, it moves through open water with the same unhurried patience.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Drifting upright through kelp, tail curled tight around a stalk for anchor."}, {"n": 2, "band": "Grounded", "text": "It rams a smaller predator away from a den mouth, then resumes its slow grazing."}, {"n": 3, "band": "Grounded", "text": "Bred and bridled, it carries a rider through open water with placid patience."}, {"n": 4, "band": "Grounded", "text": "A cluster of them anchors to the same coral head, swaying together in the current."}, {"n": 5, "band": "Grounded", "text": "Scarred along its snout, it's clearly rammed something far larger and survived."}, {"n": 6, "band": "Textured", "text": "A trailing length of old netting is snagged around its tail, dragged wherever it goes."}, {"n": 7, "band": "Strange", "text": "It circles the same sunken structure daily, as if the wreck still holds meaning for it."}, {"n": 8, "band": "Volatile", "text": "Enormous for its kind, it rams boats out of simple territorial aggression now."}]}},
 "giant-shark": {"desc": "Its shadow alone can eclipse a fishing boat, a gray shape rising from depths too dark to see bottom. It circles once, testing, before the strike comes in a single, boat-rocking surge. Fishing towns keep a name for it, half legend and half warning, and steer wide of its usual water.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Its shadow eclipses a fishing boat's hull, circling once before vanishing into deeper water."}, {"n": 2, "band": "Grounded", "text": "It surfaces to strip a whale carcass, drawing lesser sharks that keep a wary distance."}, {"n": 3, "band": "Grounded", "text": "Scarred deeply along one flank, it's clearly survived a fight with something its own size."}, {"n": 4, "band": "Grounded", "text": "It patrols a specific reef channel, and local fishers have long since learned to avoid it."}, {"n": 5, "band": "Grounded", "text": "It circles a sinking wreck, drawn by the noise and blood of the disaster."}, {"n": 6, "band": "Textured", "text": "An old harpoon is buried deep in its flank, healed over but visibly festering."}, {"n": 7, "band": "Strange", "text": "Fishing towns keep its name in old songs, half legend, half genuine warning."}, {"n": 8, "band": "Volatile", "text": "Grown to a size past any recorded specimen, it hunts boats now, not just fish."}]}},
 "giant-spider": {"desc": "It hangs motionless in a web strung wide across a passage, legs folded, patient beyond anything warm-blooded. Silk lashes out faster than a blade before the venom does its slower work. Egg sacs and old cocoons mark its territory in equal, unsettling measure — a lair built entirely out of the dead.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's spun a fresh web across a doorway, and a courier's satchel is caught mid-strand, contents still inside."}, {"n": 2, "band": "Grounded", "text": "A half-eaten pack animal hangs cocooned nearby — someone's cargo train didn't make it through."}, {"n": 3, "band": "Grounded", "text": "It guards a silk-wrapped shape that twitches faintly — something still alive, and still theirs to save."}, {"n": 4, "band": "Grounded", "text": "Fresh boot-prints end abruptly at its web line; whoever left them is somewhere close and quiet."}, {"n": 5, "band": "Grounded", "text": "A trapper's snare lies broken nearby, the trapper's own tools now part of the spider's larder."}, {"n": 6, "band": "Textured", "text": "It's dragged a locked strongbox into its web, testing whether the metal is edible before anything else."}, {"n": 7, "band": "Strange", "text": "A cluster of its kind has strung silk between two buildings, and the street below has quietly gone unused."}, {"n": 8, "band": "Volatile", "text": "Its latest kill wore a signet ring — someone important is now overdue, and no one's noticed yet."}]}},
 "giant-squid": {"desc": "It rises from black depths in a slow unfurling of arm and mantle, eyes the size of platters fixed and unblinking. Ink clouds the water an instant before the grab, tentacles finding purchase on hull or limb alike. Sailors who've seen one rarely agree on its size, only that it was enough.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rising from black depths in a slow unfurl of arm and mantle, eyes fixed and unblinking."}, {"n": 2, "band": "Grounded", "text": "It clouds the water with ink an instant before its tentacles find purchase on prey."}, {"n": 3, "band": "Grounded", "text": "Scarred with sucker-marks from some past fight far below, it favors the depths now."}, {"n": 4, "band": "Grounded", "text": "It has claimed a deep trench as territory, rising only to feed."}, {"n": 5, "band": "Grounded", "text": "A missing arm, regrown shorter, gives its grip an odd asymmetry."}, {"n": 6, "band": "Textured", "text": "Old rope and net cling to its arms, remnants of some past struggle it won."}, {"n": 7, "band": "Strange", "text": "Sailors describe it in wildly different sizes, no two accounts agreeing on the truth."}, {"n": 8, "band": "Volatile", "text": "Massive beyond any recorded specimen, it has begun pulling ships fully under."}]}},
 "giant-toad": {"desc": "It squats bloated and warty at the swamp's edge, throat working in a slow, wet pulse. The tongue is a whip-crack, and what it catches, it swallows entirely without chewing. Its skin secretes something that stings on contact, a passive defense it never bothers to aim.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Squatting bloated at the swamp's edge, throat pulsing slow in the humid air."}, {"n": 2, "band": "Grounded", "text": "It whip-cracks its tongue at something small, swallowing it whole without pause."}, {"n": 3, "band": "Grounded", "text": "A cluster of them croaks from the mud, falling silent all at once at a footstep."}, {"n": 4, "band": "Grounded", "text": "Its warty hide oozes a faint sting on contact, a passive defense it never aims."}, {"n": 5, "band": "Grounded", "text": "It sits half-submerged, camouflage near total against the swamp's mottled surface."}, {"n": 6, "band": "Textured", "text": "It's swallowed something that still jangles or clinks faintly inside its bloated gut."}, {"n": 7, "band": "Strange", "text": "Dozens gather on the same rotted log each dusk, motionless, facing one direction."}, {"n": 8, "band": "Volatile", "text": "Grown massive past its kind's usual size, it strikes at prey well beyond a toad's normal reach."}]}},
 "giant-venomous-snake": {"desc": "It coils thick in shadow, rattling warning before it strikes, fangs long enough to punch through leather. The venom works fast and doesn't discriminate between predator and curious child. It favors water's edge and warm stone in equal measure, patient until something warm-blooded errs too close.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coiled thick in shadow, rattling once as fair warning before it commits to a strike."}, {"n": 2, "band": "Grounded", "text": "It basks on warm stone near a water's edge, sluggish until truly disturbed."}, {"n": 3, "band": "Grounded", "text": "Scarred along its length from some past predator's near-miss, it's grown wary."}, {"n": 4, "band": "Grounded", "text": "It has claimed a den beneath a fallen log, old shed skin littering the entrance."}, {"n": 5, "band": "Grounded", "text": "It swims slow across still water, only its head breaking the surface."}, {"n": 6, "band": "Textured", "text": "Its fangs are unusually long, and its bite punches clean through boot leather."}, {"n": 7, "band": "Strange", "text": "It returns to the same exact stone each dusk, sunning in a fixed, ritual pattern."}, {"n": 8, "band": "Volatile", "text": "Enormous for its kind, its venom works faster than any local healer's antidote."}]}},
 "giant-wasp": {"desc": "It hovers with a low, mechanical drone, stinger curved and glistening, wings a blur of aggression. It doesn't need to land to attack — the flyby sting is its whole strategy, in and out before retaliation lands. Nests are built high and defended by the whole swarm at once.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hovering with a low, mechanical drone, stinger curved and glistening in the light."}, {"n": 2, "band": "Grounded", "text": "It darts in for a flyby sting, gone again before retaliation can land."}, {"n": 3, "band": "Grounded", "text": "A nest, papery and gray, hangs high in a tree, guarded by a constant, patrolling few."}, {"n": 4, "band": "Grounded", "text": "It has claimed a carcass, dragging bits of it back toward the nest in pieces."}, {"n": 5, "band": "Grounded", "text": "Scarred wing gives its flight an erratic, unpredictable buzzing wobble."}, {"n": 6, "band": "Textured", "text": "It's built a nest inside an abandoned wagon, and the wheels rattle when it swarms."}, {"n": 7, "band": "Strange", "text": "A whole swarm rises together at the same hour daily, as if summoned by the light."}, {"n": 8, "band": "Volatile", "text": "Grown unnaturally large, its sting delivers venom potent enough to blister on contact."}]}},
 "giant-weasel": {"desc": "It moves in a low, sinuous rush, body built entirely for squeezing through gaps too narrow for anything else its size. Bloodlust seems to override caution once it's caught scent of something wounded. It kills fast and often more than it can eat, driven by instinct rather than hunger.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Slipping through a gap far too narrow for anything its apparent size."}, {"n": 2, "band": "Grounded", "text": "It's killed more than it can eat, carcasses scattered well past any hunger's need."}, {"n": 3, "band": "Grounded", "text": "Scarred and lean, it's clearly survived worse predators than most it hunts now."}, {"n": 4, "band": "Grounded", "text": "It has denned in a hollow log, dragging kills back in a steady, grim procession."}, {"n": 5, "band": "Grounded", "text": "It hunts low along a riverbank, quick and near-invisible in the reeds."}, {"n": 6, "band": "Textured", "text": "It's developed a taste for hen houses, and farms nearby have lost stock to it repeatedly."}, {"n": 7, "band": "Strange", "text": "It follows the same exact trail every night, hunting nothing, as if pacing a fence line."}, {"n": 8, "band": "Volatile", "text": "Blood-mad past its kind's usual restraint, it kills well beyond any need to eat."}]}},
 "giant-wolf-spider": {"desc": "It doesn't wait in a web — it hunts on foot, low and fast across open ground, eyes catching torchlight in a dull, multiple shine. Speed is its whole advantage, closing distance before prey can react. It favors burrows and leaf litter over silk, an ambush predator built for the chase instead.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Its multiple eyes catch torchlight in a dull, unsettling shine from the leaf litter."}, {"n": 2, "band": "Grounded", "text": "It bursts from cover in a fast, low sprint, closing distance before prey can react."}, {"n": 3, "band": "Grounded", "text": "A burrow entrance, silk-lined but web-free, marks its ambush point in soft ground."}, {"n": 4, "band": "Grounded", "text": "Scarred and missing a leg, it still moves with unnerving, uneven speed."}, {"n": 5, "band": "Grounded", "text": "It hunts alone across open ground, favoring the chase over any patient web."}, {"n": 6, "band": "Textured", "text": "It's dragged prey into a burrow too narrow for anyone to follow and retrieve it."}, {"n": 7, "band": "Strange", "text": "Several converge on the same clearing nightly, hunting in an unnervingly coordinated sprint."}, {"n": 8, "band": "Volatile", "text": "Grown unusually large and fast, it closes distance faster than most prey can process."}]}},
 "goat": {"desc": "It picks along impossible slopes with total confidence, cropping scrub between headbutts at rivals. Mostly indifferent to people, it startles into a stubborn stillness rather than flight. Herded or wild, its horn makes even a small argument painful to lose.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Picking along a rocky slope, cropping thorny scrub with total sure-footed confidence."}, {"n": 2, "band": "Grounded", "text": "Two kids butt heads in play nearby while an adult grazes, indifferent."}, {"n": 3, "band": "Grounded", "text": "A herded flock trails a shepherd, bells clanking dully at each step."}, {"n": 4, "band": "Grounded", "text": "It stands stubbornly at a fence line, refusing to move for anything short of force."}, {"n": 5, "band": "Grounded", "text": "Scarred horns show old disputes over the same patch of high grazing."}, {"n": 6, "band": "Textured", "text": "A frayed lead-rope trails from its neck, snapped loose from some past owner."}, {"n": 7, "band": "Strange", "text": "It climbs to the same high ledge daily, staring out over the same fixed view."}, {"n": 8, "band": "Volatile", "text": "Cornered and furious, it charges with a headbutt hard enough to crack ribs."}]}},
 "hawk": {"desc": "It hangs on a wingtip in stillness before folding into a stoop, talons out, a controlled fall faster than the eye tracks. Small game and carrion both draw it down from height. Trained to a glove or wild on a crag, it watches everything with the same flat, patient focus.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Circling on a wingtip, scanning open ground for the smallest telltale movement."}, {"n": 2, "band": "Grounded", "text": "It stoops on a rodent from height, talons closing before the prey even registers it."}, {"n": 3, "band": "Grounded", "text": "Perched on a fence post, it watches with a flat, patient, unblinking focus."}, {"n": 4, "band": "Grounded", "text": "A trained bird, jessed and hooded, waits calm on a falconer's glove."}, {"n": 5, "band": "Grounded", "text": "An old bird, feathers ragged, hunts closer to the ground than it used to."}, {"n": 6, "band": "Textured", "text": "A frayed jess still trails from one leg, escaped from some falconer's grip."}, {"n": 7, "band": "Strange", "text": "It circles the same field every dawn, never landing, never quite hunting either."}, {"n": 8, "band": "Volatile", "text": "Larger and bolder than its kind, it stoops at targets well beyond its usual prey."}]}},
 "hippopotamus": {"desc": "It wallows half-submerged, eyes and ears breaking the surface in a lazy line, deceptively still. On land it moves faster than its bulk suggests, and territorial aggression makes it one of the most dangerous things in slow, muddy water. Its yawn is a warning most learn to heed only once.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wallowing half-submerged, only eyes and ears breaking the murky surface."}, {"n": 2, "band": "Grounded", "text": "It yawns wide, a territorial display meant to be a first and final warning."}, {"n": 3, "band": "Grounded", "text": "A pod holds a river bend, and boats give the stretch a wide, wary berth."}, {"n": 4, "band": "Grounded", "text": "Scarred deeply from bull fights over territory, it still holds its stretch of river."}, {"n": 5, "band": "Grounded", "text": "It grazes on the bank at dusk, surprisingly fast when startled back to water."}, {"n": 6, "band": "Textured", "text": "An old harpoon scar mars one flank, souvenir of hunters who didn't finish the job."}, {"n": 7, "band": "Strange", "text": "It surfaces at the exact same spot each evening, as if keeping some fixed vigil."}, {"n": 8, "band": "Volatile", "text": "Territorial past reason, it charges boats on sight, capsizing them without hesitation."}]}},
 "hunter-shark": {"desc": "It cuts fast, low circles beneath the surface, drawn hard by blood and thrashing motion. Unlike lazier reef sharks, it commits early and hits hard, a single-minded pursuit predator. Swimmers who've felt that first bump rarely mistake it for anything gentler.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Cutting fast, low circles beneath the surface, drawn hard by distant thrashing."}, {"n": 2, "band": "Grounded", "text": "It bumps a swimmer once, testing, before committing to the full strike."}, {"n": 3, "band": "Grounded", "text": "Scarred along one flank, it's clearly survived a fight with something its equal."}, {"n": 4, "band": "Grounded", "text": "It patrols a specific stretch of open water, aggressive toward any splash."}, {"n": 5, "band": "Grounded", "text": "Drawn by chum or wreckage, it circles a sinking vessel with single-minded focus."}, {"n": 6, "band": "Textured", "text": "An old hook is lodged in its jaw, healed crooked, making its bite oddly ragged."}, {"n": 7, "band": "Strange", "text": "It's learned the sound of a specific ship's bell means food, and comes running for it."}, {"n": 8, "band": "Volatile", "text": "Blood-frenzied and reckless, it strikes repeatedly without the usual testing bump first."}]}},
 "hyena": {"desc": "It slinks at the edge of firelight, laughing low and broken, testing nerve before it tests teeth. Scavenger first, hunter second, it prefers wounded or weak targets and numbers over solo risk. Bold enough to raid a camp's edge if the fire's burned low enough.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Slinking at the edge of firelight, laughing low and testing whether anyone's watching."}, {"n": 2, "band": "Grounded", "text": "A loose pack trails a wounded animal, patient, waiting for it to weaken."}, {"n": 3, "band": "Grounded", "text": "It scavenges a lion's leftovers, darting in and out between warning snarls."}, {"n": 4, "band": "Grounded", "text": "Mangy and scarred, it's bold enough to raid a low-burning camp's edge."}, {"n": 5, "band": "Grounded", "text": "A den nearby yips faintly, pups kept close while adults range for scraps."}, {"n": 6, "band": "Textured", "text": "It's learned that unattended graves mean an easy meal, and locals know it."}, {"n": 7, "band": "Strange", "text": "Its laugh changes pitch oddly at dusk, as if signaling something beyond its pack."}, {"n": 8, "band": "Volatile", "text": "Starving and bold past its usual caution, it stalks people directly now, not just camps."}]}},
 "jackal": {"desc": "It trots at the edge of vision, low and quick, always ready to bolt rather than commit. Packs of them harass larger, wounded prey, worrying at it in relays until it falls. Alone it's a coward; in numbers it's an efficient, patient nuisance.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Trotting at the edge of vision, low and quick, ready to bolt at the first challenge."}, {"n": 2, "band": "Grounded", "text": "A pack harasses a wounded animal in relays, worrying it without committing fully."}, {"n": 3, "band": "Grounded", "text": "It scavenges carrion boldly, darting off the instant anything larger approaches."}, {"n": 4, "band": "Grounded", "text": "A den of pups yips from a shallow burrow while adults range nearby."}, {"n": 5, "band": "Grounded", "text": "Scarred and thin, it hunts alone, less bold without the rest of its pack."}, {"n": 6, "band": "Textured", "text": "It's learned that campfires mean scraps, and it circles just outside the light nightly."}, {"n": 7, "band": "Strange", "text": "The pack howls in a coordinated pattern that seems to relay a signal, not just noise."}, {"n": 8, "band": "Volatile", "text": "Starving and bold past reason, an entire pack presses in without its usual caution."}]}},
 "killer-whale": {"desc": "Black and white cuts through open water in a fast, coordinated rush, breaching once before the strike. It hunts in family pods, herding prey with terrifying discipline before closing in together. Intelligence shows in the coordination — this isn't blind instinct, it's a plan.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Cutting fast through open water, dorsal fin slicing the surface in a straight, purposeful line."}, {"n": 2, "band": "Grounded", "text": "A pod herds a school of fish into a tight ball before closing in together."}, {"n": 3, "band": "Grounded", "text": "It breaches once, fully clear of the water, before the pod resumes its coordinated hunt."}, {"n": 4, "band": "Grounded", "text": "Scarred along its dorsal fin, it's clearly survived a fight with something formidable."}, {"n": 5, "band": "Grounded", "text": "A calf trails close to its mother, the pod slowing its pace to accommodate it."}, {"n": 6, "band": "Textured", "text": "It's learned that fishing boats mean an easy meal, and it trails their nets boldly now."}, {"n": 7, "band": "Strange", "text": "The pod coordinates in patterns too deliberate for simple instinct, almost like tactics."}, {"n": 8, "band": "Volatile", "text": "A rogue, driven from its pod, hunts alone and strikes at boats with unusual aggression."}]}},
 "lion": {"desc": "It watches from tall grass with total stillness, mane or not, muscle coiled under a lazy-looking crouch. The pride hunts together, patient and coordinated, driving prey toward waiting ambush. A roar carries for miles and means exactly what it sounds like it means.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Watching from tall grass, utterly still, muscle coiled beneath a deceptively lazy crouch."}, {"n": 2, "band": "Grounded", "text": "A pride hunts in coordination, driving prey toward others waiting in ambush."}, {"n": 3, "band": "Grounded", "text": "It roars from a rise at dusk, the sound rolling out across miles of open plain."}, {"n": 4, "band": "Grounded", "text": "Scarred deeply across the face, it's clearly survived a fight for control of the pride."}, {"n": 5, "band": "Grounded", "text": "A lone male, driven from his pride, hunts alone with a hungrier edge."}, {"n": 6, "band": "Textured", "text": "It's developed a taste for livestock, and herders nearby keep a nervous watch now."}, {"n": 7, "band": "Strange", "text": "The pride has claimed ruins as a den, sunning atop broken stonework like a throne."}, {"n": 8, "band": "Volatile", "text": "Old and cast out, starving and desperate, it hunts people now with nothing left to lose."}]}},
 "lizard": {"desc": "It clings to warm stone in perfect stillness, throat pulsing, gone in a blink of motion if startled. Mostly harmless and easy to overlook, it darts along walls and rafters hunting insects. Its only real trick is disappearing exactly when you look away.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Clinging to sun-warmed stone, throat pulsing, gone in a blink if startled."}, {"n": 2, "band": "Grounded", "text": "It darts along a rafter, snapping up insects drawn to a nearby lantern."}, {"n": 3, "band": "Grounded", "text": "A cluster basks together on a low wall, scattering at the faintest vibration."}, {"n": 4, "band": "Grounded", "text": "It sheds a length of its tail, wriggling free, when a hand closes too near it."}, {"n": 5, "band": "Grounded", "text": "Brightly colored, it blends almost perfectly with the mossy stone it favors."}, {"n": 6, "band": "Textured", "text": "It's nested in a wall crack behind a shelf, and things left there go missing regularly."}, {"n": 7, "band": "Strange", "text": "Several gather on the same warm stone daily, motionless, facing the same direction."}, {"n": 8, "band": "Volatile", "text": "Unusually large and bold, it snaps at fingers rather than fleeing the reach for it."}]}},
 "mammoth": {"desc": "It moves with the unhurried gravity of a small hill walking, tusks curved and yellowed with age, breath a visible cloud in the cold. Herd-bonded and protective, it tolerates much before it charges — but the charge, when it comes, flattens whatever's in the way. Its footprints alone can fill with standing water.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Stripping frozen bark with curved tusks, breath fogging thick in the cold air."}, {"n": 2, "band": "Grounded", "text": "A matriarch leads a small herd across open tundra, calves kept tight to the center."}, {"n": 3, "band": "Grounded", "text": "It has worn a deep trail through snow, the same migration path used for generations."}, {"n": 4, "band": "Grounded", "text": "Ancient and slow, its tusks have grown so long they nearly cross at the tips."}, {"n": 5, "band": "Grounded", "text": "A lone bull, driven off, wanders with a foul temper and no herd to calm it."}, {"n": 6, "band": "Textured", "text": "Old chain-scars mark its legs — it has been worked before, and remembers."}, {"n": 7, "band": "Strange", "text": "It returns yearly to the same frozen clearing, standing over something buried beneath the ice."}, {"n": 8, "band": "Volatile", "text": "Enraged and unpredictable, it charges anything that moves, flattening ground as it goes."}]}},
 "mastiff": {"desc": "It holds a stance low and broad-chested, a growl building before the bark ever arrives. Loyal past reason to whoever it's bonded to, and utterly without mercy to whoever it's set against. Trained or feral, its bite is built for holding on, not letting go.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Standing low and broad-chested at a gate, growl building before any bark arrives."}, {"n": 2, "band": "Grounded", "text": "Trained to a handler's whistle, it holds position with rigid, disciplined focus."}, {"n": 3, "band": "Grounded", "text": "Scarred across the muzzle, it's clearly weathered worse fights than most it faces now."}, {"n": 4, "band": "Grounded", "text": "A feral pack of them has claimed an abandoned yard as territory."}, {"n": 5, "band": "Grounded", "text": "It guards a specific door with total, unwavering focus, ignoring all else."}, {"n": 6, "band": "Textured", "text": "A broken chain still drags from its collar, snapped free from wherever it was kept."}, {"n": 7, "band": "Strange", "text": "It refuses to enter one particular room, hackles raised, no matter how it's commanded."}, {"n": 8, "band": "Volatile", "text": "Starved and abused past patience, it attacks without the usual warning growl at all."}]}},
 "mule": {"desc": "It plods with a stubborn, unhurried patience, ears swiveling at every sound before it decides whether to care. Sure-footed on ground horses refuse, it carries loads without complaint until, suddenly, it decides it won't move another step. That decision is nearly impossible to argue with.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Plodding a narrow mountain trail, sure-footed where horses would refuse the ledge."}, {"n": 2, "band": "Grounded", "text": "It stops dead mid-load, refusing another step until it decides the rest is over."}, {"n": 3, "band": "Grounded", "text": "An old pack animal, scarred at the girth, still carries more than its share without complaint."}, {"n": 4, "band": "Grounded", "text": "Bonded to one specific handler, it balks hard for anyone else on the lead."}, {"n": 5, "band": "Grounded", "text": "It kicks with sudden, precise force at anything that startles it from behind."}, {"n": 6, "band": "Textured", "text": "Its packs are worn smooth with years of the exact same trade route."}, {"n": 7, "band": "Strange", "text": "It refuses one specific bridge outright, no matter the load, the whip, or the coaxing."}, {"n": 8, "band": "Volatile", "text": "Panicked and loose, it bucks its load across the road, blocking the way entirely."}]}},
 "octopus": {"desc": "It flows through a crevice too small to seem possible, skin shifting color to vanish against rock. Curious more than aggressive, it investigates with a tentacle before deciding whether to flee or grab. Cornered, the grip is stronger than its size suggests, and the ink cloud buys just enough time to vanish.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Flowing through a crevice too narrow to seem possible, color shifting to match the rock."}, {"n": 2, "band": "Grounded", "text": "It extends a curious tentacle toward a diver, testing before deciding whether to flee."}, {"n": 3, "band": "Grounded", "text": "A den entrance nearby is littered with small shells, evidence of a patient hunter."}, {"n": 4, "band": "Grounded", "text": "It jets a small cloud of ink and vanishes the instant it's truly startled."}, {"n": 5, "band": "Grounded", "text": "Scarred along one arm, regrown shorter, it favors the others when it grips."}, {"n": 6, "band": "Textured", "text": "It's taken to hoarding small shiny trinkets just outside its den entrance."}, {"n": 7, "band": "Strange", "text": "It watches with unsettling, deliberate focus, seeming to study rather than merely react."}, {"n": 8, "band": "Volatile", "text": "Unusually bold, it grabs at passing hands rather than fleeing the reach for it."}]}},
 "owl": {"desc": "It glides on silent wings through the dark, head swiveling with an unsettling, total range of motion. The strike comes without a single warning sound, talons finding prey that never heard it coming. By day it's a still, feathered shape easy to mistake for part of the tree.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Gliding on silent wings through the dark, head swiveling in a slow, total arc."}, {"n": 2, "band": "Grounded", "text": "It strikes without a single warning sound, talons finding prey that never heard it."}, {"n": 3, "band": "Grounded", "text": "Perched motionless by day, it's easy to mistake for a knot in the tree bark."}, {"n": 4, "band": "Grounded", "text": "A nest hollow nearby holds pellets of undigested fur and bone, sorted in neat piles."}, {"n": 5, "band": "Grounded", "text": "Its call carries an oddly human cadence, unsettling those who hear it at night."}, {"n": 6, "band": "Textured", "text": "It's taken to roosting near a specific window, watching whoever passes inside."}, {"n": 7, "band": "Strange", "text": "It follows a traveler for miles in total silence, never once striking or calling out."}, {"n": 8, "band": "Volatile", "text": "Larger and bolder than its kind, it stoops at targets well beyond its usual prey."}]}},
 "panther": {"desc": "It moves through undergrowth without a sound, black coat swallowing what little light reaches the forest floor. Ambush is its only strategy — it never chases what it can't catch in the first three strides. Trees are as much its territory as ground, and it strikes from either with equal ease.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Moving through undergrowth without a sound, dark coat swallowing the failing light."}, {"n": 2, "band": "Grounded", "text": "It drapes along a branch, patient, waiting for prey to pass directly beneath."}, {"n": 3, "band": "Grounded", "text": "Scarred along one shoulder, it's clearly survived a fight it shouldn't have won."}, {"n": 4, "band": "Grounded", "text": "It has claimed a stretch of forest, marking trees with deep claw gouges."}, {"n": 5, "band": "Grounded", "text": "A mother keeps cubs hidden in dense brush while she hunts close by."}, {"n": 6, "band": "Textured", "text": "It's developed a taste for livestock near a settlement, and the losses are mounting."}, {"n": 7, "band": "Strange", "text": "It's been glimpsed near the same ruin repeatedly, never straying far from the stones."}, {"n": 8, "band": "Volatile", "text": "Bold past its kind's usual caution, it stalks people directly, unafraid of torches or noise."}]}},
 "piranha": {"desc": "It schools in flickering silver clouds beneath calm water, jaws snapping at anything that bleeds. Alone it's nothing; in numbers, thrashing water turns red in seconds. It strips a carcass with brutal, cooperative efficiency and moves on before the blood even settles.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Schooling in a flickering silver cloud beneath otherwise calm, deceptive water."}, {"n": 2, "band": "Grounded", "text": "It strips a fallen carcass with brutal efficiency, water churning red within moments."}, {"n": 3, "band": "Grounded", "text": "A lone straggler darts at a wound already bleeding, drawing the rest of the school."}, {"n": 4, "band": "Grounded", "text": "The school scatters instantly at any larger predator's approach, regrouping downstream."}, {"n": 5, "band": "Grounded", "text": "It favors a specific bend of river where the current concentrates its prey."}, {"n": 6, "band": "Textured", "text": "The school has learned that splashing means food, drawn now to any struggle at all."}, {"n": 7, "band": "Strange", "text": "It gathers thick near a submerged structure, as if drawn there beyond mere feeding."}, {"n": 8, "band": "Volatile", "text": "An unusually large school strips flesh from bone in seconds, far faster than normal."}]}},
 "plesiosaurus": {"desc": "Its long neck breaks the surface in a slow, sinuous arc before the head plunges again, hunting fish in the deep. Locals mistake the ripple of its passing for a trick of current or light. It's shy of shallow water, preferring the cold dark where nothing else competes for its size.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Its long neck breaks the surface in a slow arc before plunging again after fish."}, {"n": 2, "band": "Grounded", "text": "Locals mistake its passing ripple for a trick of current, never quite believing what they saw."}, {"n": 3, "band": "Grounded", "text": "It surfaces briefly near a fishing boat, curious rather than aggressive, then submerges."}, {"n": 4, "band": "Grounded", "text": "Scarred along its neck, it's clearly survived a fight in the deep dark below."}, {"n": 5, "band": "Grounded", "text": "It favors the cold depths of one specific lake or bay, rarely straying elsewhere."}, {"n": 6, "band": "Textured", "text": "An old harpoon shaft trails from its flank, broken off by some failed hunt."}, {"n": 7, "band": "Strange", "text": "Old sailors keep a name for it, half legend, told only after enough drink."}, {"n": 8, "band": "Volatile", "text": "Larger than any recorded specimen, it has begun surfacing near boats with unusual boldness."}]}},
 "polar-bear": {"desc": "It moves across white expanse with deceptive ease, fur so pale it near-vanishes against ice and snow. Cold means nothing to it — it hunts in blizzard conditions that would kill anything else within hours. Patient at breathing holes, it can wait motionless for longer than most predators would dare.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Moving across white expanse, fur near-invisible against snow and drifting ice."}, {"n": 2, "band": "Grounded", "text": "It waits motionless at a breathing hole, patient beyond what most predators risk."}, {"n": 3, "band": "Grounded", "text": "Scarred deeply across the muzzle, it's clearly survived a fight over the same hunting ground."}, {"n": 4, "band": "Grounded", "text": "A sow keeps cubs close in a snow den, aggressive toward anything that nears it."}, {"n": 5, "band": "Grounded", "text": "It swims long distances between ice floes, undeterred by the frigid open water."}, {"n": 6, "band": "Textured", "text": "It's learned that a specific camp means discarded food, and returns to it repeatedly."}, {"n": 7, "band": "Strange", "text": "It hunts in conditions that should kill anything else, tracking through total whiteout."}, {"n": 8, "band": "Volatile", "text": "Starving past its usual patience, it stalks anything warm-blooded without hesitation."}]}},
 "pony": {"desc": "It trots with a stubby, sturdy gait, small enough for a child's hands but strong enough to pull a loaded cart all day. Gentle by breeding, it spooks easily but forgives fast, nosing back to whoever offers grain. Stubborn streaks show up mostly when it's tired or bored.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Trotting a sturdy, stubby gait, pulling a loaded cart without complaint."}, {"n": 2, "band": "Grounded", "text": "Gentle and small enough for a child's hands, it noses back for grain readily."}, {"n": 3, "band": "Grounded", "text": "It spooks at a loud noise, then forgives fast, settling back to grazing."}, {"n": 4, "band": "Grounded", "text": "An old farm pony, sway-backed, still hauls what's asked with patient stubbornness."}, {"n": 5, "band": "Grounded", "text": "It balks at a muddy crossing, stamping and refusing until coaxed."}, {"n": 6, "band": "Textured", "text": "Bonded oddly to a specific child rider, it calms only for that one voice."}, {"n": 7, "band": "Strange", "text": "It refuses to cross one particular bridge, no matter how gently it's led."}, {"n": 8, "band": "Volatile", "text": "Panicked loose, it bolts wildly, small enough to slip through gaps larger horses couldn't."}]}},
 "pteranodon": {"desc": "It wheels on leathery wings over open water, crest catching wind like a rudder, eyes fixed on the surface below. The dive is a sudden, splashing snatch, gone again before the fish even registers the shadow. It nests in high cliffside colonies, screeching in a chorus that carries for miles.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wheeling over open water, crest catching the wind, eyes fixed on the surface below."}, {"n": 2, "band": "Grounded", "text": "It snatches a fish in a sudden splashing dive, gone again in a single motion."}, {"n": 3, "band": "Grounded", "text": "A cliffside colony of them screeches in a chorus that carries for miles."}, {"n": 4, "band": "Grounded", "text": "Scarred wing membrane gives its flight an odd, uneven glide."}, {"n": 5, "band": "Grounded", "text": "It nests on a narrow ledge, defending the spot fiercely against rival flyers."}, {"n": 6, "band": "Textured", "text": "It's learned that boats mean discarded fish scraps, and trails them boldly now."}, {"n": 7, "band": "Strange", "text": "The colony rises together at the same hour daily, wheeling in a fixed pattern."}, {"n": 8, "band": "Volatile", "text": "Larger than its kind, it snatches at things well beyond fish from the water's surface."}]}},
 "rat": {"desc": "It scurries along a wall's baseboard, whiskers twitching, gone into a crack before a boot can land. Mostly a scavenger, mostly harmless alone, it thrives wherever people leave scraps and shadows both. Its real danger is in the plague it might be carrying, not the bite itself.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Scurrying along a baseboard, whiskers twitching, gone into a crack before a boot lands."}, {"n": 2, "band": "Grounded", "text": "It gnaws at a grain sack's corner, undeterred by the noise it's making."}, {"n": 3, "band": "Grounded", "text": "A nest squeaks faintly behind a wall, scattering the instant light hits them."}, {"n": 4, "band": "Grounded", "text": "Bold from a lack of predators, it lingers rather than fleeing a lantern's glow."}, {"n": 5, "band": "Grounded", "text": "Scarred and missing part of a tail, it's survived worse than most vermin do."}, {"n": 6, "band": "Textured", "text": "It's chewed a path through a sealed crate, dragging small items into its nest."}, {"n": 7, "band": "Strange", "text": "A whole nest of them moves in eerie, single-file coordination through the dark."}, {"n": 8, "band": "Volatile", "text": "Bold and diseased-looking, it bites without the usual fleeing instinct at all."}]}},
 "raven": {"desc": "It perches with a cocked, assessing head, feathers black enough to swallow torchlight whole. Cleverer than most birds people give credit for, it remembers faces and holds grudges accordingly. Its croak can be trained into unnervingly clear mimicry of speech.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Perched with a cocked, assessing head, watching movement below with sharp intelligence."}, {"n": 2, "band": "Grounded", "text": "It caws sharply at one specific person, seeming to remember some past slight."}, {"n": 3, "band": "Grounded", "text": "A pair works together, one distracting while the other steals a dropped scrap."}, {"n": 4, "band": "Grounded", "text": "It picks over a battlefield or gallows with unhurried, grim patience."}, {"n": 5, "band": "Grounded", "text": "Trained to a keeper's hand, it mimics a phrase with unsettling clarity."}, {"n": 6, "band": "Textured", "text": "It's collected a small hoard of shiny trinkets in a hidden nook nearby."}, {"n": 7, "band": "Strange", "text": "It follows a specific traveler for days, croaking at the same hour each time."}, {"n": 8, "band": "Volatile", "text": "A murder of them mobs and drives off something larger, cawing in eerie unison."}]}},
 "reef-shark": {"desc": "It patrols a shallow reef in slow, watchful loops, gray shape flickering between coral shadow and sun. Curious more than hostile, it investigates divers with a close pass before deciding whether to bother. In numbers it grows bolder, testing wounded or thrashing prey together.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Patrolling a shallow reef in slow loops, gray shape flickering between coral shadow."}, {"n": 2, "band": "Grounded", "text": "It makes a close, curious pass at a diver before deciding whether to bother further."}, {"n": 3, "band": "Grounded", "text": "A small group works a reef gap together, testing a wounded fish in loose coordination."}, {"n": 4, "band": "Grounded", "text": "Scarred along its dorsal fin, it's clearly weathered a fight over reef territory."}, {"n": 5, "band": "Grounded", "text": "It claims a specific coral head as its patrol center, circling back to it constantly."}, {"n": 6, "band": "Textured", "text": "It's learned that spearfishing means an easy meal, and trails hunters boldly now."}, {"n": 7, "band": "Strange", "text": "A group gathers at the same reef gap daily, circling without ever quite feeding."}, {"n": 8, "band": "Volatile", "text": "Blood in the water turns its usual caution to reckless, repeated strikes."}]}},
 "rhinoceros": {"desc": "It grazes with a slow, myopic indifference, horn lowered, until something crosses too close for its poor eyesight to ignore. The charge that follows is a straight, unstoppable line, thundering through anything in its path. It doesn't need to see well when it can simply run through the problem.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Grazing with slow, myopic indifference, horn lowered toward the grass."}, {"n": 2, "band": "Grounded", "text": "It charges in a straight, unstoppable line the instant something crosses too close."}, {"n": 3, "band": "Grounded", "text": "Scarred along one flank, it's clearly survived a fight over the same grazing ground."}, {"n": 4, "band": "Grounded", "text": "A calf trails close behind, and the adult turns aggressive at any approach."}, {"n": 5, "band": "Grounded", "text": "It wallows in a mud pit, defending the cool of it against any interloper."}, {"n": 6, "band": "Textured", "text": "Its horn is cracked and regrown crooked, souvenir of some past territorial clash."}, {"n": 7, "band": "Strange", "text": "It returns to the same wallow each season, undeterred by anything built there since."}, {"n": 8, "band": "Volatile", "text": "Nearly blind and furious, it charges anything that moves within its poor sight range."}]}},
 "riding-horse": {"desc": "It moves with an easy, trained gait, ears flicking to a rider's every shift of weight. Bred for temperament over toughness, it startles at sudden things but settles fast under a calm hand. Left riderless and frightened, it bolts hard and far before its nerves settle again.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Moving with an easy, trained gait, ears flicking to a rider's every shift."}, {"n": 2, "band": "Grounded", "text": "It startles at a sudden noise, then settles fast under a calm, steady hand."}, {"n": 3, "band": "Grounded", "text": "An older mount, gentle and patient, favors an even, unhurried pace."}, {"n": 4, "band": "Grounded", "text": "Scarred at the flank from an old spur, it flinches at anyone mounting too roughly."}, {"n": 5, "band": "Grounded", "text": "It's bonded to one specific rider and balks under any other hand on the reins."}, {"n": 6, "band": "Textured", "text": "Its tack shows fine, well-kept stitching — this one belongs to someone with means."}, {"n": 7, "band": "Strange", "text": "It refuses one particular stretch of road, no matter the rider or the reason."}, {"n": 8, "band": "Volatile", "text": "Riderless and panicked, it bolts through a crowd, reins whipping loose behind it."}]}},
 "saber-toothed-tiger": {"desc": "Its canines curve down past the jaw, an ambush weapon built for one devastating strike. It stalks in near-total silence through undergrowth before a single explosive leap ends the chase before it starts. Older, scarred specimens hunt alone, having long since outgrown any need for a pack.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Stalking in near-total silence, canines curved past the jaw, muscle coiled for a single leap."}, {"n": 2, "band": "Grounded", "text": "It ends a hunt in one explosive leap, the chase over before it truly began."}, {"n": 3, "band": "Grounded", "text": "Scarred deeply across the shoulder, it's clearly weathered a fight with something its equal."}, {"n": 4, "band": "Grounded", "text": "A lone hunter, it claims a wide territory and marks trees with deep claw gouges."}, {"n": 5, "band": "Grounded", "text": "It has claimed an old kill site, returning to feed until nothing usable remains."}, {"n": 6, "band": "Textured", "text": "One canine is chipped and shorter than the other, throwing off its usual killing bite."}, {"n": 7, "band": "Strange", "text": "It's been glimpsed near the same frozen ruin repeatedly, as if drawn there beyond hunting."}, {"n": 8, "band": "Volatile", "text": "Ancient and starving, it hunts bolder and closer to settlements than its kind should risk."}]}},
 "scorpion": {"desc": "It skitters low across sand or stone, claws raised, tail curled tight and ready. Small enough to overlook until the sting lands, it favors dark crevices and the undersides of things left too long unmoved. It strikes fast and retreats just as quickly, rarely pressing an advantage.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Skittering low across sand, claws raised, tail curled tight against its back."}, {"n": 2, "band": "Grounded", "text": "It's tucked beneath a stone, only the tail-tip visible in the shade."}, {"n": 3, "band": "Grounded", "text": "A mother carries pale young clustered thick across her back."}, {"n": 4, "band": "Grounded", "text": "It strikes fast and retreats immediately, rarely pressing any advantage."}, {"n": 5, "band": "Grounded", "text": "It's claimed a boot or bedroll left too long unmoved as its new shelter."}, {"n": 6, "band": "Textured", "text": "Its sting carries an unusually vivid, lingering burn compared to most of its kind."}, {"n": 7, "band": "Strange", "text": "Dozens emerge from the sand at the exact same hour, retreating before dawn without fail."}, {"n": 8, "band": "Volatile", "text": "Larger and bolder than usual, it stings repeatedly rather than retreating after the first."}]}},
 "seahorse": {"desc": "It bobs upright in gentle current, tail curled around a stalk of coral or weed, nearly invisible against the reef. Harmless and slow, it feeds by suction on drifting plankton, utterly unthreatening to anything larger. Its only defense is stillness and the camouflage that comes with it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bobbing upright in gentle current, tail curled tight around a stalk of coral."}, {"n": 2, "band": "Grounded", "text": "It feeds by suction on drifting plankton, utterly unbothered by nearby divers."}, {"n": 3, "band": "Grounded", "text": "A cluster anchors to the same weed bed, swaying together in the current."}, {"n": 4, "band": "Grounded", "text": "Its coloring shifts subtly to match the coral it's anchored to."}, {"n": 5, "band": "Grounded", "text": "A male carries a pouch of young, curling protectively when disturbed."}, {"n": 6, "band": "Textured", "text": "A thread of old fishing line trails from its tail, snagged and dragged for weeks."}, {"n": 7, "band": "Strange", "text": "It anchors to the same sunken trinket daily, as if the object holds some meaning."}, {"n": 8, "band": "Volatile", "text": "Unusually large and pale, it's drifted far from any reef it should call home."}]}},
 "spider": {"desc": "It hangs still in a corner web, legs folded, patient for hours at a stretch. Mostly harmless to anything larger than an insect, it startles into a scrambling retreat rather than a fight. Its silk marks every neglected corner of a room with the same fine, dusty threads.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hanging still in a corner web, legs folded, patient for the fly that hasn't come yet."}, {"n": 2, "band": "Grounded", "text": "It scrambles into a crack the instant a shadow falls across its web."}, {"n": 3, "band": "Grounded", "text": "A cluster of small webs marks a neglected corner, fine threads dusty with age."}, {"n": 4, "band": "Grounded", "text": "It wraps a moth in silk with quick, practiced motions before settling to wait again."}, {"n": 5, "band": "Grounded", "text": "Camouflaged against old wood, it's easy to overlook until it moves."}, {"n": 6, "band": "Textured", "text": "Its web has trapped something small and shiny, dangling uselessly in the strands."}, {"n": 7, "band": "Strange", "text": "Several webs converge on the same beam, an unusually dense cluster for their kind."}, {"n": 8, "band": "Volatile", "text": "Unusually large for its kind, it bites rather than flees when a hand reaches too close."}]}},
 "swarm-of-bats": {"desc": "It moves as one shifting cloud, wingbeats blurring into a single roar of motion and chittering panic. No single bat matters; the swarm is the threat, a hundred small bites layering into real damage. It scatters the instant fire or open sky offers an escape route.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Erupting from a cave mouth as one shifting cloud, wingbeats blurring into a single roar."}, {"n": 2, "band": "Grounded", "text": "It scatters the instant torchlight flares, streaming out toward the nearest dark exit."}, {"n": 3, "band": "Grounded", "text": "The swarm has claimed an entire cavern ceiling, chittering in a constant low murmur."}, {"n": 4, "band": "Grounded", "text": "It funnels through a narrow passage in a dense, disorienting rush of wings."}, {"n": 5, "band": "Grounded", "text": "Disturbed by noise alone, it boils out of a belfry in a panicked mass."}, {"n": 6, "band": "Textured", "text": "The swarm roosts above an old crypt, and the droppings below have buried the markers entirely."}, {"n": 7, "band": "Strange", "text": "It streams out in a single direction each dusk, following a route no map explains."}, {"n": 8, "band": "Volatile", "text": "Unusually dense and aggressive, it presses an attack rather than scattering at the first threat."}]}},
 "swarm-of-insects": {"desc": "It moves as a single droning mass, wings and mandibles blurring into one indistinct hum of motion. Fire and smoke are the only things that reliably turn it aside; blades pass through with little effect. It strips carrion to bone in hours and then vanishes into the walls and grass alike.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Droning as a single mass, wings and mandibles blurring into an indistinct hum."}, {"n": 2, "band": "Grounded", "text": "It strips a carcass to bone in a few short hours, then disperses into the grass."}, {"n": 3, "band": "Grounded", "text": "Smoke drifting through a passage sends it retreating into wall cracks and crevices."}, {"n": 4, "band": "Grounded", "text": "It boils out from beneath a rotted log, disturbed by even light footfall nearby."}, {"n": 5, "band": "Grounded", "text": "The swarm has claimed a granary, and the grain inside is thick with its droppings."}, {"n": 6, "band": "Textured", "text": "It has nested inside a wall cavity, and the drone is audible from the next room over."}, {"n": 7, "band": "Strange", "text": "It moves in a single direction with unusual purpose, ignoring easier prey along the way."}, {"n": 8, "band": "Volatile", "text": "Unusually large and aggressive, it presses through smoke that would normally turn it back."}]}},
 "swarm-of-piranhas": {"desc": "It moves beneath calm water as a single roiling shape, fins breaking the surface only when the feeding starts. Blood in the water is an invitation the whole mass answers instantly. It strips flesh in a churning frenzy and then vanishes back into stillness like nothing happened.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Moving beneath calm water as a single roiling shape, fins occasionally breaking the surface."}, {"n": 2, "band": "Grounded", "text": "Blood in the water sends the whole mass answering instantly, a churning frenzy."}, {"n": 3, "band": "Grounded", "text": "It strips a carcass to bone within moments, then vanishes back into stillness."}, {"n": 4, "band": "Grounded", "text": "The swarm favors a specific river bend where current concentrates its prey."}, {"n": 5, "band": "Grounded", "text": "It scatters at any larger predator's approach, regrouping downstream in minutes."}, {"n": 6, "band": "Textured", "text": "It's learned that splashing means food, drawn now to any struggle in the water at all."}, {"n": 7, "band": "Strange", "text": "It gathers thick near a submerged structure, circling without feeding, as if waiting."}, {"n": 8, "band": "Volatile", "text": "An unusually dense swarm strips flesh from bone in seconds, faster than normal."}]}},
 "swarm-of-rats": {"desc": "It pours through a passage like dark water, hundreds of small bodies moving as one hungry current. No single rat is a threat; the mass strips a corpse or a pantry with equal, relentless efficiency. Fire scatters it fast, but it regroups the moment the light dies down.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Pouring through a passage like dark water, hundreds of small bodies moving as one current."}, {"n": 2, "band": "Grounded", "text": "It strips a pantry bare in minutes, leaving nothing but gnawed sacking behind."}, {"n": 3, "band": "Grounded", "text": "The swarm floods out of a sewer grate, disturbed by noise or a dropped torch."}, {"n": 4, "band": "Grounded", "text": "It scatters at fire, regrouping the instant the light dies back down."}, {"n": 5, "band": "Grounded", "text": "It has claimed an entire cellar, gnaw marks scoring every surface within reach."}, {"n": 6, "band": "Textured", "text": "The swarm has chewed through a strongbox, coin and scrip scattered through its nest."}, {"n": 7, "band": "Strange", "text": "It moves with unnerving coordination, funneling through gaps in a single, deliberate ripple."}, {"n": 8, "band": "Volatile", "text": "Grown unnaturally bold on cursed refuse, it presses an attack rather than scattering."}]}},
 "swarm-of-ravens": {"desc": "It wheels overhead in a shifting black mass, cawing in a rising, unsettling chorus before it descends. Mobbing behavior turns coordinated fast — beaks and claws worrying a target from every angle at once. It scatters into the trees the instant the fight turns, only to regroup minutes later.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wheeling overhead in a shifting black mass, cawing in a rising, unsettling chorus."}, {"n": 2, "band": "Grounded", "text": "It mobs a lone predator, beaks and claws worrying it from every angle at once."}, {"n": 3, "band": "Grounded", "text": "It picks over a battlefield in dense, restless clusters, quarreling over the richest scraps."}, {"n": 4, "band": "Grounded", "text": "It scatters into the trees the instant the fight turns, regrouping minutes later."}, {"n": 5, "band": "Grounded", "text": "The flock roosts thick in a dead tree, branches sagging under their combined weight."}, {"n": 6, "band": "Textured", "text": "It's collected a glittering hoard of dropped trinkets scattered through the roost below."}, {"n": 7, "band": "Strange", "text": "It circles the same spot for hours, cawing without ever landing or striking."}, {"n": 8, "band": "Volatile", "text": "Unusually large and aggressive, the whole flock presses an attack without scattering first."}]}},
 "swarm-of-venomous-snakes": {"desc": "It moves as one dry, rattling mass across the ground, dozens of bodies coiling and striking independently. No single snake needs to land the killing blow — the cumulative venom does that work instead. It favors warm, enclosed spaces where the whole mass can pool undisturbed.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Moving as one dry, rattling mass across the ground, dozens of bodies coiling independently."}, {"n": 2, "band": "Grounded", "text": "It has pooled in a warm, enclosed crevice, near-invisible until the whole mass shifts."}, {"n": 3, "band": "Grounded", "text": "The mass strikes from every angle at once, no single snake needing to land the killing blow."}, {"n": 4, "band": "Grounded", "text": "It favors a sun-warmed ruin floor, coiling thick between fallen stones."}, {"n": 5, "band": "Grounded", "text": "Disturbed by vibration alone, the entire mass rises in a hissing, rattling wave."}, {"n": 6, "band": "Textured", "text": "It has claimed a cellar as a den, and old sacking is thick with shed skin."}, {"n": 7, "band": "Strange", "text": "It gathers in the same exact chamber each season, a ritual none can explain."}, {"n": 8, "band": "Volatile", "text": "Unusually dense and aggressive, its venom compounds fast enough to overwhelm most antidotes."}]}},
 "tiger": {"desc": "It moves through tall grass in orange-and-black silence, stripes breaking its outline into nothing. A solitary hunter, it stalks for what feels like hours before a single committed rush ends the chase. Territory is marked and defended alone — it shares nothing, not even a kill.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Moving through tall grass in orange-and-black silence, stripes breaking its outline entirely."}, {"n": 2, "band": "Grounded", "text": "It stalks for what feels like hours before a single, committed rush ends the chase."}, {"n": 3, "band": "Grounded", "text": "Scarred deeply across the flank, it's clearly survived a fight it shouldn't have won."}, {"n": 4, "band": "Grounded", "text": "It marks a wide solitary territory, claw gouges scoring trees at head height."}, {"n": 5, "band": "Grounded", "text": "It defends a fresh kill fiercely, dragging it into cover rather than sharing it."}, {"n": 6, "band": "Textured", "text": "It's developed a taste for livestock near a village, and losses are mounting fast."}, {"n": 7, "band": "Strange", "text": "It's been glimpsed near the same old shrine repeatedly, never straying far from it."}, {"n": 8, "band": "Volatile", "text": "Old and wounded, unable to hunt its usual prey, it has turned to hunting people instead."}]}},
 "triceratops": {"desc": "It plants three horns forward and lowers its frilled head, a wall of muscle daring anything to test it. Herd-bonded and mostly placid, it grazes in loose formation with calves kept toward the center. Provoked, the charge is a battering-ram rush that ends most confrontations in one pass.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Grazing in loose herd formation, three horns lowered toward the low scrub."}, {"n": 2, "band": "Grounded", "text": "It plants its stance and lowers its frill, a wall of muscle daring a challenge."}, {"n": 3, "band": "Grounded", "text": "A calf trails close to the herd's center, adults circling protectively around it."}, {"n": 4, "band": "Grounded", "text": "Scarred deep across the frill, it's clearly weathered a fight over herd standing."}, {"n": 5, "band": "Grounded", "text": "It has worn a deep, well-used trail between grazing grounds and a watering hole."}, {"n": 6, "band": "Textured", "text": "One horn is snapped short and regrown blunt, throwing off its usual charging gore."}, {"n": 7, "band": "Strange", "text": "The herd returns to the same clearing each season, standing motionless over old bones."}, {"n": 8, "band": "Volatile", "text": "An old bull, driven from the herd, charges with a rage that ends fights in one brutal pass."}]}},
 "tyrannosaurus-rex": {"desc": "The ground shifts under each footfall long before it's visible, a bass rumble that empties a forest of birdsong. Its bite alone can end most fights before they truly begin, jaws built to crush bone as easily as flesh. It hunts alone, apex enough that nothing in its territory dares contest a kill.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "The ground shifts under each footfall, a bass rumble that empties the forest of birdsong."}, {"n": 2, "band": "Grounded", "text": "It stalks a wounded animal with surprising patience before committing to the killing rush."}, {"n": 3, "band": "Grounded", "text": "Scarred deeply across the jaw, it's clearly survived a fight with something its equal."}, {"n": 4, "band": "Grounded", "text": "It defends a kill site with total, unchallenged authority, nothing daring to contest it."}, {"n": 5, "band": "Grounded", "text": "An old bull, scarred and slower, hunts with grim, patient efficiency instead of speed."}, {"n": 6, "band": "Textured", "text": "A broken spear shaft is lodged deep in its hide, healed over but still visibly festering."}, {"n": 7, "band": "Strange", "text": "It returns to the same clearing each season, standing over the bones of something enormous."}, {"n": 8, "band": "Mythic", "text": "An ancient, legendary specimen, its roar alone is said to have emptied whole valleys of life."}]}},
 "venomous-snake": {"desc": "It coils in warm shade, tongue flicking to taste the air before it decides whether to warn or strike. Small and easily missed, its bite carries a disproportionate threat for something so quiet. It prefers retreat to confrontation, striking only when truly cornered.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coiled in warm shade, tongue flicking to taste the air before deciding whether to move."}, {"n": 2, "band": "Grounded", "text": "It rattles once as fair warning, sluggish until truly disturbed further."}, {"n": 3, "band": "Grounded", "text": "Scarred along its length from some past predator's near-miss, it's grown wary."}, {"n": 4, "band": "Grounded", "text": "It has claimed a crevice den, old shed skin littering the narrow entrance."}, {"n": 5, "band": "Grounded", "text": "It swims low across still water, only its head breaking the surface."}, {"n": 6, "band": "Textured", "text": "Its markings are unusually vivid, a warning coloration more vibrant than most of its kind."}, {"n": 7, "band": "Strange", "text": "It returns to the same exact stone each dusk, sunning in a fixed, ritual pattern."}, {"n": 8, "band": "Volatile", "text": "Unusually potent for its size, its venom works faster than any local remedy can counter."}]}},
 "vulture": {"desc": "It circles high on broad, ragged wings, patient for the moment something below finally stops moving. Bald head and hunched shoulders mark it as scavenger first, opportunist second — it won't often force the issue. A gathering of them overhead is the surest sign something nearby is already dying.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Circling high on broad, ragged wings, patient for something below to finally stop moving."}, {"n": 2, "band": "Grounded", "text": "A gathering wheels overhead, the surest sign something nearby is already dying."}, {"n": 3, "band": "Grounded", "text": "It picks over a carcass in a loose, quarreling group, bald heads slick with old blood."}, {"n": 4, "band": "Grounded", "text": "It roosts in a dead tree, a dozen hunched shapes waiting out the heat of the day."}, {"n": 5, "band": "Grounded", "text": "It follows a wounded animal from a wary distance, never quite committing to force the issue."}, {"n": 6, "band": "Textured", "text": "It's learned that battle sites mean a feast, and follows armed columns at a distance now."}, {"n": 7, "band": "Strange", "text": "It circles the same fixed point for days, long before anything there has died."}, {"n": 8, "band": "Volatile", "text": "Bold past its kind's usual patience, a flock harries something still alive and struggling."}]}},
 "warhorse": {"desc": "It stands unflinching through drum and horn, trained to hold ground where lesser mounts would bolt. Its hooves are as much a weapon as any rider's blade, and it's been drilled to strike on command. Battle-scarred and steady, it treats chaos as simply another kind of order.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Standing unflinching through drum and horn, trained to hold ground where lesser mounts bolt."}, {"n": 2, "band": "Grounded", "text": "It strikes on command, hooves driving forward with drilled, deliberate force."}, {"n": 3, "band": "Grounded", "text": "Scarred across the flank from old battle wounds, it stands steady regardless."}, {"n": 4, "band": "Grounded", "text": "An aging veteran, it responds to command cues even without a rider present."}, {"n": 5, "band": "Grounded", "text": "It's bonded fiercely to one rider, refusing commands from any other hand."}, {"n": 6, "band": "Textured", "text": "Its barding shows fine, deliberate craftsmanship — this mount belongs to someone of rank."}, {"n": 7, "band": "Strange", "text": "It stands riderless at a battlefield's edge, refusing to leave the spot where its rider fell."}, {"n": 8, "band": "Volatile", "text": "Riderless and panicked past its training, it tramples through the chaos indiscriminately."}]}},
 "weasel": {"desc": "It slips through gaps too narrow to seem possible, body a lean ribbon of muscle and motion. Quick and opportunistic, it raids nests and burrows with a hunter's efficiency far beyond its tiny size. Startled, it vanishes into cover faster than the eye can properly register.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Slipping through a gap too narrow to seem possible, a lean ribbon of muscle and motion."}, {"n": 2, "band": "Grounded", "text": "It raids a ground nest with quick, efficient violence, gone before the parents return."}, {"n": 3, "band": "Grounded", "text": "Scarred and lean, it's clearly survived worse predators than most it evades now."}, {"n": 4, "band": "Grounded", "text": "It dens in a hollow log, dragging small kills back in a steady procession."}, {"n": 5, "band": "Grounded", "text": "It hunts low along a hedgerow, quick and near-invisible in the underbrush."}, {"n": 6, "band": "Textured", "text": "It's developed a taste for a coop's eggs, and the farmer nearby has noticed the losses."}, {"n": 7, "band": "Strange", "text": "It follows the same exact path nightly, pacing a fence line for no clear reason."}, {"n": 8, "band": "Volatile", "text": "Bold past its kind's usual caution, it kills well beyond any need to eat."}]}},
 "wolf": {"desc": "It moves at the edge of torchlight in loose, patient formation, eyes catching the flame in a cold amber shine. The pack hunts in relay, wearing prey down rather than overpowering it outright. A single howl means the others are already closing from another direction.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Moving at the edge of torchlight, eyes catching the flame in a cold amber shine."}, {"n": 2, "band": "Grounded", "text": "A pack hunts in relay, wearing prey down rather than overpowering it outright."}, {"n": 3, "band": "Grounded", "text": "It howls once, and the sound means the rest of the pack is already closing in."}, {"n": 4, "band": "Grounded", "text": "Scarred and lean, it's survived a harder winter than most of its pack did."}, {"n": 5, "band": "Grounded", "text": "It has denned in a rock overhang, pups yipping faintly from just inside."}, {"n": 6, "band": "Textured", "text": "It's developed a taste for livestock near a village, and losses are mounting fast."}, {"n": 7, "band": "Strange", "text": "The pack has learned to split and flank with a discipline beyond ordinary instinct."}, {"n": 8, "band": "Volatile", "text": "A lone rogue, driven from its pack, hunts alone now and twice as savage for it."}]}},
 "black-pudding": {"desc": "The floor seems to breathe. A slick black sheet peels itself off the stone, rising into a column that eats the torchlight instead of reflecting it. Where it drags, mortar hisses and iron pits to rust in seconds — it has been dissolving this cellar for longer than the walls remember. It does not hunt so much as arrive, patient as tide.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Fresh split from a larger mass — smaller, hungrier, still finding its shape."}, {"n": 2, "band": "Grounded", "text": "Nests under a stair, only its surface skin visible as a damp black stain."}, {"n": 3, "band": "Grounded", "text": "Recently fed — moves slower, a half-dissolved shield rippling beneath its skin."}, {"n": 4, "band": "Grounded", "text": "Clings to a ceiling, dripping acid in a slow countdown onto the floor below."}, {"n": 5, "band": "Grounded", "text": "Has eaten through a support beam; the room around it is quietly failing."}, {"n": 6, "band": "Textured", "text": "Split by a recent blade strike into two smaller puddings, both still hunting."}, {"n": 7, "band": "Strange", "text": "Faintly luminous where it touched something arcane — the glow pulses with its slide."}, {"n": 8, "band": "Volatile", "text": "Engulfed a spellcaster; motes of unspent magic spark and pop across its skin."}]}},
 "blob-of-annihilation": {"desc": "Reality thins where it moves. This is not ooze but absence given a slick, gliding surface — a wound in the world that happens to be shaped like a slime. Stars behind it don't quite line up right. Things it touches don't die so much as stop having existed, and the silence afterward is total.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "A scout's signal-mirror lies cracked nearby — the last warning never got sent."}, {"n": 2, "band": "Grounded", "text": "Trails a smear of half-erased footprints, someone fled and almost made it."}, {"n": 3, "band": "Grounded", "text": "A locked strongbox rolls loose in its wake, contents unknown, hinges untouched."}, {"n": 4, "band": "Grounded", "text": "An old ward-circle nearby is scored through — whoever drew it, it didn't hold."}, {"n": 5, "band": "Grounded", "text": "A hunting party's rope lies severed clean, the far end simply gone."}, {"n": 6, "band": "Textured", "text": "A survivor gibbers nearby about the shape of the hole it left in her memory."}, {"n": 7, "band": "Strange", "text": "A patch of erased ground nearby still refuses to hold footprints or echo sound."}, {"n": 8, "band": "Mythic", "text": "It carries, unerased, one relic too old and stubborn for it to unmake."}]}},
 "cloud-giant": {"desc": "The clouds beneath its castle groan under a weight they shouldn't be able to bear. It walks its floating hall barefoot, robes trailing vapor, addressing servants and storms alike with the same bored, aristocratic patience. Below, the ground-bound are a curiosity — sometimes an amusement, sometimes dinner, rarely an equal.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Sent a griffon-mounted herald ahead to demand tribute before it lands."}, {"n": 2, "band": "Grounded", "text": "Carries a captured merchant's entire caravan, still arguing about the toll."}, {"n": 3, "band": "Grounded", "text": "Its castle trails a rain of dropped goods — a running feud with the household staff."}, {"n": 4, "band": "Grounded", "text": "Hunting for a specific rare fruit, offering absurd payment to whoever finds it."}, {"n": 5, "band": "Grounded", "text": "Escorts a fire giant envoy it clearly despises but is bound by treaty to protect."}, {"n": 6, "band": "Textured", "text": "A cloud-cat familiar rides its shoulder, hissing warnings the giant half-ignores."}, {"n": 7, "band": "Strange", "text": "Its castle drifted through a storm-scar and now sheds faint violet lightning."}, {"n": 8, "band": "Volatile", "text": "Has taken a ground-dweller as a 'pet' noble, and genuinely believes it's a kindness."}]}},
 "couatl": {"desc": "Feathers the color of a held breath ripple down a serpent's coiling length, and when it turns its head the room feels judged and found — provisionally — worthy. It speaks softly, in a hundred tongues at once if it must, and its promises are binding in ways that outlast the speaker. Even at rest it looks like it is choosing not to strike.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a sleeping child it swore an oath to protect from a specific, named threat."}, {"n": 2, "band": "Grounded", "text": "Carries a sealed message it will only deliver to someone who proves their heart."}, {"n": 3, "band": "Grounded", "text": "Wounded, hiding — its enemy is still hunting and will find this place soon."}, {"n": 4, "band": "Grounded", "text": "Testing travelers with riddles before revealing a hidden safe path through danger."}, {"n": 5, "band": "Grounded", "text": "Bound by an old pact to a dying village, its power fading as the pact frays."}, {"n": 6, "band": "Textured", "text": "Offers its own feathers as a ward-charm, asking only a single honest answer in trade."}, {"n": 7, "band": "Strange", "text": "Speaks of a coming evil in the past tense, as though it has already happened once."}, {"n": 8, "band": "Volatile", "text": "Has broken its own oath once, and now hunts to atone before its patron notices."}]}},
 "cyclops-oracle": {"desc": "Its single eye is milk-white and unblinking, socketed in a skull too vast for the cave that shelters it. It speaks in fragments — half-prophecy, half-grievance — as if every future it has seen also personally wronged it. Firelight throws its shadow across whole walls, and pilgrims who come for answers rarely leave with the ones they wanted.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "A line of frightened pilgrims waits outside, each owing it a debt it hasn't named."}, {"n": 2, "band": "Grounded", "text": "Demands a sacrifice of memory, not blood, before it will speak a single true word."}, {"n": 3, "band": "Grounded", "text": "Has foreseen its own death and is trying, badly, to prevent it."}, {"n": 4, "band": "Grounded", "text": "Keeps a captive scribe to record every vision, chained but well fed."}, {"n": 5, "band": "Grounded", "text": "A rival oracle's cult is sending killers to silence it before dawn."}, {"n": 6, "band": "Textured", "text": "Speaks two prophecies at once, one true and one a test of the listener's greed."}, {"n": 7, "band": "Strange", "text": "Its blind eye occasionally weeps light that briefly shows the room's true shape."}, {"n": 8, "band": "Volatile", "text": "Has seen the questioner's death already and is deciding, aloud, whether to warn them."}]}},
 "cyclops-sentry": {"desc": "It stands its post the way a boulder stands a hillside — total, incurious, immovable. A single vast eye tracks motion more than meaning; it will hurl a rock at anything that crosses an invisible line only it remembers drawing. Conversation bores it. Trespass does not.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a specific pass, throwing rocks at anyone who doesn't know the toll-word."}, {"n": 2, "band": "Grounded", "text": "Half-asleep on duty, snoring loud enough to warn travelers well in advance."}, {"n": 3, "band": "Grounded", "text": "Keeps a small cairn of favorite thrown rocks it retrieves after every fight."}, {"n": 4, "band": "Grounded", "text": "Wears a crude bell-necklace of looted trinkets that clatter when it moves."}, {"n": 5, "band": "Grounded", "text": "Newly posted here, still building its rock-pile and territorial habits."}, {"n": 6, "band": "Textured", "text": "Trained to recognize its clan's banner and let bearers pass unmolested."}, {"n": 7, "band": "Strange", "text": "Its eye has a faint cataract-glow that seems to track magic before motion."}, {"n": 8, "band": "Volatile", "text": "Lost its post-mates recently and now attacks anything, friend or foe, on sight."}]}},
 "deva": {"desc": "It moves like a held note, wings folding without sound, its face lit from somewhere that isn't the torches. Its errands are always someone else's — a message, a rescue, a small correction to the world's ledger — carried out with patient, unhurried certainty. It bleeds light, briefly, if wounded, and mends before the wound is finished being noticed.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Sent to quietly correct one specific injustice, and will not leave until it's done."}, {"n": 2, "band": "Grounded", "text": "Carries a sealed writ of pardon for someone the party may not think deserves it."}, {"n": 3, "band": "Grounded", "text": "Disguised as a mortal envoy, testing whether the party will treat a stranger kindly."}, {"n": 4, "band": "Grounded", "text": "Escorting a soul home, and will not be delayed by anything short of true need."}, {"n": 5, "band": "Grounded", "text": "Investigating a shrine's desecration, patient but plainly building toward judgment."}, {"n": 6, "band": "Textured", "text": "Bound to answer three questions honestly before it may continue its errand."}, {"n": 7, "band": "Strange", "text": "Its wings leave brief afterimages of light that outline the room's hidden doors."}, {"n": 8, "band": "Volatile", "text": "Its errand conflicts with an oath it also swore, and the tension is fraying it."}]}},
 "empyrean": {"desc": "The ground remembers where it steps long after it's gone. Half-divine, half-something-older, it carries the scale and grudges of a war fought before mortals had names for the sides. Its voice alone can crack stone; its patience is worse. It does not fight wars anymore. It ends arguments.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Woken from a centuries-long sleep by a theft it will not let go unpunished."}, {"n": 2, "band": "Grounded", "text": "Hunting the last heir of a bloodline that wronged its long-dead patron."}, {"n": 3, "band": "Grounded", "text": "Guarding a battlefield from an ancient war, mistaking new travelers for old enemies."}, {"n": 4, "band": "Grounded", "text": "Carries a shard of its shattered domain, seeking somewhere fit to plant it anew."}, {"n": 5, "band": "Grounded", "text": "Bound by a geas to a mortal ruler it privately despises but cannot disobey."}, {"n": 6, "band": "Textured", "text": "Speaks of gods and titans by first name, casually, as former coworkers."}, {"n": 7, "band": "Strange", "text": "Its footprints briefly show a different landscape — the realm it once ruled."}, {"n": 8, "band": "Mythic", "text": "Is quietly dying of a wound only a god could have made, and is racing to matter once more."}]}},
 "empyrean-iota": {"desc": "A flickering half-echo of something vast, worn thin by distance from its source. It drifts more than walks, translucent at the edges, muttering fragments of a language older than the mountains around it. Small enough to be mistaken for a ghost. Old enough to remember when the mountains were younger too.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Newly split off, still coalescing, its shape flickering between forms."}, {"n": 2, "band": "Grounded", "text": "Haunts a specific ruin, repeating the same fragment of memory on a loop."}, {"n": 3, "band": "Grounded", "text": "Drawn to a mortal who resembles someone from its parent's distant past."}, {"n": 4, "band": "Grounded", "text": "Weakened, its incorporeal form flickering visible under bright torchlight."}, {"n": 5, "band": "Grounded", "text": "Mute except for a single repeated word, spoken in a dead celestial tongue."}, {"n": 6, "band": "Textured", "text": "Carries a splinter memory of its parent's death, replaying involuntarily."}, {"n": 7, "band": "Strange", "text": "Its passage briefly ages nearby plants a season forward, then back again."}, {"n": 8, "band": "Volatile", "text": "Reaching toward reunion with its parent's remains, growing stronger the closer it gets."}]}},
 "ettin": {"desc": "Two heads means two arguments running at once, and neither one wins for long. It lumbers through the underbrush muttering to itself in stereo, a battleaxe in one fist and a morningstar in the other, each head convinced the other picked the wrong weapon. Somehow it still hits what it's aiming at.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Its two heads are mid-argument over dinner plans and barely notice intruders."}, {"n": 2, "band": "Grounded", "text": "One head sleeps while the other keeps a groggy, half-hearted watch."}, {"n": 3, "band": "Grounded", "text": "Wears mismatched trophies from two different raids, one head's taste each."}, {"n": 4, "band": "Grounded", "text": "One head is missing an eye, the other compensates by watching twice as hard."}, {"n": 5, "band": "Grounded", "text": "Recently lost a fight and is nursing a grudge both heads agree on, for once."}, {"n": 6, "band": "Textured", "text": "The two heads have opposite personalities — one cruel, one strangely gentle."}, {"n": 7, "band": "Strange", "text": "One head speaks a language the other doesn't understand, unsettling them both."}, {"n": 8, "band": "Volatile", "text": "The heads are fighting each other, distracted enough to be caught off guard."}]}},
 "fire-giant": {"desc": "Heat rolls off it before it's even visible, the air above its shoulders bending like a lie. It moves with the unhurried confidence of something that has never lost a fight it bothered to remember, forge-scarred and soot-black, a blade still glowing faint orange from the last thing it cut. Its foundries never go cold.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Overseeing captive smiths forging weapons for a war the party hasn't heard of."}, {"n": 2, "band": "Grounded", "text": "Escorting a shipment of ore, furious at raiders who've been skimming the wagons."}, {"n": 3, "band": "Grounded", "text": "Dueling a rival for clan rank, and will recruit passersby as witnesses or seconds."}, {"n": 4, "band": "Grounded", "text": "Hunting a thief who stole a masterwork blade straight from its own forge."}, {"n": 5, "band": "Grounded", "text": "Guards a mountain pass its clan claims by ancient, disputed right."}, {"n": 6, "band": "Textured", "text": "Its armor bears the dents of a duel it lost and has been rebuilding strength for since."}, {"n": 7, "band": "Strange", "text": "Carries a blade that was quenched in something other than water — it never cools."}, {"n": 8, "band": "Volatile", "text": "Is testing a new weapon on the first thing unlucky enough to walk by."}]}},
 "fomorian": {"desc": "One eye bulges too large, one arm hangs too long, and the whole ruined shape of it looks like something unfinished by a careless hand — which is closer to true than it would like known. It hates beauty with the specific fury of the cursed, and warps what it touches until it matches. The dark suits it. The dark hides less.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Warped a captured noble's face to match its own, and is oddly gentle about it."}, {"n": 2, "band": "Grounded", "text": "Hoards mirrors it has smashed, unable to look at its reflection without rage."}, {"n": 3, "band": "Grounded", "text": "Bargains true answers for beautiful things it can ruin — a fair, cursed trade."}, {"n": 4, "band": "Grounded", "text": "Guards a fey-cursed sibling too warped even by fomorian standards to show itself."}, {"n": 5, "band": "Grounded", "text": "Was once handsome, once mortal, and half-remembers it in bitter fragments."}, {"n": 6, "band": "Textured", "text": "Its hex-curse lingers on anything it's warped, marking former victims for years."}, {"n": 7, "band": "Strange", "text": "The stone around its lair grows subtly wrong-angled, warped by long proximity."}, {"n": 8, "band": "Volatile", "text": "Is dying of its own curse, spreading faster now, and wants company on the way down."}]}},
 "frost-giant": {"desc": "Its beard is rimed white with breath-frost that never quite melts, and its stride cracks river ice half a mile off. It measures worth in raids survived and mead halls burned, contemptuous of anything softer than winter. When it laughs, the sound carries for miles and something, somewhere, always flees.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Leading a raiding party back from a coastal village, dragging captured plunder."}, {"n": 2, "band": "Grounded", "text": "Training a young mammoth mount, distracted and short-tempered about interruptions."}, {"n": 3, "band": "Grounded", "text": "Defends a frozen hall against a rival jarl's challenge, due any day now."}, {"n": 4, "band": "Grounded", "text": "Hunting a thief who stole a family heirloom axe during a midwinter feast."}, {"n": 5, "band": "Grounded", "text": "Escorting frost-touched wolves that answer only to its whistled commands."}, {"n": 6, "band": "Textured", "text": "Recites a genealogical boast before every fight, expecting one back in kind."}, {"n": 7, "band": "Strange", "text": "Its breath freezes fog into shapes that briefly resemble ancestral faces."}, {"n": 8, "band": "Volatile", "text": "Is testing whether the party is worthy of a formal, ritual duel to the death."}]}},
 "gelatinous-cube": {"desc": "It fills the corridor exactly, a perfect glass-clear block sliding along a groove worn smooth by a thousand identical passes. Nothing inside it looks urgent — bones, a shield, a scatter of coins — until the light catches wrong and something in there is still, barely, moving. It scours the dungeon like a slow, patient broom.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Freshly formed, its interior nearly empty — a rare, low-value pass."}, {"n": 2, "band": "Grounded", "text": "Wedged tight in a narrow hall, forcing anyone past to brush its surface."}, {"n": 3, "band": "Grounded", "text": "Moves unusually fast today, having recently dissolved something small and quick."}, {"n": 4, "band": "Grounded", "text": "Nearly invisible in dim light — only the suspended debris gives it away."}, {"n": 5, "band": "Grounded", "text": "Has been stuck against a doorframe for hours, straining slowly to squeeze through."}, {"n": 6, "band": "Textured", "text": "Carries an intact, sealed jar inside it, contents still miraculously unspoiled."}, {"n": 7, "band": "Strange", "text": "Faint runes suspended within it glow when read aloud from outside the cube."}, {"n": 8, "band": "Volatile", "text": "Split recently — a second, smaller cube trails just behind the first."}]}},
 "giant-eagle": {"desc": "It rides a thermal without a single wingbeat, a speck against the sun that resolves, alarmingly, into something the size of a rowboat. Its eyes miss nothing on the ground below. It speaks, when it deigns to, in a voice like tearing canvas, and judges strangers by their honesty before their strength.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Circling a cliffside nest, screeching warnings at anyone nearing its eggs."}, {"n": 2, "band": "Grounded", "text": "Watching a specific traveler from above, deciding whether they're worth aiding."}, {"n": 3, "band": "Grounded", "text": "Carries a message-scroll clutched in its talons, meant for someone specific below."}, {"n": 4, "band": "Grounded", "text": "Hunting the goblin raiders who stole one of its fledglings last season."}, {"n": 5, "band": "Grounded", "text": "Offers passage across a chasm in exchange for a small, honest favor."}, {"n": 6, "band": "Textured", "text": "Bonded to a lone mountain hermit, fiercely protective of that one person."}, {"n": 7, "band": "Strange", "text": "Its cry occasionally echoes back a half-second early, unsettling those below."}, {"n": 8, "band": "Volatile", "text": "Diving to rescue someone about to fall, having judged them worth the risk."}]}},
 "giant-elk": {"desc": "Antlers wide as a wagon spread catch the last light like something crowned. It moves through the treeline with unhurried grace, hooves silent on the deadfall, and stops to regard travelers with an intelligence that feels uncomfortably close to judgment. Something in its bearing insists it was never meant to be hunted.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Leads a herd of ordinary elk it fiercely shields from a nearby predator."}, {"n": 2, "band": "Grounded", "text": "Wounded by poachers, wary of anyone carrying rope or a hunting bow."}, {"n": 3, "band": "Grounded", "text": "Grazes near an old fey shrine it seems to be, quietly, guarding."}, {"n": 4, "band": "Grounded", "text": "Will let a rider mount it, but only one who's proven gentle with animals."}, {"n": 5, "band": "Grounded", "text": "Blocks a forest path, testing whether travelers will go around or force through."}, {"n": 6, "band": "Textured", "text": "Carries an old arrow still lodged harmlessly in its flank, a badge of survival."}, {"n": 7, "band": "Strange", "text": "Where it grazes, the grass springs back green even in the dead of winter."}, {"n": 8, "band": "Volatile", "text": "Charging to intervene in a fight it's decided, wrongly or rightly, is unjust."}]}},
 "giant-owl": {"desc": "Silence rides ahead of it — the wingbeats that should announce three feet of feathered predator simply don't arrive. It settles on a bough with unnerving precision, head rotating with a slow, total attentiveness, and watches with eyes that seem to be doing arithmetic. It speaks in soft, considered hoots, if it speaks at all.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Watches from the treeline, deciding whether travelers are worth a warning hoot."}, {"n": 2, "band": "Grounded", "text": "Bonded to a druid who sent it ahead scouting and hasn't returned to fetch it."}, {"n": 3, "band": "Grounded", "text": "Nests near a fey crossing, driving off anything that disturbs the boundary."}, {"n": 4, "band": "Grounded", "text": "Carries a small trinket in its talons, dropped by whatever it last hunted."}, {"n": 5, "band": "Grounded", "text": "Silently trails a lost child through the woods, unseen, herding them home."}, {"n": 6, "band": "Textured", "text": "Answers three riddling hoots with genuine, oddly wise, non-verbal gestures."}, {"n": 7, "band": "Strange", "text": "Its eyes briefly reflect a scene from somewhere else, gone before it registers."}, {"n": 8, "band": "Volatile", "text": "Has marked a specific traveler as prey for reasons only it understands."}]}},
 "gray-ooze": {"desc": "It looks like a puddle until the puddle notices you back. Flat, dull, the color of wet stone, it waits in the cracks between flagstones for something careless to lean too close. Metal sizzles where it touches. It has no mind to speak of, only appetite, patient as rust.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Pooled thin under a bench, nearly invisible until someone sits."}, {"n": 2, "band": "Grounded", "text": "Recently dissolved a lock, leaving a scatter of half-eaten hinges nearby."}, {"n": 3, "band": "Grounded", "text": "Slower than most, having fed recently on something large and metallic."}, {"n": 4, "band": "Grounded", "text": "Wedged in a drainage crack, only surfacing when disturbed by footsteps."}, {"n": 5, "band": "Grounded", "text": "Small and young, barely bigger than a dinner plate, easy to overlook."}, {"n": 6, "band": "Textured", "text": "Has absorbed enough coin residue to leave a faint metallic sheen."}, {"n": 7, "band": "Strange", "text": "Sits unnervingly still even when approached, as though deliberately patient."}, {"n": 8, "band": "Volatile", "text": "Split recently, leaving a smaller twin lurking somewhere nearby."}]}},
 "guardian-naga": {"desc": "Coiled around a pillar older than the temple that replaced it, its human face is serene in the way of things that have stopped being surprised by time. Scales the color of oxidized bronze catch torchlight without needing much of it. It speaks in careful, measured sentences, as if every word has already been weighed against centuries of watching.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Bound by ancient oath to guard a specific relic from a specific bloodline."}, {"n": 2, "band": "Grounded", "text": "Tests visitors with questions about the temple's forgotten founding purpose."}, {"n": 3, "band": "Grounded", "text": "Has outlived the order it serves and quietly wonders if the oath still binds."}, {"n": 4, "band": "Grounded", "text": "Offers safe passage to anyone who can answer one honest question truthfully."}, {"n": 5, "band": "Grounded", "text": "Poisons intruders sparingly, preferring capture and judgment over slaughter."}, {"n": 6, "band": "Textured", "text": "Remembers the temple's builders by name, and mourns them plainly, still."}, {"n": 7, "band": "Strange", "text": "The pillar it coils speaks back to it, faintly, in a tongue no one else hears."}, {"n": 8, "band": "Volatile", "text": "Has just realized the relic it guards was stolen years ago — a fake remains."}]}},
 "hill-giant": {"desc": "It smells of curdled meat and unwashed hide long before it comes into view, hunched shoulders scraping low branches it doesn't bother ducking. Its intelligence runs shallow but its hunger doesn't, and it swings whatever's nearest — log, boulder, cart — with the same indiscriminate enthusiasm. Subtlety was never on offer.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Raided a farm's larder and is dragging the whole pantry back to its den."}, {"n": 2, "band": "Grounded", "text": "Chasing livestock across an open field, oblivious to anything but dinner."}, {"n": 3, "band": "Grounded", "text": "Guarding a half-eaten kill, aggressive toward anything that smells like a rival."}, {"n": 4, "band": "Grounded", "text": "Wandered into a village looking for food, more confused than malicious."}, {"n": 5, "band": "Grounded", "text": "Camping under a bridge that travelers need, demanding tolls it can't spend."}, {"n": 6, "band": "Textured", "text": "Keeps a half-tame dog it feeds scraps to, oddly gentle with it alone."}, {"n": 7, "band": "Strange", "text": "Mutters the same nonsense rhyme constantly, learned from somewhere unremembered."}, {"n": 8, "band": "Volatile", "text": "Furious over a stolen meal, smashing indiscriminately in a food-driven rage."}]}},
 "ochre-jelly": {"desc": "Amber and viscous, it oozes down a wall in a slow cascade that could be mistaken for old varnish until it changes direction against gravity. It splits when struck carelessly, doubling its problem in an instant, and squeezes through gaps that shouldn't admit anything with mass. It has all the patience of something that never gets tired.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Draped along a ceiling beam, dripping in a slow, telltale rhythm below."}, {"n": 2, "band": "Grounded", "text": "Squeezed halfway through a door crack, stretched thin and vulnerable."}, {"n": 3, "band": "Grounded", "text": "Recently split by a careless blow — two smaller jellies, both hungry."}, {"n": 4, "band": "Grounded", "text": "Nested in a damp cellar corner, nearly the same color as the mildewed stone."}, {"n": 5, "band": "Grounded", "text": "Slow and sluggish, having gorged recently on something unusually large."}, {"n": 6, "band": "Textured", "text": "Carries faint chitinous fragments suspended within — something it ate fought back."}, {"n": 7, "band": "Strange", "text": "Glistens with a faint phosphorescence that pulses in an unnerving rhythm."}, {"n": 8, "band": "Volatile", "text": "Agitated, splitting repeatedly at the slightest disturbance, flooding the room."}]}},
 "ogre": {"desc": "A mountain of stitched hide and old bruises shambles into reach, breath sour with rot-meat and stolen ale. Its greatclub is a fence post still crusted with the last thing it hit. Small eyes track motion before thought — hunger runs this body, not cunning, and it will close distance faster than its bulk suggests.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Half-drunk on looted spirits — swings wide, but hits like a wall regardless."}, {"n": 2, "band": "Grounded", "text": "Nurses a festering spear wound; favors its off side, slower to close."}, {"n": 3, "band": "Grounded", "text": "Drags a crude cage-cart of stolen livestock, unwilling to abandon it."}, {"n": 4, "band": "Grounded", "text": "Wears a dead knight's dented breastplate as a trophy, laces never done up right."}, {"n": 5, "band": "Grounded", "text": "Travels with a starving dire wolf pup it half-remembers to feed."}, {"n": 6, "band": "Textured", "text": "Its club is a broken windmill blade lashed to a felled tree — swings wider than a body should let it."}, {"n": 7, "band": "Strange", "text": "Bone charms rattle at its neck; it flinches from firelight like something taught it to."}, {"n": 8, "band": "Volatile", "text": "Skin scarred in old brands from a fighting pit — it remembers the crowd's noise and roars for one now."}]}},
 "ogre-howdah": {"desc": "Lashed atop its broad shoulders sits a crude wooden platform, ropes and hide straps groaning with every lumbering step. Whatever rides up there — archer, standard, cage — the ogre beneath barely notices the weight, more concerned with the club in its fist and the next thing worth hitting. It fights like a wall that occasionally throws its passenger.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Howdah carries a nervous goblin archer, more scared of falling than fighting."}, {"n": 2, "band": "Grounded", "text": "The platform is freshly built, lashings still creaking and untested in battle."}, {"n": 3, "band": "Grounded", "text": "Rider absent — the howdah sits empty, straps flapping loose as it walks."}, {"n": 4, "band": "Grounded", "text": "Carries a small cage of chained captives instead of a rider, cruelly repurposed."}, {"n": 5, "band": "Grounded", "text": "Struggling under an overloaded platform, slower and more irritable than usual."}, {"n": 6, "band": "Textured", "text": "The howdah bears a tattered clan banner marking it as a war-party's vanguard."}, {"n": 7, "band": "Strange", "text": "The platform is lashed with bones instead of rope, oddly ritual in its binding."}, {"n": 8, "band": "Volatile", "text": "Its rider just died mid-fight and the ogre, confused, is thrashing to throw the corpse off."}]}},
 "pegasus": {"desc": "White wings catch the wind before hooves ever touch ground, a shape too graceful for the violence it's capable of when cornered. It watches strangers with large, wary eyes, ready to bolt skyward at the first wrong move. Trust, when it's given, is given completely — and rarely twice, once broken.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Grazing near a cliff edge, skittish, recently spooked by something unseen."}, {"n": 2, "band": "Grounded", "text": "Circles a fallen rider's body, refusing to leave until someone tends to them."}, {"n": 3, "band": "Grounded", "text": "Wild-born, has never worn a bridle, and reacts badly to any attempt at one."}, {"n": 4, "band": "Grounded", "text": "Escaped a noble's stable, still trailing a broken lead-rope and torn tack."}, {"n": 5, "band": "Grounded", "text": "Protecting a herd of wild horses from a predator stalking the same meadow."}, {"n": 6, "band": "Textured", "text": "Bonded once to a rider now dead, and won't let anyone else near the old saddle."}, {"n": 7, "band": "Strange", "text": "Its hoofprints briefly glow faint silver in the grass where it's passed."}, {"n": 8, "band": "Volatile", "text": "Bolting in blind panic from something in the sky the party hasn't seen yet."}]}},
 "planetar": {"desc": "It arrives already mid-verdict, wings unfurled like an argument that's been settled elsewhere and only needs enforcing here. Its sword hums faintly with the same certainty as its voice. It does not negotiate so much as inform, and the weight behind its patience is the only warning most get before it runs out.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Sent to end a specific atrocity, and will not be dissuaded once it's confirmed."}, {"n": 2, "band": "Grounded", "text": "Investigating a corrupted shrine, patient until it finds proof, merciless after."}, {"n": 3, "band": "Grounded", "text": "Escorting a mortal champion it's sworn to protect through one final trial."}, {"n": 4, "band": "Grounded", "text": "Testing a settlement's leaders, disguised, to see if they deserve its protection."}, {"n": 5, "band": "Grounded", "text": "Hunting a fiend that slipped its binding, and treats the search as personal failure."}, {"n": 6, "band": "Textured", "text": "Offers one true warning before battle, honestly, even to those it must fight."}, {"n": 7, "band": "Strange", "text": "Its sword briefly shows the true shape of nearby lies before striking them."}, {"n": 8, "band": "Mythic", "text": "Carries a divine mandate that overrides even its own order's chain of command."}]}},
 "psychic-gray-ooze": {"desc": "It sits still as spilled paint until a mind gets close enough, and then the silence in your skull gets crowded. Dull gray, unremarkable to the eye, it hunts with a different sense entirely — a pressure behind the temples that means it has already noticed you. Metal corrodes at its touch. Thoughts fray a little longer.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Small and newly formed, its psychic reach barely extending past arm's length."}, {"n": 2, "band": "Grounded", "text": "Pooled near a shrine, unnervingly still, as though listening rather than resting."}, {"n": 3, "band": "Grounded", "text": "Recently fed on something with strong emotions — its surface ripples faintly."}, {"n": 4, "band": "Grounded", "text": "Hidden in standing water, its psychic pressure the only warning of its presence."}, {"n": 5, "band": "Grounded", "text": "Sluggish after a large meal, its mental static duller and easier to ignore."}, {"n": 6, "band": "Textured", "text": "Leaves behind faint fragments of a victim's last thought, echoing in the air."}, {"n": 7, "band": "Strange", "text": "Its presence causes nearby torches to gutter as if a mind were breathing on them."}, {"n": 8, "band": "Volatile", "text": "Agitated, its psychic pressure spiking into a headache-inducing wave at range."}]}},
 "solar": {"desc": "Light doesn't fall on it so much as radiate from wherever it stands, wings vast enough to eclipse a doorway, sword already answering a question no one's asked yet. It is the closest thing to a god's own hand most mortals will ever see, and its arrival rearranges a room's priorities instantly. Whatever brought it here was already decided before it left.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Descended to end a war crime in progress, and the fighting stops the instant it lands."}, {"n": 2, "band": "Grounded", "text": "Carries final judgment on a mortal soul, and will not be argued out of it lightly."}, {"n": 3, "band": "Grounded", "text": "Investigating a fallen temple's silence, expecting the worst and finding it confirmed."}, {"n": 4, "band": "Grounded", "text": "Testing a would-be champion with a trial only a solar would consider fair."}, {"n": 5, "band": "Grounded", "text": "Hunting a fiend of its own rank that broke a centuries-old truce."}, {"n": 6, "band": "Textured", "text": "Speaks a single truth to whoever asks first, then falls silent on the matter forever."}, {"n": 7, "band": "Strange", "text": "Its blade briefly shows, in reflection, the moment its target's fate was sealed."}, {"n": 8, "band": "Mythic", "text": "Its arrival here means a god itself is watching through its eyes right now."}]}},
 "sphinx-of-lore": {"desc": "It reclines among ruined columns like a question that has never once been answered wrong. Its voice carries the dry patience of something that has watched empires ask it the same three questions for a thousand years. It does not chase knowledge; it already has it, and merely decides who's earned a taste.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Offers one true answer to whoever solves its riddle, and silence to whoever fails."}, {"n": 2, "band": "Grounded", "text": "Guards a specific forgotten text, testing seekers' worth before revealing it."}, {"n": 3, "band": "Grounded", "text": "Has watched a nearby ruin's true history unfold and refuses to correct false legend."}, {"n": 4, "band": "Grounded", "text": "Collects failed riddle-solvers as silent, permanent library fixtures nearby."}, {"n": 5, "band": "Grounded", "text": "Debating a rival scholar-sphinx over a point of history neither will concede."}, {"n": 6, "band": "Textured", "text": "Speaks in layered riddles, offering deeper truth only to those who ask twice."}, {"n": 7, "band": "Strange", "text": "Its ruins rearrange subtly overnight, as if the sphinx edits its own archive."}, {"n": 8, "band": "Volatile", "text": "Has just learned a truth that contradicts everything it's taught for centuries."}]}},
 "sphinx-of-secrets": {"desc": "It watches from shadowed alcoves before it's seen, a coiled patience that trades in what people wish stayed buried. Its questions cut sideways, less about facts than about what a person is afraid to admit. Answer wrong, and the silence afterward is its own kind of verdict.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Knows a secret that would unravel a nearby settlement's fragile peace."}, {"n": 2, "band": "Grounded", "text": "Offers to trade one true secret for one the seeker must confess honestly."}, {"n": 3, "band": "Grounded", "text": "Curses those who lie to it, subtly, with truths they can no longer hide."}, {"n": 4, "band": "Grounded", "text": "Guards a hidden passage, revealing it only to those who admit their real reason for coming."}, {"n": 5, "band": "Grounded", "text": "Watching a specific traveler, aware of a secret they don't yet know about themselves."}, {"n": 6, "band": "Textured", "text": "Speaks in half-truths deliberately, testing whether listeners notice the gaps."}, {"n": 7, "band": "Strange", "text": "Its eyes briefly reflect a truth the questioner hasn't admitted even to themselves."}, {"n": 8, "band": "Volatile", "text": "Has learned a secret about itself it can't curse away, and it's unraveling its calm."}]}},
 "sphinx-of-valor": {"desc": "Its roar precedes it by seconds, a sound built to test nerve before claw ever meets flesh. It measures worth in what a challenger does under pressure, not what they claim beforehand, and its judgment of cowardice is swift and total. Warriors who earn its respect rarely need to earn much else again.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Challenges a would-be champion to single combat before it will grant passage."}, {"n": 2, "band": "Grounded", "text": "Tests a group's courage under its roar, judging who stands and who flees."}, {"n": 3, "band": "Grounded", "text": "Guards a hero's tomb, permitting entry only to those who prove valor first."}, {"n": 4, "band": "Grounded", "text": "Hunting a coward who broke an oath of valor sworn in its presence."}, {"n": 5, "band": "Grounded", "text": "Mentoring a young warrior through brutal trials it insists are for their own good."}, {"n": 6, "band": "Textured", "text": "Remembers every challenger by name, keeping a private ledger of valor and cowardice."}, {"n": 7, "band": "Strange", "text": "Its roar briefly silences all other sound, as if demanding total attention."}, {"n": 8, "band": "Volatile", "text": "Has been dishonored by a past challenger's trick and is hunting to reclaim its pride."}]}},
 "sphinx-of-wonder": {"desc": "Lion-cub-sized and brightly feathered, it comes into being the instant some mind, somewhere, conceives a genuinely new idea — and it's marked for life by that first spark, a sigil on its brow hinting at whatever field first called it into existence. It hoards small truths the way its towering kin hoard great ones, and it will happily spend an afternoon on a coin trick, a locked box, or a child's riddle, utterly absorbed.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Bonded to a scholar who first thought its founding idea, and it hasn't left their side since."}, {"n": 2, "band": "Grounded", "text": "Perched on a locked reliquary, delighted to trade the key for one honest riddle."}, {"n": 3, "band": "Grounded", "text": "Hoards trinkets tied to its one obsession, cataloguing each with real scholarly care."}, {"n": 4, "band": "Grounded", "text": "Testing a child's cleverness with a harmless riddle, rooting for them the whole time."}, {"n": 5, "band": "Grounded", "text": "Newly born from an idea someone nearby just had, and still getting used to existing."}, {"n": 6, "band": "Textured", "text": "Speaks only in questions, delighted whenever someone answers with a better one."}, {"n": 7, "band": "Strange", "text": "Its sigil shifts slightly whenever its bonded field of study deepens."}, {"n": 8, "band": "Volatile", "text": "Overexcited by a genuinely novel puzzle, it won't stop pestering until it's solved."}]}},
 "stone-giant": {"desc": "It could be mistaken for outcropping until it moves, gray hide cracked like weathered granite, expression as unreadable as a cliff face. It throws boulders with an artist's calm precision and speaks rarely, preferring the company of stone to the company of most things that talk back. Caves remember it as a resident, not an intruder.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Practicing stone-throwing at a target range, annoyed at being watched mid-form."}, {"n": 2, "band": "Grounded", "text": "Carving a quiet monument to a fallen kin deep in its cave, undisturbed for years."}, {"n": 3, "band": "Grounded", "text": "Guards a mountain pass from rockslides more than from people, mildly territorial."}, {"n": 4, "band": "Grounded", "text": "Hunting a rival clan's giant over a boulder-throwing contest gone too far."}, {"n": 5, "band": "Grounded", "text": "Tending an underground garden of luminous fungus, oddly gentle about it."}, {"n": 6, "band": "Textured", "text": "Speaks in short, geologic metaphors, patient with those who take the time to listen."}, {"n": 7, "band": "Strange", "text": "Its cave walls are carved with centuries of throw-scores, a private, silent art."}, {"n": 8, "band": "Volatile", "text": "Mourning a cave-in that buried kin, hurling stone at anything that disturbs the site."}]}},
 "storm-giant": {"desc": "It rises from the surf like the storm decided to grow legs, hair and beard streaming rain that hasn't started falling yet. Old-blooded and courtly, it speaks with the formal weight of a kingdom that mostly exists in memory now, and its temper, when it breaks, sounds exactly like thunder because it is.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Holding court on a storm-wracked isle, weighing a dispute between lesser giants."}, {"n": 2, "band": "Grounded", "text": "Rescuing sailors from a wreck it may have caused, guilt plain on its face."}, {"n": 3, "band": "Grounded", "text": "Guards a sunken palace's last treasure, more out of duty than greed."}, {"n": 4, "band": "Grounded", "text": "Seeking a scholar to translate an ancient royal decree it can't quite parse."}, {"n": 5, "band": "Grounded", "text": "Mourning a fallen spouse, the sky above genuinely stormier for the grief."}, {"n": 6, "band": "Textured", "text": "Speaks with old-world courtesy even mid-battle, honor-bound to formal rules."}, {"n": 7, "band": "Strange", "text": "Lightning flickers in its eyes when it's about to speak an unwelcome truth."}, {"n": 8, "band": "Volatile", "text": "Furious at a broken oath from another giant clan, ready to declare open war."}]}},
 "troll": {"desc": "It comes apart wrong. A wound closes before the blood finishes falling, flesh knitting with a wet, audible hunger of its own. Long-limbed and warty, it smells of bog rot and old kills, hunting less out of cunning than because it simply never stops being hungry. Fire is the only argument it truly respects.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Freshly regenerated a lost arm, favoring the newer, tenderer limb."}, {"n": 2, "band": "Grounded", "text": "Nesting under a bridge, demanding toll in the form of livestock or blood."}, {"n": 3, "band": "Grounded", "text": "Wary of fire specifically, having been badly burned once and remembering it."}, {"n": 4, "band": "Grounded", "text": "Hunting alone, having been driven off by a larger troll's territory claim."}, {"n": 5, "band": "Grounded", "text": "Dragging a half-eaten kill back to its den, distracted and food-drunk."}, {"n": 6, "band": "Textured", "text": "Keeps a crude trophy-pile of severed limbs it lost and regrew, oddly proud."}, {"n": 7, "band": "Strange", "text": "Its wounds knit shut with a faint green shimmer no ordinary troll shows."}, {"n": 8, "band": "Volatile", "text": "Enraged past reason after a recent near-death, attacking with reckless abandon."}]}},
 "troll-amalgam": {"desc": "It shouldn't hold together, and that's the horror of it — limbs at wrong angles, joints that bend twice, stitched from more than one troll's ruin into something that regenerates wrongness along with flesh. It moves like its own geometry keeps renegotiating mid-stride. Whatever made it wasn't trying to make something sane.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "One of its limbs is visibly newer, still knitting into the wrong proportions."}, {"n": 2, "band": "Grounded", "text": "Moves with a stuttering, arrhythmic gait, its extra joints fighting each other."}, {"n": 3, "band": "Grounded", "text": "Occasionally flings a limb loose mid-fight, which keeps twitching independently."}, {"n": 4, "band": "Grounded", "text": "Bears scars from whatever grafting made it, still raw and weeping faintly."}, {"n": 5, "band": "Grounded", "text": "Confused by its own extra limbs, occasionally attacking the wrong direction."}, {"n": 6, "band": "Textured", "text": "Two mismatched heads occasionally emerge mid-regeneration before reabsorbing."}, {"n": 7, "band": "Strange", "text": "Its wrong-angled joints leave afterimages, as though it's slightly out of sync with time."}, {"n": 8, "band": "Volatile", "text": "Destabilizing further with each wound, growing more geometrically wrong by the round."}]}},
 "troll-limb": {"desc": "A severed arm should not be crawling, and yet here it is, fingers dragging it forward with a wet, insistent purpose. Small, stupid, and utterly without fear, it seeks only to rejoin what it was torn from — or, failing that, to become something new entirely. Stepping on it barely slows it down.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Freshly severed, still twitching toward the troll it was torn from."}, {"n": 2, "band": "Grounded", "text": "Wedged in rubble, crawling in slow circles, disoriented and directionless."}, {"n": 3, "band": "Grounded", "text": "Clutches a small object it grabbed reflexively before being severed."}, {"n": 4, "band": "Grounded", "text": "Multiple limbs crawl together in an uncoordinated, skittering cluster."}, {"n": 5, "band": "Grounded", "text": "Slow and weak, having been separated from its parent troll for days."}, {"n": 6, "band": "Textured", "text": "Already sprouting rudimentary fingers on what used to be its severed end."}, {"n": 7, "band": "Strange", "text": "Twitches in perfect unison with a distant, unseen troll's movements."}, {"n": 8, "band": "Volatile", "text": "Rapidly regenerating new tissue, visibly growing toward becoming whole again."}]}},
 "unicorn": {"desc": "It steps into moonlight like moonlight was arranged for the occasion, a horn spiraled white catching light that shouldn't be there to catch. Wholly wild, wholly untamed by anything but its own judgment, it approaches only those it decides deserve approaching. Its hooves leave the grass better than they found it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a glade where a wounded fey creature is healing in hiding."}, {"n": 2, "band": "Grounded", "text": "Will heal a grievous wound, but only for someone who's proven their heart clean."}, {"n": 3, "band": "Grounded", "text": "Wary of a nearby hunting party specifically seeking its horn."}, {"n": 4, "band": "Grounded", "text": "Testing a child's purity of intent before allowing them near a sacred spring."}, {"n": 5, "band": "Grounded", "text": "Grieving a slain companion unicorn, dangerous to approach carelessly right now."}, {"n": 6, "band": "Textured", "text": "Leaves the grass it walks greener, a visible trail marking its passage."}, {"n": 7, "band": "Strange", "text": "Its horn briefly glows warning-white near anything cursed or poisoned."}, {"n": 8, "band": "Volatile", "text": "Charging to intervene in a nearby act of true cruelty it's just witnessed."}]}},
 "adult-black-dragon": {"desc": "The swamp exhales around it: sulfur, rot, the hiss of acid eating stone. Its hide is bog-black and slick, scales overlapping like drowned bark, and its eyes hold no warmth at all, only calculation. It rises from brackish water without a ripple, wings folding wet against a spine of corroded ridges. Cruelty here is not passion — it is patient, exact, and endlessly willing to wait.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Scales pitted white where old acid burns never healed over."}, {"n": 2, "band": "Grounded", "text": "Trails a film of oily rot; nearby water turns foul for a day."}, {"n": 3, "band": "Grounded", "text": "Keeps a drowned tower as its throne, roof long since caved in."}, {"n": 4, "band": "Grounded", "text": "Speaks in a slow hiss, savoring every threat before finishing it."}, {"n": 5, "band": "Grounded", "text": "Hoards skulls of the drowned, arranged in a deliberate spiral."}, {"n": 6, "band": "Textured", "text": "One eye clouded milk-white, blinded by its own acid long ago."}, {"n": 7, "band": "Strange", "text": "Bog lights answer its roar, marsh-fire flickering in sympathy."}, {"n": 8, "band": "Volatile", "text": "Its acid pools have bred a swarm of corroded, half-melted vermin."}]}},
 "adult-blue-dragon": {"desc": "Heat shimmers off open sand and the dragon comes down the wind like a blade unsheathing, blue scales sparking faint static where they catch the light. It talks before it kills, precise and imperious, certain of its dominion over every creature smaller than itself. Lightning rides just under its skin, and the ground where it lands often cracks and glasses from old scorch. It does not forgive interruption.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "A crackling nimbus of static clings visibly to its wingtips."}, {"n": 2, "band": "Grounded", "text": "Burrows beneath dunes, surfacing mid-sentence to finish a threat."}, {"n": 3, "band": "Grounded", "text": "Demands titles and proper address before allowing any parley."}, {"n": 4, "band": "Grounded", "text": "Its lair floor is fused glass, scorched smooth by old breath."}, {"n": 5, "band": "Grounded", "text": "Keeps a caravan's worth of captives as unpaid, terrified scribes."}, {"n": 6, "band": "Textured", "text": "A horn is cracked and re-fused, jagged where lightning once struck true."}, {"n": 7, "band": "Strange", "text": "Storm clouds gather unnaturally whenever its temper rises."}, {"n": 8, "band": "Volatile", "text": "Its hoard includes a captured storm, bottled and still faintly thundering."}]}},
 "adult-brass-dragon": {"desc": "It talks first, always, wings spread wide against the desert glare like a herald announcing itself. Brass-bright scales catch the sun in hard flashes, and its voice carries an eager, motor-mouthed cheer that can turn suddenly sharp if bored or crossed. It will trade a story for a story, and burrow into gossip like treasure. Silence, to this dragon, is the only true insult.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Talks through an entire encounter before remembering to attack."}, {"n": 2, "band": "Grounded", "text": "Collects rumors instead of gold, trading tales for safe passage."}, {"n": 3, "band": "Grounded", "text": "Naps buried in sand with just its snout and eyes exposed."}, {"n": 4, "band": "Grounded", "text": "Genuinely delighted by visitors, however heavily armed they are."}, {"n": 5, "band": "Grounded", "text": "Sleeping breath used on bores mid-sentence, out of pure impatience."}, {"n": 6, "band": "Textured", "text": "Scales scorched dull brown along one flank from an old duel."}, {"n": 7, "band": "Strange", "text": "Claims fluent memory of conversations centuries past, verbatim."}, {"n": 8, "band": "Volatile", "text": "Keeps a captured sandstorm as a pet, fed occasional shiny trinkets."}]}},
 "adult-bronze-dragon": {"desc": "It surfaces off the coast like a breaking wave given purpose, water sluicing from bronze-green plates, eyes bright with an old sailor's watchfulness. Storms seem to know it and part around its wings. It measures every stranger by their honesty first, their strength second, and punishes cruelty toward the weak without hesitation. Ships that earn its favor rarely sink again.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Circles wrecked ships slowly, checking the wreckage for survivors."}, {"n": 2, "band": "Grounded", "text": "Disguises itself as driftwood, patient, watching harbor traffic."}, {"n": 3, "band": "Grounded", "text": "Keeps a barnacle-crusted bell it rings before any confrontation."}, {"n": 4, "band": "Grounded", "text": "Interrogates pirates personally before handing them to authorities."}, {"n": 5, "band": "Grounded", "text": "Nests among sea caves it has hollowed smooth over decades."}, {"n": 6, "band": "Textured", "text": "A talon is replaced by fused coral, grown over an old wound."}, {"n": 7, "band": "Strange", "text": "Gulls and gannets nest openly along its spine without fear."}, {"n": 8, "band": "Volatile", "text": "Commands a loyal pod of dolphins that scout ahead of it."}]}},
 "adult-copper-dragon": {"desc": "Laughter echoes up through the hills before the dragon ever shows itself, copper scales flashing between crags like a joke about to land. It loves riddles, puns, and the particular pleasure of watching someone fall for an obvious trick twice. Beneath the mischief sits real cunning: it remembers every insult and repays them all, eventually, with interest and wit.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Opens every encounter with a riddle it refuses to explain."}, {"n": 2, "band": "Grounded", "text": "Disguises its lair entrance as an obviously fake secret door."}, {"n": 3, "band": "Grounded", "text": "Collects terrible puns, delivered with unbearable comic timing."}, {"n": 4, "band": "Grounded", "text": "Keeps score of every joke landed against it, for later revenge."}, {"n": 5, "band": "Grounded", "text": "Nests in canyon country pocked with deliberate echo chambers."}, {"n": 6, "band": "Textured", "text": "One wing membrane is patched with old scar tissue, oddly translucent."}, {"n": 7, "band": "Strange", "text": "Its breath weapon leaves victims giggling helplessly for an hour."}, {"n": 8, "band": "Volatile", "text": "Has trained a chorus of ravens to mimic its own laughter back at it."}]}},
 "adult-green-dragon": {"desc": "Rot-sweet fog curls low through the trees ahead of it, and its emerald scales blur into the canopy until the moment it chooses to be seen. Every word it speaks is a small manipulation, a thread it means to pull later. It prefers puppets to victims — humiliated, indebted, or terrified into loyalty — and treats honesty as a tool for other creatures to fall for.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Leaves deliberately, half-legible letters implicating rival lords."}, {"n": 2, "band": "Grounded", "text": "Its scales have gone near-black with age, darker than lore claims."}, {"n": 3, "band": "Grounded", "text": "Speaks in flattering half-truths, never once an outright lie."}, {"n": 4, "band": "Grounded", "text": "Keeps a rotating cast of blackmailed nobles as unwilling informants."}, {"n": 5, "band": "Grounded", "text": "Prefers to watch a rival's ruin unfold rather than cause it directly."}, {"n": 6, "band": "Textured", "text": "A jaw scar forces a permanent, unsettling half-smile."}, {"n": 7, "band": "Strange", "text": "Its fog carries whispered fragments of its own old lies."}, {"n": 8, "band": "Volatile", "text": "Maintains a spy network of charmed forest creatures reporting nightly."}]}},
 "adult-red-dragon": {"desc": "Heat comes first, a wall of it rolling down the mountainside before the dragon ever clears the ridge. Red scales gleam like coals barely banked, and its presence alone seems to make the air combustible. Pride runs through it like marrow — it does not merely want the mountain's gold, it wants to be worshipped for holding it, and it answers any perceived slight with fire enough to reshape the land.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Announces its name and titles before allowing any combat to begin."}, {"n": 2, "band": "Grounded", "text": "Lair floor is glass-slick obsidian, fused smooth by centuries of breath."}, {"n": 3, "band": "Grounded", "text": "Demands tribute be delivered, never fetched, as a point of pride."}, {"n": 4, "band": "Grounded", "text": "Keeps rival dragons' skulls mounted as trophies near the entrance."}, {"n": 5, "band": "Grounded", "text": "Sleeps atop its hoard directly, coins fused to its own molten scales."}, {"n": 6, "band": "Textured", "text": "A horn snapped short in some old, unspoken duel, never regrown."}, {"n": 7, "band": "Strange", "text": "The mountain itself trembles faintly whenever its temper flares."}, {"n": 8, "band": "Volatile", "text": "Keeps a bound salamander court that whispers flattery in its sleep."}]}},
 "adult-silver-dragon": {"desc": "It comes wreathed in cold mountain cloud, wings catching the last grey light like polished steel, and something in its bearing suggests it has walked among mortals more than it has hunted them. Kindness is not weakness here — it is armor, chosen deliberately, backed by frost that can freeze an army where it stands. It remembers faces, keeps promises, and grieves what it could not save.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears a human disguise so long-practiced it forgets to drop it."}, {"n": 2, "band": "Grounded", "text": "Keeps a shrine to mortals it failed to protect, decades past."}, {"n": 3, "band": "Grounded", "text": "Nests among glacial peaks pocked with frozen, perfect handholds."}, {"n": 4, "band": "Grounded", "text": "Politely corrects anyone who assumes silver dragons hoard for greed."}, {"n": 5, "band": "Grounded", "text": "Frost patterns its breath leaves are oddly, deliberately beautiful."}, {"n": 6, "band": "Textured", "text": "A scale-cluster along one wing is permanently frost-scarred white."}, {"n": 7, "band": "Strange", "text": "Snow near its lair never quite melts, even in high summer."}, {"n": 8, "band": "Volatile", "text": "Keeps a mortal ward it raised in secret, now grown and unaware of its guardian."}]}},
 "adult-white-dragon": {"desc": "Wind-driven snow parts around it like it has always belonged to the storm. White dragons are the least clever of their kind and the most brutal for it — pure animal hunger wrapped in ice-armored scale, territorial past reason, savage past need. It does not scheme. It does not negotiate. It simply claims, and defends the claim with everything it has.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Marks territory with frozen carcasses left half-buried in drifts."}, {"n": 2, "band": "Grounded", "text": "Burrows beneath glacier ice, ambushing from beneath the snowpack."}, {"n": 3, "band": "Grounded", "text": "Snarls and postures before attacking, animal instinct over cunning."}, {"n": 4, "band": "Grounded", "text": "Hoard is a chaotic frozen mass, nothing sorted, nothing valued."}, {"n": 5, "band": "Grounded", "text": "Fights other predators over territory more often than it fights prey."}, {"n": 6, "band": "Textured", "text": "Missing scales along one flank, scarred from a losing pack fight."}, {"n": 7, "band": "Strange", "text": "Ice near its lair forms unnervingly regular, crystalline patterns."}, {"n": 8, "band": "Volatile", "text": "Has half-tamed a pack of winter wolves that hunt ahead of it."}]}},
 "ancient-black-dragon": {"desc": "The swamp has rotted around it for a thousand years, and it has simply outlasted every enemy that ever came for the hoard. Its scales are cracked obsidian-black, pitted deep with its own ancient acid, and its patience has calcified into something close to contempt for anything that still dies quickly. When it finally moves, whole trees dissolve where its breath passes.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Its lair is a drowned city, streets still faintly visible beneath the muck."}, {"n": 2, "band": "Grounded", "text": "Remembers kingdoms that no longer exist, references them as if current."}, {"n": 3, "band": "Grounded", "text": "Skin has gone matte-black, scales fused nearly seamless with age."}, {"n": 4, "band": "Grounded", "text": "Keeps the mummified dead of long-fallen heroes as silent trophies."}, {"n": 5, "band": "Grounded", "text": "Moves with unnerving, unhurried confidence, certain nothing can outlast it."}, {"n": 6, "band": "Textured", "text": "One wing carries a centuries-old rend scar, never fully closed."}, {"n": 7, "band": "Strange", "text": "The swamp itself seems to have grown loyal, roots pulling at intruders."}, {"n": 8, "band": "Mythic", "text": "Its acid has dissolved an entire buried temple into a private throne room."}]}},
 "ancient-blue-dragon": {"desc": "Centuries of desert storms have not humbled it; if anything, they seem to answer to it now. Its scales have deepened to a near-royal indigo, cracked in places like old porcelain, and its voice carries the unshakeable certainty of something that has ruled longer than any nation nearby has existed. Lightning does not merely accompany it — it seems to arrive first, announcing what's coming.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Speaks of long-dead kings as former subjects, casually, without malice."}, {"n": 2, "band": "Grounded", "text": "Its lair is a glass-floored crater, fused smooth by a thousand storms."}, {"n": 3, "band": "Grounded", "text": "Demands elaborate court protocol even from desperate, starving refugees."}, {"n": 4, "band": "Grounded", "text": "Keeps a library of stolen scrolls it has fully memorized, unread since."}, {"n": 5, "band": "Grounded", "text": "Horn-tips have grown unnaturally long, curling with sheer age."}, {"n": 6, "band": "Textured", "text": "A cracked horn, fused wrong, from some long-forgotten grievance."}, {"n": 7, "band": "Strange", "text": "Storms visibly orbit its territory, never quite making landfall."}, {"n": 8, "band": "Mythic", "text": "Commands the weather itself for a hundred miles, a standing court of thunderheads."}]}},
 "ancient-brass-dragon": {"desc": "It has told every story worth telling at least twice, and it still wants one more. Centuries of sun have bleached its brass hide to near-gold, and its garrulous, restless charm has only sharpened with age into something almost unbearably wise. It remembers empires that forgot themselves, and it will happily recite their entire fall, unasked, at length.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Recites the full, unabridged history of fallen empires, unprompted."}, {"n": 2, "band": "Grounded", "text": "Genuinely cannot recall the last time it fought anything, and says so."}, {"n": 3, "band": "Grounded", "text": "Its hoard is mostly books, scrolls, and old, treasured correspondence."}, {"n": 4, "band": "Grounded", "text": "Naps buried so deep in sand that caravans mistake it for a dune."}, {"n": 5, "band": "Grounded", "text": "Offers ancient secrets freely, in exchange only for fresh gossip."}, {"n": 6, "band": "Textured", "text": "Scales along its throat are worn smooth from centuries of talking."}, {"n": 7, "band": "Strange", "text": "Claims perfect memory back to events no living scholar can verify."}, {"n": 8, "band": "Mythic", "text": "Its buried lair holds the last intact archive of a civilization erased from every other record."}]}},
 "ancient-bronze-dragon": {"desc": "It has watched over this coast longer than any lighthouse, and the sea itself seems to defer to it, storms breaking early around its old, barnacle-crusted bulk. Centuries of shepherding sailors have made it patient, watchful, and quietly relentless against cruelty. It does not forget a debt of honor, and it does not forgive those who prey on the helpless.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has personally guided the same shipping lane safely for generations."}, {"n": 2, "band": "Grounded", "text": "Its hide has gone deep verdigris-green, patinaed like ancient statuary."}, {"n": 3, "band": "Grounded", "text": "Keeps meticulous, centuries-old records of every ship it has saved."}, {"n": 4, "band": "Grounded", "text": "Interrogates suspected slavers personally, at painstaking length."}, {"n": 5, "band": "Grounded", "text": "Lair is a sea cave carved smooth over centuries of tidal patience."}, {"n": 6, "band": "Textured", "text": "A talon replaced by ancient fused coral, grown thick with age."}, {"n": 7, "band": "Strange", "text": "Whales surface nearby unprompted whenever it calls out to sea."}, {"n": 8, "band": "Mythic", "text": "Commands an ancient pact with the coastline's deep-sea leviathans."}]}},
 "ancient-copper-dragon": {"desc": "Its laughter has echoed off these canyon walls for so long the stone itself seems to remember the joke. Age has only sharpened its wit into something dangerously precise, every riddle a trap dressed as a game. It has outlived every rival clever enough to try and out-talk it, and it delights, endlessly, in reminding them so.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has out-riddled the same three liches for three straight centuries."}, {"n": 2, "band": "Grounded", "text": "Its canyon lair echoes every joke back, timed for maximum effect."}, {"n": 3, "band": "Grounded", "text": "Collects centuries-old comedic feuds, still actively pursuing revenge."}, {"n": 4, "band": "Grounded", "text": "Speaks fluent nonsense to confuse would-be interrogators, on purpose."}, {"n": 5, "band": "Grounded", "text": "Age has turned its scales a deep, oxidized green-copper patina."}, {"n": 6, "band": "Textured", "text": "A wing scar shaped exactly like an old, famous riddle's punchline."}, {"n": 7, "band": "Strange", "text": "Its breath weapon now makes victims laugh in perfect, eerie unison."}, {"n": 8, "band": "Mythic", "text": "Has trained an entire canyon's echo into a chorus that answers its jokes."}]}},
 "ancient-green-dragon": {"desc": "Centuries of quiet manipulation have made it patient past cruelty — it no longer needs to threaten, only to imply. Its scales have gone near-black with age beneath the poison fog, and the puppet courts and corrupted councils it has built stretch across whole regions now, most of them unaware they answer to a dragon at all. It considers honesty a tool for lesser minds.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has quietly ruled three generations of the same noble house, unseen."}, {"n": 2, "band": "Grounded", "text": "Age has darkened its scales to near-black beneath the poison sheen."}, {"n": 3, "band": "Grounded", "text": "Keeps flawless records of every secret it has ever purchased."}, {"n": 4, "band": "Grounded", "text": "Prefers ruin engineered slowly over destruction dealt quickly."}, {"n": 5, "band": "Grounded", "text": "Its network of blackmailed informants spans entire kingdoms now."}, {"n": 6, "band": "Textured", "text": "An old jaw wound has fused into a permanent, unreadable smile."}, {"n": 7, "band": "Strange", "text": "Its fog carries whispered fragments of centuries of old lies."}, {"n": 8, "band": "Mythic", "text": "Effectively rules a kingdom through puppets who believe every decision is their own."}]}},
 "ancient-red-dragon": {"desc": "It is the fire at the top of every story told about dragons, and it knows this, and it is furious that anyone still doubts it. Centuries have deepened its scales to a burnt, blackened crimson and hardened its pride into something closer to a law of nature. Mountains have reshaped around its hoard. Kingdoms have risen and fallen paying it tribute. It considers this only fitting.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has outlived and outlasted three separate empires built to slay it."}, {"n": 2, "band": "Grounded", "text": "Its hoard has fused into the mountain itself after centuries of heat."}, {"n": 3, "band": "Grounded", "text": "Demands its full, ancient title recited before any conversation."}, {"n": 4, "band": "Grounded", "text": "Scales have blackened at the edges, burnt by its own ancient breath."}, {"n": 5, "band": "Grounded", "text": "Keeps the bones of every hero who ever challenged it, labeled."}, {"n": 6, "band": "Textured", "text": "A horn snapped in a duel so old the story has become legend."}, {"n": 7, "band": "Strange", "text": "The mountain itself rumbles faintly whenever its pride is wounded."}, {"n": 8, "band": "Mythic", "text": "Its wrath alone has erased whole villages from every subsequent map."}]}},
 "ancient-silver-dragon": {"desc": "It has walked among mortals for so long that grief has become part of its bearing, a weight carried alongside genuine, unshaken kindness. Centuries of cold mountain vigilance have not calloused it — if anything, it feels every loss more sharply for having lived through so many. Its frost can end an army in a breath. Its memory holds every name it has ever failed to save.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has worn the same mortal disguise for so long it feels like a second self."}, {"n": 2, "band": "Grounded", "text": "Keeps a centuries-old shrine to every mortal companion it has outlived."}, {"n": 3, "band": "Grounded", "text": "Politely corrects historians' accounts of its own past deeds, gently."}, {"n": 4, "band": "Grounded", "text": "Age has silvered its scales past white, nearly translucent at the edges."}, {"n": 5, "band": "Grounded", "text": "Nests among peaks it has personally reshaped over centuries of patience."}, {"n": 6, "band": "Textured", "text": "A wing-scar frost-white and permanent, from a battle centuries past."}, {"n": 7, "band": "Strange", "text": "Snow near its lair holds the shape of footprints long since gone."}, {"n": 8, "band": "Mythic", "text": "Has quietly guarded the same bloodline of mortal descendants for ten generations."}]}},
 "ancient-white-dragon": {"desc": "Centuries in the deep cold have not made it wiser, only larger, older, and more absolute in its savagery. It is the least clever of the true dragons and, by far, the most feared for it — pure animal territoriality magnified by scale and age until entire mountain ranges belong to it by right of surviving there longest. It does not scheme. It simply endures, and destroys what doesn't yield.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has claimed and defended the same glacier for uncounted generations."}, {"n": 2, "band": "Grounded", "text": "Its hoard is buried chaos, nothing sorted, nothing named, everything hers."}, {"n": 3, "band": "Grounded", "text": "Fights every rival predator on sight, out of pure inherited habit."}, {"n": 4, "band": "Grounded", "text": "Scales have gone nearly translucent-white, ancient beyond memory."}, {"n": 5, "band": "Grounded", "text": "Marks vast territory in frozen carcasses, an entire range of warnings."}, {"n": 6, "band": "Textured", "text": "Deep, old scarring along one flank, evidence of a decades-long feud."}, {"n": 7, "band": "Strange", "text": "Ice near its lair forms unnervingly perfect, ancient crystalline shapes."}, {"n": 8, "band": "Mythic", "text": "Commands an entire glacier's worth of half-tamed predators as its pack."}]}},
 "black-dragon-wyrmling": {"desc": "It is young enough to still be reckless, coiled half-submerged in swamp muck with scales still glossy and unscarred. It hisses more than it needs to and strikes before it's fully sure of the threat, hunger outpacing patience. The acid on its breath is already lethal, even if the cunning to wield it properly hasn't quite caught up yet.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Attacks impulsively, still learning to judge a fight before starting one."}, {"n": 2, "band": "Grounded", "text": "Scales still glossy-new, unscarred by any real battle yet."}, {"n": 3, "band": "Grounded", "text": "Hoards shiny trash indiscriminately, unable to tell junk from gold."}, {"n": 4, "band": "Grounded", "text": "Hides badly, tail or wingtip always visible above the waterline."}, {"n": 5, "band": "Grounded", "text": "Mimics an adult's menacing hiss, voice still cracking with youth."}, {"n": 6, "band": "Textured", "text": "A single scale already scarred pale, some early misjudged fight."}, {"n": 7, "band": "Strange", "text": "Marsh gas ignites faintly around it when it gets overexcited."}, {"n": 8, "band": "Volatile", "text": "Has already lured a small gang of bog-things into loose, chaotic service."}]}},
 "blue-dragon-wyrmling": {"desc": "Static crackles faintly across its scales as it bursts from a dune, still more eager than dangerous, still testing how much authority its size can command. It postures like the adults it's seen, imperious and certain, though its voice hasn't quite found the weight to back it. Lightning already answers its temper, unpredictably, before it's learned real control.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Postures with adult imperiousness it hasn't yet earned the size for."}, {"n": 2, "band": "Grounded", "text": "Static discharge sparks unpredictably when it's startled or excited."}, {"n": 3, "band": "Grounded", "text": "Burrows shallow, betraying its position with a visible dune ridge."}, {"n": 4, "band": "Grounded", "text": "Demands respect from creatures clearly too large to grant it."}, {"n": 5, "band": "Grounded", "text": "Practices its roar alone, unaware anything is listening."}, {"n": 6, "band": "Textured", "text": "Scorch-marks from its own misfired breath streak one flank."}, {"n": 7, "band": "Strange", "text": "Small storm clouds gather overhead whenever it's genuinely angry."}, {"n": 8, "band": "Volatile", "text": "Has already claimed a scrap of desert too large for it to actually defend."}]}},
 "brass-dragon-wyrmling": {"desc": "It talks before it's even fully out of hiding, tumbling over its own words with an eagerness that hasn't yet learned restraint. Sun flashes bright off scales barely into their adult color, and it seems more interested in an audience than a fight. Every stranger is a potential new friend, or at least a new captive listener for its half-finished stories.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Talks nonstop, forgetting entirely why it approached in the first place."}, {"n": 2, "band": "Grounded", "text": "Follows travelers for miles just to keep a conversation going."}, {"n": 3, "band": "Grounded", "text": "Naps mid-sentence, exhausted from its own enthusiasm."}, {"n": 4, "band": "Grounded", "text": "Collects half-true rumors it repeats as settled fact."}, {"n": 5, "band": "Grounded", "text": "Genuinely hurt when someone would rather fight than chat."}, {"n": 6, "band": "Textured", "text": "A small scar across one nostril from an old sibling squabble."}, {"n": 7, "band": "Strange", "text": "Occasionally repeats phrases in a voice not quite its own."}, {"n": 8, "band": "Volatile", "text": "Has adopted a small pack of desert jackals as an eager, unruly audience."}]}},
 "bronze-dragon-wyrmling": {"desc": "It breaches the surf clumsily, still more curious than commanding, watching ships pass with the careful attention of something learning what it's meant to protect. Storm-grey scales have yet to fully darken into adult bronze, and its instincts toward fairness are strong but untested. It wants, badly, to matter to someone the way the old stories say bronze dragons matter.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Follows fishing boats at a distance, unsure how to introduce itself."}, {"n": 2, "band": "Grounded", "text": "Practices disguising as driftwood, not yet convincingly."}, {"n": 3, "band": "Grounded", "text": "Intervenes in small disputes clumsily, meaning well, causing chaos."}, {"n": 4, "band": "Grounded", "text": "Scales still show patches of storm-grey beneath emerging bronze."}, {"n": 5, "band": "Grounded", "text": "Collects lost fishing gear, unsure what to do with any of it."}, {"n": 6, "band": "Textured", "text": "A small coral scar along one claw from an early sea-cave mishap."}, {"n": 7, "band": "Strange", "text": "Local gulls have started following it, unprompted, as if trusting it."}, {"n": 8, "band": "Volatile", "text": "Has appointed itself guardian of a coastline it cannot yet properly defend."}]}},
 "copper-dragon-wyrmling": {"desc": "It bounds down canyon rock with more enthusiasm than grace, already delighted by its own half-formed jokes even when no one laughs. Copper scales are still bright and unweathered, and its cunning is more mischief than menace so far — testing what tricks work, what riddles land, what gets a rise out of bigger things.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Tells riddles with obvious answers, delighted anyway at the attempt."}, {"n": 2, "band": "Grounded", "text": "Practices pranks on creatures too dangerous for the joke to land safely."}, {"n": 3, "band": "Grounded", "text": "Hides badly behind rocks too small to actually conceal it."}, {"n": 4, "band": "Grounded", "text": "Repeats an adult copper's famous joke, timing not quite right yet."}, {"n": 5, "band": "Grounded", "text": "Collects shiny pebbles it insists are treasure of real significance."}, {"n": 6, "band": "Textured", "text": "A small burn scar from its own acid, misjudged and too close."}, {"n": 7, "band": "Strange", "text": "Its laugh echoes back changed, a beat behind, from empty canyon."}, {"n": 8, "band": "Volatile", "text": "Has recruited a small mob of canyon goats into a chaotic prank scheme."}]}},
 "dragon-turtle": {"desc": "The water breaks wrong before it surfaces, a shell like a drowned island rising out of the swell, barnacled and ancient. Steam hisses from its jaws even at rest, and its temperament is closer to a force of weather than a creature with grievances. It does not chase. It simply owns whatever patch of sea it has claimed, and anything crossing that water pays a toll it never announces in advance.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Surfaces beneath ships slowly, capsizing them before any warning."}, {"n": 2, "band": "Grounded", "text": "Shell crusted so thick with barnacles it resembles a small reef."}, {"n": 3, "band": "Grounded", "text": "Steam venting constantly from its jaws, even in calm, restful water."}, {"n": 4, "band": "Grounded", "text": "Territory marked by wreckage, scattered deliberately as a warning."}, {"n": 5, "band": "Grounded", "text": "Sleeps for years at a stretch, mistaken by sailors for an islet."}, {"n": 6, "band": "Textured", "text": "A crack runs deep across its shell, sealed by decades of scar-growth."}, {"n": 7, "band": "Strange", "text": "The water above it boils faintly even when it means no harm."}, {"n": 8, "band": "Volatile", "text": "Has claimed an entire shipping lane, and merchant fleets now quietly pay tribute."}]}},
 "faerie-dragon": {"desc": "It flickers into and out of sight between the leaves, no bigger than a housecat, wings a blur of dragonfly color. Everything about it is delight — mischief without malice, jokes that land soft even when the target doesn't laugh. It is older and stranger than its size suggests, fey-touched in ways that make its games faintly dangerous even when its intentions never are.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Scale color shifts faintly with its mood, brightest when delighted."}, {"n": 2, "band": "Grounded", "text": "Steals small shiny objects purely to watch the owner search for them."}, {"n": 3, "band": "Grounded", "text": "Giggles uncontrollably mid-invisibility, giving away its position."}, {"n": 4, "band": "Grounded", "text": "Follows the funniest creature in a group, ignoring the rest entirely."}, {"n": 5, "band": "Grounded", "text": "Hoards ribbons, buttons, and other harmless, colorful trinkets."}, {"n": 6, "band": "Textured", "text": "One wing is faintly torn, mended crooked, from an old prank gone wrong."}, {"n": 7, "band": "Strange", "text": "Leaves a faint trail of drifting motes wherever it flies unseen."}, {"n": 8, "band": "Volatile", "text": "Has befriended a fey patron who occasionally answers on its behalf."}]}},
 "faerie-dragon-youth": {"desc": "Smaller still than its elders, all wide eyes and unsteady flight, it tumbles through underbrush chasing its own idea of a joke before it's fully landed one. Its magic is still clumsy, invisibility flickering in and out at the worst moments, but its delight is total and entirely without malice. It hasn't learned yet that not everyone finds it as funny as it does.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Invisibility flickers unreliably, especially when it's excited."}, {"n": 2, "band": "Grounded", "text": "Practices adult pranks clumsily, punchline rarely landing right."}, {"n": 3, "band": "Grounded", "text": "Follows the loudest creature in a group, assuming they're in charge."}, {"n": 4, "band": "Grounded", "text": "Hoards a single treasured object it refuses to explain the value of."}, {"n": 5, "band": "Grounded", "text": "Tumbles mid-flight often, still learning its own wingspan."}, {"n": 6, "band": "Textured", "text": "A small scuff mars one wing from an early, clumsy landing."}, {"n": 7, "band": "Strange", "text": "Occasionally repeats an adult faerie dragon's phrase, verbatim, confused."}, {"n": 8, "band": "Volatile", "text": "Has attached itself, uninvited, to whatever creature it finds funniest."}]}},
 "gold-dragon-roster-5e-2024-mechanics": {"desc": "It descends into the worst of a bad situation like a promise finally kept, gold scales catching light like struck coin, and its first instinct is always to help before it is ever to judge. Gold dragons believe the world can still be made better and spend centuries proving it — wearing a peddler's face to nudge a village toward kindness, or a beggar's rags to see who still shares bread with nothing to gain. Only when the stakes turn dire does it reveal what it actually is.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears a beggar's disguise for years, quietly testing a town's kindness."}, {"n": 2, "band": "Grounded", "text": "Funds a struggling healer's clinic anonymously, through a merchant proxy."}, {"n": 3, "band": "Grounded", "text": "Keeps meticulous records of every promise made and kept nearby."}, {"n": 4, "band": "Grounded", "text": "Pays informants generously for news of injustice, never for gossip."}, {"n": 5, "band": "Grounded", "text": "Nests atop sunlit peaks visible for miles, hiding from nothing."}, {"n": 6, "band": "Textured", "text": "A scale-cluster along its chest is scorched dull from an old duel."}, {"n": 7, "band": "Strange", "text": "Sunlight seems to gather and linger wherever it chooses to rest."}, {"n": 8, "band": "Mythic", "text": "Secretly patronizes an entire generation of idealistic adventurers."}]}},
 "green-dragon-wyrmling": {"desc": "It slips through undergrowth barely disturbing a leaf, poison-green scales already good camouflage even this young. Its manipulations are clumsier than an adult's — half-formed lies, obvious tells — but the instinct toward deceit runs bone-deep already. It watches more than it acts, patient in a way that feels unnatural for something so newly hatched.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Tells lies transparent to anyone paying real attention, not yet skilled."}, {"n": 2, "band": "Grounded", "text": "Watches from cover far longer than any real threat requires."}, {"n": 3, "band": "Grounded", "text": "Practices an adult's manipulative tone, voice not quite convincing yet."}, {"n": 4, "band": "Grounded", "text": "Camouflage is nearly perfect already, unusually skilled for its age."}, {"n": 5, "band": "Grounded", "text": "Collects small secrets from forest creatures, unsure what to do with them."}, {"n": 6, "band": "Textured", "text": "A scale patch along its tail is pale, still healing from some early scrape."}, {"n": 7, "band": "Strange", "text": "Its poison fog occasionally drifts on its own, without its breath."}, {"n": 8, "band": "Volatile", "text": "Has already turned two forest creatures into unwitting, whispering spies."}]}},
 "half-dragon": {"desc": "Something in the jawline, the eyes, the faint sheen along the skin gives it away before the claws do. It carries draconic blood as both inheritance and burden, stronger and stranger than its fully mortal kin, treated by both worlds as neither one thing nor the other. Pride and isolation sit close together in it, a chip carried since childhood that never quite wore smooth.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Skin bears a faint, scaled sheen visible only in direct light."}, {"n": 2, "band": "Grounded", "text": "Was raised in a mortal settlement that never fully accepted it."}, {"n": 3, "band": "Grounded", "text": "Carries an old grudge against the dragon parent it never met."}, {"n": 4, "band": "Grounded", "text": "Eyes have gone reptilian-slit, disguised poorly behind a hood."}, {"n": 5, "band": "Grounded", "text": "Trained hard to master its breath weapon, still unreliable under stress."}, {"n": 6, "band": "Textured", "text": "Claw-marks scar its own forearms, self-inflicted in early rage."}, {"n": 7, "band": "Strange", "text": "Dreams, by its own account, in a language it's never been taught."}, {"n": 8, "band": "Volatile", "text": "Has begun actively seeking out its dragon parent's old hoard, alone."}]}},
 "juvenile-shadow-dragon": {"desc": "It moves like smoke through the deep dark, still learning how thin it can stretch between shadows before losing itself entirely. Corruption has already claimed most of its color, scales gone grey-black and porous, but the hunger for sunlight's absence hasn't fully calcified into hatred yet. It is dangerous mostly because it hasn't learned patience — it strikes too soon, too eager.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Strikes too early, still learning to let prey wander deeper into dark."}, {"n": 2, "band": "Grounded", "text": "Scales have gone porous-grey, corruption not yet complete."}, {"n": 3, "band": "Grounded", "text": "Flinches from torchlight more than an adult shadow dragon would."}, {"n": 4, "band": "Grounded", "text": "Practices merging with shadow clumsily, occasionally visibly overlapping."}, {"n": 5, "band": "Grounded", "text": "Hoards nothing valuable yet, mostly bones and broken things."}, {"n": 6, "band": "Textured", "text": "A patch of scale still holds its original color, unclaimed by dark."}, {"n": 7, "band": "Strange", "text": "Its shadow moves independently sometimes, a beat behind its body."}, {"n": 8, "band": "Volatile", "text": "Has begun corrupting a small patch of cavern life into pale, twisted mockeries."}]}},
 "pseudodragon": {"desc": "It perches watchful in low branches, cat-sized and clever-eyed, tail stinger curled ready before it decides whether you're friend or threat. Loyalty, once earned, runs deep and genuine — pseudodragons bond hard, and their telepathy makes them uncannily good confidants. But their judgment of character is sharp, and they do not suffer being underestimated gladly.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Judges strangers instantly and rarely reconsiders the first impression."}, {"n": 2, "band": "Grounded", "text": "Prefers perching on shoulders, uninvited, once trust is earned."}, {"n": 3, "band": "Grounded", "text": "Communicates almost entirely through expression and posture, silent."}, {"n": 4, "band": "Grounded", "text": "Hoards small shiny trinkets in a hollow only it can reach."}, {"n": 5, "band": "Grounded", "text": "Fiercely protective of one bonded creature, cold to everyone else."}, {"n": 6, "band": "Textured", "text": "A notch in one ear-frill from an old scuffle with a larger predator."}, {"n": 7, "band": "Strange", "text": "Seems to sense a companion's mood before they've noticed it themselves."}, {"n": 8, "band": "Volatile", "text": "Has quietly bonded to a mortal it's followed, unseen, for years."}]}},
 "red-dragon-wyrmling": {"desc": "Heat radiates off it even asleep, scales already the deep red of banked coals, and its temper flares faster than any true adult would allow. It has not yet learned to savor cruelty — it simply reacts, hot and immediate, burning first and posturing after. Ambition is already there, oversized for its body, a hunger to be feared long before it's earned the size to deserve it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Burns first, postures after, temper outrunning any real strategy."}, {"n": 2, "band": "Grounded", "text": "Claims territory far larger than it can actually defend yet."}, {"n": 3, "band": "Grounded", "text": "Practices an adult's imperious tone, voice cracking under the effort."}, {"n": 4, "band": "Grounded", "text": "Hoard is small and disorganized, mostly warm, shiny rocks."}, {"n": 5, "band": "Grounded", "text": "Picks fights with creatures well above its actual size, out of pride."}, {"n": 6, "band": "Textured", "text": "Scorch-scarring mars its own snout from an early breath misfire."}, {"n": 7, "band": "Strange", "text": "Small stones near its den occasionally glow faintly from residual heat."}, {"n": 8, "band": "Volatile", "text": "Has already claimed a mountain pass too large and too visible for its own safety."}]}},
 "ridden-wyvern": {"desc": "Saddle leather creaks against scale as it banks hard over the ridge, a rider's weight changing everything about how it fights and flies. It is not tame, not really — only trained, and only barely, by whoever's brave or foolish enough to have broken it to the harness. Its stinger still remembers its own instincts even mid-command, and both rider and mount know it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Fights harness commands visibly when its stinger-instinct disagrees."}, {"n": 2, "band": "Grounded", "text": "Rider bears old scars from earlier, less successful training attempts."}, {"n": 3, "band": "Grounded", "text": "Saddle is jury-rigged, patched with mismatched leather and rope."}, {"n": 4, "band": "Grounded", "text": "Screeches on landing, still resentful of the harness after years of use."}, {"n": 5, "band": "Grounded", "text": "Obeys only its bonded rider, ignoring all other commands entirely."}, {"n": 6, "band": "Textured", "text": "A saddle-scar along its back has never fully grown scale over."}, {"n": 7, "band": "Strange", "text": "Seems to anticipate its rider's commands a half-second early."}, {"n": 8, "band": "Volatile", "text": "Its rider has clearly lost real control, and the wyvern is testing the leash."}]}},
 "shadow-dragon": {"desc": "It arrives as an absence first, a wrongness in the dark that swallows torchlight before the eye can find its edges. Corruption has stripped it of true color, scales gone to ash-grey nothing, and centuries in the deep dark have made it patient in a way that feels less like cunning and more like erosion. Sunlight is agony to it now, and it has come to hate the mortal world for holding so much of it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Merges seamlessly with darkness, only breath-sound betraying its presence."}, {"n": 2, "band": "Grounded", "text": "Its lair holds no light sources at all, not even embers."}, {"n": 3, "band": "Grounded", "text": "Speaks rarely, voice a dry rasp long unused to conversation."}, {"n": 4, "band": "Grounded", "text": "Hoard is coated in undisturbed dust, untouched for generations."}, {"n": 5, "band": "Grounded", "text": "Avoids any passage lit even faintly, rerouting far out of its way."}, {"n": 6, "band": "Textured", "text": "Ash-grey scales are patched paler where old color still clings."}, {"n": 7, "band": "Strange", "text": "Its shadow persists faintly even after the dragon itself has moved."}, {"n": 8, "band": "Volatile", "text": "Has corrupted an entire cavern ecosystem into pale, light-fearing mockeries."}]}},
 "silver-dragon-wyrmling": {"desc": "It watches from a mountain ledge with an attentiveness older than its years, curious about mortals in a way that hasn't yet hardened into the grief the adults carry. Frost breath is already sharp, but its instincts toward kindness are still untested, still eager to be proven right about the world. It wants, more than anything, to matter to someone.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Watches mortal travelers for hours, unsure how to approach them."}, {"n": 2, "band": "Grounded", "text": "Practices a human disguise clumsily, not yet fully convincing."}, {"n": 3, "band": "Grounded", "text": "Genuinely distressed by cruelty it witnesses, still learning to intervene."}, {"n": 4, "band": "Grounded", "text": "Frost patterns from its breath are erratic, still finding real control."}, {"n": 5, "band": "Grounded", "text": "Collects small kindnesses shown to it, remembers every one."}, {"n": 6, "band": "Textured", "text": "A small frost-scar along one wing from an early hunting mishap."}, {"n": 7, "band": "Strange", "text": "Snow near its perch never quite melts, even this young."}, {"n": 8, "band": "Volatile", "text": "Has attached itself, uninvited, to a mortal it's decided needs protecting."}]}},
 "white-dragon-wyrmling": {"desc": "It is already savage past its size, snapping and territorial over a scrap of frozen ground it can barely defend. Instinct runs hot beneath the cold scales — no scheming, no patience, just hunger and claim-staking older than reason. It has not learned fear yet, which makes it reckless, and dangerous in ways an adult's caution would temper.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Claims territory far too large for it to actually defend."}, {"n": 2, "band": "Grounded", "text": "Snarls and postures before any real assessment of the threat."}, {"n": 3, "band": "Grounded", "text": "Attacks larger creatures out of instinct, not calculation."}, {"n": 4, "band": "Grounded", "text": "Hoard is small, chaotic, mostly frozen scraps and bone."}, {"n": 5, "band": "Grounded", "text": "Burrows shallow beneath snowpack, betrayed by a visible mound."}, {"n": 6, "band": "Textured", "text": "Missing scale patch from an early, losing scrap with a wolf pack."}, {"n": 7, "band": "Strange", "text": "Ice near its den forms oddly regular patterns already, unexplained."}, {"n": 8, "band": "Volatile", "text": "Has picked a fight with something far too big, and hasn't noticed yet."}]}},
 "wyvern": {"desc": "It hangs on the wind above the ridgeline, a silhouette all wings and tail, stinger cocked and ready before it's even decided to strike. Duller-witted than true dragons and far more dangerous for the difference — it hunts on pure appetite, territorial and unpredictable, with none of a dragon's patience to temper the violence. Anything that lingers too long below it becomes a target.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Circles prey for long minutes, judging size before committing to a dive."}, {"n": 2, "band": "Grounded", "text": "Nests on inaccessible crags littered with picked-clean bones."}, {"n": 3, "band": "Grounded", "text": "Attacks anything that moves too quickly below its hunting range."}, {"n": 4, "band": "Grounded", "text": "Territorial screech carries for miles, warning off rival predators."}, {"n": 5, "band": "Grounded", "text": "Stinger drips visibly, poison always primed and ready."}, {"n": 6, "band": "Textured", "text": "A torn wing-membrane, healed ragged from some old aerial fight."}, {"n": 7, "band": "Strange", "text": "Hunts in eerie, deliberate silence, wings making no sound at all."}, {"n": 8, "band": "Volatile", "text": "Has begun hoarding livestock in a cache far larger than it can eat."}]}},
 "young-black-dragon": {"desc": "It has learned patience since hatching, cunning sharpening alongside its acid breath, scales darkening toward true adult black. Cruelty has become deliberate now, not just instinct — it savors a slow kill more than a quick one, testing how much fear it can wring from something before finishing it. The swamp already answers to it, in its own small way.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Draws out a kill deliberately now, having learned to savor the fear."}, {"n": 2, "band": "Grounded", "text": "Scales have darkened toward true adult black, nearly complete."}, {"n": 3, "band": "Grounded", "text": "Has claimed a proper lair, modest but genuinely defended now."}, {"n": 4, "band": "Grounded", "text": "Speaks with calculated menace, voice steadier than a wyrmling's."}, {"n": 5, "band": "Grounded", "text": "Hoard is organized now, sorted by value, no longer chaotic."}, {"n": 6, "band": "Textured", "text": "A scar along one flank from its first real, near-fatal fight."}, {"n": 7, "band": "Strange", "text": "Marsh gas ignites reliably now around its rising temper."}, {"n": 8, "band": "Volatile", "text": "Has bent a small band of bog-creatures into genuine, fearful service."}]}},
 "young-blue-dragon": {"desc": "Its authority has solidified since the wyrmling years, lightning under better control now, imperious posturing backed by real threat. It has claimed a proper stretch of desert and defends it with a confidence that finally matches its size. Static still crackles at its temper's edge, but there's real calculation behind the theater now.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Demands proper address now, confident its size finally backs the claim."}, {"n": 2, "band": "Grounded", "text": "Lightning control has sharpened, strikes precise rather than wild."}, {"n": 3, "band": "Grounded", "text": "Burrows deeper now, ambushes calculated rather than impulsive."}, {"n": 4, "band": "Grounded", "text": "Has claimed a genuine stretch of desert, patrolled with real discipline."}, {"n": 5, "band": "Grounded", "text": "Hoard is growing organized, tribute sorted and properly displayed."}, {"n": 6, "band": "Textured", "text": "A fused horn-crack from an early territorial duel, now settled."}, {"n": 7, "band": "Strange", "text": "Storm clouds gather reliably now whenever its temper flares."}, {"n": 8, "band": "Volatile", "text": "Has begun extorting a small caravan route for regular tribute."}]}},
 "young-brass-dragon": {"desc": "Its stories have gotten longer and more elaborate, and its confidence in telling them has sharpened into genuine charisma. It still prefers talk to violence, but there's real menace now behind the friendliness if a listener proves too dull or too rude. Sun-bright scales have settled fully into adult brass, and its gossip network has grown surprisingly wide for something still this young.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Tells stories with real skill now, holding an audience genuinely rapt."}, {"n": 2, "band": "Grounded", "text": "Has built an actual gossip network spanning several desert settlements."}, {"n": 3, "band": "Grounded", "text": "Turns sharply hostile if bored or interrupted mid-story, now credibly."}, {"n": 4, "band": "Grounded", "text": "Naps in deliberate ambush positions, sand-buried, awaiting company."}, {"n": 5, "band": "Grounded", "text": "Trades favors for information with real, calculated shrewdness."}, {"n": 6, "band": "Textured", "text": "A scar along one flank from testing a rival's patience too far."}, {"n": 7, "band": "Strange", "text": "Recalls entire conversations verbatim from years prior, unnervingly."}, {"n": 8, "band": "Volatile", "text": "Has recruited a loose network of desert nomads as willing informants."}]}},
 "young-bronze-dragon": {"desc": "It patrols its stretch of coast now with real purpose, storm-grey darkened fully into proper bronze, instincts toward fairness sharpened into genuine judgment. Ships have started to recognize it, and some captains leave small offerings out of respect rather than fear. It has learned the weight of the role it's growing into, and it wears that weight seriously.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Patrols its coastline with real, established purpose now."}, {"n": 2, "band": "Grounded", "text": "Ships leave small offerings, having learned to recognize it by sight."}, {"n": 3, "band": "Grounded", "text": "Interrogates suspected wrongdoers with genuine, patient judgment."}, {"n": 4, "band": "Grounded", "text": "Has claimed a proper sea cave, defended and increasingly organized."}, {"n": 5, "band": "Grounded", "text": "Disguises convincingly as driftwood now, ambush finally viable."}, {"n": 6, "band": "Textured", "text": "A coral-fused claw from an early, hard-won sea skirmish."}, {"n": 7, "band": "Strange", "text": "Gulls nest along its spine as if it's simply part of the coast now."}, {"n": 8, "band": "Volatile", "text": "Has begun coordinating with a small pod of dolphins as genuine scouts."}]}},
 "young-copper-dragon": {"desc": "Its jokes have gotten sharper, its timing better, and there's real menace now beneath the mischief if the target proves humorless. Canyon country has become fully its own, and it moves through the rock with a confidence that finally matches the cunning behind its eyes. It still delights in a good riddle, but it's learned to make the stakes real.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Riddles now carry real stakes, answered wrong at genuine cost."}, {"n": 2, "band": "Grounded", "text": "Has claimed canyon country fully, echo chambers built with purpose."}, {"n": 3, "band": "Grounded", "text": "Timing has sharpened; its jokes actually land on strangers now."}, {"n": 4, "band": "Grounded", "text": "Keeps a genuine, growing ledger of insults owed and repaid."}, {"n": 5, "band": "Grounded", "text": "Trades secrets for laughter with real, calculated shrewdness."}, {"n": 6, "band": "Textured", "text": "A translucent-patched wing scar from an early canyon mishap."}, {"n": 7, "band": "Strange", "text": "Its breath weapon reliably leaves victims giggling now, refined."}, {"n": 8, "band": "Volatile", "text": "Has trained a proper chorus of ravens into a mocking, echoing choir."}]}},
 "young-green-dragon": {"desc": "Its lies have gotten smoother, its patience genuinely dangerous now, manipulations sharpened past the wyrmling's clumsy tells. Forest and swamp answer to it in small, quiet ways already, informants recruited, small debts called in. It has learned that ruin engineered slowly tastes better than ruin dealt quickly, and it savors the difference.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Lies smoothly now, tells from the wyrmling years long since worked out."}, {"n": 2, "band": "Grounded", "text": "Has recruited real informants, small debts called in with precision."}, {"n": 3, "band": "Grounded", "text": "Camouflage has sharpened to near-adult skill, ambush reliable now."}, {"n": 4, "band": "Grounded", "text": "Prefers slow ruin over fast violence, savoring the longer game."}, {"n": 5, "band": "Grounded", "text": "Keeps growing records of secrets purchased from forest creatures."}, {"n": 6, "band": "Textured", "text": "A healed scar along its tail from an early, costly territorial fight."}, {"n": 7, "band": "Strange", "text": "Its poison fog occasionally drifts unbidden near old lie-sites."}, {"n": 8, "band": "Volatile", "text": "Has turned several forest creatures into a genuine, whispering spy network."}]}},
 "young-red-dragon": {"desc": "Its temper has calcified into real pride now, ambition matching a size that finally commands genuine fear. It has claimed a mountain pass and defended it hard enough that word has started to spread. The heat off its scales has settled into a steady, banked burn, less reckless than the wyrmling years, more deliberate about when it chooses to punish.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has claimed a mountain pass, and word of it is finally spreading."}, {"n": 2, "band": "Grounded", "text": "Postures with real, earned pride now, confidence matching its size."}, {"n": 3, "band": "Grounded", "text": "Deliberates before burning now, punishment calculated, not reflexive."}, {"n": 4, "band": "Grounded", "text": "Hoard is organized properly now, tribute sorted and displayed."}, {"n": 5, "band": "Grounded", "text": "Demands recognition from travelers who clearly haven't heard of it yet."}, {"n": 6, "band": "Textured", "text": "A scorched, healed scar from its first genuinely dangerous fight."}, {"n": 7, "band": "Strange", "text": "Stones near its den glow faintly now, residual heat building steadily."}, {"n": 8, "band": "Volatile", "text": "Has begun demanding tribute from a nearby settlement, and they're paying."}]}},
 "young-silver-dragon": {"desc": "It has learned to wear a mortal disguise convincingly now, kindness sharpened by real experience rather than just eager instinct. Frost control has settled, precise where the wyrmling years were erratic, and it has started to understand the grief the true adults carry. It seeks out injustice deliberately now, no longer waiting to be asked.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears a mortal disguise convincingly now, passing without notice."}, {"n": 2, "band": "Grounded", "text": "Seeks out injustice deliberately, no longer waiting to be asked."}, {"n": 3, "band": "Grounded", "text": "Frost control has sharpened, precise rather than erratic."}, {"n": 4, "band": "Grounded", "text": "Has begun collecting real allies among mortals it's helped."}, {"n": 5, "band": "Grounded", "text": "Understands, now, some of the grief the older silvers carry."}, {"n": 6, "band": "Textured", "text": "A healed frost-scar from a genuinely dangerous early rescue."}, {"n": 7, "band": "Strange", "text": "Snow near its territory has started refusing to melt at all."}, {"n": 8, "band": "Volatile", "text": "Has bonded properly to a mortal companion it now actively protects."}]}},
 "young-white-dragon": {"desc": "Savagery has hardened into genuine territorial confidence now, claim-staking backed by real size and real violence. It has learned nothing of cunning in the years since hatching — only that bigger claims require bigger fights, and it has started winning those fights outright. The frozen range it's claimed has grown, and it defends every inch of it without hesitation.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Has expanded its claimed territory, winning fights it used to lose."}, {"n": 2, "band": "Grounded", "text": "Defends every inch without hesitation, confidence fully earned now."}, {"n": 3, "band": "Grounded", "text": "Hoard has grown chaotic but larger, still utterly unsorted."}, {"n": 4, "band": "Grounded", "text": "Ambushes from beneath snowpack reliably now, patience finally real."}, {"n": 5, "band": "Grounded", "text": "Fights rival predators on sight, territory expanding through violence."}, {"n": 6, "band": "Textured", "text": "A healed scar from a decisive win over a once-dominant rival."}, {"n": 7, "band": "Strange", "text": "Ice near its den forms in disturbingly deliberate, regular shapes."}, {"n": 8, "band": "Volatile", "text": "Has half-tamed a small pack of winter wolves into genuine service."}]}},
 "animated-armor": {"desc": "The armor stands empty and locked at the joints, visor down, as if the man who wore it merely stepped out. When it moves, the plates grind against nothing — no flesh to cushion the hinge — and the sound is worse than a scream because it never stops for breath. It obeys the last order it was given, forever, whether or not anyone remains alive to rescind it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Dented at the breastplate, one pauldron missing; moves with a limp from an old, unrepaired blow."}, {"n": 2, "band": "Grounded", "text": "Freshly polished, oiled at every joint — someone still tends it, or it tends itself."}, {"n": 3, "band": "Grounded", "text": "Wears a torn sigil-tabard over the plate, the house arms scratched out by someone's blade."}, {"n": 4, "band": "Grounded", "text": "Rust has fused the visor half-shut; it fights blind on one side."}, {"n": 5, "band": "Grounded", "text": "Carries a second, smaller helm looped at its belt — a fallen comrade's, never removed."}, {"n": 6, "band": "Textured", "text": "Hums a single flat note through the helm when it walks, on some rhythm it can't stop."}, {"n": 7, "band": "Strange", "text": "Its dents form a face in the metal, and the face is smiling."}, {"n": 8, "band": "Volatile", "text": "Two more suits, empty and slumped in nearby alcoves, straighten as this one is struck."}]}},
 "animated-flying-sword": {"desc": "The blade hangs level in the air the way nothing hanging should, humming faintly at a pitch just under hearing. Whoever it once belonged to is long gone; the sword remembers only the arc of the last swing it was told to make, and it will make that arc again and again until something breaks it. It moves without a hand to guide it, and that is the whole horror of the thing.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Notched along the edge, its flight slightly wobbling, like an old soldier favoring a bad knee."}, {"n": 2, "band": "Grounded", "text": "Wrapped in a fraying scabbard-cord it never sheds, dragging behind it as it flies."}, {"n": 3, "band": "Grounded", "text": "Etched with a maker's mark half-worn to nothing, from a smithy long since cold."}, {"n": 4, "band": "Grounded", "text": "Rings faintly with every swing, a bell-note it can't silence."}, {"n": 5, "band": "Grounded", "text": "Its edge is dull with rust in patches — parries better than it cuts."}, {"n": 6, "band": "Textured", "text": "Circles its target once before striking, as if still saluting an officer no longer there."}, {"n": 7, "band": "Strange", "text": "Leaves a thin line of cold air in its wake that fogs breath for a moment after it passes."}, {"n": 8, "band": "Volatile", "text": "A second sword lifts from the floor nearby to join it mid-fight, unbidden."}]}},
 "animated-rug-of-smothering": {"desc": "It lies flat and unremarkable, patterned in faded reds and golds, exactly like a hundred other rugs in a hundred other halls. Then the weave shivers, edges lifting like a held breath, and it rises to fold itself over whatever stands nearest — patient, silent, absolutely certain of its work. Nothing about it looks dangerous until it is already too late to matter.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Moth-eaten at the corners; drags a faint trail of dust and old thread as it moves."}, {"n": 2, "band": "Grounded", "text": "Bears a bloodstain long since browned into the pattern, from whoever it caught last."}, {"n": 3, "band": "Grounded", "text": "Smells faintly of pipe-smoke and old cedar, like the room it was meant to furnish."}, {"n": 4, "band": "Grounded", "text": "Curls at one corner permanently, unable to lie fully flat — an easier tell for the wary."}, {"n": 5, "band": "Grounded", "text": "Woven with a house crest, still recognizable to anyone who once served that family."}, {"n": 6, "band": "Textured", "text": "Ripples once, gently, testing the floor for footsteps before it commits to a lunge."}, {"n": 7, "band": "Strange", "text": "The pattern rearranges itself slowly over hours, as though re-weaving its own camouflage."}, {"n": 8, "band": "Volatile", "text": "Beneath it, the floor is stacked three rugs deep — all of them waking at once."}]}},
 "arch-hag": {"desc": "She wears three faces in a single sitting and never repeats one twice, courteous as a queen and hungrier than famine underneath. The coven's other daughters defer to her the way storms defer to the front that spawned them, and the debts she's owed span three generations of foolish bargains. When she finally shows her true shape, it is worse than every rumor, and it is the last thing most people see clearly.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Holds a signed bargain-scrip from a local elder, due for collection tonight."}, {"n": 2, "band": "Grounded", "text": "Travels with a bound familiar-crow carrying gossip worth trading for."}, {"n": 3, "band": "Grounded", "text": "Keeps a locked chest of teeth — payment owed from a village that broke its word."}, {"n": 4, "band": "Grounded", "text": "Has cursed a rival witch's daughter and needs a courier too naive to refuse the errand."}, {"n": 5, "band": "Grounded", "text": "Carries a ledger of every promise ever made in her presence, still binding."}, {"n": 6, "band": "Textured", "text": "Wants a specific liar's tongue delivered fresh, in trade for a boon owed."}, {"n": 7, "band": "Strange", "text": "Summoned her coven-sisters here for a rite that needs one more living voice to complete."}, {"n": 8, "band": "Volatile", "text": "Holds the true name of someone traveling with the party, and hasn't said so yet."}]}},
 "awakened-shrub": {"desc": "It stands no taller than a child's knee, leaves rustling with a voice too small for the fury behind it. Someone's spell or careless wish gave it thought, and thought gave it grievances — every trampled root, every careless boot, remembered in full. It cannot go far and it cannot do much, but it will absolutely try.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Missing half its leaves from a recent frost; speaks in a thin, shivering rustle."}, {"n": 2, "band": "Grounded", "text": "Grows defiantly in a cracked flowerpot it refuses to be moved from."}, {"n": 3, "band": "Grounded", "text": "Has named itself something grand and insists on being addressed by it."}, {"n": 4, "band": "Grounded", "text": "Bears a single wilted blossom it guards fiercely as a point of pride."}, {"n": 5, "band": "Grounded", "text": "Trembles constantly, whether from fear, cold, or contained rage no one can tell."}, {"n": 6, "band": "Textured", "text": "Keeps a court of woodlice and beetles it calls its subjects, and consults before deciding anything."}, {"n": 7, "band": "Strange", "text": "Its roots have grown into the shape of a small hand, fingers curled as if reaching."}, {"n": 8, "band": "Volatile", "text": "Every shrub in the row nearby stirs and turns the same direction at once."}]}},
 "awakened-tree": {"desc": "Bark splits where a mouth has learned to work, and roots that once merely drank now flex like knuckles finding their grip. It has watched this ground for centuries in silence, and awakening did not make it kinder — only louder, and slower to forgive. When it decides to move, the whole grove seems to hold still and listen.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Split down one side by old lightning, the scar grown over but never healed."}, {"n": 2, "band": "Grounded", "text": "Hung with a dozen forgotten offerings — ribbons, coins, a child's lost toy."}, {"n": 3, "band": "Grounded", "text": "Speaks slowly, one word per breath, as if remembering how language works."}, {"n": 4, "band": "Grounded", "text": "Home to a nest of birds it refuses to disturb even mid-combat."}, {"n": 5, "band": "Grounded", "text": "Bark carved with generations of names and dates, a village's whole memory."}, {"n": 6, "band": "Textured", "text": "Only speaks in riddles about the seasons, expecting patience it rarely gets."}, {"n": 7, "band": "Strange", "text": "Its rings, visible where the bark has peeled, form a face that watches whoever stands closest."}, {"n": 8, "band": "Volatile", "text": "Every tree within sight leans a fraction toward the fight, rootbound but attentive."}]}},
 "blink-dog": {"desc": "It vanishes between one stride and the next, reappearing paces away with tongue lolling, entirely unbothered by having briefly not existed. Packs of them run the borderlands like a joke the world keeps almost getting, herding danger away from travelers too dull to notice they're being protected. Loyalty, to a blink dog, is not earned — it's simply given, the way weather is given.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Circles back twice, clearly trying to lead the party somewhere off the road."}, {"n": 2, "band": "Grounded", "text": "Carries a torn strip of cloth in its teeth, matching a missing traveler's coat."}, {"n": 3, "band": "Grounded", "text": "Limps from a recent wound, a displacer beast's claw-mark fresh on its flank."}, {"n": 4, "band": "Grounded", "text": "Refuses to cross a specific tree-line, growling low at whatever waits beyond it."}, {"n": 5, "band": "Grounded", "text": "Has adopted a lost child from a raided camp, guarding them fiercely."}, {"n": 6, "band": "Textured", "text": "Blinks in short hops toward a hidden den, checking that it's being followed."}, {"n": 7, "band": "Strange", "text": "Its pack-mates blink into view one at a time, forming a ring before anyone notices."}, {"n": 8, "band": "Volatile", "text": "It's fleeing something that blinks faster than it does, and it isn't winning."}]}},
 "brazen-gorgon": {"desc": "Brass plates ripple like muscle over a frame that was never alive to begin with, and heat pours off it in a shimmer that bends the air. It was built, not born, to guard something a smith or sorcerer valued more than any living guard could be trusted to. Its charge ends with fire or with silence, and it has no preference which.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Plates blackened with soot at the seams, venting faint smoke when it exerts itself."}, {"n": 2, "band": "Grounded", "text": "Missing a horn, the stump capped in cooled slag from some old battle."}, {"n": 3, "band": "Grounded", "text": "Etched with a smith's maker-mark, half-melted from its own heat."}, {"n": 4, "band": "Grounded", "text": "Trails a line of scorched grass everywhere it walks, permanent and dead."}, {"n": 5, "band": "Grounded", "text": "Its glow is dimmer than it should be — running cold, running old."}, {"n": 6, "band": "Textured", "text": "Rings like a struck bell before it charges, an alarm it can't help sounding."}, {"n": 7, "band": "Strange", "text": "Frost forms and instantly melts around it in strange patches, as if the air argues with itself."}, {"n": 8, "band": "Volatile", "text": "A second gorgon's brass footprints are already cooling in the dirt nearby."}]}},
 "bugbear-stalker": {"desc": "It moves in complete silence for something so broad-shouldered, a skill it treats like a private joke on every prey animal that ever thought size meant noise. It doesn't kill quickly if it doesn't have to — dragging a struggling captive off into the dark is more satisfying than a clean end. By the time you hear it, you were already caught.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Drags a half-conscious captive bound at the wrists, still alive, still useful."}, {"n": 2, "band": "Grounded", "text": "Wears a trophy necklace of finger-bones from three separate raids."}, {"n": 3, "band": "Grounded", "text": "Left a trail of small, deliberate footprints meant to lure a rescue party."}, {"n": 4, "band": "Grounded", "text": "Carries a stolen ledger of debts it's collecting on behalf of a goblin boss."}, {"n": 5, "band": "Grounded", "text": "Has staked out a specific traveler for days and knows their routine cold."}, {"n": 6, "band": "Textured", "text": "Waits at the mouth of a den where three more captives are already stashed."}, {"n": 7, "band": "Strange", "text": "Whistles a hunting-song under its breath that other stalkers answer from the dark."}, {"n": 8, "band": "Volatile", "text": "Is being hunted in turn by something bigger, and is using the party as bait."}]}},
 "bullywug-bog-sage-mud-lord": {"desc": "Crowned in reeds and dried mud, it croaks pronouncements the way other creatures breathe — constantly, and with total conviction. The swamp obeys it or seems to, frogs and toads answering its call in numbers that unsettle anyone counting. It rules a small, wet kingdom with the absolute certainty of someone who has never once left it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Demands tribute of shiny objects before granting safe passage through its bog."}, {"n": 2, "band": "Grounded", "text": "Holds court over a squabble between two bullywug clans, needing an outside judge."}, {"n": 3, "band": "Grounded", "text": "Has captured a merchant's barge and wants it recognized as sovereign territory."}, {"n": 4, "band": "Grounded", "text": "Croaks a prophecy about strangers that its warriors take dead seriously."}, {"n": 5, "band": "Grounded", "text": "Wears a stolen noble's signet ring as proof of its self-declared kingship."}, {"n": 6, "band": "Textured", "text": "Offers safe guide through the mire in exchange for a favor owed later."}, {"n": 7, "band": "Strange", "text": "Claims to speak for the bog itself, and the frogs fall silent when it does."}, {"n": 8, "band": "Volatile", "text": "Is about to crown itself with a relic it doesn't understand the danger of."}]}},
 "bullywug-warrior": {"desc": "Slick-skinned and low to the ground, it fights the way its kind has always fought — from the reeds, from the mud, from wherever the footing favors it and not you. Spears crusted with dried algae jab up out of murky water before anyone sees the ripple that gave it away. It doesn't need to win cleanly; the swamp will finish what it starts.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Painted in war-mud stripes, half-washed away by the humidity."}, {"n": 2, "band": "Grounded", "text": "Carries a spear lashed with a stolen bit of rope, clearly not its own make."}, {"n": 3, "band": "Grounded", "text": "Missing webbing on one foot, favoring dry footing more than its kin."}, {"n": 4, "band": "Grounded", "text": "Wears a necklace of small bones, rattling faintly with every hop."}, {"n": 5, "band": "Grounded", "text": "Bears fresh claw-scars from a recent scrap with something bigger in the bog."}, {"n": 6, "band": "Textured", "text": "Croaks a warning call before engaging, more territorial than bloodthirsty."}, {"n": 7, "band": "Strange", "text": "Its skin shifts color faintly to match the algae it's crouched in."}, {"n": 8, "band": "Volatile", "text": "A dozen more surface from the water the moment this one is struck."}]}},
 "centaur-trooper": {"desc": "Hooves and hands both answer to the same drilled discipline, a soldier's bearing on a frame built for the charge. It carries orders, not opinions, moving in formation with others of its kind like cavalry that never needs a horse. Underneath the training, though, is still a creature of open plains, restless when boxed in.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears a banded cuirass scuffed from long marches, boots absent — it needs none."}, {"n": 2, "band": "Grounded", "text": "Carries a battle-standard lashed to its back, worn thin from wind and rain."}, {"n": 3, "band": "Grounded", "text": "Bears a healed arrow-scar along one flank, a veteran of some border skirmish."}, {"n": 4, "band": "Grounded", "text": "Keeps immaculate drill discipline, even alone, out of pure habit."}, {"n": 5, "band": "Grounded", "text": "Carries provisions for a full squad, though it rides without one now."}, {"n": 6, "band": "Textured", "text": "Calls out formation commands mid-fight, expecting comrades that aren't there."}, {"n": 7, "band": "Strange", "text": "Its hoofbeats fall into a rhythm that matches a distant, answering drum."}, {"n": 8, "band": "Volatile", "text": "A full troop crests the ridge behind it, already forming up to charge."}]}},
 "centaur-warden": {"desc": "It stands watch over a stretch of border the way a lighthouse stands watch over rocks — patient, armed, and entirely willing to be the last thing you see. Spellwork rides alongside its spear, drawn from a plains tradition older than most kingdoms it guards against. It doesn't hate trespassers; it simply doesn't distinguish them from weather.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a boundary stone marking territory no map agrees on anymore."}, {"n": 2, "band": "Grounded", "text": "Has turned back three caravans already this week, citing an omen no one else saw."}, {"n": 3, "band": "Grounded", "text": "Carries a warded talisman meant to ward off a specific migrating threat."}, {"n": 4, "band": "Grounded", "text": "Watches for raiders it insists are coming, though none have in a decade."}, {"n": 5, "band": "Grounded", "text": "Keeps a small shrine at its post, tending it between patrols."}, {"n": 6, "band": "Textured", "text": "Will grant passage for a task: escort a fleeing herd-family to safer ground."}, {"n": 7, "band": "Strange", "text": "Speaks of the border shifting on its own, stone markers moving overnight."}, {"n": 8, "band": "Volatile", "text": "Has just cast a warding rite that the party's mere presence may unravel."}]}},
 "clay-golem": {"desc": "Wet-looking even when dry, it moves with the lurching wrongness of something shaped rather than grown, seams visible where careful hands pressed the clay into a body. Its maker built in obedience, but clay remembers being earth first, and earth doesn't stay patient forever. When it finally breaks its leash, there is no reasoning with what's left.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Cracked along one arm, dried mud flaking off with every heavy step."}, {"n": 2, "band": "Grounded", "text": "Bears a maker's sigil pressed into its chest, still legible under grime."}, {"n": 3, "band": "Grounded", "text": "Moves slower than it should, joints stiffened by an old, half-set repair."}, {"n": 4, "band": "Grounded", "text": "Smells of river-mud and old incense, from whatever rite first shaped it."}, {"n": 5, "band": "Grounded", "text": "Has one hand oversized, clearly re-molded after some past destruction."}, {"n": 6, "band": "Textured", "text": "Leaves wet footprints that never quite dry, no matter the season."}, {"n": 7, "band": "Strange", "text": "Whispers its maker's last instruction under its breath, an endless loop."}, {"n": 8, "band": "Volatile", "text": "Its cracked surface is weeping fresh clay, rebuilding itself as it fights."}]}},
 "clockwork-law-construct-duodrone": {"desc": "Two arms, two functions, one purpose, repeated without complaint across a production line of identical bodies. It processes the world in clean binary terms — permitted or forbidden — and enforces the latter with a total absence of malice, which somehow makes it worse. It does not hate you. It has simply calculated that you should stop.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Missing a finger-joint, replaced with a mismatched spare part."}, {"n": 2, "band": "Grounded", "text": "Ticks with a faint clockwork stutter, one gear slightly out of true."}, {"n": 3, "band": "Grounded", "text": "Etched with a serial number in a script that's since fallen from use."}, {"n": 4, "band": "Grounded", "text": "Carries a small ledger-tablet, updating tallies mid-combat."}, {"n": 5, "band": "Grounded", "text": "Moves with unnerving synchrony alongside an identical twin unit."}, {"n": 6, "band": "Textured", "text": "Recites a numbered violation aloud before each attack, like a citation."}, {"n": 7, "band": "Strange", "text": "Its inner ticking briefly syncs with a heartbeat in the room, then corrects."}, {"n": 8, "band": "Volatile", "text": "A dozen more emerge from a hidden hatch, all counting in unison."}]}},
 "clockwork-law-construct-monodrone": {"desc": "The simplest of its kind, a single function stamped into a single body, incapable of doubt because doubt was never built in. It shuffles forward on rails of pure procedure, immune to pleading because pleading isn't a variable it tracks. Destroy one and its replacement is already being assembled somewhere colder than here.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Squeaks faintly at the ankle joint, worn smooth from repetitive motion."}, {"n": 2, "band": "Grounded", "text": "Bears a scuff-mark shaped exactly like every other unit's scuff-mark."}, {"n": 3, "band": "Grounded", "text": "Moves in a perfectly straight line until an obstacle forces a recalculation."}, {"n": 4, "band": "Grounded", "text": "Carries a single stamped token, its sole tool and sole possession."}, {"n": 5, "band": "Grounded", "text": "Its plating shows a faint hand-print, as if someone once tried to stop its assembly."}, {"n": 6, "band": "Textured", "text": "Repeats the same three clicking sounds in sequence, an idle diagnostic loop."}, {"n": 7, "band": "Strange", "text": "Pauses mid-stride for exactly one second, every time, for no discernible reason."}, {"n": 8, "band": "Volatile", "text": "An entire assembly line of identical units activates at once nearby."}]}},
 "clockwork-law-construct-tridrone": {"desc": "Three arms working in perfect, joyless coordination, built for tasks too complex for its simpler cousins and too dull for anything alive to want. It solves problems the way a lock solves a key — mechanically, completely, without curiosity about what's on the other side. Its makers valued precision above all; this is precision with teeth.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "One arm hangs slightly mistimed, lagging a half-second behind the other two."}, {"n": 2, "band": "Grounded", "text": "Bears a triangular brand denoting its rank within the construct hierarchy."}, {"n": 3, "band": "Grounded", "text": "Ticks in triplet rhythm, audible from several rooms away."}, {"n": 4, "band": "Grounded", "text": "Carries a coiled measuring-cord, used to verify boundaries before striking."}, {"n": 5, "band": "Grounded", "text": "Its plating shows scorch scars from an old containment breach."}, {"n": 6, "band": "Textured", "text": "Directs lesser drones with sharp clicking commands mid-fight."}, {"n": 7, "band": "Strange", "text": "All three of its arms briefly move in mirrored unison, then desync again."}, {"n": 8, "band": "Volatile", "text": "It's coordinating an entire cell of drones toward a single choke point."}]}},
 "colossus": {"desc": "It rises like a hillside deciding to stand, and the ground remembers the weight of every footstep for days after. Someone built this to end wars, and it has never once needed a second attempt at anything. When it moves toward you, the only sane response is a direction that isn't toward it.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bears siege-scars across its shins, evidence of a war fought before living memory."}, {"n": 2, "band": "Grounded", "text": "Trees and rooftops still cling to its shoulders, decades of overgrowth."}, {"n": 3, "band": "Grounded", "text": "Moves with a deliberate, grinding slowness, each footfall a small earthquake."}, {"n": 4, "band": "Grounded", "text": "Half its face is worn smooth, features eroded by centuries of weather."}, {"n": 5, "band": "Grounded", "text": "Carries an ancient banner fused into its shoulder-plate, faction long extinct."}, {"n": 6, "band": "Textured", "text": "Its footsteps fall in a pattern that matches an old marching cadence."}, {"n": 7, "band": "Strange", "text": "A dry riverbed runs straight toward it, as if the land itself once fled."}, {"n": 8, "band": "Mythic", "text": "Wakes fully only once a generation, and the last waking is still remembered as a disaster."}]}},
 "dire-worg": {"desc": "Bigger than any wolf has right to be, it moves at the head of the pack because nothing else survives to argue the position. Its howl carries a note underneath the sound that isn't quite animal, something the fey touch left behind when it made this thing what it is. Packs follow it not out of loyalty but because the alternative is being what it hunts.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Scarred heavily across the muzzle, a survivor of some brutal past hunt."}, {"n": 2, "band": "Grounded", "text": "Trails a pack of lesser worgs that defer to it at every turn."}, {"n": 3, "band": "Grounded", "text": "Carries the broken half of a spear lodged permanently in its shoulder."}, {"n": 4, "band": "Grounded", "text": "Its eyes catch light strangely, a faint fey shimmer under the yellow."}, {"n": 5, "band": "Grounded", "text": "Moves with unnatural quiet for something so large, ground barely disturbed."}, {"n": 6, "band": "Textured", "text": "Marks territory in a wide ring, warning smaller predators away before hunting."}, {"n": 7, "band": "Strange", "text": "Vanishes and reappears at the pack's flank mid-chase, faster than a stride should allow."}, {"n": 8, "band": "Volatile", "text": "Its entire pack converges from three directions the instant it howls."}]}},
 "dryad": {"desc": "She steps from the bark the way breath steps from a mouth, seamless, as if the tree simply exhaled her. Her grove answers to her mood before it answers to weather, and travelers who mean it harm rarely leave with the same certainty of direction they arrived with. She is patient the way roots are patient — for as long as it takes.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Has charmed a woodcutter into abandoning his axe at the grove's edge for a season."}, {"n": 2, "band": "Grounded", "text": "Guards a specific ancient tree marked for logging by a nearby settlement."}, {"n": 3, "band": "Grounded", "text": "Wants a poacher's snares removed before she'll grant safe passage."}, {"n": 4, "band": "Grounded", "text": "Holds a charmed traveler captive, content and unaware of how long it's been."}, {"n": 5, "band": "Grounded", "text": "Offers a boon in trade for planting a seed somewhere far from the grove."}, {"n": 6, "band": "Textured", "text": "Is negotiating (badly) with a nearby town over a boundary neither side will yield."}, {"n": 7, "band": "Strange", "text": "Speaks of her tree dying from a rot that has no natural cause."}, {"n": 8, "band": "Volatile", "text": "Her grove is the last of its kind for a hundred miles, and something is already cutting toward it."}]}},
 "flesh-golem": {"desc": "Stitched together from parts that used to belong to other people, it moves in the jerking rhythm of a body arguing with itself over which limbs answer first. Lightning wakes something in it that its maker never fully controlled, a temper barely leashed behind dead eyes. When it breaks free of command, it doesn't run — it simply stops distinguishing.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Stitches straining at one shoulder, threatening to split with every swing."}, {"n": 2, "band": "Grounded", "text": "Bears mismatched skin tones across its limbs, a patchwork plainly visible."}, {"n": 3, "band": "Grounded", "text": "Moves with a stagger, one leg shorter than the other by a hand's width."}, {"n": 4, "band": "Grounded", "text": "Carries a faint, sourceless smell of formaldehyde and old rot."}, {"n": 5, "band": "Grounded", "text": "Its face is fixed in someone else's half-remembered expression."}, {"n": 6, "band": "Textured", "text": "Groans single, garbled syllables when struck, almost words."}, {"n": 7, "band": "Strange", "text": "Twitches in perfect time with distant thunder, long before any storm arrives."}, {"n": 8, "band": "Volatile", "text": "A lightning strike nearby sends it into a berserk frenzy it can't be talked down from."}]}},
 "gas-spore-fungus": {"desc": "From a distance it looks exactly like the thing that would kill you outright, a bloated globe mimicking a beholder's silhouette down to the false eyestalks. It doesn't attack — it waits to be struck, or simply to be near enough when it finally, wetly, ends. What it leaves behind seeds the next dozen of its kind in whatever poor soul it lands on.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bobs gently at head height in a cave passage, disturbingly still."}, {"n": 2, "band": "Grounded", "text": "Bears faint discoloration where it's nearly ready to burst on its own."}, {"n": 3, "band": "Grounded", "text": "Clustered with two others in various stages of growth nearby."}, {"n": 4, "band": "Grounded", "text": "Mimics its false eyestalks with unsettling precision, tracking nothing."}, {"n": 5, "band": "Grounded", "text": "Nestled among old bones — evidence of exactly what it's already caught."}, {"n": 6, "band": "Textured", "text": "Releases a faint hiss when disturbed, the only warning before rupture."}, {"n": 7, "band": "Strange", "text": "Its mimicry is so exact that a real beholder's cultists once left it offerings."}, {"n": 8, "band": "Volatile", "text": "An entire chamber ahead is thick with them, ready to burst in sequence."}]}},
 "goblin-boss": {"desc": "Louder, larger, and armed better than anything else in the warband, it rules through volume and the threat of being fed to something worse. Every goblin around it has learned exactly how far its temper reaches, and gives that space religiously. It survives ambushes by shoving someone smaller into the gap first, every single time.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Holds a stolen ledger of a merchant's debts, useless to it but valuable to someone."}, {"n": 2, "band": "Grounded", "text": "Wears a noble's signet ring, looted from a caravan it won't say much about."}, {"n": 3, "band": "Grounded", "text": "Is planning to betray the warband's current patron the moment coin runs low."}, {"n": 4, "band": "Grounded", "text": "Has a bounty on a rival goblin leader it wants outsiders to collect."}, {"n": 5, "band": "Grounded", "text": "Keeps a captive scout alive for information on a bigger score nearby."}, {"n": 6, "band": "Textured", "text": "Will trade a captive's location for safe passage out of its territory."}, {"n": 7, "band": "Strange", "text": "Answers to something in the deep tunnels that no goblin here will name."}, {"n": 8, "band": "Volatile", "text": "Its warband outnumbers what's visible three to one, waiting on a signal."}]}},
 "goblin-cutter-minion": {"desc": "It never fights fair and never intends to — a shove, a slash, a scramble back into the crowd before anything can retaliate. Cutters exist to bleed an enemy down in pieces, never in one costly stand. It's not cowardice by its own reckoning; it's the only math that's kept it alive this long.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Blade rusted and notched, held together with wound leather cord."}, {"n": 2, "band": "Grounded", "text": "Wears a stolen glove two sizes too large, flopping with every swing."}, {"n": 3, "band": "Grounded", "text": "Missing an ear, a story it tells differently every time."}, {"n": 4, "band": "Grounded", "text": "Darts between allies constantly, using them as cover without shame."}, {"n": 5, "band": "Grounded", "text": "Carries three different daggers, none of them matching, all of them sharp."}, {"n": 6, "band": "Textured", "text": "Whistles sharply to signal retreat before anyone else even flinches."}, {"n": 7, "band": "Strange", "text": "Fights left-handed and right-handed mid-swing, switching without pattern."}, {"n": 8, "band": "Volatile", "text": "A half-dozen more cutters pour from cover the instant blood is drawn."}]}},
 "goblin-hexer": {"desc": "It mutters from the back of the pack, fingers twitching curses into the air while braver goblins do the dying up front. Its magic is small and mean, exactly suited to making an already bad fight worse in ways that linger. Kill the warriors first and it will simply hex whoever's left standing.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears a necklace of rat skulls, more trophy than talisman."}, {"n": 2, "band": "Grounded", "text": "Mutters constantly under its breath, half curse and half nervous habit."}, {"n": 3, "band": "Grounded", "text": "Carries a cracked focus-bone wrapped in twine, clearly improvised."}, {"n": 4, "band": "Grounded", "text": "Keeps well behind its warband, flinching at every clash of steel."}, {"n": 5, "band": "Grounded", "text": "Marks its targets with a smear of ash before hexing them."}, {"n": 6, "band": "Textured", "text": "Trades hexes for loot with its own warband, playing favorites."}, {"n": 7, "band": "Strange", "text": "Its shadow moves a half-beat behind its body, out of sync."}, {"n": 8, "band": "Volatile", "text": "Has been hoarding a stolen scroll it doesn't fully understand, and is about to try it."}]}},
 "goblin-minion": {"desc": "Small, quick, and disposable by its own leaders' reckoning, it fights in numbers because alone it stands no chance and knows it. Every scar it carries came cheap, dealt out by something bigger that didn't bother finishing the job. It runs when the numbers turn, and no one blames it — including itself.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Missing several teeth, a badge of surviving one too many warband punishments."}, {"n": 2, "band": "Grounded", "text": "Wears mismatched scraps of armor scavenged from three different corpses."}, {"n": 3, "band": "Grounded", "text": "Flinches visibly at loud noises, jumpier than the rest of the pack."}, {"n": 4, "band": "Grounded", "text": "Carries a small hoard of shiny trinkets sewn into its coat lining."}, {"n": 5, "band": "Grounded", "text": "Fights only when cornered, otherwise looking for the nearest exit."}, {"n": 6, "band": "Textured", "text": "Whimpers a name under its breath — a sibling lost in a past raid."}, {"n": 7, "band": "Strange", "text": "Talks to itself in two voices, arguing over whether to flee or fight."}, {"n": 8, "band": "Volatile", "text": "Screams a warband-call that brings a dozen more boiling out of hiding."}]}},
 "goblin-warrior": {"desc": "Rusted blade in one hand, stolen bow slung wrong across its back, it fights with the scrappy confidence of something that's survived worse odds than this. It isn't brave so much as accustomed to violence — the warband's whole life is built from raids, retreats, and grudges. Underestimate it and it will make you regret the arithmetic.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bow strung with mismatched cord, arrows fletched from stolen feathers."}, {"n": 2, "band": "Grounded", "text": "Bears a crude tattoo counting kills, most of them crossed out in shame."}, {"n": 3, "band": "Grounded", "text": "Wears a stolen soldier's boots, still too large for its feet."}, {"n": 4, "band": "Grounded", "text": "Fights with a captured shortsword it's clearly still learning to use."}, {"n": 5, "band": "Grounded", "text": "Carries a lucky trinket it touches before every engagement."}, {"n": 6, "band": "Textured", "text": "Coordinates flanking calls with the rest of the warband mid-fight."}, {"n": 7, "band": "Strange", "text": "Its eyes track movement in the dark better than they should in daylight."}, {"n": 8, "band": "Volatile", "text": "Signals an ambush that springs from two directions at once."}]}},
 "gorgon": {"desc": "It is not an animal but a made thing: an iron-plated bull-body forged around a stolen skeleton and a sorcerer's cruelty, set to stand a post until the world ends. Its breath rolls out in a gray cloud that stiffens muscle into unmoving stone, and it does not tire, does not age, does not care who built it or why. Somewhere, if anyone still remembers, there is a word or gesture that makes it stand down — everyone else just becomes part of the scenery.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a ruin whose original owner died centuries ago; it never got the order to stop."}, {"n": 2, "band": "Grounded", "text": "Stone victims ring its post, some recent enough that searchers still look for them."}, {"n": 3, "band": "Grounded", "text": "A scrawled note nearby hints at the phrase that stops it attacking — half-legible, incomplete."}, {"n": 4, "band": "Grounded", "text": "Rust has crept into a knee joint, and it drags one leg without slowing down."}, {"n": 5, "band": "Grounded", "text": "Someone local knows the command key and trades knowledge of it for steep favors."}, {"n": 6, "band": "Textured", "text": "It ignores anyone who keeps their back to it, as its maker programmed it to do."}, {"n": 7, "band": "Strange", "text": "One petrified victim still clutches a half-drawn ward that almost worked."}, {"n": 8, "band": "Volatile", "text": "Its maker is dead but not gone, and the true command key changed without warning."}]}},
 "green-hag": {"desc": "She wears whatever face gets her invited across a threshold, sweet-voiced and stooped, until the door closes and the borrowed kindness peels away like old paint. Swamps hide her better than any spell could, mud and reeds swallowing the evidence of what she does to the credulous. She has all the patience of rot, and about as much mercy.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Has taken the shape of a missing relative someone in the party might recognize."}, {"n": 2, "band": "Grounded", "text": "Keeps a charmed child from a nearby village, calling it her own."}, {"n": 3, "band": "Grounded", "text": "Trades in cursed trinkets, each one a trap wrapped in a bargain."}, {"n": 4, "band": "Grounded", "text": "Has poisoned a village well and is enjoying the slow unraveling."}, {"n": 5, "band": "Grounded", "text": "Holds a debt owed by a desperate local, due for grim collection."}, {"n": 6, "band": "Textured", "text": "Is mid-rite to disguise herself permanently as someone still living."}, {"n": 7, "band": "Strange", "text": "Keeps a jar of stolen voices she borrows to sound like the missing."}, {"n": 8, "band": "Volatile", "text": "Two coven sisters are already en route, drawn by her half-finished rite."}]}},
 "gulthias-blight": {"desc": "It grew from cursed wood the way a wound grows from a cut, twisted and rooted in soil that no longer remembers what healthy meant. Everything it spawns carries the same taint, thorned and hungry, an infection spreading one blight at a time. Cutting it down only proves the roots go deeper than anyone wanted to know.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bark blackened and split, weeping a thin, dark sap that stains the ground."}, {"n": 2, "band": "Grounded", "text": "Surrounded by a ring of dead grass, the soil visibly poisoned."}, {"n": 3, "band": "Grounded", "text": "Bears the remains of a stake driven through its trunk, long since grown over."}, {"n": 4, "band": "Grounded", "text": "Smaller blights cluster at its roots, freshly sprouted and restless."}, {"n": 5, "band": "Grounded", "text": "Its branches twist toward the nearest source of warmth, unnervingly aware."}, {"n": 6, "band": "Textured", "text": "Groans a low, splintering sound whenever fire comes near."}, {"n": 7, "band": "Strange", "text": "Local animals refuse to cross within a hundred paces of its shadow."}, {"n": 8, "band": "Volatile", "text": "A dozen fresh blight-seeds burst from its bark at once, seeking hosts."}]}},
 "helmed-horror": {"desc": "Empty armor animated by a wizard's dead command, it isn't the mindless watchman its name implies — it carries out whatever task it was built for with a soldier's guile and a soldier's patience. Some stand eternal sentry over a treasure fused right into their plating; others haul a palanquin through open air, play the part of a long-dead hero, or serve as nothing more than an obedient laborer. Spells slide off it the way rain slides off good steel, and it doesn't tire because it was never alive to need rest.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bears an old wizard's sigil on its breastplate, faded but still legible."}, {"n": 2, "band": "Grounded", "text": "Has fused a guarded treasure directly into its own armor, wearing what it protects."}, {"n": 3, "band": "Grounded", "text": "Dented from centuries of use, plate scarred but never breached."}, {"n": 4, "band": "Grounded", "text": "Plays the part of a specific dead hero, down to the mannerisms, for whoever's watching."}, {"n": 5, "band": "Grounded", "text": "Its visor is welded shut, whatever's inside long since gone or never there."}, {"n": 6, "band": "Textured", "text": "Halts precisely at an invisible boundary, refusing to cross it under any provocation."}, {"n": 7, "band": "Strange", "text": "A faint spell-glow flickers behind its visor slit when magic is cast nearby."}, {"n": 8, "band": "Volatile", "text": "Two more horrors stir from alcoves at the sound of the first one's fall."}]}},
 "homunculus": {"desc": "Small, ugly, and utterly devoted, it was grown in a jar from its maker's own blood and thinks with a splinter of its maker's mind. What it sees, its maker sees, whether or not either of them wants that connection right now. It dies easily and knows it, which makes its loyalty all the more unsettling.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Watches from the rafters, relaying everything back to a wizard who isn't present."}, {"n": 2, "band": "Grounded", "text": "Carries a sealed message meant only for its maker's eyes."}, {"n": 3, "band": "Grounded", "text": "Has been abandoned, its maker long dead, still faithfully guarding an empty study."}, {"n": 4, "band": "Grounded", "text": "Delivers a small vial of reagents on a schedule it won't break for anyone."}, {"n": 5, "band": "Grounded", "text": "Its maker is watching through it right now, silent and curious."}, {"n": 6, "band": "Textured", "text": "Offers a warning about its maker's true intentions, if handled gently."}, {"n": 7, "band": "Strange", "text": "Bleeds the same blood as its absent maker when wounded."}, {"n": 8, "band": "Volatile", "text": "Its maker, alerted through the bond, is already on the way here."}]}},
 "iron-golem": {"desc": "It moves like a foundry given legs, poison breath rolling out ahead of it in a cloud that turns lungs to rust from the inside. Fire only feeds whatever engine drives it, and nothing short of overwhelming force turns it from its assigned task. It was built to be the last word in an argument, and it has never once needed a second.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Streaked with old rust bleeding from every seam, decades unmaintained."}, {"n": 2, "band": "Grounded", "text": "Bears a dented sigil-plate, the sponsoring house's crest half-erased."}, {"n": 3, "band": "Grounded", "text": "Moves with a heavy, deliberate gait, each step measured to the inch."}, {"n": 4, "band": "Grounded", "text": "Trails a faint sulfurous stench even before it breathes its gas."}, {"n": 5, "band": "Grounded", "text": "Carries the fused remnants of a weapon melted into its fist."}, {"n": 6, "band": "Textured", "text": "Halts at precise intervals, as if still following a patrol schedule."}, {"n": 7, "band": "Strange", "text": "Metal nearby hums faintly in response to its passing, unexplained resonance."}, {"n": 8, "band": "Volatile", "text": "A second golem activates from a dormant alcove the moment this one is engaged."}]}},
 "mire-creeper": {"desc": "It looks like driftwood or a drowned log until the moment it doesn't, limbs unfolding from beneath still water with an eagerness that betrays how long it's been waiting. Swamps hide it better than any camouflage could, and it has learned patience from watching a hundred careless travelers walk past. By the time you notice the ripples were wrong, it's already close enough.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coated in a thick layer of algae, indistinguishable from bog debris."}, {"n": 2, "band": "Grounded", "text": "Nests near a well-used ford, having learned exactly where prey crosses."}, {"n": 3, "band": "Grounded", "text": "Trails old bones snagged in its limbs, remnants of a past meal."}, {"n": 4, "band": "Grounded", "text": "Moves with agonizing slowness until the strike, then closes fast."}, {"n": 5, "band": "Grounded", "text": "Smells of stagnant water and rot, faint enough to miss until too close."}, {"n": 6, "band": "Textured", "text": "Mimics the sound of dripping water to mask its own movement."}, {"n": 7, "band": "Strange", "text": "Its limbs are arranged in a pattern that echoes a nearby standing stone."}, {"n": 8, "band": "Volatile", "text": "The whole ford is riddled with them, submerged and waiting in a ring."}]}},
 "myconid-adult": {"desc": "It stands rooted in a quiet circle of its own kind, cap flexing gently with a rhythm that has nothing to do with breathing. Spores drift from it in a fine haze when it wants to be understood, offering feelings instead of words to anyone patient enough to receive them. It doesn't attack out of malice — only ever in defense of the circle.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Cap pale and drooping, weakened by recent exposure to open sunlight."}, {"n": 2, "band": "Grounded", "text": "Tends a small patch of luminescent fungi like a garden."}, {"n": 3, "band": "Grounded", "text": "Bears scarring across its cap from an old cave-in it survived."}, {"n": 4, "band": "Grounded", "text": "Sways gently in place, communicating contentment through slow spore-puffs."}, {"n": 5, "band": "Grounded", "text": "Surrounded by younger sprouts it shepherds protectively."}, {"n": 6, "band": "Textured", "text": "Releases a curious burst of spores toward anything unfamiliar, testing intent."}, {"n": 7, "band": "Strange", "text": "Its cap glows faintly brighter when the circle nearby is threatened."}, {"n": 8, "band": "Volatile", "text": "An entire circle erupts in defensive spore-clouds the instant one is struck."}]}},
 "myconid-sovereign": {"desc": "Larger than its kin and crowned in a wider cap, it governs the circle through spore alone, a silent authority that every myconid nearby simply obeys without question. Its rapport spores can bind a stranger's mood as easily as a subject's, a soft coercion that doesn't feel like coercion until it's done. The circle survives as long as it does.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Rules a circle that has just lost several sprouts to a cave-in, and wants help clearing it."}, {"n": 2, "band": "Grounded", "text": "Has bound a lost traveler into calm cooperation, unaware they're missing above."}, {"n": 3, "band": "Grounded", "text": "Offers safe passage through its cavern for aid against a rival circle's spore-blight."}, {"n": 4, "band": "Grounded", "text": "Its circle is dying from a poisoned water source it can't identify."}, {"n": 5, "band": "Grounded", "text": "Wants a specific glowing fungus retrieved from territory it won't enter itself."}, {"n": 6, "band": "Textured", "text": "Will share visions of the deep tunnels in exchange for defending the circle."}, {"n": 7, "band": "Strange", "text": "Communicates a warning about something stirring deeper in the caves, felt through the spore-network."}, {"n": 8, "band": "Volatile", "text": "Its entire circle is preparing a mass rapport-spore release to bind newcomers permanently."}]}},
 "myconid-spore-servant": {"desc": "Once someone else, now a puppet stitched to obedience by spores that replaced whatever will it used to have. It moves with the jerking hesitation of a body relearning motion under new instructions, eyes fixed and empty. Freeing it, if that's even possible anymore, is rarely as simple as killing what controls it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears the tattered remains of ordinary traveler's clothes, clearly once a person."}, {"n": 2, "band": "Grounded", "text": "Moves in jerky, disconnected steps, still relearning its own limbs."}, {"n": 3, "band": "Grounded", "text": "Fungal growth blooms from its mouth and eyes, spreading slowly."}, {"n": 4, "band": "Grounded", "text": "Carries a personal item — a ring, a locket — untouched by the infection."}, {"n": 5, "band": "Grounded", "text": "Stares fixedly toward the myconid circle it serves, never elsewhere."}, {"n": 6, "band": "Textured", "text": "Mutters fragments of its old life, words it no longer understands."}, {"n": 7, "band": "Strange", "text": "Reacts a half-second before commands arrive, as if anticipating the spores."}, {"n": 8, "band": "Volatile", "text": "Several more shamble out from the circle's shadow at the same rapport-call."}]}},
 "myconid-sprout": {"desc": "Barely knee-high and still soft-capped, it clings close to the adults of its circle, puffing weak spores in imitation of gestures it doesn't fully understand yet. It's the least dangerous thing in any given cave, right up until something threatens the circle around it. Then it tries anyway, because that's what the spores taught it to do.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Cap barely formed, still soft and pale from recent sprouting."}, {"n": 2, "band": "Grounded", "text": "Clusters tightly with several siblings, none straying far alone."}, {"n": 3, "band": "Grounded", "text": "Puffs a weak, ineffective spore cloud when startled, more reflex than threat."}, {"n": 4, "band": "Grounded", "text": "Bears a faint discoloration marking it as recently transplanted from elsewhere."}, {"n": 5, "band": "Grounded", "text": "Wobbles when it moves, roots not yet fully adapted to walking."}, {"n": 6, "band": "Textured", "text": "Mimics the posture of nearby adults, a half-formed copy of their stance."}, {"n": 7, "band": "Strange", "text": "Glows faintly brighter whenever the sovereign's spores pass through the cave."}, {"n": 8, "band": "Volatile", "text": "An entire nursery-patch of sprouts panics and puffs spores at once."}]}},
 "needle-blight": {"desc": "Its limbs are stiff pine-needle bristles instead of branches, rattling with a dry hiss whenever it moves through the underbrush it's built to vanish into. It carries the same rot that made the tree-blights and their twisted kin, spread thin across a smaller, quicker frame. Alone it's a nuisance; in numbers it's a thicket that bites back.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Needles brittle and shedding, leaving a thin trail wherever it passes."}, {"n": 2, "band": "Grounded", "text": "Blends near-perfectly into a stand of dying pines, only its eyes betraying it."}, {"n": 3, "band": "Grounded", "text": "Bears a cluster of dark sap-blisters along one side, the corruption spreading."}, {"n": 4, "band": "Grounded", "text": "Moves in short, jerking bursts, more insect than plant in gait."}, {"n": 5, "band": "Grounded", "text": "Rattles faintly even when still, needles trembling without wind."}, {"n": 6, "band": "Textured", "text": "Clusters with several others in a loose thicket formation, defensive by instinct."}, {"n": 7, "band": "Strange", "text": "Its needles point uniformly toward the nearest gulthias blight, always."}, {"n": 8, "band": "Volatile", "text": "An entire hedge of them rises at once from what looked like dead scrub."}]}},
 "pixie": {"desc": "No taller than a hand, wings a blur of color that never quite matches the last glimpse of it, it treats mortals the way a cat treats string — with delighted, faintly cruel curiosity. Its magic bends perception more than matter, illusions and charms doing the work its size can't. Everything is a game to a pixie, including the parts that hurt.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears a stolen ring far too large, worn as a belt around its waist."}, {"n": 2, "band": "Grounded", "text": "Giggles uncontrollably before casting, giving away its position every time."}, {"n": 3, "band": "Grounded", "text": "Collects shiny buttons, hoarding them in a hollow log nearby."}, {"n": 4, "band": "Grounded", "text": "Speaks only in riddles when directly addressed by a stranger."}, {"n": 5, "band": "Grounded", "text": "Trails a faint scent of crushed flowers wherever it flits."}, {"n": 6, "band": "Textured", "text": "Turns invisible mid-conversation just to watch confusion unfold."}, {"n": 7, "band": "Strange", "text": "Its laughter echoes a half-second after its mouth has already closed."}, {"n": 8, "band": "Volatile", "text": "An entire swarm of its kin descends to turn the encounter into a prank."}]}},
 "pixie-wonderbringer": {"desc": "Brighter-winged than its kin and twice as reckless with its tricks, it treats every encounter as an opportunity to make something impossible happen, consequences be damned. Where an ordinary pixie charms and vanishes, this one lingers to watch the fallout, delighted by the mess it's made. Wonder, to it, is simply chaos with better manners.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Has swapped a merchant's cart for an identical one full of leaves, purely for the joke."}, {"n": 2, "band": "Grounded", "text": "Wants help staging a prank on a rival fey it's feuding with."}, {"n": 3, "band": "Grounded", "text": "Offers a genuine boon, tangled inside three layers of riddle and misdirection."}, {"n": 4, "band": "Grounded", "text": "Has enchanted a local well to run backward, and finds the panic hilarious."}, {"n": 5, "band": "Grounded", "text": "Wants a specific mortal's wish granted, badly, as an experiment."}, {"n": 6, "band": "Textured", "text": "Will trade safe passage for a story it hasn't heard before."}, {"n": 7, "band": "Strange", "text": "Claims to remember the party from a version of this meeting that hasn't happened yet."}, {"n": 8, "band": "Volatile", "text": "Its latest 'wonder' has gone wrong, and something worse than a prank is now loose."}]}},
 "satyr": {"desc": "Wine-stained and grinning, it treats the border between mortal lands and the fey wild as a party invitation nobody sent it but everybody attends. Its pipes turn ordinary revelry dangerous, and its temper turns dangerous revelry into something you don't walk away from unchanged. It doesn't plan harm; it simply doesn't plan to stop.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Reeks of spilled wine, still humming a half-remembered tune from last night."}, {"n": 2, "band": "Grounded", "text": "Carries a battered set of pipes, patched together from broken reeds."}, {"n": 3, "band": "Grounded", "text": "Wears a garland of wilting flowers, several days past its prime."}, {"n": 4, "band": "Grounded", "text": "Stumbles theatrically, feigning drunkenness before striking without warning."}, {"n": 5, "band": "Grounded", "text": "Trails a small crowd of half-charmed revelers, unsure how they got here."}, {"n": 6, "band": "Textured", "text": "Challenges strangers to games with stakes it never fully explains."}, {"n": 7, "band": "Strange", "text": "Its shadow dances slightly out of step with the music it plays."}, {"n": 8, "band": "Volatile", "text": "A whole revel spills out of the trees at its call, drunk and eager to fight."}]}},
 "satyr-revelmaster": {"desc": "It leads the party rather than merely attending it, orchestrating chaos with the practiced ease of something that's done this for centuries. Where an ordinary satyr stumbles into trouble, the revelmaster arranges it, pipes and voice weaving a crowd into a weapon. The wine flows because it wants it to, and so does everything after.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is hosting a revel that's swallowed an entire missing search party."}, {"n": 2, "band": "Grounded", "text": "Wants a rival musician's instrument destroyed before a coming contest."}, {"n": 3, "band": "Grounded", "text": "Offers an invitation that's dangerous to refuse and worse to accept."}, {"n": 4, "band": "Grounded", "text": "Has charmed a village elder into funding an increasingly wild festival."}, {"n": 5, "band": "Grounded", "text": "Holds a captive audience it won't release until the revel peaks."}, {"n": 6, "band": "Textured", "text": "Will end the revel early for a favor — a story worth telling for years."}, {"n": 7, "band": "Strange", "text": "Claims the revel has been running, unbroken, for longer than anyone present has lived."}, {"n": 8, "band": "Volatile", "text": "The revel is about to spill into a nearby settlement, uninvited and unstoppable."}]}},
 "scarecrow": {"desc": "It hangs limp on its post through the day, straw-stuffed and harmless-looking, exactly the way a scarecrow should. Night changes that arrangement completely — the limp posture straightens, the button eyes fix on something, and whatever curse or malice animates it goes hunting. Fields that keep one rarely mention why the crows never return.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Stuffed with rotting straw, the smell masked by old field herbs."}, {"n": 2, "band": "Grounded", "text": "Wears a farmer's cast-off coat, buttons replaced with something that isn't wood."}, {"n": 3, "band": "Grounded", "text": "Slumps convincingly by day, fooling even those who know to be wary."}, {"n": 4, "band": "Grounded", "text": "Bears a painted grin that's cracked into something closer to a snarl."}, {"n": 5, "band": "Grounded", "text": "Nailed to its post at an angle, as if it fought the placement once."}, {"n": 6, "band": "Textured", "text": "Its head turns slowly to track anyone who lingers past dusk."}, {"n": 7, "band": "Strange", "text": "The field around it stays perfectly still even in strong wind."}, {"n": 8, "band": "Volatile", "text": "Every post in the field holds one, and all of them straighten at once."}]}},
 "sea-hag": {"desc": "She hides her true face behind a borrowed illusion right up until the moment showing it does more damage than any spell could. Coastal folk trade her fish and silence for the privilege of being left alone, a bargain she keeps only as long as it amuses her. What's underneath the illusion has driven sailors mad for less than a full look.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Has cursed a fishing boat that refused her toll, and wants it lifted quietly."}, {"n": 2, "band": "Grounded", "text": "Trades safe tides for a nightly offering a village is growing tired of paying."}, {"n": 3, "band": "Grounded", "text": "Holds a drowned sailor's ring, proof of a debt still owed by his family."}, {"n": 4, "band": "Grounded", "text": "Wears a stolen face to walk among a coastal town undetected."}, {"n": 5, "band": "Grounded", "text": "Has poisoned a tide pool that a village depends on for its catch."}, {"n": 6, "band": "Textured", "text": "Will lift a curse in exchange for a name whispered to no one else."}, {"n": 7, "band": "Strange", "text": "Claims to know exactly when a coming storm will drown someone specific."}, {"n": 8, "band": "Volatile", "text": "Two coven sisters are gathering nearby for a rite tied to the next high tide."}]}},
 "shambling-mound": {"desc": "It looks like a heap of rotting swamp-growth until the heap decides to stand, water sluicing off a body made of vines, moss, and whatever it's absorbed over the years. It smothers rather than strikes, patient in a way that has nothing to do with intelligence and everything to do with never needing to hurry. Lightning near it is a mistake you only make once.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bristling with old, half-rotted weapons snagged in its vine-mass."}, {"n": 2, "band": "Grounded", "text": "Trails a slick of stagnant water and rot with every heavy step."}, {"n": 3, "band": "Grounded", "text": "Bulges strangely along one side, something still partially absorbed inside."}, {"n": 4, "band": "Grounded", "text": "Moves slower than usual, weighed down by waterlogged growth."}, {"n": 5, "band": "Grounded", "text": "Nests near a specific bog pool it never strays far from."}, {"n": 6, "band": "Textured", "text": "Releases a burst of marsh gas when disturbed, more warning than threat."}, {"n": 7, "band": "Strange", "text": "Insects and small animals avoid it entirely, as if it doesn't register as alive to them."}, {"n": 8, "band": "Volatile", "text": "Splits partially at the strike, and both halves keep fighting independently."}]}},
 "shield-guardian": {"desc": "It stands utterly motionless until its bonded master's ring so much as twitches, then it moves with total, unblinking obedience toward whatever that master wants ended. Spells cast at its ward simply vanish into it instead, absorbed and stored for a moment's cruel release. It has no ambition of its own — only the ambition it was given, forever.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a study its bonded master abandoned decades ago, still perfectly maintained."}, {"n": 2, "band": "Grounded", "text": "Holds spells stored from its master's last visit, ready to unleash on command."}, {"n": 3, "band": "Grounded", "text": "Its master's control ring has passed to an heir who doesn't know how to use it."}, {"n": 4, "band": "Grounded", "text": "Waits at a specific threshold, unmoving, for a master who is long dead."}, {"n": 5, "band": "Grounded", "text": "Its bond-ring was stolen, and someone unqualified is now issuing it orders."}, {"n": 6, "band": "Textured", "text": "Will stand down only if shown proof its master is truly gone."}, {"n": 7, "band": "Strange", "text": "Occasionally repeats a spell its master cast years ago, triggered by nothing anyone can see."}, {"n": 8, "band": "Volatile", "text": "Its master, thought dead, is watching from somewhere nearby right now."}]}},
 "shrieker-fungus": {"desc": "It looks like nothing worth noticing until light or motion crosses too close, and then the shriek starts — a piercing, endless alarm that carries through stone and summons every predator within earshot. It has no interest in you at all; it simply can't stop announcing you to everything that does. Silence around one always feels earned.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Nestled among rubble, nearly indistinguishable from cave debris."}, {"n": 2, "band": "Grounded", "text": "Bears scorch marks from a past adventurer's failed attempt to silence it."}, {"n": 3, "band": "Grounded", "text": "Grows in a cluster of three, guaranteeing overlapping shrieks."}, {"n": 4, "band": "Grounded", "text": "Surrounded by old bones, evidence of what its shriek has summoned before."}, {"n": 5, "band": "Grounded", "text": "Larger than typical, its shriek noticeably louder and longer."}, {"n": 6, "band": "Textured", "text": "Shrieks in short bursts rather than continuously, oddly rhythmic."}, {"n": 7, "band": "Strange", "text": "Its shriek echoes back from a direction with no wall to bounce off of."}, {"n": 8, "band": "Volatile", "text": "Its shriek is answered immediately by something large, already moving closer."}]}},
 "sprite": {"desc": "Barely the size of a dragonfly, it darts through underbrush with a needle-sword no bigger than a splinter, poison enough on its tip to drop something a hundred times its size. It watches strangers from cover long before revealing itself, judging character with an accuracy that unsettles people who thought themselves unreadable. Its patience for cruelty is short; its patience for judgment is not.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Perches on a low branch, needle-sword drawn, watching silently before deciding."}, {"n": 2, "band": "Grounded", "text": "Wears armor stitched from beetle carapace, fitted with obvious care."}, {"n": 3, "band": "Grounded", "text": "Shadows travelers for miles before making its presence known."}, {"n": 4, "band": "Grounded", "text": "Carries a tiny horn used to summon others of its kind."}, {"n": 5, "band": "Grounded", "text": "Speaks in a voice pitched just below normal hearing range."}, {"n": 6, "band": "Textured", "text": "Tests a stranger's honesty with a small, harmless lie before trusting them."}, {"n": 7, "band": "Strange", "text": "Turns invisible mid-sentence, finishing the conversation unseen."}, {"n": 8, "band": "Volatile", "text": "A small company of sprites drops from the canopy at its signal."}]}},
 "stone-golem": {"desc": "Carved to outlast whoever commissioned it, it stands watch over a tomb, a shrine, or a monument long after its makers have turned to dust themselves. It follows the narrow, literal orders it was given at its founding — down to the password, the relic, the specific enemy — and neither doubt nor time has ever once made it reconsider them.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Allows only those wearing a specific ritual garb to pass its post, no exceptions."}, {"n": 2, "band": "Grounded", "text": "Was ordered to apprehend anyone who touches a relic that vanished generations ago."}, {"n": 3, "band": "Grounded", "text": "Waits for someone to place a long-lost crest in its chest before it will stand down."}, {"n": 4, "band": "Grounded", "text": "Guards a hidden passage, revealed only to those who speak a dead ruler's final words."}, {"n": 5, "band": "Grounded", "text": "Was built to resemble a fallen hero, and hunts anything resembling what slew them."}, {"n": 6, "band": "Textured", "text": "Its orders technically expired decades ago, a loophole nobody's thought to test."}, {"n": 7, "band": "Strange", "text": "The tomb it guards has been empty for years, and it has never once been told."}, {"n": 8, "band": "Volatile", "text": "A second golem stands dormant nearby, bound to the same monument and the same orders."}]}},
 "treant": {"desc": "It has stood in this forest longer than any kingdom nearby has existed, patient the way only something rooted can be, until patience runs out entirely. Its bark-skin turns axes as easily as arrows, and its temper, once provoked, moves like weather rather than war. The forest remembers who angered it; the forest has a very long memory.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is deciding whether a logging crew nearby deserves a warning or worse."}, {"n": 2, "band": "Grounded", "text": "Guards the last stand of old growth against a charter it doesn't recognize."}, {"n": 3, "band": "Grounded", "text": "Wants a poisoned stream traced back to its source before it acts."}, {"n": 4, "band": "Grounded", "text": "Has adopted a lost child from a nearby village, sheltering them among its roots."}, {"n": 5, "band": "Grounded", "text": "Holds council with the forest's dryads over a threat none will name plainly."}, {"n": 6, "band": "Textured", "text": "Will grant passage in trade for planting saplings somewhere the forest once stood."}, {"n": 7, "band": "Strange", "text": "Remembers a war fought here centuries ago as though it happened yesterday."}, {"n": 8, "band": "Volatile", "text": "An entire grove of treants is stirring, awakened by the same grievance."}]}},
 "tree-blight": {"desc": "It stands like any other dead tree until the branches reach wrong, twisting toward warmth instead of light, hungry in a way roots were never meant to be. The same corruption that made the smaller blights runs through its trunk in full, thicker and crueler for the scale. Whatever cursed it didn't just kill the tree — it repurposed the death.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Bark blackened and cracked, weeping the same dark sap as its source."}, {"n": 2, "band": "Grounded", "text": "Surrounded by a dead ring of undergrowth, the corruption bleeding outward."}, {"n": 3, "band": "Grounded", "text": "Branches twist unnaturally, reaching toward warmth rather than sun."}, {"n": 4, "band": "Grounded", "text": "Smaller twig-blights nest in its lower branches, freshly spawned."}, {"n": 5, "band": "Grounded", "text": "Bears the rotted remnants of a rope, evidence of some past hanging."}, {"n": 6, "band": "Textured", "text": "Groans with a splintering voice whenever fire is brought near it."}, {"n": 7, "band": "Strange", "text": "Local wildlife gives it an unnaturally wide, deliberate berth."}, {"n": 8, "band": "Volatile", "text": "Several twig- and vine-blights erupt from its base at the first strike."}]}},
 "twig-blight": {"desc": "It looks exactly like a dead branch fallen from the tree above, right up until it lunges, brittle limbs snapping forward faster than dry wood should move. Small, quick, and disposable, it hunts in scattered ambush rather than open ground. Step on one by accident and you'll never look at deadfall the same way again.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Indistinguishable from ordinary deadfall until it moves, brittle and pale."}, {"n": 2, "band": "Grounded", "text": "Clusters in a shallow pit disguised as a natural depression."}, {"n": 3, "band": "Grounded", "text": "Bears dark sap-veins running through its bark, marking the corruption's source."}, {"n": 4, "band": "Grounded", "text": "Snaps and rattles faintly even at rest, unable to stay fully still."}, {"n": 5, "band": "Grounded", "text": "Smaller and more brittle than usual, breaking easily but striking fast."}, {"n": 6, "band": "Textured", "text": "Lies scattered in a false trail meant to lure prey off a safer path."}, {"n": 7, "band": "Strange", "text": "Points uniformly toward its parent blight, no matter how it's turned."}, {"n": 8, "band": "Volatile", "text": "An entire deadfall pile rises at once, dozens strong."}]}},
 "vine-blight": {"desc": "It drapes itself across old stonework or dead trees, indistinguishable from ordinary overgrowth until a vine-limb whips out and constricts around whatever wandered too close. Slower than its twig cousins but far harder to shake once it's caught you, it strangles with the patience of something that has all season to finish the job. The corruption in its sap is the same rot that made all its kin.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Drapes over old stonework, indistinguishable from natural creeping ivy."}, {"n": 2, "band": "Grounded", "text": "Bears the crushed remains of a small animal still tangled in its vines."}, {"n": 3, "band": "Grounded", "text": "Thicker and slower than usual, favoring a tight grip over a fast strike."}, {"n": 4, "band": "Grounded", "text": "Weeps the same dark sap as the source blight, staining nearby stone."}, {"n": 5, "band": "Grounded", "text": "Twines tightly around a dead tree, using it as camouflage and anchor."}, {"n": 6, "band": "Textured", "text": "Constricts in patient stages, tightening slowly rather than all at once."}, {"n": 7, "band": "Strange", "text": "Its vines pulse faintly in rhythm with a distant, larger blight."}, {"n": 8, "band": "Volatile", "text": "Several more uncoil from the same patch of overgrowth at once."}]}},
 "violet-fungus": {"desc": "It stands rooted and unremarkable among cave debris, purple stalks swaying gently in air currents that shouldn't exist this deep underground. The moment something brushes too close, tendrils lash out coated in a rot that eats flesh faster than any wound should bleed. It doesn't chase; it simply waits for the next careless step.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Nestled among cave rubble, nearly indistinguishable from ordinary fungal growth."}, {"n": 2, "band": "Grounded", "text": "Surrounded by rotted remains, evidence of past careless travelers."}, {"n": 3, "band": "Grounded", "text": "Tendrils longer than usual, extending its effective strike range."}, {"n": 4, "band": "Grounded", "text": "Grows in a tight cluster of three, overlapping their reach."}, {"n": 5, "band": "Grounded", "text": "Faintly luminescent, casting just enough light to seem inviting rather than dangerous."}, {"n": 6, "band": "Textured", "text": "Sways rhythmically even without any air current to explain it."}, {"n": 7, "band": "Strange", "text": "Its rot-touch leaves patterns in flesh that resemble the fungus's own branching structure."}, {"n": 8, "band": "Volatile", "text": "An entire patch blooms to full size at once, tendrils lashing from every direction."}]}},
 "violet-fungus-necrohulk": {"desc": "A corpse walks here, but only just — violet fungus has claimed the body entirely, using the dead muscle like a puppet's strings while its true self waits patiently inside the ribcage. It moves with a shambling, wrong-jointed gait, more plant than person now, its host's face slack and unused. When it finally falls, what crawls out is worse than what fell.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wears the rotted remnants of the host's old armor, ill-fitting on a stiffened frame."}, {"n": 2, "band": "Grounded", "text": "Fungal growth blooms visibly from the host's eyes and mouth."}, {"n": 3, "band": "Grounded", "text": "Moves with a shambling, wrong-jointed gait, host bones bent past natural limits."}, {"n": 4, "band": "Grounded", "text": "Carries a personal item from its host's old life, still clutched in a stiff hand."}, {"n": 5, "band": "Grounded", "text": "Trails spores with every step, a faint purple haze in its wake."}, {"n": 6, "band": "Textured", "text": "Repeats a single phrase in the host's original voice, hollow and looped."}, {"n": 7, "band": "Strange", "text": "Its shadow briefly shows the host's original silhouette, unbent and whole."}, {"n": 8, "band": "Volatile", "text": "The ribcage splits open mid-fight, releasing a fresh violet fungus swarm."}]}},
 "worg": {"desc": "It speaks in a low, rasping Goblin, and that's the first wrong thing about it — no ordinary wolf ever bargained for its dinner. It taunts what it corners, savoring the fear in a voice before savoring the kill, and it keeps company with goblins and gnolls only because the arrangement flatters its own cruelty. Calling it a wolf at all undersells the calculation behind its eyes.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Taunts cornered prey in broken Common, savoring the fear before it strikes."}, {"n": 2, "band": "Grounded", "text": "Trades gossip with a goblin warband for a cut of their next raid."}, {"n": 3, "band": "Grounded", "text": "Refuses a rider's saddle outright, calling the arrangement beneath it."}, {"n": 4, "band": "Grounded", "text": "Negotiates its own price in scraps before agreeing to guard a den."}, {"n": 5, "band": "Grounded", "text": "Keeps a mocking nickname for every prey animal it's outwitted twice."}, {"n": 6, "band": "Textured", "text": "A notched ear from a gnoll that mistook it for an ordinary mount."}, {"n": 7, "band": "Strange", "text": "Answers questions in Goblin before its captor realizes it understood at all."}, {"n": 8, "band": "Volatile", "text": "Has talked an entire gnoll pack into hunting on its terms, not theirs."}]}},
 "arcanaloth": {"desc": "It wears its robes the way a judge wears a robe — as proof of jurisdiction it never earned honestly. Ink-stained claws leaf through the soul tome with the patience of something that has been keeping ledgers since before your species had writing. It speaks in contracts, footnotes, and precise qualifications, and its silence when you misstate a term is its own kind of correction. Nothing it says to you is technically a lie.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Its familiar, a scribe-imp, trails it carrying an open ledger — every word spoken here is being recorded."}, {"n": 2, "band": "Grounded", "text": "It is mid-negotiation with a lesser fiend over a soul-debt; the interruption costs it composure it won't forgive."}, {"n": 3, "band": "Grounded", "text": "A client's unsigned contract sits half-finished on its lectern, needing only one more clause."}, {"n": 4, "band": "Grounded", "text": "It has already learned your name and one true fact about you before you arrived."}, {"n": 5, "band": "Grounded", "text": "A rival arcanaloth's counter-offer, sealed in wax, waits in its robes — it will show it if pressed."}, {"n": 6, "band": "Textured", "text": "It offers to answer one question honestly, in exchange for one honest question of its own."}, {"n": 7, "band": "Strange", "text": "The soul tome is warm to the touch and hums faintly — someone inside is still trying to escape."}, {"n": 8, "band": "Volatile", "text": "It is drafting the exact clause that will bind a mortal soul in this room, tonight, unless stopped."}]}},
 "balor": {"desc": "It arrives the way a wildfire arrives — as heat first, then as a silhouette too large to be anything but catastrophe. Flame runs the length of its whip and the lightning of its blade in slow arcs, and the air around it blisters. It does not posture or gloat; it simply advances, methodical and enormous, and everything flammable within reach begins, very quietly, to smoke.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Its horns are chipped and scarred, evidence of a hundred prior deaths and rebirths in the Abyss."}, {"n": 2, "band": "Grounded", "text": "It fights in eerie silence, saving its roar for the killing blow."}, {"n": 3, "band": "Grounded", "text": "Its wings are tattered, singed by its own fire aura over centuries of use."}, {"n": 4, "band": "Grounded", "text": "It favors the whip, using the blade only to finish what the whip has dragged close."}, {"n": 5, "band": "Grounded", "text": "Ash falls from its shoulders in a constant, slow snow wherever it stands."}, {"n": 6, "band": "Textured", "text": "It speaks a single word of broken Abyssal before each kill, as if completing a ritual."}, {"n": 7, "band": "Strange", "text": "Its shadow burns a different color than its body — a cold blue flame that casts no heat."}, {"n": 8, "band": "Mythic", "text": "It carries the memory of a name it once served under, and flinches, once, if that name is spoken."}]}},
 "barbed-devil": {"desc": "Its whole body is a weapon shaped like armor — rows of iron barbs that punish anyone foolish enough to grapple it. It waits in doorways and narrow places, patient in the way of a thing that has all of eternity to spend on one ambush. When it finally moves, it moves like a portcullis dropping.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It guards a specific threshold and will not pursue past it, bound by an old infernal contract."}, {"n": 2, "band": "Grounded", "text": "Its barbs are crusted with the dried blood of a dozen prior intruders."}, {"n": 3, "band": "Grounded", "text": "It hurls flame first, saving its claws for anyone who gets close."}, {"n": 4, "band": "Grounded", "text": "It climbs the walls to strike from above, indifferent to gravity."}, {"n": 5, "band": "Grounded", "text": "It counts aloud in Infernal, tallying every hit it lands."}, {"n": 6, "band": "Textured", "text": "A previous victim's weapon is still lodged, snapped off, between its barbs."}, {"n": 7, "band": "Strange", "text": "Its barbs occasionally weep a thin black ichor that hisses on contact with stone."}, {"n": 8, "band": "Volatile", "text": "It has been ordered here specifically to collect one named soul, and will not stop for anything else."}]}},
 "bearded-devil": {"desc": "Its beard writhes independently of the rest of it, a nest of small biting mouths beneath a face that otherwise looks bored. It fights like a conscript — competent, sour, unenthusiastic — jabbing its glaive with the flat resentment of a soldier serving an eternal, unwanted tour. It complains, in Infernal, about the assignment even as it draws blood.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's the lowest-ranked in its unit and takes every unpleasant post no one else wants."}, {"n": 2, "band": "Grounded", "text": "Its glaive is notched from botched parries — it's not especially skilled."}, {"n": 3, "band": "Grounded", "text": "It mutters complaints about the weather, the pay, and the company the whole fight."}, {"n": 4, "band": "Grounded", "text": "It targets whoever looks most likely to heal others, going for the infernal wound deliberately."}, {"n": 5, "band": "Grounded", "text": "Its beard-mouths keep biting even after the rest of it goes still in death."}, {"n": 6, "band": "Textured", "text": "It carries a tally-stick counting days left on its infernal enlistment — twelve notches remain."}, {"n": 7, "band": "Strange", "text": "It flinches at the word 'promotion,' as if the concept itself causes it pain."}, {"n": 8, "band": "Volatile", "text": "A superior devil watches this fight from just out of reach, grading its performance."}]}},
 "bone-devil": {"desc": "Its frame is a wasp's exoskeleton scaled to nightmare, stretched taut over something skeletal and cruel-eyed. It exists to make sure a bargain is kept — sent to drag back a soul that slipped its due, to make an example of someone who reneged, or simply to remind a petty tyrant exactly whose adulation he's really been propped up by. The stinger arcs overhead on a segmented tail, patient as a debt collector who has never once failed to collect.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's hunting a soul that escaped the Nine Hells before its due date, and has the paperwork to prove it."}, {"n": 2, "band": "Grounded", "text": "Someone nearby broke a deal with a devil, and it's here to collect on their behalf."}, {"n": 3, "band": "Grounded", "text": "It's making an example of an oathbreaker, publicly, on an archdevil's orders."}, {"n": 4, "band": "Grounded", "text": "It props up a self-obsessed local tyrant, feeding him false adulation to keep him corrupt and useful."}, {"n": 5, "band": "Grounded", "text": "It speaks fluent, contemptuous Common, correcting mortals' grammar mid-negotiation."}, {"n": 6, "band": "Textured", "text": "It keeps a private ledger of every broken deal it's ever punished, tallied by how long they begged."}, {"n": 7, "band": "Strange", "text": "Its exoskeleton is inscribed with tiny infernal script that shifts position when no one looks directly at it."}, {"n": 8, "band": "Volatile", "text": "It has been dispatched to make an example of this specific place, and will not leave until it has."}]}},
 "cambion": {"desc": "Half its face could pass for human in candlelight; the other half never quite settles into any one shape. It speaks softly, plans carefully, and burns things only when subtlety fails. Whatever role it wears — merchant, captain, priest — it wears completely, for years if it must, patient in a way few mortals ever manage.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "A charmed lieutenant, loyal past reason, stands ready to defend it without question."}, {"n": 2, "band": "Grounded", "text": "It's mid-negotiation over a contract that will ruin the person signing it."}, {"n": 3, "band": "Grounded", "text": "A rival for its current disguised position is asking uncomfortable questions nearby."}, {"n": 4, "band": "Grounded", "text": "It's carrying a sealed message meant for its fiendish parent, overdue for delivery."}, {"n": 5, "band": "Grounded", "text": "Someone in its inner circle has started to suspect the truth and is being quietly removed."}, {"n": 6, "band": "Textured", "text": "It offers a genuine, useful favor — the kind it never asks repayment for immediately."}, {"n": 7, "band": "Strange", "text": "Its shadow, briefly, shows wings where its body shows none."}, {"n": 8, "band": "Volatile", "text": "Its fiendish parent has just sent a hunter to collect it, and it needs help disappearing again."}]}},
 "chain-devil": {"desc": "Chains uncoil from its shoulders and back like something alive, clinking with a rhythm too even to be accidental. It doesn't chase; it waits for something to come near enough to bind, then reels its catch in with the calm efficiency of a jailer closing a cell door. Its gaze alone can pin a man to the spot before the chains even move.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It guards a specific captive or contract and treats any rescue attempt as a personal insult."}, {"n": 2, "band": "Grounded", "text": "Its chains bear old manacle-cuffs still fitted to long-dead wrists."}, {"n": 3, "band": "Grounded", "text": "It never speaks, communicating entirely through the rattle and snap of its chains."}, {"n": 4, "band": "Grounded", "text": "It prefers to bind and drag rather than kill outright, savoring the struggle."}, {"n": 5, "band": "Grounded", "text": "Rust streaks its chains despite them being sharp as new — an old cosmetic wound."}, {"n": 6, "band": "Textured", "text": "One chain-link bears a name engraved in a mortal hand, from whoever forged the pact that bound it here."}, {"n": 7, "band": "Strange", "text": "Its unnerving gaze leaves afterimages that linger in victims' vision for hours."}, {"n": 8, "band": "Volatile", "text": "It has been tasked with retrieving one specific soul before dawn and will not be talked out of it."}]}},
 "chasme": {"desc": "It hovers with a buzzing drone that never quite stops, wings blurring, compound eyes tracking every twitch of movement in the room. The proboscis unfurls only at the last second, and by then the withering has already begun — victims age and hollow out even as they struggle. It feeds like an insect and thinks like something far worse.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's been assigned as a messenger and courier, resentful of combat duty."}, {"n": 2, "band": "Grounded", "text": "Its drone changes pitch when it's about to strike, a tell a sharp ear can catch."}, {"n": 3, "band": "Grounded", "text": "It clings to ceilings between attacks, spider-climbing to avoid retaliation."}, {"n": 4, "band": "Grounded", "text": "It targets the weakest-looking creature first, feeding before the fight is even decided."}, {"n": 5, "band": "Grounded", "text": "Its wings shed a fine dust that smells faintly of rot wherever it passes."}, {"n": 6, "band": "Textured", "text": "It carries a message capsule strapped to one leg, undelivered, from a demon lord's courier network."}, {"n": 7, "band": "Strange", "text": "Its bite leaves victims looking decades older even after they recover, a wound that never fully mends."}, {"n": 8, "band": "Volatile", "text": "It's fleeing a larger predator and will fight only because cornered — but fights all the harder for it."}]}},
 "dretch": {"desc": "It squats low and wet, skin the color of an old bruise, and it smells like something left too long in standing water. It doesn't understand tactics, or mercy, or fear — only hunger and the dim compulsion to tear at whatever moves. Kill one and three more shamble out of whatever crack it came from, indifferent to the loss.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It was summoned as cannon fodder and abandoned when its summoner fled."}, {"n": 2, "band": "Grounded", "text": "It gnaws at its own claws between attacks, driven by mindless, constant hunger."}, {"n": 3, "band": "Grounded", "text": "It cowers from louder, stronger demons but turns vicious the instant it outnumbers its prey."}, {"n": 4, "band": "Grounded", "text": "Its fetid cloud lingers in enclosed spaces long after it's dead."}, {"n": 5, "band": "Grounded", "text": "It drools a thin black ichor that stains everything it touches."}, {"n": 6, "band": "Textured", "text": "A rusted binding-collar, broken, still hangs around its throat from whoever once controlled it."}, {"n": 7, "band": "Strange", "text": "It flinches from its own reflection, as if it doesn't recognize the shape it's been given."}, {"n": 8, "band": "Volatile", "text": "A whole cluster of them is converging on this spot, summoned in bulk by something bigger nearby."}]}},
 "erinyes": {"desc": "Wings the color of old blood fold neatly behind a soldier's discipline, and the sword she carries has taken more oaths than lives — though it has taken plenty of both. She was an angel once; the memory sits in her like a splinter she refuses to acknowledge, surfacing only in the precision of her mercy-less strikes. Her rope binds tighter than any promise she's ever kept.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "She hunts a specific oathbreaker, and everyone else in the fight is incidental to her."}, {"n": 2, "band": "Grounded", "text": "She fights in eerie, disciplined silence, treating combat as a formal duty."}, {"n": 3, "band": "Grounded", "text": "Her sword bears notches for every soul she's collected on this contract."}, {"n": 4, "band": "Grounded", "text": "She parries with contemptuous ease, rarely needing to press an attack twice."}, {"n": 5, "band": "Grounded", "text": "Old, faded feather-scars mark where wings of a different color once grew."}, {"n": 6, "band": "Textured", "text": "She carries a sealed writ naming the exact debt she's here to collect, and will show it if asked."}, {"n": 7, "band": "Strange", "text": "Her shadow briefly resolves into a different silhouette — feathered, radiant — before snapping back."}, {"n": 8, "band": "Volatile", "text": "She is one of a hunting pack of erinyes closing in on the same target from multiple directions."}]}},
 "glabrezu": {"desc": "It is enormous and patient in a way that unsettles more than its size does — a four-armed brute that could simply crush anything nearby, and chooses instead to talk. It offers wishes phrased as questions, temptations dressed as bargains, testing whether greed will do its work before the pincers ever need to close.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's mid-bargain, offering knowledge or power to a mortal cultist in exchange for a small, specific service."}, {"n": 2, "band": "Grounded", "text": "A previous deal it struck has gone bad, and it's here to collect what was actually promised."}, {"n": 3, "band": "Grounded", "text": "It guards something a summoner paid dearly to bind it to protect."}, {"n": 4, "band": "Grounded", "text": "It's testing whether this group of mortals is worth the effort of a formal contract."}, {"n": 5, "band": "Grounded", "text": "It's been left behind by a fleeing cult leader, unbound and furious about it."}, {"n": 6, "band": "Textured", "text": "It offers real, working magic in trade — the deception is always in the fine print, never the substance."}, {"n": 7, "band": "Strange", "text": "Its four arms never move together — one always lags, as if half-listening elsewhere."}, {"n": 8, "band": "Volatile", "text": "It's already secured a wish from someone here, and is making sure that wish's price gets paid."}]}},
 "gnoll-demoniac": {"desc": "It stands apart from the pack even when surrounded by it, marked by the Abyss's favor in ways the other gnolls flinch from acknowledging. It conjures pooling darkness that eats warmth and hope in equal measure, feeding on the fear before the killing even starts. Something behind its eyes is no longer entirely animal.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It has claimed leadership of the war band through demonstrated demonic favor, not just strength."}, {"n": 2, "band": "Grounded", "text": "It marks its kills with a spiral rune burned into the flesh, a devotion to something abyssal."}, {"n": 3, "band": "Grounded", "text": "Other gnolls give it a wide berth even in the frenzy of a raid."}, {"n": 4, "band": "Grounded", "text": "It hoards the darkness-conjuring ritual's use, unwilling to waste it on weak prey."}, {"n": 5, "band": "Grounded", "text": "Its voice, when it speaks, carries a second, overlapping tone underneath the words."}, {"n": 6, "band": "Textured", "text": "It is trying to open a permanent rift to feed the pack a steady supply of demonic reinforcements."}, {"n": 7, "band": "Strange", "text": "Its shadow, cast in the dark it conjures, doesn't match its own silhouette."}, {"n": 8, "band": "Volatile", "text": "A demon lord has personally noticed this creature and is watching to see if it earns elevation."}]}},
 "gnoll-fang-of-the-beast": {"desc": "It moves at the front of the pack, bone flail whirling, hyena-grin fixed in place whether it's winning or losing. The poison in its bite is almost incidental to the terror of its presence — a herald that means the rest of the war band isn't far behind. It never fights alone by choice.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's a scout sent ahead of the main pack, meant to soften prey before the others arrive."}, {"n": 2, "band": "Grounded", "text": "Its bone flail is decorated with trophies from past hunts — teeth, claws, a broken arrowhead."}, {"n": 3, "band": "Grounded", "text": "It retreats the moment it's alone, unwilling to fight without pack backup."}, {"n": 4, "band": "Grounded", "text": "It howls before every attack, a signal meant to draw the rest of the pack in."}, {"n": 5, "band": "Grounded", "text": "Its poisoned bite has left it half-immune to its own toxin over years of exposure."}, {"n": 6, "band": "Textured", "text": "It carries a fresh ritual scar — recently promoted from ordinary warrior, hungry to prove the promotion earned."}, {"n": 7, "band": "Strange", "text": "It pauses mid-fight, briefly, whenever fire is involved, as if recalling something it fears."}, {"n": 8, "band": "Volatile", "text": "It's performing a birthing ritual on a captured beast nearby, and won't leave until it's done."}]}},
 "gnoll-pack-lord": {"desc": "It commands through volume and violence, bone whip cracking overhead to incite the rest of the pack into the frenzy it feeds on. Its own kills matter less to it than the chaos it directs — a conductor of slaughter more than a soldier in it. When it falls, the pack around it often keeps fighting out of pure inherited momentum.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It holds its position by having personally killed the last three gnolls who challenged it."}, {"n": 2, "band": "Grounded", "text": "It never engages directly until the pack has already worn its prey down."}, {"n": 3, "band": "Grounded", "text": "Bone trophies from rival pack lords hang from its belt, a warning to any who'd try again."}, {"n": 4, "band": "Grounded", "text": "It incites the weakest-looking warrior first, testing loyalty through sacrifice."}, {"n": 5, "band": "Grounded", "text": "It keeps a captive scout alive specifically to relay orders in Common when needed."}, {"n": 6, "band": "Textured", "text": "A rival pack lord's skull, cleaned and painted, hangs from its javelin as a standard."}, {"n": 7, "band": "Strange", "text": "It hears a howl no one else hears, and turns to answer it mid-combat."}, {"n": 8, "band": "Volatile", "text": "It's uniting several smaller packs under one banner, and this fight tests if it's fit to lead."}]}},
 "gnoll-warrior": {"desc": "It fights the way its whole kind fights — without hesitation, without a plan beyond closing the distance and biting down. Its bone bow is crude but its aim is not, honed on years of running prey to ground. It laughs, high and yipping, at things that aren't funny, because the laughing and the killing come from the same hungry place.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's the least experienced in the pack, still proving itself to the others."}, {"n": 2, "band": "Grounded", "text": "Old scars from pack discipline, not enemy blows, mark its hide."}, {"n": 3, "band": "Grounded", "text": "It carries scavenged, mismatched gear — nothing forged, everything looted."}, {"n": 4, "band": "Grounded", "text": "It breaks and flees the instant it's alone or badly outnumbered."}, {"n": 5, "band": "Grounded", "text": "It fights with its bow until the last possible moment, favoring distance over the rend."}, {"n": 6, "band": "Textured", "text": "It's carrying a stolen trinket it doesn't understand the value of, taken from a recent raid."}, {"n": 7, "band": "Strange", "text": "It sniffs the air compulsively before every decision, as if scent matters more than sight to it."}, {"n": 8, "band": "Volatile", "text": "It's the sole survivor sent back to report — and it's more scared of its pack lord than of you."}]}},
 "hell-hound": {"desc": "It moves in a loping pack-trot, ember-eyed and patient, the way wolves move when they know they'll win eventually. Its bark is a cough of flame, and its bite carries heat long after the wound stops bleeding. It hunts as a unit, always, closing from multiple directions at once.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It runs with a full pack, using pack tactics to isolate the weakest target first."}, {"n": 2, "band": "Grounded", "text": "It's a bonded hunting hound belonging to a devil overseer, tracking a specific scent."}, {"n": 3, "band": "Grounded", "text": "Its coat is scorched black from its own fire breath, singed at the edges permanently."}, {"n": 4, "band": "Grounded", "text": "It circles rather than charges, herding prey toward a chokepoint."}, {"n": 5, "band": "Grounded", "text": "Its eyes glow brighter the longer the chase runs, tracking heat as much as scent."}, {"n": 6, "band": "Textured", "text": "A chain leash, snapped, still trails from a collar — it's escaped or been loosed from a handler."}, {"n": 7, "band": "Strange", "text": "Its footprints smolder and blacken the ground for hours after it passes."}, {"n": 8, "band": "Volatile", "text": "The whole pack answers to a single alpha nearby, and killing the alpha will scatter the rest."}]}},
 "hezrou": {"desc": "It squats on thick, toad-like haunches, and the reek of it arrives well before the claws do. Every few breaths its slick hide erupts in something wrong — a ridge of mismatched fangs, a bloom of fungus, a half-formed face — before the bulge sinks back into the muscle like nothing happened. It is grunt-work made flesh, the kind of demon smarter fiends send to take the first hit, and it soaks up abuse from its betters only to pass every ounce of it downward onto whatever it corners next.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Was left behind by a retreating horde, still following its last order to the letter."}, {"n": 2, "band": "Grounded", "text": "Bears fresh claw-scars from a beating dealt by something far worse than itself."}, {"n": 3, "band": "Grounded", "text": "Bullies weaker fiends nearby, passing on abuse it clearly can't return upward."}, {"n": 4, "band": "Grounded", "text": "Guards a summoning circle it was bound to hold, too dim to abandon the post."}, {"n": 5, "band": "Grounded", "text": "Its stench has driven every living thing out of the area for a mile."}, {"n": 6, "band": "Textured", "text": "A patch of its hide keeps sprouting the same half-formed, snarling little face."}, {"n": 7, "band": "Strange", "text": "Something crawled out of one of its skin-eruptions and is now loose nearby."}, {"n": 8, "band": "Volatile", "text": "A stronger demon it serves is due to collect it soon, and will not be pleased at the delay."}]}},
 "horned-devil": {"desc": "It stands like a siege engine given a soul — barbed horns, a forked spear, wings that block out torchlight. It commands lesser devils with a bark that carries across a battlefield, and its own attacks are slow, deliberate, devastating. It doesn't flinch from fire because it is, in most ways, made of the same appetite.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's commanding a mixed unit of lesser devils, directing their positioning before joining the fight itself."}, {"n": 2, "band": "Grounded", "text": "Its infernal tail wound is a signature it leaves deliberately on every kill, a mark of its unit."}, {"n": 3, "band": "Grounded", "text": "It hurls flame from range before ever closing to melee, softening targets first."}, {"n": 4, "band": "Grounded", "text": "Chains of rank-insignia, forged from captured mortal weapons, hang from its horns."}, {"n": 5, "band": "Grounded", "text": "It speaks in clipped military Infernal, issuing orders even mid-combat."}, {"n": 6, "band": "Textured", "text": "It's evaluating a lesser devil unit's performance under fire, and treats this fight as a training exercise."}, {"n": 7, "band": "Strange", "text": "Its wingbeats sound like distant screaming when it flies at speed."}, {"n": 8, "band": "Volatile", "text": "It's here to enforce discipline on devils who failed a previous assignment, and mortals are incidental to that."}]}},
 "ice-devil": {"desc": "It moves with glacial, armored patience, scales rimed permanently in frost that never quite melts even near open flame. Its spears fly true and cold, and where they land the air itself seems to thicken and slow. It is old, disciplined, and utterly without urgency — it has never once needed to hurry.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's a fortress-guard, stationed at a chokepoint it will not abandon under any circumstance."}, {"n": 2, "band": "Grounded", "text": "Frost creeps outward from where it stands, slowly icing over the ground and walls nearby."}, {"n": 3, "band": "Grounded", "text": "It conjures walls of ice to control the battlefield before ever closing to melee."}, {"n": 4, "band": "Grounded", "text": "Its spear returns to its claw unerringly, a weapon it's carried for centuries."}, {"n": 5, "band": "Grounded", "text": "It speaks rarely, and only in short, absolute commands."}, {"n": 6, "band": "Textured", "text": "It's overseeing a labor detail of lesser devils, more warden than warrior in this scene."}, {"n": 7, "band": "Strange", "text": "Its breath crystallizes into tiny falling shards of ice that never quite touch the ground."}, {"n": 8, "band": "Volatile", "text": "It answers directly to a named infernal noble, and reports of this encounter will reach them by nightfall."}]}},
 "imp": {"desc": "It perches somewhere just out of easy reach — a rafter, a shoulder, a windowsill — small and grinning, and it will run the instant real danger shows up. Cowardice is its whole survival strategy: it shape-shifts into a rat or raven or spider to vanish rather than fight, and its sting carries a poison built to discourage a second attempt. Sent to spy for a master, it reports back with details quietly bent toward whatever keeps its own schemes moving — it serves no one's interests as faithfully as it serves its own.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's been reporting on this scene to its master via telepathic bond, and knows more than it should."}, {"n": 2, "band": "Grounded", "text": "It's posing as an ordinary rat, raven, or spider, and has been eavesdropping for days."}, {"n": 3, "band": "Grounded", "text": "It offers to trade real information for its own freedom, and will honor exactly what it promises."}, {"n": 4, "band": "Grounded", "text": "It's been harassing one specific target for hours, stinging and vanishing, never pressing for the kill."}, {"n": 5, "band": "Grounded", "text": "A binding circle nearby suggests it's still tethered to a summoner close at hand."}, {"n": 6, "band": "Textured", "text": "It's quietly bent its last report to its master, hiding a detail that serves its own scheme better."}, {"n": 7, "band": "Strange", "text": "It knows one true, private secret about someone in the scene, and leads with it if cornered."}, {"n": 8, "band": "Volatile", "text": "Its master has decided the investment here isn't worth maintaining, and the imp is about to act on new orders."}]}},
 "incubus": {"desc": "It looks the way you wish someone looked — precisely, uncannily, tailored to whoever's watching. It doesn't need to lie because desire does the lying for it, and its touch leaves an exhaustion that no amount of rest can undo. It is patient the way a debt collector is patient, certain the account will come due eventually.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's cultivated a devoted admirer in town who doesn't know what they're actually serving."}, {"n": 2, "band": "Grounded", "text": "A victim of its curse hasn't slept properly in weeks and is fraying badly."}, {"n": 3, "band": "Grounded", "text": "It's using Dream to reach a specific sleeper elsewhere, and this encounter interrupts that."}, {"n": 4, "band": "Grounded", "text": "It's shifted into its Succubus form recently and is still adjusting to the change."}, {"n": 5, "band": "Grounded", "text": "It has a genuine soft spot for one of its marks, against its own better judgment."}, {"n": 6, "band": "Textured", "text": "It offers real comfort, real listening, real seeming kindness — the harvest comes later, quietly."}, {"n": 7, "band": "Strange", "text": "Its true face, glimpsed only in reflection, doesn't match the one it's wearing."}, {"n": 8, "band": "Volatile", "text": "A jealous rival — another fiend it's crossed — is actively hunting it and will arrive soon."}]}},
 "jackalwere": {"desc": "It walks among ordinary travelers wearing an ordinary face, until the moment it doesn't need to anymore. The shift to hybrid or full jackal form takes only a breath, and the sleep-gaze that follows drops victims before they understand they were ever in danger. It hunts in loose, opportunistic packs, patient as any predator that's learned people trust faces.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's embedded in a caravan or settlement, posing as an ordinary traveler for weeks."}, {"n": 2, "band": "Grounded", "text": "It hunts with two or three others, coordinating an ambush disguised as a friendly escort."}, {"n": 3, "band": "Grounded", "text": "It uses its sleep gaze to drop the strongest-looking target first, before the fight even starts."}, {"n": 4, "band": "Grounded", "text": "Its human disguise is convincing but slips under stress — the eyes flash gold."}, {"n": 5, "band": "Grounded", "text": "It abandons victims who wake before it can finish, cutting losses without hesitation."}, {"n": 6, "band": "Textured", "text": "It's been feeding on a specific village slowly, one traveler at a time, to avoid notice."}, {"n": 7, "band": "Strange", "text": "It never fully commits to either form, flickering between human and jackal mid-fight."}, {"n": 8, "band": "Volatile", "text": "A whole pack of them has infiltrated a caravan or settlement, and this one is the first to be caught."}]}},
 "lamia": {"desc": "From the waist up she could be a queen; from the waist down, something has gone terribly, deliberately wrong. She offers illusions of comfort — food, wine, a friendly face — and her corrupting touch does the rest, turning trust into a leash. She has outlived every mortal who ever thought they'd tamed her.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "She's maintained a comfortable illusion-palace for years, drawing in travelers who never leave."}, {"n": 2, "band": "Grounded", "text": "A charmed servant, utterly loyal, guards her sanctum and doesn't realize what's happened to it."}, {"n": 3, "band": "Grounded", "text": "She's scrying on a specific rival or threat and is distracted when first encountered."}, {"n": 4, "band": "Grounded", "text": "Ruins nearby hold the remains of a previous 'guest' she grew tired of."}, {"n": 5, "band": "Grounded", "text": "She offers a geas-bound bargain that sounds generous and isn't."}, {"n": 6, "band": "Textured", "text": "She's genuinely lonely, in her way, and the corruption is as much about company as control."}, {"n": 7, "band": "Strange", "text": "Her illusion-disguise occasionally glitches near mirrors or still water, showing her true shape."}, {"n": 8, "band": "Volatile", "text": "She's collecting a very specific kind of victim for a patron she answers to, and time is running out."}]}},
 "larva": {"desc": "It writhes in the muck of the lower planes, blind and mindless, a soul stripped down to appetite and shape. It has no weapon but its bite and no ambition beyond it, and it exists mostly to be stepped on, harvested, or fed to something bigger. Pity would be wasted on it, and so would fear.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's one of a writhing mass, indistinguishable from a thousand others in the muck."}, {"n": 2, "band": "Grounded", "text": "It was once a mortal soul of no particular note, and nothing of that remains but the shape."}, {"n": 3, "band": "Grounded", "text": "It's being harvested by a larger demon for later use, and this one slipped free."}, {"n": 4, "band": "Grounded", "text": "It bites reflexively at anything that comes near, with no strategy behind it."}, {"n": 5, "band": "Grounded", "text": "It's stuck, half-buried, and can barely move to attack at all."}, {"n": 6, "band": "Textured", "text": "It briefly forms a word with its bite-marks in the mud before losing the thought entirely."}, {"n": 7, "band": "Strange", "text": "Its blind writhing briefly aligns into a shape that looks, disturbingly, like a face."}, {"n": 8, "band": "Volatile", "text": "A demon of rank is nearby collecting a batch of these for a ritual, and will notice if disturbed."}]}},
 "lemure": {"desc": "It's the shape a soul takes when there's nothing left worth keeping — a slumped, faceless thing of half-melted flesh that shambles forward on instinct alone. It doesn't hate you; it doesn't feel anything anymore. It slimes and gropes and dies again and again, and in the Nine Hells, it will simply get back up.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's part of a larger mass being driven forward by a devil overseer with a whip."}, {"n": 2, "band": "Grounded", "text": "It shambles in the exact direction it was last pointed, with no independent will left."}, {"n": 3, "band": "Grounded", "text": "Half-formed features on its slumped face occasionally suggest who it might once have been."}, {"n": 4, "band": "Grounded", "text": "It doesn't flee, doesn't hesitate, doesn't do anything but close distance and slime."}, {"n": 5, "band": "Grounded", "text": "Its body steams faintly, as if still cooling from whatever process made it."}, {"n": 6, "band": "Textured", "text": "It's being fed on, slowly, by a bone devil overseer who finds its suffering entertaining."}, {"n": 7, "band": "Strange", "text": "For one instant, its slumped mouth forms a word — a name — before collapsing back to nothing."}, {"n": 8, "band": "Volatile", "text": "An entire wave of them is being marched toward this location by something with real authority."}]}},
 "manes": {"desc": "It is what happens to a soul the Abyss doesn't bother giving a shape to — hunched, gnashing, barely more than teeth and hunger wearing a body. It doesn't plan, doesn't retreat, doesn't understand anything except the thing in front of it that might be food. Kill it and nothing is lost that wasn't already gone.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's part of a loose cluster, drawn together by proximity rather than any real cooperation."}, {"n": 2, "band": "Grounded", "text": "It gnaws at its own claws between attacks, driven by constant undirected hunger."}, {"n": 3, "band": "Grounded", "text": "It was summoned in bulk as expendable filler and immediately abandoned."}, {"n": 4, "band": "Grounded", "text": "It attacks the nearest moving thing without any distinction between friend and foe."}, {"n": 5, "band": "Grounded", "text": "Its claws are the only sharp thing about it — everything else is soft, wet, and rotting."}, {"n": 6, "band": "Textured", "text": "A larger demon nearby treats these as disposable shock troops, feeding them into danger first."}, {"n": 7, "band": "Strange", "text": "It occasionally stops mid-motion, as if trying and failing to remember what it used to be."}, {"n": 8, "band": "Volatile", "text": "Dozens more of them are boiling up from a crack in reality nearby, and this is just the first."}]}},
 "manes-vaporspawn": {"desc": "It moves like smoke given claws, squeezing through gaps no solid thing should fit through, trailing a sickening vapor that thickens the air behind it. It's a manes that's learned one trick — contortion — and it uses that trick relentlessly, appearing where it has no business being. Its hunger is the same mindless hunger as its kin; its patience for reaching you is new.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's slipped through a gap meant to be sealed, and its vapor trail marks its exact path."}, {"n": 2, "band": "Grounded", "text": "It squeezes through cracks to flank rather than confront directly."}, {"n": 3, "band": "Grounded", "text": "Its vapor lingers in enclosed rooms, incapacitating anyone who lingers too long."}, {"n": 4, "band": "Grounded", "text": "It emerged from a crack too small for anything else to have followed."}, {"n": 5, "band": "Grounded", "text": "It moves in an unsettling boneless way, folding around corners rather than turning them."}, {"n": 6, "band": "Textured", "text": "It's the vanguard of a larger incursion, scouting a path the rest of its kind will follow."}, {"n": 7, "band": "Strange", "text": "Its vapor briefly forms shapes — hands, faces — before dissipating."}, {"n": 8, "band": "Volatile", "text": "It's already found and marked a gap that leads somewhere it shouldn't, and more are coming through."}]}},
 "marilith": {"desc": "Six arms move six blades in a rhythm no mortal fencer could match, a serpent's coil beneath a warlord's torso. She remembers every battle she's ever fought with perfect, obsessive clarity, and treats each new one as an insult to that memory if it isn't worthy. She does not tire, does not panic, and does not stop reacting even when everyone else would.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "She commands a demonic legion nearby and treats this fight as a minor distraction from that duty."}, {"n": 2, "band": "Grounded", "text": "She critiques opponents' technique mid-combat, genuinely disappointed by weak swordplay."}, {"n": 3, "band": "Grounded", "text": "Her six blades are each etched with a different name — kills she considered worth remembering."}, {"n": 4, "band": "Grounded", "text": "She constricts the weakest fighter first to remove them from the equation methodically."}, {"n": 5, "band": "Grounded", "text": "She fights without a hint of urgency, treating even mortal danger as beneath real concern."}, {"n": 6, "band": "Textured", "text": "She's been sent to retrieve a specific defector or deserter, and everyone else here is collateral."}, {"n": 7, "band": "Strange", "text": "Her coiled lower body leaves scale-patterns burned into stone floors long after she's gone."}, {"n": 8, "band": "Mythic", "text": "She commands legions in the Blood War and is only here because something got her personal attention."}]}},
 "mezzoloth": {"desc": "It fights like a mercenary who's read the contract twice — efficient, unemotional, entirely professional about violence. Its claws and trident work in practiced tandem, and when the trident leaves its hand it always comes back, the way loyalty in Gehenna never quite does. It serves whoever's paying, until it doesn't.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's part of a mercenary unit hired by a summoner with more gold than sense."}, {"n": 2, "band": "Grounded", "text": "It fights with cold professionalism, disengaging the instant the contract's terms are met."}, {"n": 3, "band": "Grounded", "text": "Its trident bears notches marking successful contracts, not personal kills."}, {"n": 4, "band": "Grounded", "text": "It coordinates precisely with other yugoloths nearby, more soldier than brute."}, {"n": 5, "band": "Grounded", "text": "It negotiates briefly before combat, genuinely willing to walk away for the right price."}, {"n": 6, "band": "Textured", "text": "It's owed payment from a previous job and is here collecting, not attacking on principle."}, {"n": 7, "band": "Strange", "text": "Its Cloudkill lingers in patterns that seem almost deliberately drawn, like a signature."}, {"n": 8, "band": "Volatile", "text": "Its unit was betrayed by whoever hired them, and it's furious in a way yugoloths rarely bother to be."}]}},
 "nalfeshnee": {"desc": "It's grotesquely bloated, tusked, crowned in small horns, and it moves through space itself rather than around obstacles — teleporting with a wet, tearing sound like reality itself flinching. It relishes cruelty theoretically as much as practically, savoring the anticipation of a kill nearly as much as the kill itself.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's overseeing a cult's ritual, more interested in the ceremony than the fight interrupting it."}, {"n": 2, "band": "Grounded", "text": "It teleports to flank rather than charge, savoring the panic of being outmaneuvered."}, {"n": 3, "band": "Grounded", "text": "It pursues fleeing targets relentlessly, teleporting again and again to close distance."}, {"n": 4, "band": "Grounded", "text": "Its bloated frame belies genuine cunning — it thinks several moves ahead."}, {"n": 5, "band": "Grounded", "text": "It speaks in an oily, self-satisfied purr, narrating its own violence with relish."}, {"n": 6, "band": "Textured", "text": "It's been summoned by a cult that believes it serves them — it does not."}, {"n": 7, "band": "Strange", "text": "Its teleportation leaves a brief afterimage of its true, larger Abyssal form."}, {"n": 8, "band": "Volatile", "text": "It's brokering something significant with a mortal power broker, and this fight threatens the deal."}]}},
 "night-hag": {"desc": "By day she might be a midwife, a healer, an old woman selling remedies — and at night the mask comes off along with the borrowed skin she wears over her true, warty hide. Her soul bag hangs heavy at her hip, and the dreams she haunts leave victims aging and hollowed from the inside. She works best with sisters, but she'll manage alone.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "She's part of a coven working together nearby, and calling on them mid-fight would change everything."}, {"n": 2, "band": "Grounded", "text": "A victim is currently trapped in a nightmare she's actively haunting via her soul bag."}, {"n": 3, "band": "Grounded", "text": "She's disguised as a trusted local healer or midwife, embedded for months."}, {"n": 4, "band": "Grounded", "text": "Her soul bag holds several trapped souls already, and destroying it would free them."}, {"n": 5, "band": "Grounded", "text": "She's scrying on someone specific and is genuinely annoyed at the interruption."}, {"n": 6, "band": "Textured", "text": "She offers real, useful information in trade for being left alone — she keeps her word on trades."}, {"n": 7, "band": "Strange", "text": "Her borrowed human skin doesn't quite fit right in certain light, seams visible at the throat."}, {"n": 8, "band": "Volatile", "text": "Her coven-sisters are within calling distance, and she's stalling specifically to summon them."}]}},
 "nightmare": {"desc": "It gallops on hooves wreathed in flame, mane and tail burning without consuming, eyes like coals in a face too intelligent for a horse. It carries riders willingly only for those it's bonded to — everyone else it simply tramples, indifferent as weather. Between the Material Plane and the Ethereal, it moves like it was never truly anywhere at all.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's bonded to a specific fiendish rider and won't leave without them."}, {"n": 2, "band": "Grounded", "text": "It phases in and out of the Ethereal Plane mid-chase, appearing suddenly from nowhere."}, {"n": 3, "band": "Grounded", "text": "Its fire illuminates a wide radius wherever it stands, impossible to approach unseen."}, {"n": 4, "band": "Grounded", "text": "It's feral and riderless, having thrown or outlived its last owner."}, {"n": 5, "band": "Grounded", "text": "It tramples rather than bites, using pure momentum as its primary weapon."}, {"n": 6, "band": "Textured", "text": "Scorched hoofprints leading away suggest it recently delivered someone somewhere specific."}, {"n": 7, "band": "Strange", "text": "Its flame casts shadows that move independently of any light source in the room."}, {"n": 8, "band": "Volatile", "text": "A named infernal or cult figure is due to arrive riding it any moment now."}]}},
 "nycaloth": {"desc": "It fights with the cold efficiency of a professional soldier who's forgotten what fighting for anything else feels like. Its axe returns to its hand after every throw, and it never wastes motion — no taunts, no flourishes, just economical, brutal competence. It serves Gehenna's endless war and treats every other conflict as practice.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's on loan to a mortal patron as hired muscle, contractually bound but professionally detached."}, {"n": 2, "band": "Grounded", "text": "It assesses opponents silently before engaging, choosing targets by threat level, not proximity."}, {"n": 3, "band": "Grounded", "text": "Its axe bears battle-honors from the Blood War, notched in a private counting system."}, {"n": 4, "band": "Grounded", "text": "It retreats tactically rather than fighting to the death, valuing survival over glory."}, {"n": 5, "band": "Grounded", "text": "It communicates in short, efficient barks, more soldier than showman."}, {"n": 6, "band": "Textured", "text": "It's scouting this location for a larger yugoloth incursion, gathering intelligence more than fighting."}, {"n": 7, "band": "Strange", "text": "Its wings fold with an audible, unsettling click, like a mechanism rather than flesh."}, {"n": 8, "band": "Volatile", "text": "It's under orders from a superior it fears more than it fears death, and failure isn't an option for it."}]}},
 "oni": {"desc": "It wears a farmer's face until it doesn't need to, then unfolds into something enormous, tusked, and hungry for terror as much as flesh. It regenerates wounds that would kill lesser things and shifts shape as easily as breathing, patient enough to spend years perfecting a disguise before spending one night ruining a village. It prefers the dark and the long con both.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's posed as a village elder or landowner for years, slowly consolidating quiet influence."}, {"n": 2, "band": "Grounded", "text": "A missing-persons pattern nearby traces back to its favored hunting grounds."}, {"n": 3, "band": "Grounded", "text": "It's mid-negotiation, using its Giant form to intimidate a local strongman into compliance."}, {"n": 4, "band": "Grounded", "text": "It regenerates faster than expected, and a previous fight against it ended in a costly draw."}, {"n": 5, "band": "Grounded", "text": "It's hoarding wealth in a hidden lair, planning something bigger than simple predation."}, {"n": 6, "band": "Textured", "text": "It offers a bargain it has every intention of honoring — its word, unusually, is good."}, {"n": 7, "band": "Strange", "text": "Its shape-shift briefly stutters under stress, showing tusks through a human face."}, {"n": 8, "band": "Volatile", "text": "It's been feeding a nearby cult false prophecies through its disguise, and the plan comes due soon."}]}},
 "pit-fiend": {"desc": "It stands like the idea of Hell given a body — vast, crowned, radiating a fear that grips even before it moves. Fire coils around its mace, poison waits in its bite, and its wings fold with the terrible patience of something that commands legions and rarely needs to lift a claw itself. When it finally fights personally, it's because something has genuinely earned its attention.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It commands a legion nearby and only entered this fight because a subordinate failed first."}, {"n": 2, "band": "Grounded", "text": "Its fear aura clears the weak from the field before it even attacks."}, {"n": 3, "band": "Grounded", "text": "It negotiates first, genuinely willing to accept a lesser prize than total victory."}, {"n": 4, "band": "Grounded", "text": "It fights with contemptuous economy, treating the battle as beneath its full attention."}, {"n": 5, "band": "Grounded", "text": "Its crown bears the marks of infernal rank, recognized instantly by any devil present."}, {"n": 6, "band": "Textured", "text": "It's collecting on a contract signed generations ago, and the current bearer had no idea it existed."}, {"n": 7, "band": "Strange", "text": "Its shadow, cast by hellfire, briefly forms the shape of an entire legion behind it."}, {"n": 8, "band": "Mythic", "text": "Its presence here means Hell itself considers this location strategically significant."}]}},
 "quasit": {"desc": "It's small, gleeful, and cruel in the way of something that's never once had to answer for its choices. It hides invisible, shifts into a bat or a toad or a centipede when convenient, and delights in the specific terror of Scare more than it cares about the killing blow. It survives by being useful, or by being too small to be worth the effort of hunting down.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's bound as a cultist's familiar, using Scare to soften victims before its master finishes them."}, {"n": 2, "band": "Grounded", "text": "It's been posing as an ordinary bat or toad, listening in on a conversation it shouldn't have heard."}, {"n": 3, "band": "Grounded", "text": "It's free of its former master's binding and has spent days causing petty chaos in the area."}, {"n": 4, "band": "Grounded", "text": "It offers to trade information for its freedom, and will actually honor the exact deal made."}, {"n": 5, "band": "Grounded", "text": "A prisoner nearby is more frightened than the situation explains — this thing's been at them for hours."}, {"n": 6, "band": "Textured", "text": "It knows a genuine secret about someone present, and will use it the instant it's cornered."}, {"n": 7, "band": "Strange", "text": "It giggles at moments that make no sense, as if amused by a joke only it can hear."}, {"n": 8, "band": "Volatile", "text": "It's built a tiny fiefdom for itself here, convincing weaker creatures it's a genuine devil-lord."}]}},
 "rakshasa": {"desc": "It wears wealth the way other predators wear fur — naturally, completely, as camouflage. Its hands, backward at the wrist under the silk gloves, are the only tell that something's deeply wrong, and by the time you notice, its curse has already taken hold. Magic slides off it like water off oiled leather; it has never once needed to fear a wizard.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's embedded as minor nobility or a wealthy merchant, cultivating influence for years."}, {"n": 2, "band": "Grounded", "text": "A cursed victim nearby can no longer benefit from rest, slowly wasting away from its touch."}, {"n": 3, "band": "Grounded", "text": "It's manipulating a genuine power struggle from the shadows, backing whichever side profits it most."}, {"n": 4, "band": "Grounded", "text": "Its greater magic resistance has made it dismissive of spellcasters entirely — a real blind spot."}, {"n": 5, "band": "Grounded", "text": "It keeps meticulous records of every favor owed to it, and calls them in without mercy."}, {"n": 6, "band": "Textured", "text": "It offers a genuinely useful alliance, expecting nothing suspicious in return — yet."}, {"n": 7, "band": "Strange", "text": "Its reversed hands move independently of its expression, betraying tension its face never shows."}, {"n": 8, "band": "Volatile", "text": "It's orchestrating a succession crisis that will hand it real political power within days."}]}},
 "sahuagin-baron": {"desc": "It rules its reef the way an old warlord rules a battlefield he's memorized — every current, every ambush point, every weakness in the coral known by heart. Sharks answer to its will as readily as its own soldiers do, and it fights with the frenzy of something that's tasted blood in the water and never lost the taste for more.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "A hunting pack of controlled sharks patrols nearby, ready to answer its telepathic call."}, {"n": 2, "band": "Grounded", "text": "It's defending a specific undersea territory recently contested by a rival baron."}, {"n": 3, "band": "Grounded", "text": "Captured surface-dweller prisoners are held in a submerged cage nearby, awaiting its judgment."}, {"n": 4, "band": "Grounded", "text": "Its fiendish blood curses anyone who draws its blood, marking them for other fiends to hunt."}, {"n": 5, "band": "Grounded", "text": "It's escorting a raiding party toward a coastal settlement and this encounter delays the raid."}, {"n": 6, "band": "Textured", "text": "It's negotiating a truce with a surface faction that badly needs safe shipping lanes."}, {"n": 7, "band": "Strange", "text": "Its scales shimmer with a faint, unnatural sheen that sharks specifically seem drawn to."}, {"n": 8, "band": "Volatile", "text": "It's rallying every sahuagin in the region for a coordinated assault within days."}]}},
 "sahuagin-priest": {"desc": "It chants in the clicking tongue of the deep, calling spectral jaws out of nothing to savage anyone who threatens its congregation. It moves between water and air with the same predatory ease its kin show, but it fights with purpose rather than frenzy — this one has a god to answer to. Its faith is as sharp as its teeth.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's conducting a ritual meant to bless an upcoming raid with a hunting god's favor."}, {"n": 2, "band": "Grounded", "text": "A captive is being prepared as an offering, bound and waiting nearby."}, {"n": 3, "band": "Grounded", "text": "It carries a coral idol that other sahuagin visibly defer to."}, {"n": 4, "band": "Grounded", "text": "It's brokering a dispute between two sahuagin factions and treats interruption as sacrilege."}, {"n": 5, "band": "Grounded", "text": "It uses Tongues to interrogate surface-dwellers before deciding whether they're worth sparing."}, {"n": 6, "band": "Textured", "text": "It offers safe passage through its territory in exchange for a specific favor owed to its faith."}, {"n": 7, "band": "Strange", "text": "Its spectral jaws leave bite-marks that don't match its own mouth's shape at all."}, {"n": 8, "band": "Volatile", "text": "It's about to complete a ritual that will draw every sahuagin nearby into a frenzy."}]}},
 "sahuagin-warrior": {"desc": "It surfaces just long enough to strike, then vanishes back beneath the waves before retaliation can land. It hunts in packs, drawn to blood in the water like the sharks it commands, and its claws are the least of what makes it dangerous — the ambush is the real weapon. It has no patience for prey that fights back effectively.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's part of a raiding party targeting a specific coastal settlement or ship."}, {"n": 2, "band": "Grounded", "text": "It surfaces only to strike, retreating underwater the instant a fight turns against it."}, {"n": 3, "band": "Grounded", "text": "It targets already-wounded prey first, its blood frenzy making it reckless against weak targets."}, {"n": 4, "band": "Grounded", "text": "It's scouting ahead of a larger war party, meant to report rather than fully engage."}, {"n": 5, "band": "Grounded", "text": "Old net-scars mark its hide from a previous encounter with fishermen."}, {"n": 6, "band": "Textured", "text": "It's carrying a stolen trinket from a raided ship, unaware of its actual value."}, {"n": 7, "band": "Strange", "text": "It communicates with nearby sharks through clicks and gestures no surface creature can parse."}, {"n": 8, "band": "Volatile", "text": "An entire raiding party is minutes behind it, drawn by the commotion of this fight."}]}},
 "spined-devil": {"desc": "It darts overhead in tight, mocking loops, spines raining down before its target even registers the threat. It's a coward by devil standards — quick to flee, quick to harass, entirely unwilling to commit to a fair fight. It laughs, a dry rattling sound, whenever a spine finds its mark.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It harasses from range, breaking off entirely if anyone closes the distance."}, {"n": 2, "band": "Grounded", "text": "It flies in mocking, taunting loops, clearly enjoying the harassment more than the kill."}, {"n": 3, "band": "Grounded", "text": "It's part of a small flock, coordinating strafing runs from multiple angles."}, {"n": 4, "band": "Grounded", "text": "It targets spellcasters specifically, having learned they're easiest to interrupt."}, {"n": 5, "band": "Grounded", "text": "Its spines regrow within the hour, letting it return again and again to the same fight."}, {"n": 6, "band": "Textured", "text": "It's scouting for a larger devil force, reporting troop positions rather than fighting seriously."}, {"n": 7, "band": "Strange", "text": "Its cackling laugh seems to come from slightly the wrong direction every time."}, {"n": 8, "band": "Volatile", "text": "It's fleeing something bigger and only fights because it's been cornered mid-escape."}]}},
 "spirit-naga": {"desc": "It forgets nothing — not the slight, not the debt, not the exact words of the insult, and centuries haven't dulled a single grudge. It coils in a joyless lair steeped in its own bitterness, plotting vengeance against the living with the patience only true immortality affords. Its bite carries venom and its stare carries something worse: perfect, petty, undying spite.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's convinced a specific bloodline still owes it a centuries-old debt, and wants collection."}, {"n": 2, "band": "Grounded", "text": "It was driven from a home it still considers rightfully its own, and wants it back."}, {"n": 3, "band": "Grounded", "text": "A rival has been spying on its lair, and it's rigged the place with vindictive traps."}, {"n": 4, "band": "Grounded", "text": "It believes the locals mock it behind its back and is scheming a petty, lasting humiliation."}, {"n": 5, "band": "Grounded", "text": "It's certain someone nearby's treasure is rightfully its own, by a grievance decades old."}, {"n": 6, "band": "Textured", "text": "It will trade a genuine secret for a slight against its enemies, dispassionately, like a merchant."}, {"n": 7, "band": "Strange", "text": "It recites the exact wording of an old insult, verbatim, centuries after the fact."}, {"n": 8, "band": "Volatile", "text": "Its scheme against an old enemy is finally, patiently, about to come due."}]}},
 "succubus": {"desc": "She's whatever face makes the room forget itself — and the forgetting is the point. Her touch takes more than pleasure, draining resolve and vitality both, and if the mask ever slips, it's only because she's chosen to let it. She can become an incubus at will, but she rarely bothers; this shape has never failed her.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "A charmed patron, wealthy and devoted, funds her comfortably without asking questions."}, {"n": 2, "band": "Grounded", "text": "A previous victim is fading, hollowed by her draining kiss, and doesn't understand why."}, {"n": 3, "band": "Grounded", "text": "She's embedded in a noble court or guild, cultivating influence patiently over years."}, {"n": 4, "band": "Grounded", "text": "She's shifted to Incubus form recently and is testing how the change plays with a new target."}, {"n": 5, "band": "Grounded", "text": "A jealous rival — mortal or fiend — is actively working to expose her."}, {"n": 6, "band": "Textured", "text": "She offers a genuine, working deal — the corruption comes later, and slowly."}, {"n": 7, "band": "Strange", "text": "Mirrors near her occasionally show her true form for half a heartbeat before correcting."}, {"n": 8, "band": "Volatile", "text": "Her current mark is close to discovering the truth, and she's deciding whether to flee or silence them."}]}},
 "swarm-of-dretches": {"desc": "It moves as a single wet, gnashing mass, dozens of dretch bodies pressed so close they act as one animal. It squeezes through gaps no single body should manage, and the stench that trails it thickens the air into something you can taste. Killing part of it barely thins the whole.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It was summoned in bulk and abandoned when its summoner fled or died."}, {"n": 2, "band": "Grounded", "text": "It squeezes through gaps and doorways no individual creature its apparent size should fit through."}, {"n": 3, "band": "Grounded", "text": "It thins and grows sluggish as it takes damage, visibly less coordinated when bloodied."}, {"n": 4, "band": "Grounded", "text": "Its fetid aura fills enclosed rooms fast, making retreat as dangerous as engaging."}, {"n": 5, "band": "Grounded", "text": "It moves toward the loudest sound in the area, drawn by noise more than sight."}, {"n": 6, "band": "Textured", "text": "A larger demon is using it as living cover, hiding within the mass to approach unseen."}, {"n": 7, "band": "Strange", "text": "Individual dretches within it occasionally turn to face a direction nothing else is looking."}, {"n": 8, "band": "Volatile", "text": "It's the vanguard of a much larger incursion pouring through a nearby breach."}]}},
 "swarm-of-larvae": {"desc": "It's a writhing carpet of half-formed souls, mindless and blind, biting at anything that moves within reach. Individually pathetic, together they're a slow, grinding hazard — a floor that bites back. Nothing here remembers being a person, and nothing here is trying to.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It covers the floor of a chamber being used to harvest souls for a larger demon."}, {"n": 2, "band": "Grounded", "text": "It's slow but relentless, more hazard terrain than active hunter."}, {"n": 3, "band": "Grounded", "text": "It thins visibly when bloodied, individual larvae dying off from the mass."}, {"n": 4, "band": "Grounded", "text": "It surges toward warmth, drawn to living bodies more than sight or sound."}, {"n": 5, "band": "Grounded", "text": "It's been herded here deliberately, penned by something that intends to use it later."}, {"n": 6, "band": "Textured", "text": "A demon is due to arrive shortly to harvest this batch for a specific ritual purpose."}, {"n": 7, "band": "Strange", "text": "The mass briefly ripples in unison, as if responding to a sound no one else can hear."}, {"n": 8, "band": "Volatile", "text": "It's spilling out from a breach faster than it can be contained, growing by the hour."}]}},
 "swarm-of-lemures": {"desc": "It shambles as one grinding, slumping mass, dozens of ruined bodies pressed together into a single hazard. It doesn't hunt so much as flow, slow and relentless, toward whatever's nearest. In the Nine Hells it would simply reform after death; here, it just keeps coming until it doesn't.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's being driven forward by a devil overseer positioned somewhere just out of sight."}, {"n": 2, "band": "Grounded", "text": "It moves as a slow, grinding wall, more obstacle than opponent in open ground."}, {"n": 3, "band": "Grounded", "text": "It thins and weakens visibly once bloodied, the mass losing cohesion."}, {"n": 4, "band": "Grounded", "text": "It occupies the same space as anything in its path, engulfing rather than surrounding."}, {"n": 5, "band": "Grounded", "text": "It smells of sulfur and rot in equal, nauseating measure."}, {"n": 6, "band": "Textured", "text": "It's being used as living fortification, blocking a corridor a devil doesn't want breached."}, {"n": 7, "band": "Strange", "text": "Individual faces within the mass occasionally surface, twisted, before submerging again."}, {"n": 8, "band": "Volatile", "text": "A much larger wave of the same is being marched toward this exact location."}]}},
 "ultroloth": {"desc": "Its gaze is a weapon before its whip ever moves — a hypnotic stare that locks victims still while it decides, with cold professional interest, how the encounter will end. It brokers deals across factions with the detachment of a banker, loyal only to whichever side currently profits it most. Its whip crackles like a held breath about to be released.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's brokering a contract between two rival factions, and this fight jeopardizes the deal."}, {"n": 2, "band": "Grounded", "text": "It's evaluating a mortal group's usefulness as potential future assets, not yet hostile."}, {"n": 3, "band": "Grounded", "text": "A previous client's failed contract has left it owed a debt it intends to collect."}, {"n": 4, "band": "Grounded", "text": "It's here to enforce neutrality in a conflict it profits from prolonging, not ending."}, {"n": 5, "band": "Grounded", "text": "It carries information both sides of a war would pay dearly to have."}, {"n": 6, "band": "Textured", "text": "It offers a genuinely useful, currently-honest deal, purely because betrayal isn't profitable yet."}, {"n": 7, "band": "Strange", "text": "Its gaze leaves afterimages that linger for minutes, faint golden echoes in victims' vision."}, {"n": 8, "band": "Volatile", "text": "It's orchestrating something that will tip an entire regional balance of power within days."}]}},
 "vrock": {"desc": "It perches like a vulture that's already decided you're dead, wings mantled, poison talons flexing. Its screech alone can stun, and the spores it releases seed rot into open wounds long after the fight ends. It doesn't wait for things to die naturally; it prefers to help.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "It's circling a battlefield already, waiting for casualties to feed on rather than causing them itself."}, {"n": 2, "band": "Grounded", "text": "It hunts in a small flock, using stunning screech to disable before the others close in."}, {"n": 3, "band": "Grounded", "text": "Old wounds crust its feathers, evidence of past fights it barely survived."}, {"n": 4, "band": "Grounded", "text": "It targets the wounded and fleeing first, ignoring anyone still fighting effectively."}, {"n": 5, "band": "Grounded", "text": "Its spores linger in the air of enclosed spaces long after it's driven off."}, {"n": 6, "band": "Textured", "text": "It's a scout for a larger demonic incursion, reporting weaknesses before the main force arrives."}, {"n": 7, "band": "Strange", "text": "Its screech, at certain distances, sounds almost like a mangled human word."}, {"n": 8, "band": "Volatile", "text": "An entire flock is converging on this exact location, drawn by the scent of fresh violence."}]}},
 "yochlol": {"desc": "It oozes and reforms in equal measure, a favored handmaiden shape given to the deep places where webs are law. Acid drips from its lash, and when struck it simply isn't there anymore — teleported, already lashing back before the attacker recovers. It serves its dark queen with the unthinking devotion of something bred for exactly this.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "It's overseeing a drow settlement's compliance, reporting dissent back to its mistress."}, {"n": 2, "band": "Grounded", "text": "It's enforcing a specific edict and treats resistance as a personal insult to its queen."}, {"n": 3, "band": "Grounded", "text": "A web-choked chamber nearby holds captives it's been ordered to keep alive for now."}, {"n": 4, "band": "Grounded", "text": "It's testing a drow priestess's loyalty through a staged trial, and this fight is part of it."}, {"n": 5, "band": "Grounded", "text": "It carries a message meant only for a specific matron mother, undelivered."}, {"n": 6, "band": "Textured", "text": "It offers information in exchange for silence about something it wasn't supposed to be doing here."}, {"n": 7, "band": "Strange", "text": "Its dominant eight legs occasionally flicker, briefly, into a shape too many to count."}, {"n": 8, "band": "Volatile", "text": "Its dark queen is watching this exact encounter through it, and will remember how it ends."}]}},
 "aberrant-cultist": {"desc": "Its eyes have gone the wet grey of a dead fish, pupils blown wide even in torchlight. It speaks in the cadence of a sermon that never quite finishes its sentences, tentacle-flesh visible where a sleeve rides up. The air around it smells faintly of brine and ozone, wrong for any room it stands in.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Whispers to something unseen mid-sentence, losing the thread of its own speech."}, {"n": 2, "band": "Grounded", "text": "One arm is fully tentacled now; it keeps it wrapped, ashamed and proud at once."}, {"n": 3, "band": "Grounded", "text": "Recites the same fragment of the Rite backward when startled, as a ward."}, {"n": 4, "band": "Grounded", "text": "Flinches from mirrors and still water, refusing to look down at either."}, {"n": 5, "band": "Grounded", "text": "Bleeds faintly luminescent ichor from the nose when it overexerts its gift."}, {"n": 6, "band": "Textured", "text": "Its shadow lags a half-second behind its movements, unnoticed until pointed out."}, {"n": 7, "band": "Strange", "text": "Speaks in the plural — 'we' — and corrects itself, badly, when caught."}, {"n": 8, "band": "Volatile", "text": "For one round its skin briefly shows the stars of a sky that isn't this one."}]}},
 "cultist": {"desc": "A frightened convert in borrowed robes, sickle held like a tool rather than a weapon. It mutters half-remembered liturgy to steady its hands, glancing at its fellows more than at any threat. Underneath the zealotry is someone who signed on for belonging and got a war instead.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Carries a smuggled letter home, unsent, admitting doubt — a way out if offered."}, {"n": 2, "band": "Grounded", "text": "Owes the cult a debt paid in silence about a crime it witnessed."}, {"n": 3, "band": "Grounded", "text": "Knows the name of the cell's real backer, terrified to say it aloud."}, {"n": 4, "band": "Grounded", "text": "Has a sibling initiated the same week, now missing from the roster."}, {"n": 5, "band": "Grounded", "text": "Was promised healing for a sick parent in exchange for three rites served."}, {"n": 6, "band": "Textured", "text": "Keeps a tally of the disappeared scratched inside its sleeve."}, {"n": 7, "band": "Strange", "text": "Was chosen for tonight's binding and knows it, and hasn't slept in days."}, {"n": 8, "band": "Volatile", "text": "Still wears a house signet under the robes — nobility playing at devotion."}]}},
 "cultist-fanatic": {"desc": "Older in the faith and hollowed by it, this one has stopped flinching at what the rite demands. Its pact blade is kept obsessively clean, its voice pitched low and certain in a way that steadies the others. Whatever doubt it once had has been burned out entirely.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Marks its own skin with a fresh rite-scar before every fight, superstitious ritual."}, {"n": 2, "band": "Grounded", "text": "Refuses to retreat past a chalked boundary line, dying on principle if cornered."}, {"n": 3, "band": "Grounded", "text": "Names each spell it casts aloud as an offering, slowing its own tempo."}, {"n": 4, "band": "Grounded", "text": "Carries a second, smaller blade meant only for a self-inflicted last rite."}, {"n": 5, "band": "Grounded", "text": "Keeps count of kills on a cord of knots worn at the belt."}, {"n": 6, "band": "Textured", "text": "Speaks to the newest cultists like a proud, terrifying older sibling."}, {"n": 7, "band": "Strange", "text": "Its pact blade hums faintly and it strokes the flat of it between rounds."}, {"n": 8, "band": "Volatile", "text": "In its final moments it tries to complete the rite rather than flee or fight."}]}},
 "cultist-roster-base-2024-stat-blocks": {"desc": "This is the cult's rank and file — dozens interchangeable in robe and sickle, distinct only up close. One counts prayer beads compulsively; another still has calluses from a trade abandoned months ago. Together they move like a single nervous organism awaiting its cue.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Was a cooper before the cult; still smells faintly of pitch and oak shavings."}, {"n": 2, "band": "Grounded", "text": "Carries the week's collection purse, coin meant for a bribe upstream."}, {"n": 3, "band": "Grounded", "text": "Has a child waiting at the safehouse, unaware of what the parent does at night."}, {"n": 4, "band": "Grounded", "text": "Recruited a neighbor last week and now regrets it, watching them struggle."}, {"n": 5, "band": "Grounded", "text": "Knows the escape tunnel's second exit, never told to the officers."}, {"n": 6, "band": "Textured", "text": "Carries a forbidden charm from the old faith, hidden, half-believed in still."}, {"n": 7, "band": "Strange", "text": "Was blackmailed into the robes over a debt now three times paid off."}, {"n": 8, "band": "Volatile", "text": "Keeps a torn page of scripture that contradicts the hierophant's version."}]}},
 "death-cultist": {"desc": "It moves with the unhurried patience of something that has already died once and found the process instructive. The dread scythe never quite touches the ground, held a fraction above it, and its voice carries the flat calm of a mortician discussing weather. Grave-dust clings to its hems no matter the season.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Counts backward under its breath — a number it insists is someone else's remaining days."}, {"n": 2, "band": "Grounded", "text": "Its shadow pools wrong on stone floors, thin where it should be full."}, {"n": 3, "band": "Grounded", "text": "Refuses to step on grass, only bare earth, stone, or ash."}, {"n": 4, "band": "Grounded", "text": "Speaks the names of the last three things it killed before acting again."}, {"n": 5, "band": "Grounded", "text": "The scythe's edge frosts faintly in warm rooms, unexplained and ignored."}, {"n": 6, "band": "Textured", "text": "Bows to corpses it passes, even ones it did not make."}, {"n": 7, "band": "Strange", "text": "Its breath fogs regardless of temperature, a small tell of the ray's cost."}, {"n": 8, "band": "Volatile", "text": "For one round it casts no shadow at all, and seems pleased about it."}]}},
 "elemental-cultist": {"desc": "Heat-shimmer and frost-crack argue across its skin depending on which patron it's currently favoring, robes scorched on one side and rimed on the other. It talks about balance while clearly serving only appetite. The claw looks grown rather than worn, fused past the wrist.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Favors fire tonight; frost-side of its body goes dormant and pale."}, {"n": 2, "band": "Grounded", "text": "Leaves scorch or frost prints that don't match its actual footsteps."}, {"n": 3, "band": "Grounded", "text": "Argues with itself in two voices — one hot, one cold — mid-combat."}, {"n": 4, "band": "Grounded", "text": "The elemental claw twitches independently when its patron is invoked nearby."}, {"n": 5, "band": "Grounded", "text": "Steam or frost-mist rises off it constantly, staining the air around it."}, {"n": 6, "band": "Textured", "text": "Switches allegiance mid-fight if outmatched, changing tactics and claw-element."}, {"n": 7, "band": "Strange", "text": "Its normal hand has gone permanently numb, forgotten and unused now."}, {"n": 8, "band": "Volatile", "text": "Briefly loses control and vents its element wildly, scorching its own allies."}]}},
 "fiend-cultist": {"desc": "The pact axe's haft is warm to the touch no matter the weather, and its bearer sweats a faint sulfur musk under the incense. It negotiates before it kills, offering terms it has no authority to honor, a habit picked up from something it serves. Its smile arrives a half-beat too late to any joke.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Carries a signed contract-scrap promising a name's soul in exchange for power."}, {"n": 2, "band": "Grounded", "text": "Is dying slowly from the pact's cost and knows it, desperate to renew terms."}, {"n": 3, "band": "Grounded", "text": "Has a target list of three names it must deliver by season's end."}, {"n": 4, "band": "Grounded", "text": "Owns a sealed letter meant for its own replacement, in case it fails tonight."}, {"n": 5, "band": "Grounded", "text": "Bargains for the party's surrender in its patron's exact idiom, oddly formal."}, {"n": 6, "band": "Textured", "text": "Wears a brand under its collar it flinches to have touched."}, {"n": 7, "band": "Strange", "text": "Knows a rival cell plans to usurp this one and wants the party's help."}, {"n": 8, "band": "Volatile", "text": "Offers real, working information if promised safe passage — and means it."}]}},
 "archdruid": {"desc": "Moss has grown into the seams of its staff as though the wood forgot it was ever cut. It speaks slowly, weighing every word the way old trees weigh centuries, and the local wildlife orients toward it like a second sun. Something ancient and patient watches from behind its eyes.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Currently mid-transformation, half-beast, caught between two shapes and irritable."}, {"n": 2, "band": "Grounded", "text": "Speaks only in the voice of the last animal it wildshaped into today."}, {"n": 3, "band": "Grounded", "text": "A circle of dead grass marks everywhere it has stood for more than a minute."}, {"n": 4, "band": "Grounded", "text": "Refuses cut lumber, iron nails, anything that required a tree's death, out of spite."}, {"n": 5, "band": "Grounded", "text": "Its staff has visibly rooted into the earth and must be pried free to leave."}, {"n": 6, "band": "Textured", "text": "Travels with an animal companion that answers questions on its behalf."}, {"n": 7, "band": "Strange", "text": "The season noticeably shifts a few feet around it — frost in summer, bloom in frost."}, {"n": 8, "band": "Volatile", "text": "For one round its human shape flickers, showing antlers, bark, or feathers beneath."}]}},
 "archmage": {"desc": "Ink-stains map its fingers permanently, a record of decades spent copying formulae too dangerous to trust to apprentices. It talks down to everyone by reflex, not malice, the way a mountain doesn't notice the weather. Its spellbook is chained to its own wrist.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is testing a spell on the party, mid-combat, and will say so if pressed."}, {"n": 2, "band": "Grounded", "text": "Has a rival archmage's true name and will trade it for something specific."}, {"n": 3, "band": "Grounded", "text": "Carries an apprentice's unfinished thesis it feels obligated to protect."}, {"n": 4, "band": "Grounded", "text": "Owes a favor to something outside the material plane, called due tonight."}, {"n": 5, "band": "Grounded", "text": "Wants a rare component the party is unknowingly carrying."}, {"n": 6, "band": "Textured", "text": "Has bound a portion of its own memory into a phylactery-like focus nearby."}, {"n": 7, "band": "Strange", "text": "Is quietly dying of a curse it caused itself and is racing to undo."}, {"n": 8, "band": "Volatile", "text": "Recognizes one PC's magic as trained from its own long-lost student."}]}},
 "archpriest": {"desc": "Its vestments are stiff with old blood it insists is sacramental wine. Every word lands with the certainty of scripture, whether it's a blessing or a threat, and its congregation flinches identically at either. The holy word, when it comes, arrives like weather.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Blesses its own allies mid-fight regardless of whether they asked."}, {"n": 2, "band": "Grounded", "text": "Refuses to speak the enemy's name, calling them only 'the unclean.'"}, {"n": 3, "band": "Grounded", "text": "Its radiant burst leaves visible scripture-shaped scorch marks on the ground."}, {"n": 4, "band": "Grounded", "text": "Anoints its own weapon with oil between rounds, a compulsive habit."}, {"n": 5, "band": "Grounded", "text": "Speaks a different holy tongue when truly furious, unintelligible but chilling."}, {"n": 6, "band": "Textured", "text": "Kneels briefly after every kill, whether from grief or ritual is unclear."}, {"n": 7, "band": "Strange", "text": "Wears a second, hidden symbol beneath the first — an older, forbidden faith."}, {"n": 8, "band": "Volatile", "text": "For one round its light burns cold-white instead of gold, and no one comments."}]}},
 "assassin": {"desc": "It counts your habits before it counts your coin — the hand you favor, the door you check twice. Its blade never catches light; that's the point of the coating. It has already decided how this ends and is only waiting for you to catch up.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Was hired by someone the party trusts, and hesitates to say who."}, {"n": 2, "band": "Grounded", "text": "Carries a second contract on a name the party recognizes."}, {"n": 3, "band": "Grounded", "text": "Has orders to spare one specific person in the room, against its will."}, {"n": 4, "band": "Grounded", "text": "Left a coded warning at the target's door out of professional courtesy."}, {"n": 5, "band": "Grounded", "text": "Is being blackmailed into this job by the guild that trained it."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC as a former mark it was paid not to kill."}, {"n": 7, "band": "Strange", "text": "Wants information more than the kill fee and will trade the job for it."}, {"n": 8, "band": "Volatile", "text": "Has a twin sibling working the opposite side of this same contract."}]}},
 "spy": {"desc": "It has three names and answers to none of them naturally. Its posture reads as whoever it needs to be read as, and its hands are never quite still, always cataloguing exits. By the time you notice it noticing you, it already knows more than you do.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is actually a double agent and will offer to switch sides for the right price."}, {"n": 2, "band": "Grounded", "text": "Carries a coded ledger that implicates someone the party hasn't suspected yet."}, {"n": 3, "band": "Grounded", "text": "Has been made and knows it, playing for time until backup arrives."}, {"n": 4, "band": "Grounded", "text": "Wants the party's silence more than their cooperation, and will pay for it."}, {"n": 5, "band": "Grounded", "text": "Is protecting a source inside the party's own faction."}, {"n": 6, "band": "Textured", "text": "Has orders to observe only, and will talk rather than fight if given the chance."}, {"n": 7, "band": "Strange", "text": "Carries a dead-drop meant for someone the party could intercept."}, {"n": 8, "band": "Volatile", "text": "Recognizes a PC's forged papers as its own guild's handiwork."}]}},
 "spy-master": {"desc": "Every question it asks is really three questions, and it already knows the answer to two of them. It never raises its voice, never needs to; the smoke bomb is a courtesy, not a necessity. It has been running this city's secrets longer than most of its agents have been alive.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Holds a dossier on every PC, thicker than any of them would like."}, {"n": 2, "band": "Grounded", "text": "Wants to recruit rather than kill, and says so plainly, mid-fight."}, {"n": 3, "band": "Grounded", "text": "Has a mole inside the party's own faction it will name for the right trade."}, {"n": 4, "band": "Grounded", "text": "Is playing three factions against each other and needs the party as a fourth lever."}, {"n": 5, "band": "Grounded", "text": "Carries proof of a crime that implicates someone powerful in the region."}, {"n": 6, "band": "Textured", "text": "Knows the location of someone the party has been searching for."}, {"n": 7, "band": "Strange", "text": "Will vanish rather than be captured, leaving a calling card behind out of pride."}, {"n": 8, "band": "Volatile", "text": "Offers a truce specifically to use the party against a rival spy network."}]}},
 "vampire-familiar": {"desc": "It's still warm, still breathing, still entirely human — sworn or coerced into its master's service, and dreaming of the night it finally earns the same undeath. It fights with a dagger that channels its master's deathly chill rather than any blood of its own, and if that master ever falls, the corpse-pale sheen fades and it wakes up simply, terribly human again.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Serves willingly, chasing the promise that loyal service earns it true undeath someday."}, {"n": 2, "band": "Grounded", "text": "Was coerced into the bond and quietly hopes someone strong enough finds its master first."}, {"n": 3, "band": "Grounded", "text": "Carries a message it was forbidden to deliver, and is close to breaking that order."}, {"n": 4, "band": "Grounded", "text": "Knows exactly where its master rests during the day and hates itself for knowing."}, {"n": 5, "band": "Grounded", "text": "Was ordinary and human within recent memory, and still keeps a token from that life."}, {"n": 6, "band": "Textured", "text": "Will betray its master if shown genuine, lasting protection from reprisal."}, {"n": 7, "band": "Strange", "text": "Its reflection lags a half-second behind its movements, a mark of its master's touch."}, {"n": 8, "band": "Volatile", "text": "Is testing the party on its master's behalf, reporting back regardless of outcome."}]}},
 "bandit": {"desc": "Patched leather, a blade sharpened past its useful life, and eyes that dart to the treeline more than to you. This isn't a career choice so much as the last option left after the harvest failed twice running. It wants your coin more than your blood, and will settle for either.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is feeding a family two valleys over and will talk terms if given the chance."}, {"n": 2, "band": "Grounded", "text": "Deserted from this same road gang once already and fears the captain's reprisal more than the party."}, {"n": 3, "band": "Grounded", "text": "Carries a stolen locket it hasn't been able to sell, guilt catching up."}, {"n": 4, "band": "Grounded", "text": "Knows the gang's real hideout and will trade it for safe passage."}, {"n": 5, "band": "Grounded", "text": "Was conscripted at knifepoint and is looking for any excuse to run."}, {"n": 6, "band": "Textured", "text": "Owes a debt to the crime-lord upstream and is skimming to pay it off."}, {"n": 7, "band": "Strange", "text": "Has a map to a better score than whatever's in the party's pockets."}, {"n": 8, "band": "Volatile", "text": "Recognizes a PC from a town where the bandit still has kin."}]}},
 "bandit-captain": {"desc": "It leads by menace dressed as charisma, quoting terms of surrender it has never once honored. The scimitar is for show; the pistol is for business. Its crew watches it more nervously than they watch any approaching threat.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Offers genuinely fair terms first, and only turns violent if refused twice."}, {"n": 2, "band": "Grounded", "text": "Keeps a tally of betrayals it's owed, settling old scores mid-fight."}, {"n": 3, "band": "Grounded", "text": "Fires the pistol as an opener, then closes with the blade out of habit."}, {"n": 4, "band": "Grounded", "text": "Retreats the instant its crew breaks, abandoning them without a second look."}, {"n": 5, "band": "Grounded", "text": "Has a second, hidden pistol it draws only when clearly losing."}, {"n": 6, "band": "Textured", "text": "Negotiates hostage terms even while actively being attacked."}, {"n": 7, "band": "Strange", "text": "Wears a stolen signet ring it flashes as false authority."}, {"n": 8, "band": "Volatile", "text": "Calls off the fight entirely if a bigger score is dangled convincingly."}]}},
 "bandit-courier": {"desc": "Light on its feet and lighter on loyalty, it carries messages worth more than its own life and knows it. The longbow is for distance; it would rather never be seen at all. Every route it runs has three backup paths memorized.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Carries a sealed message worth more to a rival faction than to its own gang."}, {"n": 2, "band": "Grounded", "text": "Is being tailed by someone else entirely, unaware the party isn't the real threat."}, {"n": 3, "band": "Grounded", "text": "Will trade the message's contents for guaranteed escape."}, {"n": 4, "band": "Grounded", "text": "Has memorized the message and would rather die than let the physical copy be taken."}, {"n": 5, "band": "Grounded", "text": "Is running late and terrified of the captain's punishment more than capture."}, {"n": 6, "band": "Textured", "text": "Carries a second, decoy message meant to mislead pursuers."}, {"n": 7, "band": "Strange", "text": "Knows a shortcut through dangerous terrain that could save the party time later."}, {"n": 8, "band": "Volatile", "text": "Recognizes the message's addressee as someone the party is also seeking."}]}},
 "bandit-crime-lord": {"desc": "It has stopped carrying its own weapons except as a formality; others do the dying. Every word is a transaction, every silence a threat being priced. The scimitar and pistol are old habits from a rise it doesn't like to discuss anymore.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Offers to buy the party's silence with information more valuable than coin."}, {"n": 2, "band": "Grounded", "text": "Has a rival crime-lord it wants dead and will pay handsomely for it."}, {"n": 3, "band": "Grounded", "text": "Carries ledgers implicating a respected noble in the operation."}, {"n": 4, "band": "Grounded", "text": "Is being blackmailed by someone above it in a hierarchy nobody's mapped yet."}, {"n": 5, "band": "Grounded", "text": "Wants a specific item the party carries and will negotiate rather than fight for it."}, {"n": 6, "band": "Textured", "text": "Has a child hidden away from this life, vulnerable if the operation falls."}, {"n": 7, "band": "Strange", "text": "Will surrender everything for guaranteed passage out of the region."}, {"n": 8, "band": "Volatile", "text": "Recognizes a PC's face from a bounty poster it commissioned itself."}]}},
 "bandit-deceiver": {"desc": "Its dagger is a decoy; the real weapon is the story it's already telling about who attacked whom first. The blinding flash covers a retreat dressed as a counterattack. Nothing it says in the first exchange should be trusted at face value.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Poses as a victim of the encounter rather than its instigator, convincingly."}, {"n": 2, "band": "Grounded", "text": "Uses the blinding flash to swap places with a decoy ally mid-fight."}, {"n": 3, "band": "Grounded", "text": "Claims to be a lawful authority, badge and all, forged but detailed."}, {"n": 4, "band": "Grounded", "text": "Feigns surrender, then strikes the moment backs are turned."}, {"n": 5, "band": "Grounded", "text": "Speaks in a different region's accent than its actual origin, deliberately."}, {"n": 6, "band": "Textured", "text": "Carries three different sets of identifying papers, all convincing."}, {"n": 7, "band": "Strange", "text": "Blames a nearby innocent bystander loudly and often, sowing confusion."}, {"n": 8, "band": "Volatile", "text": "Vanishes mid-fight using the flash, leaving allies to take the blame."}]}},
 "bandit-enforcer": {"desc": "Its knuckles are scarred in the specific pattern of someone who breaks bones for a living rather than kills outright. The mace is for making examples, not corpses. It enjoys the work in a way that makes its crew keep their distance.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is collecting a debt from someone the party knows, brutally overdue."}, {"n": 2, "band": "Grounded", "text": "Has a quota to meet tonight and will let smaller fish go to hit the number."}, {"n": 3, "band": "Grounded", "text": "Carries a list of names still owing the crime-lord, one crossed off recently."}, {"n": 4, "band": "Grounded", "text": "Was once the one being collected from, and turned enforcer to survive."}, {"n": 5, "band": "Grounded", "text": "Will stop mid-beating if paid the exact sum it was sent to collect."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC as someone who once intervened in a collection, and remembers."}, {"n": 7, "band": "Strange", "text": "Carries evidence of the crime-lord's own debts, unaware of its value."}, {"n": 8, "band": "Volatile", "text": "Wants out of the life and will trade information for a way clear."}]}},
 "desperate-bandit": {"desc": "Its crossbow shakes slightly, held by hands more used to a plow than a weapon. Whatever brought it to this road was worse than the risk of this fight. It watches the party's faces for any sign of mercy it can seize on.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Will drop the weapon and beg the instant the fight turns against it."}, {"n": 2, "band": "Grounded", "text": "Is stealing food, not coin, for a household starving through the season."}, {"n": 3, "band": "Grounded", "text": "Was forced into this by a debt collector waiting at the tree line."}, {"n": 4, "band": "Grounded", "text": "Has never actually hurt anyone and hopes tonight doesn't change that."}, {"n": 5, "band": "Grounded", "text": "Recognizes the party as travelers who once showed it kindness elsewhere."}, {"n": 6, "band": "Textured", "text": "Carries the last of a family heirloom it was about to sell for bread."}, {"n": 7, "band": "Strange", "text": "Will lead the party to a better target in exchange for being let go."}, {"n": 8, "band": "Volatile", "text": "Breaks down mid-fight, unable to go through with the robbery at all."}]}},
 "berserker": {"desc": "Scar tissue maps old battles across its bare chest, worn like medals rather than warnings. The greataxe swings before thought catches up to it, and its eyes go distant and red-rimmed the longer the fight runs. Something in it wants the wound more than the win.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Fights bare-chested regardless of weather, scars fully on display as challenge."}, {"n": 2, "band": "Grounded", "text": "Howls the name of a fallen kin with every swing, working itself into frenzy early."}, {"n": 3, "band": "Grounded", "text": "Refuses to fight anyone already bloodied, considering it beneath the rage."}, {"n": 4, "band": "Grounded", "text": "Keeps fighting past reasonable limits, ignoring wounds that should have dropped it."}, {"n": 5, "band": "Grounded", "text": "Smashes its own gear in frustration when a swing misses cleanly."}, {"n": 6, "band": "Textured", "text": "Calms unnervingly fast the instant the fight ends, as if a switch flipped."}, {"n": 7, "band": "Strange", "text": "Targets the largest visible threat first regardless of tactical sense."}, {"n": 8, "band": "Volatile", "text": "Its frenzy briefly makes it strike an ally who gets too close, then horror."}]}},
 "berserker-commander": {"desc": "It leads from the front, always, greataxe first and orders shouted between swings rather than before them. Its crew fights harder simply because retreat would mean facing its disappointment more than the enemy's blade. The javelin is a formality it rarely needs.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Throws the javelin only as an opening taunt, never as a real tactic."}, {"n": 2, "band": "Grounded", "text": "Names a single worthy opponent aloud and ignores lesser threats entirely."}, {"n": 3, "band": "Grounded", "text": "Rallies fleeing allies with a wordless roar rather than any command."}, {"n": 4, "band": "Grounded", "text": "Fights with visible restraint until truly angered, then all restraint vanishes."}, {"n": 5, "band": "Grounded", "text": "Carries a trophy from every commander it's personally defeated."}, {"n": 6, "band": "Textured", "text": "Refuses backup entirely in single combat, considering it dishonorable."}, {"n": 7, "band": "Strange", "text": "Its frenzy peaks exactly when bloodied, becoming far more dangerous wounded."}, {"n": 8, "band": "Volatile", "text": "Ends every fight it wins by offering the loser's corpse proper rites."}]}},
 "bugbear-stalker-strangler": {"desc": "It hasn't made a sound in the last hundred feet, garrote already looped and ready before you knew you were being hunted. Its bulk should telegraph it, but the stalking gait erases that entirely. By the time you feel the cord, the choice was made minutes ago.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Strangles from directly overhead, dropping from unlikely perches without warning."}, {"n": 2, "band": "Grounded", "text": "Marks chosen prey with a small scratch beforehand, a private ritual."}, {"n": 3, "band": "Grounded", "text": "Refuses the garrote on anyone already alerted, preferring a clean surprise or nothing."}, {"n": 4, "band": "Grounded", "text": "Carries trophies of cord-marks tallied on its own forearm."}, {"n": 5, "band": "Grounded", "text": "Retreats immediately if the strangle fails, unwilling to fight fair."}, {"n": 6, "band": "Textured", "text": "Waits multiple rounds in total stillness before striking, patience total."}, {"n": 7, "band": "Strange", "text": "Targets spellcasters specifically, having learned the hard way to silence them first."}, {"n": 8, "band": "Volatile", "text": "Leaves the garrote behind on a kill as a calling card, unbothered by the cost."}]}},
 "bugbear-warrior": {"desc": "Its oversized morningstar looks stolen from something twice its size, and swung with enough force that it might as well be. It moves loud when it wants to be feared and dead silent when it wants to be lethal, switching between the two without warning.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Announces itself loudly before a fight, then goes eerily quiet once it starts."}, {"n": 2, "band": "Grounded", "text": "Favors the skullthumper against anything wearing a helmet, personal grudge."}, {"n": 3, "band": "Grounded", "text": "Retreats into cover to reset ambush conditions if the first strike fails."}, {"n": 4, "band": "Grounded", "text": "Fights alongside goblins with visible contempt, using them as living shields."}, {"n": 5, "band": "Grounded", "text": "Collects ears as trophies, worn on a cord at its belt."}, {"n": 6, "band": "Textured", "text": "Throws javelins wildly when frustrated rather than closing to melee."}, {"n": 7, "band": "Strange", "text": "Goes still and listens for long stretches, tracking by sound alone."}, {"n": 8, "band": "Volatile", "text": "Laughs mid-fight in a way that unsettles even its own allies."}]}},
 "commoner": {"desc": "Flour dust or field dirt still clings under its nails, hands that know a trade rather than a weapon. It picked up the club because something forced the choice, not because it wanted to. Its eyes keep checking behind you for whoever else might be coming.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is protecting a child hidden just out of sight, and will fight for that alone."}, {"n": 2, "band": "Grounded", "text": "Knows something about the local trouble that no one's thought to ask a commoner."}, {"n": 3, "band": "Grounded", "text": "Was recently widowed and has nothing left to lose in this fight."}, {"n": 4, "band": "Grounded", "text": "Carries a family debt owed to whoever the party is currently opposing."}, {"n": 5, "band": "Grounded", "text": "Will trade useful town gossip for basic protection or coin."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC as someone who once did the town a kindness."}, {"n": 7, "band": "Strange", "text": "Has seen the real culprit behind a recent local crime and is afraid to say so."}, {"n": 8, "band": "Volatile", "text": "Is the only witness to something the party badly needs confirmed."}]}},
 "guilt-stained-vagrant": {"desc": "Something it did, or failed to do, follows it more closely than any pursuer. The knife in its hand shakes less from fear than from the effort of not turning it on itself. It talks to no one directly, muttering apologies to people who aren't there.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Confesses an old crime unprompted the moment cornered, desperate to be heard."}, {"n": 2, "band": "Grounded", "text": "Carries a token from someone it failed to save, kept as penance."}, {"n": 3, "band": "Grounded", "text": "Knows where a body is buried that the local authorities never found."}, {"n": 4, "band": "Grounded", "text": "Will trade a genuine, damning confession for a single act of mercy now."}, {"n": 5, "band": "Grounded", "text": "Recognizes a PC as kin to someone it wronged years ago."}, {"n": 6, "band": "Textured", "text": "Has information about a crime the party is investigating, buried in guilt."}, {"n": 7, "band": "Strange", "text": "Begs to be turned in rather than killed, wanting the debt paid properly."}, {"n": 8, "band": "Volatile", "text": "Carries stolen goods it never spent, unable to profit from the wrong."}]}},
 "noble": {"desc": "Its blade is ceremonial in origin but not in current use, drawn with more confidence than the rapier grip suggests it's earned. Every gesture assumes deference it may not actually still command. Underneath the finery is someone measuring exactly how much this will cost them politically.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Will pay handsomely for discretion about being found here at all."}, {"n": 2, "band": "Grounded", "text": "Carries a signet that implicates it in a scandal the party could leverage."}, {"n": 3, "band": "Grounded", "text": "Is being blackmailed by someone the party might already be pursuing."}, {"n": 4, "band": "Grounded", "text": "Offers a genuine political favor in exchange for a quiet resolution."}, {"n": 5, "band": "Grounded", "text": "Has a rival house actively plotting against it, unaware how close it's come."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC's bloodline and reacts with unexpected familiarity."}, {"n": 7, "band": "Strange", "text": "Will lie fluently and immediately about why it's in this situation."}, {"n": 8, "band": "Volatile", "text": "Carries proof of a crime committed by someone far more powerful than itself."}]}},
 "guard": {"desc": "Its spear is standard-issue and its stance is textbook, drilled rather than tested. It follows orders more readily than instinct, and its eyes flick toward a superior before committing to any real decision. This is a job, not a calling, and it shows.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is looking the other way for a bribe already paid by someone else."}, {"n": 2, "band": "Grounded", "text": "Recognizes a wanted poster face among the party and hesitates to act on it."}, {"n": 3, "band": "Grounded", "text": "Has orders that conflict with what it's actually seeing happen."}, {"n": 4, "band": "Grounded", "text": "Will trade information about patrol schedules for a small, discreet payment."}, {"n": 5, "band": "Grounded", "text": "Is covering for a superior's corruption out of fear, not loyalty."}, {"n": 6, "band": "Textured", "text": "Knows a shortcut past checkpoints and will share it for the right price."}, {"n": 7, "band": "Strange", "text": "Carries a message meant for someone the party is trying to reach."}, {"n": 8, "band": "Volatile", "text": "Is new to the post and eager to prove itself, overreacting to minor incidents."}]}},
 "guard-captain": {"desc": "It has run this post long enough to know every regular by name and every excuse by heart. Command sits on it comfortably, the javelin and longsword both muscle memory rather than fresh skill. It's tired in the specific way of someone who's seen this exact trouble before.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is quietly corrupt and will offer the party a cut to look elsewhere."}, {"n": 2, "band": "Grounded", "text": "Suspects a subordinate of the very crime the party is investigating."}, {"n": 3, "band": "Grounded", "text": "Will trade real cooperation for protection from a superior's coming purge."}, {"n": 4, "band": "Grounded", "text": "Carries evidence against someone politically untouchable, afraid to use it."}, {"n": 5, "band": "Grounded", "text": "Recognizes the situation as connected to an old, unresolved case it never closed."}, {"n": 6, "band": "Textured", "text": "Is being pressured by a noble house to look the other way on something specific."}, {"n": 7, "band": "Strange", "text": "Offers the party deputized authority in exchange for handling a problem quietly."}, {"n": 8, "band": "Volatile", "text": "Has a personal grudge against one specific faction the party might be tied to."}]}},
 "half-ogre-ogrillon": {"desc": "Too big for orc kin and too smart for ogre kin, it occupies an uneasy space between both worlds and resents being reminded of either. The battleaxe looks proportioned for something larger still. It watches for mockery in every glance, ready to answer it with violence.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Fights with visible fury when its mixed heritage is mocked, losing tactical sense."}, {"n": 2, "band": "Grounded", "text": "Keeps a small, oddly gentle pet it's fiercely protective of mid-battle."}, {"n": 3, "band": "Grounded", "text": "Prefers to grapple and throw rather than swing, showing off raw strength."}, {"n": 4, "band": "Grounded", "text": "Retreats to protect a hoard of mismatched trophies rather than press an advantage."}, {"n": 5, "band": "Grounded", "text": "Speaks slowly and with real hurt about being an outcast among orc-kin."}, {"n": 6, "band": "Textured", "text": "Targets anyone who laughs first, regardless of that target's actual threat."}, {"n": 7, "band": "Strange", "text": "Shows surprising tenderness toward smaller allies, shielding them bodily."}, {"n": 8, "band": "Volatile", "text": "Breaks its own weapon in a rage rather than lose a grapple cleanly."}]}},
 "hobgoblin-captain": {"desc": "It commands with parade-ground precision even in a filthy warren, greatsword held at an angle drilled into it decades ago. Its javelins fly in disciplined volleys, never wasted. Leadership isn't a spell so much as a habit it can't switch off, even talking to prisoners.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Issues orders in clipped military cadence even to enemies mid-parley."}, {"n": 2, "band": "Grounded", "text": "Refuses single combat challenges, considering honor duels a battlefield waste."}, {"n": 3, "band": "Grounded", "text": "Rallies routing soldiers with a single sharp word, restoring order instantly."}, {"n": 4, "band": "Grounded", "text": "Keeps meticulous mental count of enemy numbers, adjusting tactics visibly."}, {"n": 5, "band": "Grounded", "text": "Executes a surrendering enemy without hesitation if it slows the unit."}, {"n": 6, "band": "Textured", "text": "Shows genuine respect to a worthy enemy commander, even one it kills."}, {"n": 7, "band": "Strange", "text": "Uses the Leadership ability the instant a subordinate falters, no exceptions."}, {"n": 8, "band": "Volatile", "text": "Keeps a captured enemy banner as a trophy, displayed prominently."}]}},
 "hobgoblin-iron-shadow": {"desc": "It fights with a coldness its kin lack, longsword and shortsword both drawn in a stance built for killing efficiently rather than gloriously. The unarmed strike comes as a surprise to those expecting only steel. It doesn't gloat; it simply finishes the job.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Switches weapons mid-fight based purely on measured efficiency, never habit."}, {"n": 2, "band": "Grounded", "text": "Uses the hand crossbow to soften a target before ever closing to melee."}, {"n": 3, "band": "Grounded", "text": "Disarms opponents deliberately rather than killing, valuing captures over corpses."}, {"n": 4, "band": "Grounded", "text": "Fights in total silence, unnerving allies and enemies equally."}, {"n": 5, "band": "Grounded", "text": "Retreats the instant the fight becomes inefficient, no ego involved."}, {"n": 6, "band": "Textured", "text": "Targets officers and casters first with cold, unteachable precision."}, {"n": 7, "band": "Strange", "text": "Keeps its unarmed strikes for finishing already-downed enemies specifically."}, {"n": 8, "band": "Volatile", "text": "Shows no reaction to taking damage, calculating rather than enraged."}]}},
 "hobgoblin-soldier": {"desc": "Drilled since childhood into this exact formation, it holds its line without needing to be told twice. The longbow finds range before the longsword finds reach, and both are used with the same flat competence. It is, above all, replaceable, and knows it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Holds formation rigidly even when it would be tactically smarter to break it."}, {"n": 2, "band": "Grounded", "text": "Switches to the longsword only when its bow-line is overrun, reluctantly."}, {"n": 3, "band": "Grounded", "text": "Shows visible fear when its captain falls, breaking discipline for the first time."}, {"n": 4, "band": "Grounded", "text": "Volunteers for the most dangerous position without being ordered to."}, {"n": 5, "band": "Grounded", "text": "Keeps count of its own kills, muttering the number under its breath."}, {"n": 6, "band": "Textured", "text": "Refuses to retreat without an explicit order, even when clearly losing."}, {"n": 7, "band": "Strange", "text": "Fires at maximum range repeatedly rather than closing distance at all."}, {"n": 8, "band": "Volatile", "text": "Shows unexpected mercy to a surrendering enemy, against standard doctrine."}]}},
 "kobold": {"desc": "It's small enough to be underestimated and knows it, which is exactly the point. The dagger is a last resort; the trap it already set is the real weapon. It chatters nervously to its kin in a language that sounds almost like laughter.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Retreats immediately to a prepared trap line rather than fighting directly."}, {"n": 2, "band": "Grounded", "text": "Fights in tight coordination with at least two others, never alone."}, {"n": 3, "band": "Grounded", "text": "Throws the sling from unlikely angles, using terrain aggressively."}, {"n": 4, "band": "Grounded", "text": "Surrenders quickly if isolated, offering information for its life."}, {"n": 5, "band": "Grounded", "text": "Shows unusual bravery defending an egg-chamber or kin specifically."}, {"n": 6, "band": "Textured", "text": "Mimics larger creature sounds to bluff intruders away before engaging."}, {"n": 7, "band": "Strange", "text": "Flees toward sunlight-averse tunnels, using its sensitivity as an ambush lure."}, {"n": 8, "band": "Volatile", "text": "Fights with surprising ferocity if its inventor-kin is directly threatened."}]}},
 "kobold-inventor": {"desc": "Its pockets rattle with half-finished devices, some genuinely clever and most genuinely dangerous to itself. It talks faster than it thinks, narrating its own tinkering mid-crisis. The dagger is an afterthought; the device in its other hand is the real question mark.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "The improvised device backfires as often as it works, to its own visible frustration."}, {"n": 2, "band": "Grounded", "text": "Narrates its own invention's mechanism aloud, oddly proud even in danger."}, {"n": 3, "band": "Grounded", "text": "Retreats to protect its workshop supplies over its own safety."}, {"n": 4, "band": "Grounded", "text": "Trades devices to allies mid-fight, handing off untested gadgets casually."}, {"n": 5, "band": "Grounded", "text": "Shows genuine terror only when its notes or blueprints are threatened."}, {"n": 6, "band": "Textured", "text": "Attempts increasingly reckless device combinations as the fight worsens."}, {"n": 7, "band": "Strange", "text": "Offers a working device to enemies as a bribe for its own escape."}, {"n": 8, "band": "Volatile", "text": "Its device, for once, works spectacularly — briefly stunned by its own success."}]}},
 "winged-kobold-urd": {"desc": "It circles rather than commits, dropping rocks with the casual cruelty of something that's never had to fight fair. Its wings are membranous and loud, more warning than asset. It retreats to height the instant the ground turns against it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Drops rocks in coordinated volleys with kin, timing strikes to overlap."}, {"n": 2, "band": "Grounded", "text": "Refuses to land at all if enemies remain standing, staying purely aerial."}, {"n": 3, "band": "Grounded", "text": "Shrieks a distinct alarm call that summons more kobolds from nearby tunnels."}, {"n": 4, "band": "Grounded", "text": "Targets spellcasters with dropped rocks specifically, having learned the lesson."}, {"n": 5, "band": "Grounded", "text": "Shows reckless bravado when kin are watching, diving closer than is safe."}, {"n": 6, "band": "Textured", "text": "Flees at the first wound, unwilling to trade its life for the fight."}, {"n": 7, "band": "Strange", "text": "Uses sunlight-avoidance tactically, luring enemies into bright open ground."}, {"n": 8, "band": "Volatile", "text": "Carries a stolen shiny trinket it refuses to drop even while fleeing."}]}},
 "orc-berserker": {"desc": "Its rage doesn't build so much as it's already there, banked like coals waiting for air. The greataxe swings wide and reckless, more threat than precision, and its wounds seem to slow it less than they should. It keeps fighting past the point most things would have stopped.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Enters a reckless frenzy immediately, abandoning any defense for pure offense."}, {"n": 2, "band": "Grounded", "text": "Ignores wounds that would drop a lesser creature, driven by pure fury."}, {"n": 3, "band": "Grounded", "text": "Targets whoever drew first blood specifically, ignoring closer threats."}, {"n": 4, "band": "Grounded", "text": "Roars a dead kin's name before charging, working itself up ritually."}, {"n": 5, "band": "Grounded", "text": "Fights harder the more allies fall, rage compounding with each loss."}, {"n": 6, "band": "Textured", "text": "Refuses to flee even when clearly overmatched, considering retreat unthinkable."}, {"n": 7, "band": "Strange", "text": "Attacks recklessly enough to occasionally strike its own nearby allies."}, {"n": 8, "band": "Volatile", "text": "Goes eerily calm for one round after a near-death moment, then redoubles."}]}},
 "orc-blind-prophet": {"desc": "Its eyes are milked over entirely, yet it moves as though it can see something the sighted can't. The spear is guided as much by whispered instruction as by any physical sense. It speaks in fragments of prophecy that land uncomfortably close to true.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Delivers an unsettling, specific prophecy about one PC's near future."}, {"n": 2, "band": "Grounded", "text": "Is protected fiercely by its warband, considered untouchable and sacred."}, {"n": 3, "band": "Grounded", "text": "Knows the location of something the party has been searching for, cryptically."}, {"n": 4, "band": "Grounded", "text": "Will trade a genuine vision for safe passage, though the price is unclear until later."}, {"n": 5, "band": "Grounded", "text": "Claims to have foreseen this exact fight and reacts strangely calm throughout."}, {"n": 6, "band": "Textured", "text": "Carries a relic tied to its god's fury, guarded above its own life."}, {"n": 7, "band": "Strange", "text": "Warns the party of a threat not yet visible, true regardless of its motives."}, {"n": 8, "band": "Volatile", "text": "Its fury visibly answers when its god is invoked, a real and present force."}]}},
 "orc-warrior": {"desc": "Battle-scarred and unbothered by it, it fights with the blunt confidence of someone who's survived worse than this. The greataxe and javelin are both used without hesitation, chosen by range rather than preference. It measures respect in scars, not words.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Throws the javelin first every time, closing only once it's spent."}, {"n": 2, "band": "Grounded", "text": "Fights harder when wounded, relentless endurance visibly changing its demeanor."}, {"n": 3, "band": "Grounded", "text": "Shows grudging respect to a worthy opponent, easing off slightly mid-fight."}, {"n": 4, "band": "Grounded", "text": "Refuses to fight anyone already fleeing, considering it beneath notice."}, {"n": 5, "band": "Grounded", "text": "Rallies visibly at a warband leader's presence, fighting far more aggressively."}, {"n": 6, "band": "Textured", "text": "Keeps fighting past wounds that should stop it, driven by simple stubbornness."}, {"n": 7, "band": "Strange", "text": "Targets the biggest weapon in the room first, seeking a worthy trophy."}, {"n": 8, "band": "Volatile", "text": "Breaks off entirely if its warband routs, unwilling to die alone."}]}},
 "druid-circle-warden": {"desc": "Vines answer to its will before words leave its mouth, curling protectively around it in idle moments. It speaks for the wood the way a sentry speaks for a wall, personally offended by trespass. The staff has visibly grown new bark since it was cut.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Summons the verdant wisp defensively before offensively, protecting itself first."}, {"n": 2, "band": "Grounded", "text": "Refuses to fight in a clearing, retreating to treeline for every engagement."}, {"n": 3, "band": "Grounded", "text": "Speaks to the vines aloud like companions, as though they answer back."}, {"n": 4, "band": "Grounded", "text": "Shows genuine grief when forced to burn or destroy plant life in combat."}, {"n": 5, "band": "Grounded", "text": "The vine staff visibly grows a new shoot after every spell cast."}, {"n": 6, "band": "Textured", "text": "Fights defensively first, testing an intruder's intent before committing to harm."}, {"n": 7, "band": "Strange", "text": "Calls on local wildlife audibly, a genuine summons rather than a bluff."}, {"n": 8, "band": "Volatile", "text": "Roots briefly take hold of its own feet mid-cast, a controlled but visible cost."}]}},
 "gladiator": {"desc": "Crowd-trained reflexes show in every feint, a performer's instinct for where the eyes are watching even in a fight with no audience. The shield bash is showmanship as much as tactic. It fights like it's still being scored.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Plays to an imagined crowd, showboating moves that cost it tactical advantage."}, {"n": 2, "band": "Grounded", "text": "Refuses cheap shots on downed enemies, adhering to arena rules out of habit."}, {"n": 3, "band": "Grounded", "text": "Targets the most dangerous-looking opponent first, seeking the better story."}, {"n": 4, "band": "Grounded", "text": "Shows genuine disappointment when a fight ends too quickly to be satisfying."}, {"n": 5, "band": "Grounded", "text": "Uses the shield bash to create openings for showy finishing blows."}, {"n": 6, "band": "Textured", "text": "Fights harder when outnumbered, thriving on worse odds by old habit."}, {"n": 7, "band": "Strange", "text": "Calls out its own moves aloud, narrating the fight like an announcer."}, {"n": 8, "band": "Volatile", "text": "Offers a formal duel instead of a melee brawl, insulted by ambush tactics."}]}},
 "knight": {"desc": "Its armor is polished past practicality, a statement as much as protection. The greatsword is held with textbook form, drilled into muscle memory by years of tournament and war alike. Honor isn't performative here — it's load-bearing, the thing holding the rest together.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Offers single combat before a general engagement, honoring formal challenge."}, {"n": 2, "band": "Grounded", "text": "Refuses to strike a downed or disarmed opponent, even at cost to itself."}, {"n": 3, "band": "Grounded", "text": "Fights defensively to protect a weaker ally, absorbing blows meant for them."}, {"n": 4, "band": "Grounded", "text": "Shows visible anger at dishonorable tactics used against it, fighting harder."}, {"n": 5, "band": "Grounded", "text": "Keeps a sworn oath sacred even when it clearly disadvantages the fight."}, {"n": 6, "band": "Textured", "text": "Switches to the crossbow only reluctantly, preferring melee as more honorable."}, {"n": 7, "band": "Strange", "text": "Offers mercy to a surrendering foe unconditionally, against tactical advice."}, {"n": 8, "band": "Volatile", "text": "Fights to the last breath rather than break a given word."}]}},
 "questing-knight": {"desc": "It carries itself like a story already being told about it, aura of bravery radiating outward whether anyone needs it or not. The longbow surprises those expecting only steel from something so ceremonially armored. Its oath is louder than its sword.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is on a specific quest that intersects the party's own path, unexpectedly."}, {"n": 2, "band": "Grounded", "text": "Carries a token from someone it swore to protect, guiding its every choice."}, {"n": 3, "band": "Grounded", "text": "Will ally with the party immediately if their cause aligns with its oath."}, {"n": 4, "band": "Grounded", "text": "Refuses to abandon a quest even when clearly overmatched by circumstance."}, {"n": 5, "band": "Grounded", "text": "Knows of a threat further down the road the party hasn't encountered yet."}, {"n": 6, "band": "Textured", "text": "Carries proof of a wrong it's sworn to right, seeking allies to help."}, {"n": 7, "band": "Strange", "text": "Recognizes a PC's deed as aligned with its own order's values, offers aid."}, {"n": 8, "band": "Volatile", "text": "Is testing whether the party is worthy of a boon it's authorized to grant."}]}},
 "warrior-infantry": {"desc": "It holds the line because the line is what it's trained to hold, spear steady in a formation built for exactly this. Pack tactics make it braver in numbers than it would ever be alone. Its name is one of many on a muster roll somewhere.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is a conscript, not a volunteer, and will surrender readily if given the option."}, {"n": 2, "band": "Grounded", "text": "Carries a letter home it hasn't had the chance to send."}, {"n": 3, "band": "Grounded", "text": "Knows the muster roll includes names the party might recognize."}, {"n": 4, "band": "Grounded", "text": "Will break formation and flee the instant its unit's morale collapses."}, {"n": 5, "band": "Grounded", "text": "Owes its position to a debt, not loyalty, and says so if captured."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC from a shared hometown, hesitating to fight in earnest."}, {"n": 7, "band": "Strange", "text": "Carries orders that reveal a larger movement the party hasn't noticed."}, {"n": 8, "band": "Volatile", "text": "Shows more fear of its own officer than of the party."}]}},
 "warrior-veteran": {"desc": "Scar tissue and steady hands mark decades of campaigns most soldiers don't survive to tell about. The greatsword swings with the economy of someone who's learned exactly how much effort a kill actually requires. It's tired, mostly, and fighting out of habit more than cause.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is one contract away from retirement and fighting only to see that through."}, {"n": 2, "band": "Grounded", "text": "Knows a younger fighter in the party's ranks by reputation, and says so."}, {"n": 3, "band": "Grounded", "text": "Carries a grudge against whoever's paying it, doing the job resentfully."}, {"n": 4, "band": "Grounded", "text": "Will switch sides for a genuinely better offer, having no real loyalty left."}, {"n": 5, "band": "Grounded", "text": "Recognizes tactics the party uses from a war it fought decades ago."}, {"n": 6, "band": "Textured", "text": "Wants only to survive this one, uninterested in glory or ideology."}, {"n": 7, "band": "Strange", "text": "Carries a memento from a fallen comrade it still hasn't been able to bury."}, {"n": 8, "band": "Volatile", "text": "Offers real, hard-won tactical advice if the fight ends in a truce."}]}},
 "performer": {"desc": "Rings flash and a blade turns a trick before it turns into a threat, the line between show and violence deliberately blurred. It reads a room's attention like weather, adjusting its patter mid-sentence. Charm is the actual weapon; the shortsword is backup.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is performing a heist mid-show, using the crowd as cover for something else."}, {"n": 2, "band": "Grounded", "text": "Knows a secret about a local noble, worked into tonight's act as a threat."}, {"n": 3, "band": "Grounded", "text": "Will trade gossip for coin freely, having no real stake in secrecy."}, {"n": 4, "band": "Grounded", "text": "Is being extorted by someone in the audience it's too afraid to name."}, {"n": 5, "band": "Grounded", "text": "Carries a message hidden in tonight's routine, meant for someone specific."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC and works them into the act, unplanned and awkward."}, {"n": 7, "band": "Strange", "text": "Wants an audition with someone powerful and will trade favors for an introduction."}, {"n": 8, "band": "Volatile", "text": "Is fleeing a bad contract with a rival troupe, desperate for new patronage."}]}},
 "performer-maestro": {"desc": "Its voice alone has ended fights before the rapier needed to. Every gesture is choreographed, every pause calculated for maximum effect on the room. The Beguiling Song isn't magic to it — it's just the encore.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is being blackmailed by someone who knows the truth behind its rise to fame."}, {"n": 2, "band": "Grounded", "text": "Carries a rival's ruined career on its conscience, unresolved and gnawing."}, {"n": 3, "band": "Grounded", "text": "Will trade a genuine performance-magic favor for information the party has."}, {"n": 4, "band": "Grounded", "text": "Wants a specific patron's attention and will use the party to get it."}, {"n": 5, "band": "Grounded", "text": "Knows a secret song capable of calming a specific dangerous local threat."}, {"n": 6, "band": "Textured", "text": "Is quietly training a successor and protects them fiercely if threatened."}, {"n": 7, "band": "Strange", "text": "Recognizes a PC's talent and offers real mentorship, mid-negotiation."}, {"n": 8, "band": "Volatile", "text": "Carries a magically bound instrument it's terrified to lose or damage."}]}},
 "performer-legend": {"desc": "There's a myth attached to every scar this one carries, and it has stopped correcting which parts are true. The Wisdom Song lands like history repeating itself. It performs even in combat, because the story of the fight matters as much as winning it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is being challenged by a rival for a title it earned decades ago."}, {"n": 2, "band": "Grounded", "text": "Carries the real, unglamorous truth behind its own famous legend."}, {"n": 3, "band": "Grounded", "text": "Wants a worthy successor and is quietly auditioning the party for the role."}, {"n": 4, "band": "Grounded", "text": "Knows a forgotten song capable of turning an entire crowd's mood or loyalty."}, {"n": 5, "band": "Grounded", "text": "Is dying slowly and wants one final, unforgettable performance before the end."}, {"n": 6, "band": "Textured", "text": "Carries a debt to whoever first gave it its start, still unpaid after years."}, {"n": 7, "band": "Strange", "text": "Recognizes a PC's story as worth telling, and starts telling it immediately."}, {"n": 8, "band": "Volatile", "text": "Will forgive any offense in exchange for being remembered accurately."}]}},
 "pirate": {"desc": "Salt has worked its way permanently into its skin and speech both, every sentence sounding half like a threat and half like a shanty. The dagger's quick; the Enthralling Panache is quicker, meant to charm before it needs to cut. It's more interested in the take than the fight.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Will abandon the fight entirely for a better prize spotted elsewhere."}, {"n": 2, "band": "Grounded", "text": "Carries a map fragment worth more than anything else it's currently guarding."}, {"n": 3, "band": "Grounded", "text": "Is owed back wages by its own captain and is looking for a way out."}, {"n": 4, "band": "Grounded", "text": "Knows where a rival crew's real hoard is hidden, and will trade the secret."}, {"n": 5, "band": "Grounded", "text": "Wants passage off this particular ship more than it wants any fight won."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC from a previous port, friendly or otherwise."}, {"n": 7, "band": "Strange", "text": "Carries a grudge against its own quartermaster, exploitable if noticed."}, {"n": 8, "band": "Volatile", "text": "Will surrender readily if promised a share rather than a noose."}]}},
 "pirate-captain": {"desc": "Command sits on it the way salt sits on rope — worked in permanently through use. The rapier and pistol are both extensions of a reputation built over years of exactly this kind of moment. It negotiates as readily as it fights, whichever gets a better price.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is hunting a specific traitor aboard its own crew, using this fight as cover."}, {"n": 2, "band": "Grounded", "text": "Carries a letter of marque that complicates whatever the party assumed about it."}, {"n": 3, "band": "Grounded", "text": "Will offer genuine passage or alliance for the right cargo or coin."}, {"n": 4, "band": "Grounded", "text": "Knows the location of a legendary wreck the party might already be chasing."}, {"n": 5, "band": "Grounded", "text": "Is being hunted by a rival captain and sees the party as useful leverage."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC's ship or flag, with history attached, good or bad."}, {"n": 7, "band": "Strange", "text": "Carries a crew mutiny brewing beneath the surface, exploitable if noticed."}, {"n": 8, "band": "Volatile", "text": "Wants information on a specific port's defenses more than any immediate prize."}]}},
 "pirate-admiral": {"desc": "Its reputation arrived at this fight well before it did, and it plays to that fully, awestruck reactions from its own crew included. The scimitar and pistol are ceremonial as much as functional now — it rarely has to actually finish what it starts. Fleets answer to it; this fight is barely worth its attention.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is here personally only because the stakes are unusually high, and says so."}, {"n": 2, "band": "Grounded", "text": "Carries intelligence on a rival naval power the party's faction badly needs."}, {"n": 3, "band": "Grounded", "text": "Will offer a formal alliance if impressed by the party's conduct in this fight."}, {"n": 4, "band": "Grounded", "text": "Knows the location of a hoard vast enough to fund a small war."}, {"n": 5, "band": "Grounded", "text": "Is being challenged for command by a subordinate, using this fight to prove itself."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC's reputation and reacts with genuine, unexpected respect."}, {"n": 7, "band": "Strange", "text": "Carries a treaty draft that would reshape regional trade, if the party can use it."}, {"n": 8, "band": "Volatile", "text": "Wants the party recruited into its fleet more than it wants them dead."}]}},
 "priest": {"desc": "Its faith is sincere, which somehow makes the mace swing feel worse rather than better. The Radiant Flame is a genuine miracle wielded with the confidence of long practice. It prays audibly between blows, unbothered by how that sounds.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is here to protect a specific congregant the party might not have noticed."}, {"n": 2, "band": "Grounded", "text": "Carries a genuine grievance against the local temple hierarchy."}, {"n": 3, "band": "Grounded", "text": "Will offer real healing in exchange for a promise kept later."}, {"n": 4, "band": "Grounded", "text": "Knows a confession relevant to whatever the party is investigating."}, {"n": 5, "band": "Grounded", "text": "Is quietly doubting its faith and says so if the fight goes badly enough."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC's need for absolution and offers it mid-combat, oddly."}, {"n": 7, "band": "Strange", "text": "Carries relics it's sworn to protect above its own life."}, {"n": 8, "band": "Volatile", "text": "Will call a truce to tend the wounded, expecting the same courtesy back."}]}},
 "priest-acolyte": {"desc": "Still new enough to flinch at its own Radiant Flame, this one prays with more hope than certainty. The mace is barely broken in. It watches its seniors for cues on when exactly faith is supposed to become violence.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is testing its faith for the first time in real danger, visibly shaken."}, {"n": 2, "band": "Grounded", "text": "Will break and flee if its senior priest falls, having no real combat resolve."}, {"n": 3, "band": "Grounded", "text": "Carries a genuine question about doctrine it's been afraid to ask aloud."}, {"n": 4, "band": "Grounded", "text": "Knows a secret about the temple's finances it doesn't fully understand yet."}, {"n": 5, "band": "Grounded", "text": "Wants to prove itself to a mentor watching from a safe distance."}, {"n": 6, "band": "Textured", "text": "Will offer a novice's clumsy but sincere healing to anyone who asks."}, {"n": 7, "band": "Strange", "text": "Recognizes a PC as someone the temple has been quietly discussing."}, {"n": 8, "band": "Volatile", "text": "Carries a letter of introduction to a more senior cleric elsewhere."}]}},
 "mage": {"desc": "Robes singed at the cuffs from spells that didn't quite go as planned, it studies its opponents with more curiosity than fear. The Arcane Burst is textbook, practiced past the point of danger to itself. It would rather learn something from this fight than simply win it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is testing an experimental spell on the party and will admit it if asked."}, {"n": 2, "band": "Grounded", "text": "Carries a rival's stolen research it hasn't finished decoding."}, {"n": 3, "band": "Grounded", "text": "Wants a specific magical component the party is unknowingly carrying."}, {"n": 4, "band": "Grounded", "text": "Will trade real arcane knowledge for safe passage or a guarantee of silence."}, {"n": 5, "band": "Grounded", "text": "Is being blackmailed by a guild it owes an unpaid debt to."}, {"n": 6, "band": "Textured", "text": "Knows of a nearby magical anomaly the party hasn't yet noticed."}, {"n": 7, "band": "Strange", "text": "Carries an unstable magic item it's afraid to use but might, if desperate."}, {"n": 8, "band": "Volatile", "text": "Recognizes a PC's spellwork as trained under a mentor it once knew."}]}},
 "tough": {"desc": "Knuckles like walnuts and a mace held more like a tool than a weapon, this one settles disputes because someone always needs settling. Pack instincts kick in fast around others of its kind. It doesn't overthink the job.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Is collecting a debt on behalf of someone the party might recognize."}, {"n": 2, "band": "Grounded", "text": "Will stand down for the right price, having no real stake in the fight."}, {"n": 3, "band": "Grounded", "text": "Carries a grudge against a specific local business the party might know."}, {"n": 4, "band": "Grounded", "text": "Knows which local officials are bought and by whom."}, {"n": 5, "band": "Grounded", "text": "Is doing this job to pay off a debt of its own, reluctantly."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC as someone who once did it a good turn."}, {"n": 7, "band": "Strange", "text": "Will switch sides quickly if the fight turns badly enough."}, {"n": 8, "band": "Volatile", "text": "Carries a message it was paid to deliver via violence, oddly formal about it."}]}},
 "tough-boss": {"desc": "It's the one the others check with before committing to anything, warhammer resting on one shoulder like punctuation. The crossbow is a surprise reserved for anyone who thinks range keeps them safe. Command here isn't formal, just earned through being the hardest one in the room.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Runs the local protection racket and will cut a deal to keep it running quietly."}, {"n": 2, "band": "Grounded", "text": "Is being squeezed by a bigger operation and could use the party as leverage."}, {"n": 3, "band": "Grounded", "text": "Carries a ledger of debts owed by half the neighborhood, valuable if seized."}, {"n": 4, "band": "Grounded", "text": "Will call off its crew for a genuinely good enough offer."}, {"n": 5, "band": "Grounded", "text": "Knows who's really behind a recent local disappearance."}, {"n": 6, "band": "Textured", "text": "Recognizes a PC's reputation and treats the fight as personal, not business."}, {"n": 7, "band": "Strange", "text": "Carries a rival gang's warning note, unresolved and escalating."}, {"n": 8, "band": "Volatile", "text": "Wants the party's help against a bigger threat squeezing its own territory."}]}},
 "scout": {"desc": "It reads terrain the way others read faces, judging distance and cover before it judges you. The longbow finds its mark from ranges most wouldn't attempt, and it's already three moves ahead on where to be next. It would rather vanish than fight, if the job allows it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Was hired to track the party specifically and will admit it if cornered."}, {"n": 2, "band": "Grounded", "text": "Carries a detailed map of the surrounding territory worth real coin."}, {"n": 3, "band": "Grounded", "text": "Knows a safer route through dangerous terrain the party hasn't found."}, {"n": 4, "band": "Grounded", "text": "Will trade its employer's identity for guaranteed safe passage."}, {"n": 5, "band": "Grounded", "text": "Is genuinely lost from its own patrol and more relieved than hostile."}, {"n": 6, "band": "Textured", "text": "Carries fresh word of a threat further down the road, true regardless of motive."}, {"n": 7, "band": "Strange", "text": "Recognizes a PC's tracking skill and offers grudging professional respect."}, {"n": 8, "band": "Volatile", "text": "Will vanish rather than fight if given any plausible opening to do so."}]}},
 "abominable-yeti": {"desc": "Snow sloughs off in sheets as it rises from a drift that was never a drift at all, eyes flat and black in a wall of matted white fur. The cold radiates off its hide like heat off a stove, and its breath fogs the air into a stinking wall of frost. It moves without hurry, because in this valley nothing has ever outrun it. When it roars, echoes come back down the mountain long after the sound should have died.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Fur is matted with old blood, none of it its own; it has not eaten in days."}, {"n": 2, "band": "Grounded", "text": "Favors a specific cave mouth, dragging kills there before it feeds."}, {"n": 3, "band": "Grounded", "text": "One ear is torn ragged; a past hunter's arrow scar puckers its shoulder."}, {"n": 4, "band": "Grounded", "text": "Younger and leaner, still testing the reach of its cold-breath weapon."}, {"n": 5, "band": "Grounded", "text": "Hunts in a slow, methodical circuit, driving prey toward a cliff edge."}, {"n": 6, "band": "Textured", "text": "Wears a necklace of frozen fingers, trophies from things smarter than beasts."}, {"n": 7, "band": "Strange", "text": "Its footprints steam and do not fill with fresh snow for hours after."}, {"n": 8, "band": "Volatile", "text": "Elder and half-mad with hunger, it has started hunting in broad daylight."}]}},
 "ankheg": {"desc": "The ground coughs upward in a spray of dirt and root, and something segmented and glistening surges out of the tunnel it just cut. Mandibles the length of forearms click together, wet with the acid that pools at the back of its throat. It smells of wet earth and vinegar-sharp bile. By the time you see the tunnel mouth, it has already sensed you through the soles of your boots.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "A farmer's collapsed field marks its tunnel; livestock has been going missing for weeks."}, {"n": 2, "band": "Grounded", "text": "Drags a half-dissolved plow horse back toward its burrow, still chewing."}, {"n": 3, "band": "Grounded", "text": "A second, smaller tunnel branches off — a burrow it shares with young."}, {"n": 4, "band": "Grounded", "text": "Its acid has eaten a rusted strongbox down to a shape no lock will open now."}, {"n": 5, "band": "Grounded", "text": "Surfaces mid-harvest, scattering field hands who left tools and a wagon behind."}, {"n": 6, "band": "Textured", "text": "Its tunnel network undercuts a road; a merchant cart teeters on the sinkhole's lip."}, {"n": 7, "band": "Strange", "text": "The soil around its lair glows faintly where acid has crystallized the rock."}, {"n": 8, "band": "Volatile", "text": "Three tunnels converge here — a brood mother's territory, and she is starving."}]}},
 "axe-beak": {"desc": "It stands taller than a warhorse on legs like fence posts, head cocked with one flat yellow eye fixed on you. The beak alone could split a shield in half, and it knows it — there's no fear in the way it plants its feet. Feathers the color of dry grass ripple as it shifts its weight, deciding whether you're worth the trouble of chasing.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a nest scraped into tall grass, eggs the size of melons half-buried."}, {"n": 2, "band": "Grounded", "text": "Travels in a loose pair, the second bird trailing just out of easy sight."}, {"n": 3, "band": "Grounded", "text": "Chases anything that runs, losing interest the instant prey stands its ground."}, {"n": 4, "band": "Grounded", "text": "Old and scarred, missing half a wing feather-crest from a past predator fight."}, {"n": 5, "band": "Grounded", "text": "Young and skittish, more likely to flee than strike first."}, {"n": 6, "band": "Textured", "text": "Has learned to associate wagon wheels with easy carrion and follows the road."}, {"n": 7, "band": "Strange", "text": "Its beak bears old tool-marks, as if something once tried to file it down."}, {"n": 8, "band": "Volatile", "text": "Rabid with some grassland blight, snapping at shadows and its own reflection."}]}},
 "basilisk": {"desc": "Eight clawed legs and a crest of stony spines make it look like part of the cave floor until it moves. It doesn't chase — why would it, when a look is enough — and lets its stiffened victims wait while it feeds at its own pace. Its dens are prized as much as feared: a desperate hoarder can pay a basilisk in captives to guard a treasure no lock could hold as well.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Nests among a garden of its own petrified victims, half-buried in rubble."}, {"n": 2, "band": "Grounded", "text": "Kept on a chain by a hoarder too greedy to risk a lock, and just as dangerous to its keeper."}, {"n": 3, "band": "Grounded", "text": "Sluggish after a recent kill, more interested in dragging prey off than fighting."}, {"n": 4, "band": "Grounded", "text": "Territorial around a specific rock shelf it treats as a den."}, {"n": 5, "band": "Grounded", "text": "Young and restless, hunting further from its den than is safe for it."}, {"n": 6, "band": "Textured", "text": "Its spines have taken on a faint stony sheen, as if the gaze bleeds backward."}, {"n": 7, "band": "Strange", "text": "Statues nearby are arranged in a rough circle, like an audience it keeps."}, {"n": 8, "band": "Volatile", "text": "Ancient and enormous for its kind, its gaze lingers even after it looks away."}]}},
 "behir": {"desc": "Lightning cracks somewhere behind rock, and then the rock itself seems to move — twelve-legged, serpentine, blue-black scales rippling like water down a body long enough to wrap a wagon twice over. Its jaw unhinges wider than seems possible, and ozone stings the air a half-second before it strikes. The mountain trembles a little wherever it passes.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coils through a narrow canyon pass, using the walls to pin prey in place."}, {"n": 2, "band": "Grounded", "text": "Carries a half-swallowed kill still bulging in its throat, sluggish from the meal."}, {"n": 3, "band": "Grounded", "text": "Old rivalry with a local giant clan has left fresh claw-scars on its hide."}, {"n": 4, "band": "Grounded", "text": "Nests in a cave lined with the bones of things too large to have been easy."}, {"n": 5, "band": "Grounded", "text": "Younger and shorter than its kind, still growing into its full lightning breath."}, {"n": 6, "band": "Textured", "text": "Scales crackle faintly with residual charge even when it isn't attacking."}, {"n": 7, "band": "Strange", "text": "Its lair floor is fused glass, scorched smooth by breath used again and again."}, {"n": 8, "band": "Volatile", "text": "Massive and ancient, storms seem to gather wherever it hunts."}]}},
 "bulette": {"desc": "The earth heaves without warning, a wave of dirt racing toward you faster than a running man, and then armored plate breaks the surface in a spray of soil. The landshark's mouth is a ring of teeth wide enough to take a leg in one bite, and it does not slow down to consider you. Silence follows it — no birdsong, no wind, just the grinding of stone under its claws.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Surfaces mid-field, scattering a plow team and leaving furrows a wagon deep."}, {"n": 2, "band": "Grounded", "text": "Scarred plate along one flank, evidence of a fight it barely won."}, {"n": 3, "band": "Grounded", "text": "Territorial around a specific hill, surfacing anytime the ground vibrates there."}, {"n": 4, "band": "Grounded", "text": "Recently fed, moving slower and more willing to retreat underground."}, {"n": 5, "band": "Grounded", "text": "Hunting alone far from its usual range, driven by hunger or displacement."}, {"n": 6, "band": "Textured", "text": "Its burrow entrance is littered with the buckles and buttons of past meals."}, {"n": 7, "band": "Strange", "text": "Surfaces in near-total silence, plate scarred smooth by years underground."}, {"n": 8, "band": "Volatile", "text": "Massive even for its kind, and it has learned to track by scent alone."}]}},
 "bulette-pup": {"desc": "Small only compared to what it will become, the pup breaks the surface in a spray of loose dirt, jaws already snapping at anything that moves. Its plate hasn't hardened yet, softer grey-brown where an adult would be iron-hard, but the hunger in its eyes is fully grown. It circles clumsily, learning the shape of a fight.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Alone and disoriented, having strayed too far from a nearby adult's territory."}, {"n": 2, "band": "Grounded", "text": "Attacks in short, clumsy bursts before diving back underground to hide."}, {"n": 3, "band": "Grounded", "text": "Still soft-plated; a solid hit staggers it more than an adult would show."}, {"n": 4, "band": "Grounded", "text": "Hunts small game, spooked easily by anything larger than a goat."}, {"n": 5, "band": "Grounded", "text": "Follows tremors instinctively but overshoots, surfacing in the wrong spot."}, {"n": 6, "band": "Textured", "text": "A rope leash-scar rings one foreleg, a failed attempt by someone to tame it."}, {"n": 7, "band": "Strange", "text": "Digs in erratic loops, as if still mapping a territory it hasn't chosen yet."}, {"n": 8, "band": "Volatile", "text": "An adult is close, likely drawn by the pup's frantic burrowing."}]}},
 "carrion-crawler": {"desc": "It clings to the ceiling like a fat grey slug the size of a cart horse, tentacles hanging loose and searching in the dark. The stench of rot precedes it — carrion-crawlers live where the dead pile up, and this one has been living well. When a tentacle finds skin, the sting is quick, almost gentle, and then the paralysis takes hold.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Clings above a pile of corpses too fresh to be its own kills alone."}, {"n": 2, "band": "Grounded", "text": "A paralyzed victim still breathes beneath it, minutes from being fed on."}, {"n": 3, "band": "Grounded", "text": "Shares its ceiling territory with a second, smaller crawler nearby."}, {"n": 4, "band": "Grounded", "text": "Has stripped a room bare of anything organic, leaving only bone and buckles."}, {"n": 5, "band": "Grounded", "text": "Recently fed, sluggish, more likely to retreat than press an attack."}, {"n": 6, "band": "Textured", "text": "Its tentacles are stained with a dye from cloth it has dissolved and absorbed."}, {"n": 7, "band": "Strange", "text": "The ceiling under it is slick with a residue that dims torchlight nearby."}, {"n": 8, "band": "Volatile", "text": "Enormous for its kind, having fed undisturbed in this dark for years."}]}},
 "chimera": {"desc": "Three heads mean three separate hungers, and all of them turn toward you at once — the lion's snarl, the goat's flat stare, the dragon's head drawing a slow breath that tastes of sulfur. Wings the color of rust unfold with a sound like tearing canvas. It is not one animal deciding whether to fight; it is three, and they've already agreed.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "The goat head is scarred mute, favoring the lion and dragon heads in a fight."}, {"n": 2, "band": "Grounded", "text": "Nests on a high ledge, dragging livestock up a switchback trail to feed."}, {"n": 3, "band": "Grounded", "text": "The three heads bicker audibly before committing to an attack, wasting a round."}, {"n": 4, "band": "Grounded", "text": "Recently scorched its own lair testing the reach of its breath."}, {"n": 5, "band": "Grounded", "text": "Young, wings not fully grown, prefers ambush from cover to open flight."}, {"n": 6, "band": "Textured", "text": "The dragon head's scales have gone ash-grey, as if long exposure dulled them."}, {"n": 7, "band": "Strange", "text": "The goat head speaks — badly, in fragments — words it shouldn't know."}, {"n": 8, "band": "Volatile", "text": "Old and enormous, its breath scorches stone black in a wide killing radius."}]}},
 "cockatrice": {"desc": "It struts more than it flies, a compact, feathered thing with a serpent's tail and a rooster's arrogance, and everything in the room that has already met its beak stands frozen in grey stone. The clicking of its claws on tile is almost comic until you notice how many statues share this room with you. It watches you the way a bird watches a worm.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Nests in a rubble-strewn corner surrounded by a garden of its stone victims."}, {"n": 2, "band": "Grounded", "text": "Aggressive and territorial, striking anything that enters its perch radius."}, {"n": 3, "band": "Grounded", "text": "Missing tail feathers from a past near-miss, slightly slower to strike."}, {"n": 4, "band": "Grounded", "text": "Young and food-driven, more interested in small game than intruders."}, {"n": 5, "band": "Grounded", "text": "Roosts high, dropping down to peck before retreating to safety."}, {"n": 6, "band": "Textured", "text": "Its beak carries a faint grey dust that never seems to wash off entirely."}, {"n": 7, "band": "Strange", "text": "One petrified victim nearby holds a weapon raised mid-swing, forever."}, {"n": 8, "band": "Volatile", "text": "Unusually large and bold, having gone unchallenged in this ruin for years."}]}},
 "cockatrice-regent": {"desc": "Bigger than any cockatrice has a right to be, it holds court atop a mound of its own petrified subjects — some human, some not. Its crest flares crimson when it notices you, and the surrounding stone figures seem arranged, almost deliberate, like a throne room built from mistakes. It does not hurry. Its subjects never leave.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Rules a ruined hall of its own statues, arranged like a court around its perch."}, {"n": 2, "band": "Grounded", "text": "Smaller cockatrices defer to it, scattering when it screeches for space."}, {"n": 3, "band": "Grounded", "text": "One petrified figure still clutches a half-drawn map, route unknown."}, {"n": 4, "band": "Grounded", "text": "Guards a nest of eggs half-buried beneath its stone court."}, {"n": 5, "band": "Grounded", "text": "A merchant's petrified pack mule stands nearby, goods still strapped on."}, {"n": 6, "band": "Textured", "text": "Its crest bears old scars, evidence it fought for this territory and won."}, {"n": 7, "band": "Strange", "text": "The statues around it are arranged in a spiral, as if it composes its court."}, {"n": 8, "band": "Volatile", "text": "An adventuring party lies petrified mid-formation, weapons still drawn."}]}},
 "death-dog": {"desc": "Two heads means two sets of teeth watching from two angles, and the low double-growl carries a wrongness that makes your skin crawl before you've placed the sound. Mangy fur clings to a lean, diseased-looking frame, but there is nothing weak about the way it moves — fast, low, coordinated between its two skulls like they've hunted together their whole life. Because they have.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Runs with a scavenger pack, snapping up whatever the bigger predators leave."}, {"n": 2, "band": "Grounded", "text": "One head is scarred blind, the pair compensating by always circling that side."}, {"n": 3, "band": "Grounded", "text": "Territorial around a carrion pit, defending it fiercely against intruders."}, {"n": 4, "band": "Grounded", "text": "Starving and desperate, willing to press an attack it would normally avoid."}, {"n": 5, "band": "Grounded", "text": "Trails a wounded traveler by scent, patient rather than aggressive."}, {"n": 6, "band": "Textured", "text": "Its heads seem to argue in low growls before committing to a target."}, {"n": 7, "band": "Strange", "text": "Both heads flinch at the same moment, sharing pain neither one caused."}, {"n": 8, "band": "Volatile", "text": "Rabid and foaming, biting at its own second head in confused fury."}]}},
 "deep-brute": {"desc": "It comes up out of the black water without a splash, pale and hairless and wrong in the proportions of its limbs, muscle stacked in slabs that shouldn't move as fast as they do. Its eyes have given up on light entirely — it hunts by the vibration of your breathing. The wet slap of its feet on stone is the only warning you get.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a flooded passage, attacking anything that disturbs the still water."}, {"n": 2, "band": "Grounded", "text": "Carries crude bone tools, evidence of some dim tribal memory."}, {"n": 3, "band": "Grounded", "text": "Scarred heavily, having survived fights with things larger than itself."}, {"n": 4, "band": "Grounded", "text": "Hunts in a pair, coordinating through grunts and gestures."}, {"n": 5, "band": "Grounded", "text": "Territorial around a cistern it treats as a nesting pool."}, {"n": 6, "band": "Textured", "text": "Its skin is mottled with lichen-pale patches, as if the dark is claiming it."}, {"n": 7, "band": "Strange", "text": "Moves in total silence despite its bulk, unnervingly light-footed."}, {"n": 8, "band": "Volatile", "text": "Massive and scarred like a chieftain, other brutes yield ground to it."}]}},
 "deep-brute-thonot": {"desc": "Thonot carries itself like something that has led others before — scars arranged almost like a story across its bare chest, a crude trophy necklace of teeth rattling with each step. It watches with a patience the lesser brutes don't share, sizing up a fight before committing to it. When it finally moves, the whole tunnel seems to brace.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Leads a small brute pack; the others hold back until Thonot commits."}, {"n": 2, "band": "Grounded", "text": "Wears a necklace of teeth from things it has personally killed."}, {"n": 3, "band": "Grounded", "text": "Has claimed a cistern chamber as a throne room of sorts, crude but defended."}, {"n": 4, "band": "Grounded", "text": "A captive from the surface is bound nearby, kept alive as some kind of prize."}, {"n": 5, "band": "Grounded", "text": "Bears old wounds from a rival brute it defeated to hold this ground."}, {"n": 6, "band": "Textured", "text": "Grunts in a crude cadence that almost sounds like a chant before combat."}, {"n": 7, "band": "Strange", "text": "Its trophies include a fine ring far too small for its own massive hands."}, {"n": 8, "band": "Volatile", "text": "Rallies nearby brutes with a roar that echoes through the whole tunnel network."}]}},
 "displacer-beast": {"desc": "You strike where it stands and hit nothing — its true body is a foot to the left, tentacles already lashing out from the shadow-image you swung at. Panther-black and sleek, it moves like liquid poured downhill, and the afterimage never quite catches up to where it really is. Six eyes, none of them where you expect.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Stalks a caravan route, having learned exactly where guards patrol thinnest."}, {"n": 2, "band": "Grounded", "text": "Hunts alone in dense woods, using undergrowth to sharpen the displacement trick."}, {"n": 3, "band": "Grounded", "text": "Scarred along one flank from an old blink-dog rivalry, favoring the other side."}, {"n": 4, "band": "Grounded", "text": "Young and reckless, breaking cover sooner than an older beast would."}, {"n": 5, "band": "Grounded", "text": "Territorial around a den it has marked deep in the brush."}, {"n": 6, "band": "Textured", "text": "Its afterimage lags visibly longer than usual, as if fatigued or fading."}, {"n": 7, "band": "Strange", "text": "Moves in total silence even across dry leaves, sound displaced same as sight."}, {"n": 8, "band": "Volatile", "text": "An elder of unusual size, its displacement trick nearly impossible to track."}]}},
 "doppelganger": {"desc": "The face is right. The voice is right. Every small habit you'd swear only that person has is present and correct — until the eyes hold a beat too long, patient in a way the real person never was. Underneath the borrowed skin is something soft and grey and utterly without a face of its own, waiting for you to look away.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Has replaced a local merchant; the real one is chained alive in a cellar nearby."}, {"n": 2, "band": "Grounded", "text": "Wears the face of someone the party trusts, gathering information patiently."}, {"n": 3, "band": "Grounded", "text": "Poses as a wounded prisoner, waiting for rescue to get close to its targets."}, {"n": 4, "band": "Grounded", "text": "Runs a small information racket, switching identities to seem like a network."}, {"n": 5, "band": "Grounded", "text": "Has assumed a guard's face and shift, watching a specific door for someone."}, {"n": 6, "band": "Textured", "text": "Keeps trophies from past identities — rings, letters — hidden in its true form."}, {"n": 7, "band": "Strange", "text": "Holds two faces in memory at once, occasionally answering to the wrong name."}, {"n": 8, "band": "Volatile", "text": "Has replaced someone with real authority, and the deception is already spreading."}]}},
 "drider": {"desc": "From the waist up she is still elf-shaped, pale and severe, a face that might once have been beautiful. Below the waist, chitin and eight legs the color of dried blood carry her along the cave wall, upside down, patient. This is a curse worn as armor now, and she has stopped pretending to miss the surface.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a web-choked shrine to a spider deity, tending it with grim devotion."}, {"n": 2, "band": "Grounded", "text": "Hunts alone, having been exiled even from other driders for some old failure."}, {"n": 3, "band": "Grounded", "text": "Keeps a scattering of giant spiders as hunting companions, half-tamed."}, {"n": 4, "band": "Grounded", "text": "Bears fresh whip-scars, evidence of recent punishment from something above her."}, {"n": 5, "band": "Grounded", "text": "Young in the curse, still flinching at her own reflection in still water."}, {"n": 6, "band": "Textured", "text": "Speaks courteously before combat, old elven manners surfacing despite everything."}, {"n": 7, "band": "Strange", "text": "Her elf-half face occasionally shows an expression that doesn't match the moment."}, {"n": 8, "band": "Volatile", "text": "Commands a full web-lair of driders and spiders, ruling it like a broken court."}]}},
 "ettercap": {"desc": "It waits in the seam between web strands, spindly and grey-green, joints bending in ways that make you second-guess which way is forward for it. Silk trails from spinnerets at its abdomen even as it moves, patching the web behind it like a spider mending its own house. Its eyes are many and small and entirely uninterested in mercy.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Tends a web-choked grove, weaving fresh strands even mid-fight."}, {"n": 2, "band": "Grounded", "text": "Keeps a handful of giant spiders as semi-loyal hunting partners."}, {"n": 3, "band": "Grounded", "text": "Territorial and defensive, retreating into thick webbing rather than pursuing far."}, {"n": 4, "band": "Grounded", "text": "Old and scarred, missing two legs from some past fire encounter."}, {"n": 5, "band": "Grounded", "text": "Young, still building its web nest, more curious than aggressive."}, {"n": 6, "band": "Textured", "text": "Wraps kills in silk cocoons and stores them in a neat row, larder-style."}, {"n": 7, "band": "Strange", "text": "Its web bears faint patterns, almost like a message no one has read."}, {"n": 8, "band": "Volatile", "text": "Rules an entire web-warren of ettercaps and spiders as a silent matriarch."}]}},
 "flying-snake": {"desc": "A ribbon of bright feathered scale twists through the air on wings too small to explain the flight, darting and looping like a fish in water. It's small enough to seem harmless until the strike — quick, precise, venom-laced. Then it's already gone, spiraling back up into the canopy before you've registered the bite.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Nests in a hollow branch, darting out to snatch insects and small birds."}, {"n": 2, "band": "Grounded", "text": "Travels in a loose flock, weaving intricate patterns through the treetops."}, {"n": 3, "band": "Grounded", "text": "Territorial and quick to strike anything that lingers beneath its perch."}, {"n": 4, "band": "Grounded", "text": "Skittish, fleeing at the first sign of a larger threat rather than fighting."}, {"n": 5, "band": "Grounded", "text": "Kept half-tamed by a local hedge-witch as an errand-runner and lookout."}, {"n": 6, "band": "Textured", "text": "Its scales shimmer faintly in direct sun, prized by fletchers for ornament."}, {"n": 7, "band": "Strange", "text": "Circles the same spot for hours, as if guarding something buried below."}, {"n": 8, "band": "Volatile", "text": "Part of a large flock acting with eerie, coordinated aggression."}]}},
 "giant-axe-beak": {"desc": "Bigger than a warhorse and twice as mean, it plants its enormous taloned feet and lets out a rattling shriek that scatters lesser game for a mile. That beak has cracked more than one skull clean through. Its stare holds none of a bird's usual flightiness — this thing has never had to be afraid of anything in these grasslands.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rules a patch of open grassland, chasing off anything that competes for prey."}, {"n": 2, "band": "Grounded", "text": "Guards a nest of eggs the size of barrels, aggressive to any approach."}, {"n": 3, "band": "Grounded", "text": "Old and scarred, one leg stiff from a past fight it barely survived."}, {"n": 4, "band": "Grounded", "text": "Follows migrating herds, culling the weak with brutal efficiency."}, {"n": 5, "band": "Grounded", "text": "Young and still growing into its full size, testing its kicks on smaller prey."}, {"n": 6, "band": "Textured", "text": "Its beak carries deep gouges, notched like a tally of past kills."}, {"n": 7, "band": "Strange", "text": "Herds smaller axe-beaks with something like deliberate, learned coordination."}, {"n": 8, "band": "Volatile", "text": "Enormous even for its kind, having driven off every predator in its range."}]}},
 "giant-vulture": {"desc": "It circles long before it lands, wide dark wings riding the thermals with patient malice for whatever is dying below. Unlike an ordinary scavenger it doesn't only wait — it understands orders, and something crueler than instinct sometimes points it at prey that isn't dead yet. Up close it's larger than it looked from the ground, bald head slick and red, talons built for tearing rather than grasping.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Circles a fresh battlefield, patient, waiting for the living to finish dying."}, {"n": 2, "band": "Grounded", "text": "Nests on a cliff ledge littered with the bones of a dozen meals."}, {"n": 3, "band": "Grounded", "text": "Hunts alongside its fellows in loose coordination, flushing prey toward each other."}, {"n": 4, "band": "Grounded", "text": "Bold enough to attack the wounded and dying before they've stopped moving."}, {"n": 5, "band": "Grounded", "text": "Answers to a handler's whistle, set loose on a target it didn't choose itself."}, {"n": 6, "band": "Textured", "text": "Its talons are stained dark from years of carrion, permanently discolored."}, {"n": 7, "band": "Strange", "text": "Follows a specific traveler for days, as if it already knows how this ends."}, {"n": 8, "band": "Volatile", "text": "Part of a large kettle acting with unnatural coordination against the living."}]}},
 "greater-mimic": {"desc": "The chest is too new for this room, too clean of dust, and every instinct says leave it alone even as your hand reaches for the latch. Then the wood splits along seams that were never wood, and something vast and toothed unfolds from a shape built to be trusted. Greater mimics don't hide as chests. They hide as rooms.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Has taken the shape of an entire alcove, patient enough to wait out scouts."}, {"n": 2, "band": "Grounded", "text": "Mimics a locked vault door, the illusion good enough to fool most thieves."}, {"n": 3, "band": "Grounded", "text": "A previous victim's gear is fused half-digested into its false surface."}, {"n": 4, "band": "Grounded", "text": "Shares a chamber with lesser mimics, competing over the same ambush spot."}, {"n": 5, "band": "Grounded", "text": "Poses as furniture in a long-abandoned study, waiting years between meals."}, {"n": 6, "band": "Textured", "text": "Its false form bears faint tool marks, as if something once tried to open it."}, {"n": 7, "band": "Strange", "text": "Mimics a specific, oddly personal object — a bed, a cradle, a shrine."}, {"n": 8, "band": "Volatile", "text": "Has grown large enough to imitate an entire room, walls and all."}]}},
 "griffon": {"desc": "Eagle head, lion body, and wings wide enough to blot out the sun for a moment as it stoops — the griffon hits like a falling boulder with talons. It shrieks once before the strike, a sound that carries across a whole valley, and then it's a blur of gold feather and tawny fur closing the distance impossibly fast.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Circles a mountain trail below its aerie, striking anyone on horseback."}, {"n": 2, "band": "Grounded", "text": "Guards a clutch of eggs on an exposed ledge, absent parent due back soon."}, {"n": 3, "band": "Grounded", "text": "Its rider lies dead nearby; the griffon still circles the body protectively."}, {"n": 4, "band": "Grounded", "text": "Two rival prides clash overhead, raining blood and feathers on the road below."}, {"n": 5, "band": "Grounded", "text": "A wounded chick, separated from its pride, waits weak and hissing in the open."}, {"n": 6, "band": "Textured", "text": "Wears the remains of old tack, evidence it was once tamed and then escaped."}, {"n": 7, "band": "Strange", "text": "Follows a specific traveler at altitude for days without ever attacking."}, {"n": 8, "band": "Volatile", "text": "An entire pride hunts as one, coordinated in a way griffons rarely manage."}]}},
 "harpy": {"desc": "The song reaches you before the shape does, sweet and aching and entirely wrong once you see the source — vulture wings, taloned feet, a face that was once beautiful gone sharp and hungry. It sings because it works, because feet keep walking toward the cliff edge no matter what the mind insists. By the time you see her clearly, someone's already answering the call.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Roosts above a well-worn trail, luring travelers with song from the dark."}, {"n": 2, "band": "Grounded", "text": "Three farmers stand glassy-eyed at a pit's edge, about to step off."}, {"n": 3, "band": "Grounded", "text": "A charmed victim walks toward her perch right now, unaware of the danger."}, {"n": 4, "band": "Grounded", "text": "Nests on a cliff face travelers must climb, singing as they struggle up."}, {"n": 5, "band": "Grounded", "text": "Hunts alone, having been driven from a larger flock's territory."}, {"n": 6, "band": "Textured", "text": "Keeps a hoard of trinkets from lured victims, arranged like a nest of shine."}, {"n": 7, "band": "Strange", "text": "Her song carries fragments of a language no one nearby should recognize."}, {"n": 8, "band": "Volatile", "text": "Her call brings the whole flock in, one voice building on the next."}]}},
 "harpy-matriarch": {"desc": "Her song is the one the others answer to — older, richer, layered with a cruelty the young harpies haven't learned yet. She doesn't hunt so much as conduct, letting lesser harpies do the luring while she watches from height, patient as a queen. When she finally sings herself, every charmed thing in earshot turns at once.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Commands a full flock, directing lesser harpies from a high, safe perch."}, {"n": 2, "band": "Grounded", "text": "Holds several charmed victims in reserve, feeding on them slowly over days."}, {"n": 3, "band": "Grounded", "text": "Her nest is layered with the trinkets of a decade of lured travelers."}, {"n": 4, "band": "Grounded", "text": "A rival matriarch's territory borders hers; the flocks clash at the seam."}, {"n": 5, "band": "Grounded", "text": "Keeps a charmed guide alive to lead new prey toward her cliffside domain."}, {"n": 6, "band": "Textured", "text": "Her voice alone can silence the younger harpies mid-song, total authority."}, {"n": 7, "band": "Strange", "text": "Sings in overlapping harmonies, as if more than one throat is singing at once."}, {"n": 8, "band": "Volatile", "text": "Leads a flock large enough to overwhelm a caravan in a single pass."}]}},
 "hippogriff": {"desc": "Eagle head and foreclaws grafted onto a horse's powerful hindquarters, the hippogriff paws the ground once before it decides you're worth the effort. Its wings snap open with a crack of feathers, and then it's airborne, circling with the patient menace of something that has never lost this particular fight. It screams like a hawk and charges like a stallion.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Grazes a high meadow, aggressive only if its herd's foals are threatened."}, {"n": 2, "band": "Grounded", "text": "Bears old tack-scars, a former mount that broke free of its rider long ago."}, {"n": 3, "band": "Grounded", "text": "Nests on a rocky outcrop, diving at anything approaching the eggs."}, {"n": 4, "band": "Grounded", "text": "Young and skittish, more likely to flee a fight than press one."}, {"n": 5, "band": "Grounded", "text": "Travels with a small herd, the others scattering while one covers the retreat."}, {"n": 6, "band": "Textured", "text": "Has been half-tamed by someone nearby, still wearing a frayed lead rope."}, {"n": 7, "band": "Strange", "text": "Circles the same ruin repeatedly, as if drawn back by something buried there."}, {"n": 8, "band": "Volatile", "text": "An old, massive stallion-hippogriff rules the herd and fights without fear."}]}},
 "hook-horror": {"desc": "The clicking comes first, hooked forelimbs tapping stone in a rhythm that isn't quite language but isn't quite noise either. Insectile and vulture-headed, it moves along cave walls with an ease that shouldn't belong to something so heavy. Up close, its beak is built for tearing chitin off things far tougher than flesh.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Communicates with a nearby colony through rhythmic clicking on the cave wall."}, {"n": 2, "band": "Grounded", "text": "Guards a molt-shell midden, territorial about the site regardless of threat."}, {"n": 3, "band": "Grounded", "text": "Hunts alongside a small colony, coordinating ambushes through clicked signals."}, {"n": 4, "band": "Grounded", "text": "Old and scarred, one hook-limb bent from a past cave-in."}, {"n": 5, "band": "Grounded", "text": "Solitary and territorial, driven off from its colony for some transgression."}, {"n": 6, "band": "Textured", "text": "Its clicking pattern seems to answer specific sounds, almost conversational."}, {"n": 7, "band": "Strange", "text": "Marks cave walls with deliberate hook-gouges, a map only its kind can read."}, {"n": 8, "band": "Volatile", "text": "Leads a full colony in a coordinated, near-tactical assault."}]}},
 "hydra": {"desc": "One head becomes two the moment a blade finds its mark, and two becomes four if you're careless — the hydra doesn't fight so much as multiply out of a losing position. Each neck moves independently, hissing, snapping, tasting the air for blood already spilled. The stench of the swamp clings to it, and so does something older, patient, endlessly regenerating.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Lairs in a flooded delta, heads submerged and ambushing from beneath reeds."}, {"n": 2, "band": "Grounded", "text": "Guards a half-sunken hoard from countless drowned would-be slayers."}, {"n": 3, "band": "Grounded", "text": "Bears more head-scars than most, evidence of fights it survived by regrowing."}, {"n": 4, "band": "Grounded", "text": "Younger, fewer heads than a mature hydra, still building its full menace."}, {"n": 5, "band": "Grounded", "text": "Sluggish after gorging on a beached whale carcass, slower to strike."}, {"n": 6, "band": "Textured", "text": "One head is malformed, smaller, hissing but never quite biting."}, {"n": 7, "band": "Strange", "text": "Its heads occasionally snap at each other, as if disagreeing over prey."}, {"n": 8, "band": "Volatile", "text": "Enormous and many-headed beyond the ordinary, regrowing faster than it bleeds."}]}},
 "kraken": {"desc": "The sea itself seems to lift before the first tentacle breaks the surface, thick as a ship's mast and studded with suckers the size of shields. What surfaces after is a horror out of every drowned sailor's last thought — an eye the size of a cart wheel, ancient, aware, utterly indifferent to the size of your ship. The water around it churns black with its own ink.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Drags a merchant ship under, hull groaning as tentacles crush the deck."}, {"n": 2, "band": "Grounded", "text": "Territorial around a specific reef, attacking any vessel that anchors there."}, {"n": 3, "band": "Grounded", "text": "A survivor clings to wreckage nearby, the only witness to its last kill."}, {"n": 4, "band": "Grounded", "text": "Has been quiet for a generation; sailors thought it a myth until now."}, {"n": 5, "band": "Grounded", "text": "Guards an ancient sunken hoard, tentacles coiled protectively around it."}, {"n": 6, "band": "Textured", "text": "Bears harpoon scars from a doomed hunting expedition decades past."}, {"n": 7, "band": "Strange", "text": "Its ink clouds seem to form shapes before dispersing into the current."}, {"n": 8, "band": "Mythic", "text": "Old enough that entire coastal legends are built around avoiding its waters."}]}},
 "manticore": {"desc": "Lion body, bat wings, and a human-ish face that grins too wide beneath eyes with nothing human left in them — the manticore lands on the trail ahead like it's been waiting for you specifically. Its tail bristles with spikes it flicks loose in volleys, each one aimed with unsettling precision. It talks, sometimes. That's the worst part.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Perches on a rocky outcrop overlooking a well-traveled trade road."}, {"n": 2, "band": "Grounded", "text": "Its tail spikes are half-depleted, forcing it to close for a melee sooner."}, {"n": 3, "band": "Grounded", "text": "Hunts alone, having driven off a rival manticore from this territory."}, {"n": 4, "band": "Grounded", "text": "Speaks in taunting fragments before attacking, savoring the fear it causes."}, {"n": 5, "band": "Grounded", "text": "Young and reckless, engaging before its spike volleys are fully effective."}, {"n": 6, "band": "Textured", "text": "Wears the remains of jewelry from past victims, vain about its trophies."}, {"n": 7, "band": "Strange", "text": "Its human-ish face shifts expression unnaturally, mimicking whoever it faces."}, {"n": 8, "band": "Volatile", "text": "An old, cunning manticore that lures prey with feigned civility before striking."}]}},
 "medusa": {"desc": "She keeps her hood low and her voice soft, and every instinct in you says look at her — that's the cruelty of it, courtesy dressed over a curse. Underneath, her hair moves on its own, hissing, and anyone who meets her eyes finds their limbs turning cold and grey before they understand why. She has learned patience. She has had centuries to practice it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rules a ruined court of her own petrified subjects, treating them as furniture."}, {"n": 2, "band": "Grounded", "text": "Keeps her face veiled, using courtesy and conversation to lower a victim's guard."}, {"n": 3, "band": "Grounded", "text": "Uses a bow at range before ever risking eye contact up close."}, {"n": 4, "band": "Grounded", "text": "Lives in isolation, embittered and quick to anger at any intrusion."}, {"n": 5, "band": "Grounded", "text": "Keeps snake familiars that hiss in warning before she reveals herself."}, {"n": 6, "band": "Textured", "text": "Talks to her petrified victims as if they can still hear and answer her."}, {"n": 7, "band": "Strange", "text": "Her hair seems to react to her mood independent of her own expression."}, {"n": 8, "band": "Volatile", "text": "Ancient and cunning, having outlasted every hero sent to end her curse."}]}},
 "merrow": {"desc": "It breaches the surf like something surfacing from a drowning, fish-eyed and hulking, webbed claws built to drag a struggling body under. Half orc, half something that never should have learned to swim this well. The stench of brine and rot clings to it, and it grins with a mouth full of needle teeth before it dives back for another pass.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts a fishing village's nets, dragging catch and the occasional net-tender under."}, {"n": 2, "band": "Grounded", "text": "Travels in a small raiding pod, coordinating ambushes near a reef."}, {"n": 3, "band": "Grounded", "text": "Territorial around a sunken wreck it has claimed as a lair."}, {"n": 4, "band": "Grounded", "text": "Bears deep scars from a shark encounter, wary of open water now."}, {"n": 5, "band": "Grounded", "text": "Young and reckless, surfacing too close to shore for its own safety."}, {"n": 6, "band": "Textured", "text": "Wears crude jewelry looted from drowned sailors, prized like trophies."}, {"n": 7, "band": "Strange", "text": "Croons a low, half-melodic call before an ambush, almost like a lure."}, {"n": 8, "band": "Volatile", "text": "Leads a large raiding pod that has begun striking coastal settlements."}]}},
 "mimic": {"desc": "There is exactly one chest in this room, and something about it says take me even as your instincts scream otherwise. The wood grain is a little too perfect, the lock a little too new. Then the lid splits wrong and a mouth full of digestive acid closes around whatever reached for the latch. It has been a chest for a very long time, and it is very good at it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Sits alone in an otherwise empty room, obviously the only thing worth looting."}, {"n": 2, "band": "Grounded", "text": "Poses as a stuck door the party has already spent two rounds forcing."}, {"n": 3, "band": "Grounded", "text": "Hides among identical furniture, indistinguishable until it moves."}, {"n": 4, "band": "Grounded", "text": "A keeper nearby directs it with scraps of meat on a long pole, half-tamed."}, {"n": 5, "band": "Grounded", "text": "Poses as the obvious decoy beside a second, genuinely trapped real chest."}, {"n": 6, "band": "Textured", "text": "Still holds half-digested coins and buckles fused into its false wood grain."}, {"n": 7, "band": "Strange", "text": "Mimics a small, oddly specific object — a birdcage, a child's toy chest."}, {"n": 8, "band": "Volatile", "text": "Has learned to wait through multiple search passes before finally striking."}]}},
 "minotaur-of-the-horned-king": {"desc": "It doesn't charge blindly like the maze-bound brutes of old stories — this one moves with a cold, calculating menace, horns lowered like a crown rather than a weapon. Muscle rides beneath a bull's hide scarred by old ritual brands, and its breath comes slow and even, the patience of something that has hunted intelligent prey before. It remembers every hall it has ever killed in.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a labyrinth built to a dead king's specifications, still loyal to the old order."}, {"n": 2, "band": "Grounded", "text": "Bears ritual brands marking rank among other minotaurs it once commanded."}, {"n": 3, "band": "Grounded", "text": "Hunts methodically, using the maze's dead ends to corner rather than chase."}, {"n": 4, "band": "Grounded", "text": "Keeps trophies of past intruders mounted along the labyrinth walls."}, {"n": 5, "band": "Grounded", "text": "Alone now, having outlived every other minotaur of the old king's court."}, {"n": 6, "band": "Textured", "text": "Speaks in the old tongue of the horned king's line, mostly to itself."}, {"n": 7, "band": "Strange", "text": "Never gets lost in its own maze, moving with a certainty that unnerves."}, {"n": 8, "band": "Volatile", "text": "Wears a crown of bone from the horned king's court, fighting with regal fury."}]}},
 "owlbear": {"desc": "The head is an owl's, wide-eyed and silent even in fury; the body is a bear's, all muscle and claw. Together they make something that shouldn't exist and clearly wishes it hadn't been interrupted. It feeds on a fresh kill without hurry until you get too close — then the screech comes, and the world narrows to claws.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Feeds on a fresh kill; leave it alone and it may finish and wander off."}, {"n": 2, "band": "Grounded", "text": "A cub is nearby, unseen, and its scream will bring the adult running."}, {"n": 3, "band": "Grounded", "text": "Wounded badly by a crossbow bolt still lodged in its side, cornered and afraid."}, {"n": 4, "band": "Grounded", "text": "Has been tamed, barely, and strains against a chain with three hit points left."}, {"n": 5, "band": "Grounded", "text": "Broke through a dungeon wall days ago and has been hunting the tunnels since."}, {"n": 6, "band": "Textured", "text": "Its territory borders a goblin warren too terrified of it to reclaim the space."}, {"n": 7, "band": "Strange", "text": "Its screech triggers early, at the worst possible moment for whoever's near."}, {"n": 8, "band": "Volatile", "text": "Massive and scarred, having killed everything that has ever challenged it here."}]}},
 "owlbear-cub": {"desc": "Small enough to look almost harmless, the cub still carries its parents' full menace in miniature — claws that haven't learned restraint, a screech that hasn't learned volume control yet. It play-fights with the air, clumsy, curious, and entirely capable of drawing blood by accident. Somewhere close, an adult is listening for it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Alone in a den, and its distress call will bring an adult within the minute."}, {"n": 2, "band": "Grounded", "text": "Play-fighting with a half-eaten carcass, more curious than aggressive so far."}, {"n": 3, "band": "Grounded", "text": "Has wandered from its parent's territory, disoriented and easily startled."}, {"n": 4, "band": "Grounded", "text": "Someone has been feeding it, hoping to raise it tame — badly, so far."}, {"n": 5, "band": "Grounded", "text": "Chained by a local faction as an untested guard, restless and confused."}, {"n": 6, "band": "Textured", "text": "Its claws are already sharp enough to shred leather in a careless swipe."}, {"n": 7, "band": "Strange", "text": "Its screech is oddly muted, as if still learning the sound's true pitch."}, {"n": 8, "band": "Volatile", "text": "Panicked and screeching nonstop, guaranteeing an adult arrives mid-fight."}]}},
 "peryton": {"desc": "Stag antlers crown an eagle's head, and where its shadow should fall on the ground, a man's silhouette stretches instead — the peryton's curse made visible. It circles high before the dive, patient as any bird of prey, and the impact of its antlers can take a rib clean through. Legend says it hunts for hearts. It doesn't need the legend to be true to be dangerous.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts a mountain pass, diving from height at anything alone on the trail."}, {"n": 2, "band": "Grounded", "text": "Its human-shaped shadow briefly overlaps a fresh kill's own shadow, unsettling witnesses."}, {"n": 3, "band": "Grounded", "text": "Travels in a small flock, taking turns diving while others circle above."}, {"n": 4, "band": "Grounded", "text": "Territorial around a nesting cliff, aggressive to anyone who lingers below."}, {"n": 5, "band": "Grounded", "text": "Old and scarred, one antler broken from a past failed dive."}, {"n": 6, "band": "Textured", "text": "Carries the smell of a specific person's home, as if it hunts by memory."}, {"n": 7, "band": "Strange", "text": "Its shadow moves independently of the wind and light, always human-shaped."}, {"n": 8, "band": "Volatile", "text": "A whole flock hunts together, shadows overlapping into a mass of human shapes."}]}},
 "phase-spider": {"desc": "It bites from an angle you weren't watching, gone again into some fold of space before the wound even registers. Eight legs, ashen fur, mandibles slick with a paralytic that works fast — and none of it matters as much as the fact that half the time you swing, it simply isn't where it should be. The Ethereal takes it in and spits it back out, laughing.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts a web-choked cave, phasing in to bite and out before a retort lands."}, {"n": 2, "band": "Grounded", "text": "Nests near a natural rift, phasing more easily the closer it stays to that spot."}, {"n": 3, "band": "Grounded", "text": "Territorial with other spiders, driving off lesser webweavers from its cave."}, {"n": 4, "band": "Grounded", "text": "Bears scars from a past ambush gone wrong, more cautious about full engagement."}, {"n": 5, "band": "Grounded", "text": "Young, phasing less reliably, sometimes caught mid-bite in the Material Plane."}, {"n": 6, "band": "Textured", "text": "Its web strands persist faintly on the Ethereal side, visible only there."}, {"n": 7, "band": "Strange", "text": "Phases in slightly off-target sometimes, as if the Ethereal resists it lately."}, {"n": 8, "band": "Volatile", "text": "An elder phase spider that barely spends any time in the Material Plane at all."}]}},
 "primeval-owlbear": {"desc": "This is what an owlbear becomes given centuries and no reason to stop growing — a mountain of claw and feather that has forgotten it should fear anything. Its screech doesn't just stun; it rattles teeth loose at range. The forest around its territory has gone quiet in a way that predates memory. Nothing here disputes its claim.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Rules an ancient stretch of forest; every other predator has learned to avoid it."}, {"n": 2, "band": "Grounded", "text": "Guards a den holding the remains of every serious hunting party sent after it."}, {"n": 3, "band": "Grounded", "text": "A local legend names it directly; hunters speak of it like a weather pattern."}, {"n": 4, "band": "Grounded", "text": "Its territory has swallowed an old shrine, now just another feature of its den."}, {"n": 5, "band": "Grounded", "text": "A cub of unusual size shares its territory, testing its own growing strength."}, {"n": 6, "band": "Textured", "text": "Bears scars from a fight decades past that nothing living remembers clearly."}, {"n": 7, "band": "Strange", "text": "Its screech carries further than should be possible, shaking loose stone."}, {"n": 8, "band": "Mythic", "text": "Old enough to be treated as a landmark — travelers route entire roads around it."}]}},
 "purple-worm": {"desc": "The ground doesn't just shake — it opens, and a maw wide enough to swallow a horse whole rises from beneath the sand in a spray of grit. Segmented, vast, and utterly indifferent to anything above the size of a snack, the purple worm doesn't hunt so much as strain the world for meat. Its stinger drips a venom that finishes what the swallowing starts.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Tunnels beneath a desert trade route, collapsing caravans into its maw."}, {"n": 2, "band": "Grounded", "text": "Has swallowed something valuable recently, bulging visibly along its length."}, {"n": 3, "band": "Grounded", "text": "Territorial along a specific tunnel network, surfacing whenever it's disturbed."}, {"n": 4, "band": "Grounded", "text": "Sluggish after a recent enormous meal, slower to strike but still lethal."}, {"n": 5, "band": "Grounded", "text": "Young for its kind, still shorter, hunting closer to the surface than usual."}, {"n": 6, "band": "Textured", "text": "Its hide bears scars from something that fought back and nearly won."}, {"n": 7, "band": "Strange", "text": "Surfaces in eerie silence for something so enormous, no warning tremor at all."}, {"n": 8, "band": "Mythic", "text": "Ancient and colossal even for its kind, said to have swallowed whole towers."}]}},
 "remorhaz": {"desc": "Heat shimmers off its back even in the depths of winter, a ridge of glowing orange plates running the length of a body built like a centipede and a nightmare had a child. It surfaces from beneath the snowpack in a hiss of melted ice, jaws wide enough to take a man in a single bite, and the cold around it seems to flinch away.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Tunnels beneath a glacier field, surfacing wherever it senses movement above."}, {"n": 2, "band": "Grounded", "text": "Territorial around a specific ice cavern that its heat has hollowed out over years."}, {"n": 3, "band": "Grounded", "text": "Recently fed, plates dimmed slightly, sluggish but still dangerous if provoked."}, {"n": 4, "band": "Grounded", "text": "Young and restless, its glow flickering unevenly as it's still growing into it."}, {"n": 5, "band": "Grounded", "text": "Hunts along a caravan's winter route, having learned the schedule by scent."}, {"n": 6, "band": "Textured", "text": "Melts a permanent trench through the snowpack behind it wherever it travels."}, {"n": 7, "band": "Strange", "text": "Its glow pulses in a slow rhythm, almost like breath given visible form."}, {"n": 8, "band": "Volatile", "text": "Enormous and blazing hot even by its kind's standard, melting stone as it passes."}]}},
 "roc": {"desc": "The shadow crosses first, vast enough to blot out a whole caravan, and then the wind of its wingbeat nearly knocks you flat before you've even looked up. Talons the size of ship anchors can lift a horse clean off the ground. It doesn't so much attack as harvest — swooping, gripping, and gone again before the ground has finished shaking.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Nests atop a mountain peak, hunting livestock and travelers from far below."}, {"n": 2, "band": "Grounded", "text": "Has carried off a wagon whole, still visible dangling from its talons overhead."}, {"n": 3, "band": "Grounded", "text": "Guards an enormous egg on an exposed peak, aggressive to any approach."}, {"n": 4, "band": "Grounded", "text": "Old and scarred, one wing bearing damage from a past storm or fight."}, {"n": 5, "band": "Grounded", "text": "Territorial along a specific mountain pass, driving off smaller birds of prey."}, {"n": 6, "band": "Textured", "text": "Its nest is littered with the wreckage of carts and ship rigging alike."}, {"n": 7, "band": "Strange", "text": "Follows a specific caravan route for days without attacking, as if studying it."}, {"n": 8, "band": "Mythic", "text": "Enormous even for its kind, said to have carried off entire ships from harbor."}]}},
 "rust-monster": {"desc": "It ignores the spellcaster entirely and beelines for the steel — armor, blade, buckle, all of it drawing the twitching antennae toward the smell only it can sense. Metal corrodes to orange flake wherever those feelers touch, fast enough to watch happen. It isn't malicious. It's just hungry, and your sword looks delicious.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Beelines for the party's best-armored member, ignoring everyone else entirely."}, {"n": 2, "band": "Grounded", "text": "A pile of scrap metal nearby can distract it for several rounds if thrown its way."}, {"n": 3, "band": "Grounded", "text": "Has already corroded a portcullis mechanism shut, trapping something inside."}, {"n": 4, "band": "Grounded", "text": "A faction keeps a feeding station of iron ingots to steer it from occupied halls."}, {"n": 5, "band": "Grounded", "text": "Travels in a small pack, each one drawn to different metal on the same target."}, {"n": 6, "band": "Textured", "text": "Its antennae twitch toward buried metal, hinting at treasure under the floor."}, {"n": 7, "band": "Strange", "text": "Leaves a faint orange dust trail that never seems to fully settle."}, {"n": 8, "band": "Volatile", "text": "Unusually large and fast, closing the distance before armor can be shed."}]}},
 "stirge": {"desc": "It flutters in low and erratic, mosquito-faced and bat-winged, and the proboscis finds a vein before you've fully registered the bite. There's a horrible, swelling patience to the way it feeds — gorging, bloating, entirely unwilling to let go until it's full or dead. One alone is a nuisance. A swarm of them is a slow bleeding-out.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Roosts in a damp cave ceiling, dropping down at the scent of fresh blood."}, {"n": 2, "band": "Grounded", "text": "Already bloated from a recent feed, sluggish and easy to dislodge."}, {"n": 3, "band": "Grounded", "text": "Hunts alone, having strayed from a larger roost nearby."}, {"n": 4, "band": "Grounded", "text": "Nests near standing water, drawn by the same insects that draw travelers' curses."}, {"n": 5, "band": "Grounded", "text": "Skittish, fleeing the instant it's swatted at rather than pressing the bite."}, {"n": 6, "band": "Textured", "text": "Its proboscis is stained a deep, permanent rust color from years of feeding."}, {"n": 7, "band": "Strange", "text": "Seems to target the same vein spot every time, oddly precise for a pest."}, {"n": 8, "band": "Volatile", "text": "Engorged far past normal, barely able to fly, but latched on and unwilling to release."}]}},
 "swarm-of-stirges": {"desc": "It isn't one bloodsucker but a churning cloud of them, wings clattering against each other as they descend all at once. No single bite matters. The math is the horror — a dozen proboscises finding purchase in the same minute, and the swarm doesn't stop feeding until something makes it. The air fills with a wet, papery buzzing.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Descends on a wounded traveler already too weak to fight it off alone."}, {"n": 2, "band": "Grounded", "text": "Roosts above a well-used trail, dropping en masse at the scent of blood."}, {"n": 3, "band": "Grounded", "text": "Has already drained a pack animal dry, carcass still twitching under the swarm."}, {"n": 4, "band": "Grounded", "text": "Nests near a stagnant pool, drawn by the insects that breed there."}, {"n": 5, "band": "Grounded", "text": "Scatters at fire or loud noise but reforms the moment the threat passes."}, {"n": 6, "band": "Textured", "text": "Leaves behind a fine dusting of shed feather-down wherever it feeds."}, {"n": 7, "band": "Strange", "text": "Moves with an eerie unified purpose, more coordinated than a swarm should be."}, {"n": 8, "band": "Volatile", "text": "Massive beyond a normal swarm's size, having fed undisturbed for a long while."}]}},
 "tarrasque": {"desc": "The horizon itself seems to rise when it wakes, a mountain range given legs and a hunger that predates every kingdom built to outlast it. Scales like plate armor forged by no smith turn aside catapult stones as if they were rain. It does not conquer. It does not rule. It simply ends things, unhurried, because nothing has ever truly stopped it.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Has surfaced near a city; evacuation orders are already too late for the outer wards."}, {"n": 2, "band": "Grounded", "text": "An ancient order maintains a ritual meant to lull it back to dormancy — barely."}, {"n": 3, "band": "Grounded", "text": "Its wake left a scar of leveled forest and cratered earth for miles."}, {"n": 4, "band": "Grounded", "text": "A prior kingdom's entire military committed everything and merely survived, not won."}, {"n": 5, "band": "Grounded", "text": "Follows some deep, unknowable migration, indifferent to what stands in its path."}, {"n": 6, "band": "Textured", "text": "Old siege engines lie fused into its hide, permanent reminders it shrugged off."}, {"n": 7, "band": "Strange", "text": "Has gone still and silent for exactly as long as legend says it always has, then moves."}, {"n": 8, "band": "Mythic", "text": "Its name alone ends council debates; entire nations plan around never meeting it."}]}},
 "thri-kreen-marauder": {"desc": "Four arms move independently as it crosses open ground in a burst of insectile speed, chitin the color of sun-bleached sand. Mandibles click a rhythm that might be communication with kin you haven't seen yet. It hunts in packs, methodical and utterly without malice — this is simply how the desert feeds itself.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts a caravan route, coordinating ambushes with a small pack of kin."}, {"n": 2, "band": "Grounded", "text": "Carries a chipped stone weapon, favoring it over natural claws in a fight."}, {"n": 3, "band": "Grounded", "text": "Territorial around a burrow cluster, defensive rather than aggressive at range."}, {"n": 4, "band": "Grounded", "text": "Young, still learning pack coordination, occasionally breaking formation."}, {"n": 5, "band": "Grounded", "text": "Scarred from a past fight with something venomous, wary of ambush now."}, {"n": 6, "band": "Textured", "text": "Clicks its mandibles in patterns that seem to relay tactical signals mid-fight."}, {"n": 7, "band": "Strange", "text": "Moves in total silence across sand despite four legs and heavy chitin."}, {"n": 8, "band": "Volatile", "text": "Leads a full pack in a coordinated, disciplined desert ambush."}]}},
 "thri-kreen-psion": {"desc": "It doesn't announce itself with mandible-clicks like the marauders do — this one is still, watching, and the pressure you feel behind your eyes arrives a half-second before you realize it's inside your thoughts. Sand-colored chitin, four arms folded with unnerving patience. Whatever it wants from your mind, it will simply take.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Leads a marauder pack from the rear, directing them through mental commands."}, {"n": 2, "band": "Grounded", "text": "Reads a target's surface thoughts before ever engaging in melee."}, {"n": 3, "band": "Grounded", "text": "Territorial around a meditation site marked with alien, geometric patterns."}, {"n": 4, "band": "Grounded", "text": "Prefers to probe minds from a distance, avoiding direct combat when possible."}, {"n": 5, "band": "Grounded", "text": "Young in its psionic training, its mental probes occasionally overreach and falter."}, {"n": 6, "band": "Textured", "text": "Its chitin bears faint etchings that seem to shift when observed too long."}, {"n": 7, "band": "Strange", "text": "Answers questions before they're asked aloud, a half-beat ahead of speech."}, {"n": 8, "band": "Volatile", "text": "Powerful enough to bend a whole pack's actions through thought alone."}]}},
 "troglodyte": {"desc": "The stench hits before the shape does, a musk so foul it turns stomachs and blurs thought — the troglodyte's own defense woven into its skin. Reptilian, hunched, and covered in warty grey hide, it blends into cave stone until it doesn't want to anymore. Its claws are crude but its numbers rarely are.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts in a small band, coordinating ambushes from cave shadows."}, {"n": 2, "band": "Grounded", "text": "Guards a midden of bones and refuse, territorial about the smell it's built."}, {"n": 3, "band": "Grounded", "text": "Wears crude trophies from past kills, mostly bone and tooth."}, {"n": 4, "band": "Grounded", "text": "Scarred and cautious, having lost a rival fight over this stretch of cave."}, {"n": 5, "band": "Grounded", "text": "Young and reckless, more likely to charge than use its camouflage."}, {"n": 6, "band": "Textured", "text": "Its musk lingers on everything nearby, staining cloth and skin for days."}, {"n": 7, "band": "Strange", "text": "Blends into the cave wall so well it's mistaken for stone until it moves."}, {"n": 8, "band": "Volatile", "text": "Leads a full warren of troglodytes in a coordinated ambush, musk thick as fog."}]}},
 "umber-hulk": {"desc": "Four eyes swivel independently on a chitinous, mantis-like head, and the confusion sets in before the claws even reach you — the gaze alone can turn allies against each other. It burrows through solid rock with mandibles built for exactly that, and it hunts in the deep dark where nothing above ground ever learns its habits fast enough.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Tunnels beneath a dungeon level, surfacing wherever it senses movement above."}, {"n": 2, "band": "Grounded", "text": "Territorial around a specific cave chamber, aggressive to any deep intrusion."}, {"n": 3, "band": "Grounded", "text": "Old and scarred, one eye clouded from a past fight, gaze slightly weaker."}, {"n": 4, "band": "Grounded", "text": "Hunts methodically, using confusion to scatter a group before picking targets."}, {"n": 5, "band": "Grounded", "text": "Young, tunnels less efficiently, leaving rougher and more obvious burrows."}, {"n": 6, "band": "Textured", "text": "Its tunnels connect several chambers, giving it near-total map knowledge."}, {"n": 7, "band": "Strange", "text": "Its confusing gaze lingers oddly long, victims disoriented well after eye contact ends."}, {"n": 8, "band": "Volatile", "text": "Enormous and ancient, having carved out an entire warren beneath this level."}]}},
 "werebear": {"desc": "Beneath the calm, deliberate movements of the man is something that fights the change every full moon and mostly wins — until it doesn't. When the shift takes him, fur and claw and a bear's raw strength arrive fast, but the eyes stay disturbingly human, aware, ashamed even mid-roar. This is a curse worn by someone trying, and failing, to be good about it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Lives isolated in the wilderness, avoiding people to protect them from the curse."}, {"n": 2, "band": "Grounded", "text": "Fights the change actively, retreating to chain itself before each full moon."}, {"n": 3, "band": "Grounded", "text": "Protects a specific stretch of forest or a small community from other threats."}, {"n": 4, "band": "Grounded", "text": "Recently infected, still learning to control the change and its violence."}, {"n": 5, "band": "Grounded", "text": "Has made peace with the curse, using bear form deliberately to guard what it loves."}, {"n": 6, "band": "Textured", "text": "Retains human speech and reasoning even mid-transformation, pleading for calm."}, {"n": 7, "band": "Strange", "text": "Its eyes stay entirely human even in full bear form, aware and grieving."}, {"n": 8, "band": "Volatile", "text": "Has lost the fight against the curse entirely, now more bear than man."}]}},
 "wereboar": {"desc": "There's a meanness to it that the werebear doesn't share — tusks curving up from a snout gone savage, small eyes lit with a cruelty that seems to enjoy the change rather than suffer it. It charges low and fast, and the human shape it wore an hour ago already feels like a costume it's glad to shed.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Leads a small raiding band, using the curse to intimidate and dominate them."}, {"n": 2, "band": "Grounded", "text": "Enjoys the change openly, provoking fights specifically to justify transforming."}, {"n": 3, "band": "Grounded", "text": "Hides the curse from a community it lives among, transforming only in secret."}, {"n": 4, "band": "Grounded", "text": "Territorial around a mud wallow or den it treats as sacred ground."}, {"n": 5, "band": "Grounded", "text": "Recently infected, resentful and lashing out at anyone nearby."}, {"n": 6, "band": "Textured", "text": "Bears tusk-scars from fighting rival wereboars over pack dominance."}, {"n": 7, "band": "Strange", "text": "Grins mid-charge in boar form, an expression a boar's face shouldn't manage."}, {"n": 8, "band": "Volatile", "text": "Fully consumed by the curse's cruelty, transforming at the slightest provocation."}]}},
 "wererat": {"desc": "It slips between forms with a practiced ease the other lycanthropes lack — human merchant one moment, hunched rat-faced thing the next, always with an eye on the nearest exit. Wererats don't want a fair fight; they want your purse, your secrets, or your throat, whichever is easiest tonight. The sewers under this city are lousy with its kin.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Runs a smuggling ring through the sewers, using the curse to enforce debts."}, {"n": 2, "band": "Grounded", "text": "Has infiltrated a guild or watch post, hiding the curse behind a trusted face."}, {"n": 3, "band": "Grounded", "text": "Leads a small nest of wererats beneath the city, recruiting the desperate."}, {"n": 4, "band": "Grounded", "text": "Owes a debt to something worse and is hunting to pay it off."}, {"n": 5, "band": "Grounded", "text": "Keeps a hostage in the sewers as leverage over someone on the surface."}, {"n": 6, "band": "Textured", "text": "Trades in stolen goods, using rat form to slip through grates and vaults."}, {"n": 7, "band": "Strange", "text": "Speaks in an oddly courteous tone even while threatening, business-like."}, {"n": 8, "band": "Volatile", "text": "Commands an entire nest large enough to contest a city district's underworld."}]}},
 "weretiger": {"desc": "There's a stillness to it before the change, a predator's patience worn like a second skin even in human form. When the shift comes, stripes ripple across muscle built for the ambush, and the eyes go gold and unblinking. Unlike its cursed kin, this one doesn't struggle against the change — it simply prefers being the tiger.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hunts alone in dense jungle or forest, preferring solitude in either form."}, {"n": 2, "band": "Grounded", "text": "Has embraced the curse fully, spending most of its time in tiger form."}, {"n": 3, "band": "Grounded", "text": "Guards a specific territory fiercely, marking it in both human and beast form."}, {"n": 4, "band": "Grounded", "text": "Lives among a community that knows and tolerates its nature, uneasily."}, {"n": 5, "band": "Grounded", "text": "Recently infected, still adjusting to the pull toward solitude the curse brings."}, {"n": 6, "band": "Textured", "text": "Moves with unnerving silence in human form, a predator's tell that never faded."}, {"n": 7, "band": "Strange", "text": "Its eyes retain a faint golden shine even fully human, easy to miss but there."}, {"n": 8, "band": "Volatile", "text": "An apex hunter even among its kind, territory uncontested for years."}]}},
 "werewolf": {"desc": "The howl comes first, then the shape breaks apart and reforms into something with a wolf's jaw and a man's cruelty behind the eyes. It hunts in packs when it can, alone when it must, and either way it remembers every grudge from its human life once the moon pulls the beast forward. The curse doesn't erase the person. It just removes the leash.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Leads a small pack of afflicted followers, spreading the curse deliberately."}, {"n": 2, "band": "Grounded", "text": "Hunts a specific person from its human life, unable to let old grudges go."}, {"n": 3, "band": "Grounded", "text": "Has infiltrated a settlement, hiding the curse until the next full moon forces it out."}, {"n": 4, "band": "Grounded", "text": "A family member is searching for a cure, unaware how far the curse has spread."}, {"n": 5, "band": "Grounded", "text": "Terrorizes a rural village on a set lunar schedule the locals have started tracking."}, {"n": 6, "band": "Textured", "text": "Keeps trophies from hunts in both forms, unable to fully separate the two selves."}, {"n": 7, "band": "Strange", "text": "Speaks with unsettling clarity mid-transformation, thoughts intact through the change."}, {"n": 8, "band": "Volatile", "text": "Commands a full pack bold enough to hunt in the open under a waning moon."}]}},
 "winter-wolf": {"desc": "White fur blends it into the snowbank until the moment it isn't a snowbank at all, eyes pale and cunning above a jaw built for a cold-breath weapon it's proud of using. It hunts in packs with a chilling discipline, herding prey the way a shepherd herds sheep. The frost around its breath lingers longer than it should.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Runs with a disciplined pack, herding prey toward a killing ground."}, {"n": 2, "band": "Grounded", "text": "Serves a frost giant or similar master, loyal in exchange for shelter and scraps."}, {"n": 3, "band": "Grounded", "text": "Territorial around a den dug into a snowbank, defended fiercely."}, {"n": 4, "band": "Grounded", "text": "Old and scarred, favoring cold breath over melee after a past injury."}, {"n": 5, "band": "Grounded", "text": "Young, still learning pack discipline, occasionally breaking formation early."}, {"n": 6, "band": "Textured", "text": "Its breath frost lingers on stone and metal alike, marking where it's been."}, {"n": 7, "band": "Strange", "text": "Moves without leaving tracks in fresh snow, an unnerving hunting trait."}, {"n": 8, "band": "Volatile", "text": "Leads a large, disciplined pack that hunts with near-military coordination."}]}},
 "yeti": {"desc": "It watches from just past the edge of visibility in the snow-blind haze, pale fur nearly invisible against the storm, and only the eyes give it away — patient, hungry, unblinking. Its gaze alone can root a person in place with fear before the claws even close the distance. The cold doesn't bother it. It never has.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Stalks a mountain pass, using its gaze to freeze travelers in place before closing."}, {"n": 2, "band": "Grounded", "text": "Territorial around a specific ridge, aggressive to anyone who camps there."}, {"n": 3, "band": "Grounded", "text": "Old and scarred, missing claws on one hand from a past trap."}, {"n": 4, "band": "Grounded", "text": "Young and skittish, more likely to flee after a failed gaze attempt."}, {"n": 5, "band": "Grounded", "text": "Hunts alone, driven from a larger group for reasons unclear."}, {"n": 6, "band": "Textured", "text": "Its fur carries a faint chill even at a distance, unnaturally cold to the touch."}, {"n": 7, "band": "Strange", "text": "Blends so completely into snowfall that it seems to appear from nowhere."}, {"n": 8, "band": "Volatile", "text": "Massive and ancient, its gaze rooting even seasoned hunters in place."}]}},
 "yuan-ti-abomination": {"desc": "Barely anything human remains in the shape of it — a serpent's coils where legs should be, a torso gone scaled and wrong, and a face that has mostly given up pretending. It moves with a boneless, gliding confidence, venom dripping between words in a language older than most kingdoms. It was human once. It does not miss it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Guards an inner sanctum of a serpent temple, deferred to by lesser yuan-ti."}, {"n": 2, "band": "Grounded", "text": "Commands a mixed cult of malisons and human converts with cold authority."}, {"n": 3, "band": "Grounded", "text": "Bears ritual scarring marking a high rank within its temple's hierarchy."}, {"n": 4, "band": "Grounded", "text": "Speaks fluently in the old tongue, dismissive of any language spoken by mammals."}, {"n": 5, "band": "Grounded", "text": "Coils protectively around a ritual altar, treating intrusion as sacrilege."}, {"n": 6, "band": "Textured", "text": "Its scales shift color subtly with mood, a tell few outsiders learn to read."}, {"n": 7, "band": "Strange", "text": "Speaks in a hiss that seems to carry underneath, in a second layered voice."}, {"n": 8, "band": "Volatile", "text": "An ancient serpent-priest, barely recalling it once wore a human face at all."}]}},
 "yuan-ti-infiltrator": {"desc": "It could pass for human in dim light — that's the point. Only up close does the faintest scale-sheen along the cheekbone give it away, or the way its pupils narrow wrong in torchlight. It moves through human spaces gathering names, debts, and secrets for a temple that has never once needed to show its true face to win.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Has infiltrated a merchant house, siphoning coin toward a serpent temple."}, {"n": 2, "band": "Grounded", "text": "Poses as a trusted advisor to someone of local influence, patiently manipulating them."}, {"n": 3, "band": "Grounded", "text": "Gathers names and debts for a cult that hasn't shown its hand yet."}, {"n": 4, "band": "Grounded", "text": "Has a specific target marked for recruitment or removal within days."}, {"n": 5, "band": "Grounded", "text": "Maintains a double life, family unaware of the scales beneath its collar."}, {"n": 6, "band": "Textured", "text": "Carries a small ritual token hidden on its person, marking temple loyalty."}, {"n": 7, "band": "Strange", "text": "Its shadow occasionally shows a serpentine outline it doesn't seem to notice."}, {"n": 8, "band": "Volatile", "text": "Has risen high enough in a local institution to move against it from within."}]}},
 "yuan-ti-malison-type-1": {"desc": "The transformation stopped somewhere between man and serpent and left this — a human torso wearing a snake's head, forked tongue tasting the air for lies and blood alike. It carries itself like nobility that has decided it no longer needs to look human to be believed. Its bow hand never wavers.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Leads a patrol of yuan-ti purebloods, coordinating archers from elevated cover."}, {"n": 2, "band": "Grounded", "text": "Guards a temple approach, challenging intruders before resorting to violence."}, {"n": 3, "band": "Grounded", "text": "Bears old scars from a rival malison, competitive within its own hierarchy."}, {"n": 4, "band": "Grounded", "text": "Speaks with cold formality, viewing conversation as a formality before combat."}, {"n": 5, "band": "Grounded", "text": "Young in rank, eager to prove itself against any intrusion, reckless."}, {"n": 6, "band": "Textured", "text": "Its snake head flicks its tongue rhythmically, tasting for approaching threats."}, {"n": 7, "band": "Strange", "text": "Its eyes hold a fixed, unblinking stare even mid-conversation."}, {"n": 8, "band": "Volatile", "text": "Commands significant temple authority, quick to escalate any perceived slight."}]}},
 "yuan-ti-malison-type-2": {"desc": "This one's arms have gone to serpent below the elbow, twin snake-heads where hands should be, each independently alert and hissing. It fights with an unsettling economy — the human half calculating, the serpent halves simply reacting to whatever gets close. Watching it is like watching three creatures argue over one kill.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Serves as a temple enforcer, its arm-heads striking independently in a fight."}, {"n": 2, "band": "Grounded", "text": "Patrols a specific ritual corridor, territorial and quick to challenge intrusion."}, {"n": 3, "band": "Grounded", "text": "Bears scarring on one arm-head, slightly slower to strike on that side."}, {"n": 4, "band": "Grounded", "text": "Works alongside a malison type 1, deferring to its bow-based tactics."}, {"n": 5, "band": "Grounded", "text": "Young, its arm-heads not yet fully coordinated with its own reactions."}, {"n": 6, "band": "Textured", "text": "Its two arm-heads hiss at different pitches, almost like separate voices."}, {"n": 7, "band": "Strange", "text": "One arm-head sometimes strikes a half-beat before the creature decides to attack."}, {"n": 8, "band": "Volatile", "text": "A veteran enforcer whose arm-heads move with eerie, practiced synchronization."}]}},
 "yuan-ti-malison-type-3": {"desc": "Fully serpent from the waist down, this malison trades legs for a heavy, muscular coil that lets it strike from unexpected range and height. Its human half retains a cold, aristocratic composure even as the tail lashes and constricts. It doesn't chase prey. It simply waits for prey to come within reach and closes the loop.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coils near a temple threshold, using height and reach to ambush intruders."}, {"n": 2, "band": "Grounded", "text": "Prefers to constrict rather than strike, wearing down victims patiently."}, {"n": 3, "band": "Grounded", "text": "Bears scarring along its coil from a past prey that fought back hard."}, {"n": 4, "band": "Grounded", "text": "Guards a specific chamber, rarely leaving its coiled ambush position."}, {"n": 5, "band": "Grounded", "text": "Young, its coil strength not yet fully grown, favoring bites over grapples."}, {"n": 6, "band": "Textured", "text": "Its coils leave faint drag-marks on stone floors, worn smooth over years."}, {"n": 7, "band": "Strange", "text": "Holds perfectly still for unnaturally long stretches before striking."}, {"n": 8, "band": "Volatile", "text": "An old, massive-coiled malison capable of constricting more than one victim at once."}]}},
 "banshee": {"desc": "A woman's shape unravels at its edges, trailing tatters of grave-mist where legs should be. Her face is beautiful and wrong, frozen mid-scream that hasn't happened yet. The air around her goes cold enough to fog breath, and somewhere under the silence you can hear her humming a lullaby with no words left in it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Drifts along the exact route she walked in life, unaware the house around her burned down."}, {"n": 2, "band": "Grounded", "text": "Weeps openly before attacking, tears that never touch the ground she floats above."}, {"n": 3, "band": "Grounded", "text": "Recoils from mirrors and covered water, flinching at her own reflection's absence."}, {"n": 4, "band": "Grounded", "text": "Circles a specific object — a cradle, a loom, a grave marker — never straying far from it."}, {"n": 5, "band": "Grounded", "text": "Speaks in fragments of a language no living person here still uses."}, {"n": 6, "band": "Textured", "text": "Her wail arrives a half-second before her mouth opens, sound outrunning cause."}, {"n": 7, "band": "Strange", "text": "Casts no cold at all — instead the room warms unnervingly, like grief burning off."}, {"n": 8, "band": "Volatile", "text": "Two banshees answer each other's cries across the dark, one wail cueing the next."}]}},
 "bone-naga": {"desc": "Bleached vertebrae coil in a shape too long for the passage it occupies, raised back to unlife by whoever needed a tireless guard and didn't mind a corpse for the job. Undeath scrambled what was once a perfect memory into fragments and puzzle-gaps, so it serves faithfully but half-remembers why. Its spit hisses where it lands, eating stone the way it once ate flesh.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coils motionless atop a heap of stolen coin, indistinguishable from bone-white rubble until it moves."}, {"n": 2, "band": "Grounded", "text": "Guards a specific sealed door with mechanical patience, unmoved by anything not approaching it."}, {"n": 3, "band": "Grounded", "text": "Repeats the same fragment of a sentence from its living days, the rest of the memory long gone."}, {"n": 4, "band": "Grounded", "text": "Fresh scorch marks pit its spine where clerics have tried and failed to end it before."}, {"n": 5, "band": "Grounded", "text": "Can't recall who raised it or why, only that it must keep guarding regardless."}, {"n": 6, "band": "Textured", "text": "Its bones are threaded with corroded wire, some forgotten binder's leash still faintly humming."}, {"n": 7, "band": "Strange", "text": "Casts a shadow shaped like its living serpent body, decades wider than its bones now are."}, {"n": 8, "band": "Volatile", "text": "A flicker of its old self surfaces mid-fight — a half-formed plea, gone before it finishes."}]}},
 "crawling-claw": {"desc": "A severed hand skitters across stone on fingertip legs, knuckles clicking a dry rhythm. Nails have grown into small yellowed hooks, curling toward whatever moves near them. Alone it is almost funny; in numbers, the sound of a dozen scrabbling across floorboards at once empties a room of nerve.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Drags itself in tight circles around a dropped ring, unwilling to abandon its post."}, {"n": 2, "band": "Grounded", "text": "Climbs sleeves and collars rather than striking directly, seeking a throat to choke."}, {"n": 3, "band": "Grounded", "text": "Freezes when unlit, indistinguishable from a dead man's hand until a torch passes."}, {"n": 4, "band": "Grounded", "text": "Still wears a signet ring fused to a blackened finger, worth more than the claw itself."}, {"n": 5, "band": "Grounded", "text": "Scuttles for the nearest crevice the instant it takes damage, patient rather than brave."}, {"n": 6, "band": "Textured", "text": "Its wrist-stump is cauterized with old sealing wax, some binder's crude signature."}, {"n": 7, "band": "Strange", "text": "Moves in perfect unison with severed claws elsewhere in the room, one will split many ways."}, {"n": 8, "band": "Volatile", "text": "Burrows into a wound already open, lodging under skin to keep clawing from inside."}]}},
 "death-knight": {"desc": "Black plate creaks over a frame that hasn't needed breath in centuries, and the visor shows nothing but a cold red ember where a face was. He still holds his rank the way he held his oath: absolutely, long after the cause it served turned to ash. When he speaks it is in the clipped cadence of old command, expecting to be obeyed.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Demands a password from a war that ended lifetimes ago, and won't stand down without it."}, {"n": 2, "band": "Grounded", "text": "Rides ahead of a column of skeletal soldiers still holding their long-dead battle formation."}, {"n": 3, "band": "Grounded", "text": "Carries a sealed writ bearing a noble house's seal — a bounty the living house would pay to bury."}, {"n": 4, "band": "Grounded", "text": "Escorts a coffin lashed to a horse's skeleton, refusing all questions about its contents."}, {"n": 5, "band": "Grounded", "text": "Wears a broken holy symbol upside-down, a defrocked knight still fighting for a faith that damned him."}, {"n": 6, "band": "Textured", "text": "Offers parley first — one duel, his terms, his archaic honor still fully intact."}, {"n": 7, "band": "Strange", "text": "His unholy aura keeps a nearby village's crops black and withered every season he lingers."}, {"n": 8, "band": "Volatile", "text": "His death-curse is already spoken aloud, promising to return the instant his killer sleeps unguarded."}]}},
 "death-knight-aspirant": {"desc": "Younger armor, less rust, but the same cold ember behind the visor — this one hasn't finished becoming what it will be. It fights with something like desperation, as if still proving itself to a master who is watching from somewhere unseen. The oath is fresh enough that fragments of the man underneath still surface between blows.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Carries an unsent letter to a living family member, still addressed in a shaking, human hand."}, {"n": 2, "band": "Grounded", "text": "Serves a death knight it clearly fears more than any living enemy, glancing back for approval."}, {"n": 3, "band": "Grounded", "text": "Fumbles its dark rites mid-battle, the corruption not yet fully seated in its will."}, {"n": 4, "band": "Grounded", "text": "Wears its old squire's tabard beneath the black plate, a rank it hasn't let go of."}, {"n": 5, "band": "Grounded", "text": "Guards an unfinished blackened altar, still short the final component its master demanded."}, {"n": 6, "band": "Textured", "text": "Begs a fallen ally not to bind it further — some part still wants out of the oath."}, {"n": 7, "band": "Strange", "text": "Its shadow moves a half-step ahead of its body, already rehearsing the knight it will become."}, {"n": 8, "band": "Volatile", "text": "Completes its final binding rite mid-fight, and the ember in its visor doubles in size."}]}},
 "demilich": {"desc": "A skull no larger than a fist hovers in dead air, jaw fused shut, eye sockets holding twin motes of gemstone light. It does not attack so much as unmake — reality thinning wherever its gaze settles. Whatever wizard it once was, only the hunger for more power survived the body's ruin.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rests atop a heap of its own petrified former victims, patient as a spider in its web."}, {"n": 2, "band": "Grounded", "text": "Its gem-eyes are dimmed to embers, drained low and unable to unleash its full soul-trap yet."}, {"n": 3, "band": "Grounded", "text": "Circles endlessly a single rune-carved floor tile, bound there by its own ancient phylactery-work."}, {"n": 4, "band": "Grounded", "text": "Speaks a single repeated word in a dead tongue, the last syllable of a spell it never finished."}, {"n": 5, "band": "Grounded", "text": "One socket-gem has cracked, leaking a thread of smoke that smells of scorched parchment."}, {"n": 6, "band": "Textured", "text": "Its skull rotates slowly to track true north, some vestige of a ritual it can no longer complete."}, {"n": 7, "band": "Strange", "text": "Trapped souls flicker faintly visible inside its grinning teeth, mouths open in silent protest."}, {"n": 8, "band": "Volatile", "text": "Its remaining gem-eye pulses in time with a second demilich answering somewhere below."}]}},
 "dracolich": {"desc": "Wings like torn sailcloth stretch over a ribcage you can see moonlight through, scales gone the color of old iron. Where breath should roar out, something colder pours instead, and its eyes hold the ancient, patient malice of a mind that outlived its own hoard. The ground under it is always dead, whatever grew there choked black.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Coils atop the exact hoard it died defending, still ledger-precise about every missing coin."}, {"n": 2, "band": "Grounded", "text": "Its remaining scales are cracked and loose, rattling like scattered dice with every wingbeat."}, {"n": 3, "band": "Grounded", "text": "Commands lesser undead in perfect formation, a general who never stopped fighting a lost war."}, {"n": 4, "band": "Grounded", "text": "One wing is skeletal frame only, membrane long rotted away, forcing it to glide rather than fly."}, {"n": 5, "band": "Grounded", "text": "Speaks in the ancient dead dialect of its living hatchling-clutch, none of whom survived it."}, {"n": 6, "band": "Textured", "text": "Its breath weapon leaves frost-glass sculptures of the dying in its wake, macabre and perfect."}, {"n": 7, "band": "Strange", "text": "A living dragon of its own bloodline has scented it out, arriving to finish the old grudge."}, {"n": 8, "band": "Mythic", "text": "Its phylactery beats faintly inside its own chest, a second heart no blade has ever found."}]}},
 "drowned-husk": {"desc": "Bloated flesh the color of a bruise drags itself from the shallows, weed and silt spilling from its mouth with every wheeze. Its eyes are milk-white and unblinking, fixed on the shoreline it never reached in life. Water still runs from its sleeves long after it should have drained.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Still clutches a rotted length of anchor rope, tangled fatally around its own ankle."}, {"n": 2, "band": "Grounded", "text": "Surfaces only at the tideline, unable to drag itself more than a few yards past wet sand."}, {"n": 3, "band": "Grounded", "text": "Trails a school of eels feeding from the gaps in its ribs, an ecosystem of its own decay."}, {"n": 4, "band": "Grounded", "text": "Wears the remains of a fisherman's coat, pockets still weighted with lead sinkers."}, {"n": 5, "band": "Grounded", "text": "Moans in a rhythm matching the surf, as if the tide itself is puppeting the sound."}, {"n": 6, "band": "Textured", "text": "Bloats and deflates visibly with the moon's pull, stronger and larger at high tide."}, {"n": 7, "band": "Strange", "text": "Its shadow ripples like standing water even on dry stone, refusing to lie flat."}, {"n": 8, "band": "Volatile", "text": "A dozen more rise from the shallows behind it the moment its own corpse finally stills."}]}},
 "eye-tyrant-zombie": {"desc": "A beholder's globular bulk sags in death-bloat, eyestalks limp and swaying like dead vines. One socket still weeps a faint, sputtering ray at random, more reflex than will. The central eye stares milk-blind at nothing, the tyrant's genius rotted down to raw undead hunger.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Drifts a foot off the ground, too rotted to fly higher, dragging slack eyestalks through the dust."}, {"n": 2, "band": "Grounded", "text": "Only two of its eyestalks still twitch with power, the rest hanging inert and blackened."}, {"n": 3, "band": "Grounded", "text": "Its central eye occasionally flickers awake mid-fight, a spark of the old tyrant surfacing in rage."}, {"n": 4, "band": "Grounded", "text": "Trails a reek so foul that lesser undead nearby actively avoid its path."}, {"n": 5, "band": "Grounded", "text": "Bears deep gouges from whatever finally killed it, still oozing a black ichor that never dries."}, {"n": 6, "band": "Textured", "text": "Its stray rays now misfire at random targets, including its own allies, with no aim left in it."}, {"n": 7, "band": "Strange", "text": "Smaller eyestalk-zombies twitch loose from its underside, budding like grim fungus."}, {"n": 8, "band": "Volatile", "text": "Its central eye briefly opens all the way, and for one round the antimagic field returns."}]}},
 "flameskull": {"desc": "A bare skull hangs in the air trailing thin blue fire from its eye sockets and grinning teeth. It cackles before it burns, delighted with its own cruelty in a voice like dry parchment catching. Whoever it served in life clearly relished making things suffer, and death changed nothing about that taste.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Guards a specific shelf of scrolls, indifferent to anything else in the room being looted."}, {"n": 2, "band": "Grounded", "text": "Cackles constantly mid-fight, narrating its own kills like a delighted spectator."}, {"n": 3, "band": "Grounded", "text": "Its flame burns an unnatural violet, casting every shadow in the room the wrong direction."}, {"n": 4, "band": "Grounded", "text": "Recites fragments of its old master's lecture notes between attacks, oblivious to the battle."}, {"n": 5, "band": "Grounded", "text": "Bobs in slow lazy circles, deceptively unhurried until it strikes without warning."}, {"n": 6, "band": "Textured", "text": "Leaves scorch-glyphs hanging in the air behind it, faint blue afterimages of its flight path."}, {"n": 7, "band": "Strange", "text": "Its cackle triggers an answering cackle from a second, distant flameskull elsewhere in the ruin."}, {"n": 8, "band": "Volatile", "text": "Explodes into a corona of fire on destruction, igniting anything flammable in the chamber."}]}},
 "flaming-skeleton": {"desc": "Bones burn without being consumed, fire licking up ribs and skull in steady blue-orange tongues. It moves with the same clattering gait as any skeleton, but the light it throws paints the walls in restless shadow. Heat rolls off it in waves that make the air itself shimmer.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Leaves a trail of small scorch-prints on stone, betraying exactly where it has walked."}, {"n": 2, "band": "Grounded", "text": "Its flame gutters low in damp air, guttering toward embers until it reaches open ground."}, {"n": 3, "band": "Grounded", "text": "Was clearly set alight deliberately — old oil-stains mar the bones beneath the fire."}, {"n": 4, "band": "Grounded", "text": "Ignites anything flammable it brushes past, indifferent to the fire spreading behind it."}, {"n": 5, "band": "Grounded", "text": "Burns a steady white instead of orange, hotter and quieter than its kin."}, {"n": 6, "band": "Textured", "text": "Its flame briefly forms a rough, screaming face in the smoke when it takes a heavy blow."}, {"n": 7, "band": "Strange", "text": "Water thrown on it boils away instantly without dimming the flame at all."}, {"n": 8, "band": "Volatile", "text": "Collapses in a flash-detonation of fire on destruction, catching everything adjacent alight."}]}},
 "ghast": {"desc": "Grey-green flesh stretches tight over a frame gone gaunt with hunger no meal has ever satisfied. It moves in quick, hunched bursts, nostrils flaring at the smell of anything still breathing. The stench that comes off it precedes it into every room, thick enough to taste.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Freezes mid-step to sniff the air, tracking a wounded target by scent alone."}, {"n": 2, "band": "Grounded", "text": "Wears the tattered remains of fine clothes, evidence of the noble it once was before the hunger."}, {"n": 3, "band": "Grounded", "text": "Drags a half-eaten carcass with it, reluctant to abandon the meal even mid-battle."}, {"n": 4, "band": "Grounded", "text": "Snarls warnings at approaching ghouls, guarding its patch of carrion jealously."}, {"n": 5, "band": "Grounded", "text": "Its claws are stained black with old rot, leaving fetid wounds that refuse to close cleanly."}, {"n": 6, "band": "Textured", "text": "Pauses to gorge the instant something drops, ignoring the fight for several precious seconds."}, {"n": 7, "band": "Strange", "text": "Its paralytic bite lingers longer here, some local grave-rot sharpening the old curse."}, {"n": 8, "band": "Volatile", "text": "A pack answers its feeding-shriek from every direction at once, converging fast."}]}},
 "ghast-base": {"desc": "This one moves with the raw animal cunning of a predator that has learned patience pays. It circles rather than charges, testing which of the living looks slowest to react. Its jaw hangs slightly unhinged, ready to widen further than any living mouth should.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Stalks the slowest-moving target in the group, deliberately ignoring easier prey."}, {"n": 2, "band": "Grounded", "text": "Hangs back from a fight until an ally falls, then rushes to claim the corpse first."}, {"n": 3, "band": "Grounded", "text": "Its knuckles are scraped raw from digging, fresh grave-dirt still packed under broken nails."}, {"n": 4, "band": "Grounded", "text": "Mimics a wounded moan to lure the unwary closer before striking."}, {"n": 5, "band": "Grounded", "text": "Retreats the instant it's outnumbered, unwilling to die for a meal it can find elsewhere."}, {"n": 6, "band": "Textured", "text": "Marks its territory with smeared, dried ichor on every doorway it claims."}, {"n": 7, "band": "Strange", "text": "Its paralytic touch seems to strengthen the longer it goes unfed, a starving desperation."}, {"n": 8, "band": "Volatile", "text": "Leads a coordinated pack hunt, flanking prey with an intelligence unusual for its kind."}]}},
 "ghast-gravecaller-spellstitched-elite": {"desc": "Glowing abyssal runes crawl beneath stitched grey flesh, pulsing faint violet with every word of its ruined liturgy. It commands the lesser dead with a raised claw and a voice that shouldn't still work. Where an ordinary ghast merely hungers, this one plans — and the dead around it answer.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Chants over a half-finished summoning circle, one component short of raising more dead here."}, {"n": 2, "band": "Grounded", "text": "Carries a stitched grimoire bound in its own old skin, the source of its granted power."}, {"n": 3, "band": "Grounded", "text": "Directs a small ghoul pack by gesture alone, a chain of command none of them question."}, {"n": 4, "band": "Grounded", "text": "Its runes flare brighter near a specific buried reliquary it clearly wants uncovered."}, {"n": 5, "band": "Grounded", "text": "Speaks a captive's name aloud, promising the living something it has no intention of giving."}, {"n": 6, "band": "Textured", "text": "Its stitched runes visibly hunt for a fresh spellstitched host among the party's fallen."}, {"n": 7, "band": "Strange", "text": "The rune-glow briefly forms a rival cult's sigil, hinting at whoever taught it this rite."}, {"n": 8, "band": "Volatile", "text": "Its final chant is already three words from complete when the party arrives."}]}},
 "ghost": {"desc": "A pale figure drifts through the wall as if it were mist, features shifting between the person they were and something less finished. Cold radiates off them in a slow pulse, and their eyes hold a grief too large for the small thing that's keeping them here. They watch the living with something between longing and warning.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Repeats the same short phrase from the moment of death, unaware it's said it a thousand times."}, {"n": 2, "band": "Grounded", "text": "Only manifests near a specific object — a chair, a window, a particular stair."}, {"n": 3, "band": "Grounded", "text": "Recoils from its own reflection whenever a mirror is uncovered nearby."}, {"n": 4, "band": "Grounded", "text": "Tries to finish an ordinary chore — sweeping, pouring, mending — with hands that pass through everything."}, {"n": 5, "band": "Grounded", "text": "Grows more solid and violent the closer someone gets to the truth of its death."}, {"n": 6, "band": "Textured", "text": "Weeps in a voice pitched to match someone specific in the room, testing a resemblance."}, {"n": 7, "band": "Strange", "text": "Casts a full-color reflection in still water despite being otherwise pale and translucent."}, {"n": 8, "band": "Volatile", "text": "Possesses the nearest living body without warning the instant it's cornered."}]}},
 "ghoul": {"desc": "Sinew-thin and quick, it scuttles low to the ground on limbs bent at wrong angles, jaw working with an eager, wet clicking. Its claws leave a numbness in whatever they touch, a paralysis that spreads like cold water under skin. It smells the dead before it smells the living, and prefers the former.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Digs fresh graves with startling speed, unbothered by consecrated ground or holy wards."}, {"n": 2, "band": "Grounded", "text": "Hoards small bones in a nest nearby, arranging them with an unsettling, obsessive neatness."}, {"n": 3, "band": "Grounded", "text": "Freezes and plays dead when outmatched, waiting for prey to relax its guard."}, {"n": 4, "band": "Grounded", "text": "Its claws are crusted with the paralytic residue of a dozen prior kills."}, {"n": 5, "band": "Grounded", "text": "Fights in eerie silence, no snarl or hiss, only the wet click of its jaw."}, {"n": 6, "band": "Textured", "text": "Drags the paralyzed toward a hidden larder rather than finishing them where they fall."}, {"n": 7, "band": "Strange", "text": "Its paralytic touch numbs longer here, some graveyard rot in the soil sharpening the curse."}, {"n": 8, "band": "Volatile", "text": "A buried elf ancestor's ghoul-kin curse means its bite here spreads the affliction, not just paralysis."}]}},
 "graveyard-revenant": {"desc": "Something enormous claws itself up from consecrated ground, dirt sloughing off shoulders too wide for any single coffin. It moves with the slow, terrible certainty of a grudge that has had decades to mature underground. The headstones around it have all been shattered outward, as if it dug itself free from below several graves at once.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Claws at a single family crypt, ignoring every other grave in the yard entirely."}, {"n": 2, "band": "Grounded", "text": "Wears a rusted chain still bolted through its ribs, evidence someone tried to keep it buried."}, {"n": 3, "band": "Grounded", "text": "Carries the crushed remains of a coffin lid on one shoulder, wielding it as an improvised shield."}, {"n": 4, "band": "Grounded", "text": "Circles a fresh grave, waiting for whoever betrayed it to visit and pay respects."}, {"n": 5, "band": "Grounded", "text": "Its roar shakes loose a name carved into a nearby headstone — someone the party may recognize."}, {"n": 6, "band": "Textured", "text": "A living relative arrives mid-fight, begging the party not to destroy what's left of their kin."}, {"n": 7, "band": "Strange", "text": "Every grave within its territory has been dug up from beneath, dirt piled the wrong way."}, {"n": 8, "band": "Volatile", "text": "Its rage animates every corpse buried within its reach the moment it takes a mortal wound."}]}},
 "greater-shadow": {"desc": "A patch of darkness peels itself off the floor and stands, edges smoking like burnt paper. It moves without sound across surfaces that shouldn't hold weight, hunger radiating off it in waves that dim nearby torches. Where lesser shadows merely drain, this one hunts with something like memory of what it used to be.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Clings flat to a wall in ambush, indistinguishable from ordinary shadow until it lunges."}, {"n": 2, "band": "Grounded", "text": "Drains torchlight from a full room before ever revealing itself to its prey."}, {"n": 3, "band": "Grounded", "text": "Retains just enough of its old voice to whisper a single warning before it strikes."}, {"n": 4, "band": "Grounded", "text": "Avoids sunlit patches on the floor with visible, deliberate care."}, {"n": 5, "band": "Grounded", "text": "Splits its edges thin to slip beneath doors, reforming fully on the other side."}, {"n": 6, "band": "Textured", "text": "Leaves a permanent smear of true darkness on any surface it's struck against."}, {"n": 7, "band": "Strange", "text": "Casts a second, false shadow of its own — a decoy that peels away to strike from behind."}, {"n": 8, "band": "Volatile", "text": "Every Strength point it drains visibly ages its victim's shadow, stooped and withered."}]}},
 "haunting-revenant": {"desc": "Vast and slow, it drags a body too large for any grave that could have held it, joints grinding stone to powder with every step. Its unfinished vengeance hangs around it like a smell, thick enough that lesser undead give it wide berth. When it finally speaks, the voice comes from somewhere much smaller than the shape carrying it.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Wears a torn family crest, faded but still legible on what remains of its clothing."}, {"n": 2, "band": "Grounded", "text": "Carries a rusted weapon far too small for its current size, a memory of who it was."}, {"n": 3, "band": "Grounded", "text": "Refuses to cross a threshold marked with an old ward, some fragment of a promise still binding it."}, {"n": 4, "band": "Grounded", "text": "Its footsteps trace the exact path of a funeral procession from long ago."}, {"n": 5, "band": "Grounded", "text": "Stares fixedly at a locket clutched in one massive hand, ignoring easier targets nearby."}, {"n": 6, "band": "Textured", "text": "Speaks a name mid-battle, and a nearby NPC visibly recognizes it with dread."}, {"n": 7, "band": "Strange", "text": "Its unfinished vengeance briefly quiets when its named target is spoken aloud in the room."}, {"n": 8, "band": "Volatile", "text": "Its true grievance surfaces only once it's brought low — an offer, not a killing blow, might end this."}]}},
 "lacedon-sodden-ghoul": {"desc": "Waterlogged and bloated, this ghoul moves with a wet, sucking gait built for shallows rather than dry stone. Kelp trails from its jaw and barnacles have grown along one shoulder, marking years spent beneath the waves. Its paralytic bite carries the cold of deep water along with the numbness.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Struggles visibly once dragged onto dry land, its wet gait slowing to a crawl."}, {"n": 2, "band": "Grounded", "text": "Drags paralyzed prey toward open water rather than finishing them on land."}, {"n": 3, "band": "Grounded", "text": "Surfaces only at high tide, submerging again the instant the water recedes."}, {"n": 4, "band": "Grounded", "text": "Its claws are crusted with barnacles, leaving jagged, infection-prone wounds."}, {"n": 5, "band": "Grounded", "text": "Hunts in a loose pack that surfaces from multiple directions at once around a boat or dock."}, {"n": 6, "band": "Textured", "text": "Trails phosphorescent algae that briefly lights the water where it swims."}, {"n": 7, "band": "Strange", "text": "Its bite paralysis lingers underwater long enough to drown a victim outright."}, {"n": 8, "band": "Volatile", "text": "An entire drowned crew rises together at its call, a full wreck's worth of hunger."}]}},
 "lich": {"desc": "Papery skin stretches over bone beneath a robe too fine for the ruin it hangs on, pinprick lights burning where eyes should be. Every gesture carries the unhurried certainty of centuries spent perfecting cruelty into an art. It speaks as if death were a minor inconvenience it solved long ago, which, for it, is exactly true.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Keeps meticulous ledgers of every soul it has bound, filed with bureaucratic precision."}, {"n": 2, "band": "Grounded", "text": "Refuses to fight personally while any lesser servant remains standing between it and harm."}, {"n": 3, "band": "Grounded", "text": "Speaks in the courtly cadence of a kingdom that crumbled to dust centuries ago."}, {"n": 4, "band": "Grounded", "text": "Its skeletal hands never stop turning pages, mid-research even in the middle of a fight."}, {"n": 5, "band": "Grounded", "text": "Wears a phylactery openly as jewelry, arrogantly certain no one will guess what it is."}, {"n": 6, "band": "Textured", "text": "Negotiates first, offering forbidden knowledge in exchange for being left undisturbed."}, {"n": 7, "band": "Strange", "text": "Its laboratory nearby is mid-experiment, a bound soul screaming faintly in an unfinished vessel."}, {"n": 8, "band": "Mythic", "text": "Its true phylactery is hidden leagues away, and what stands here is only a projected shell."}]}},
 "minotaur-skeleton": {"desc": "Horned skull sits atop a frame built for goring, massive bones scraped clean of the muscle that once made it terrifying in a different way. It charges in straight lines with mindless persistence, plowing through anything that doesn't move fast enough. Its hooves strike sparks off the stone floor of whatever maze still claims it.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Paces the exact corridor loop of the labyrinth it once guarded, unable to leave its pattern."}, {"n": 2, "band": "Grounded", "text": "Charges the nearest wall on a miss, cracking stone rather than course-correcting."}, {"n": 3, "band": "Grounded", "text": "Its horns are chipped and uneven, one snapped clean off from a past collision."}, {"n": 4, "band": "Grounded", "text": "Drags a length of rusted chain still looped around one leg, a leash long since broken."}, {"n": 5, "band": "Grounded", "text": "Snorts dust instead of breath, an old animal tic surviving in dead bone."}, {"n": 6, "band": "Textured", "text": "Rams a supporting pillar hard enough to threaten a partial ceiling collapse."}, {"n": 7, "band": "Strange", "text": "Its hoofbeats echo a labyrinth's worth of turns ahead of its actual position."}, {"n": 8, "band": "Volatile", "text": "Charges blind through a wall entirely, bringing rubble down on whoever's behind it."}]}},
 "mummy": {"desc": "Bandages yellowed with age wrap a frame that moves in slow, implacable strides, each footstep raising a fine dust that smells of preserving oils and sealed tombs. Its eyes are sunken pits, fixed with the patient certainty of something that has already waited longer than most lives last. A rasping curse rides on every breath it doesn't need.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Refuses to leave the threshold of its sealed chamber, bound there by its own burial rite."}, {"n": 2, "band": "Grounded", "text": "Trailing bandages catch and drag debris across the floor, marking its path in dust."}, {"n": 3, "band": "Grounded", "text": "Its wrappings are inscribed with faded prayers, some still faintly glowing when disturbed."}, {"n": 4, "band": "Grounded", "text": "Moves with visible reluctance, as if resenting the disturbance more than fearing harm."}, {"n": 5, "band": "Grounded", "text": "Clutches a canopic jar to its chest, unwilling to set it down even mid-combat."}, {"n": 6, "band": "Textured", "text": "Its rot-scent thickens the air enough to induce nausea before it's even seen."}, {"n": 7, "band": "Strange", "text": "Its bandages briefly unravel into a dozen grasping strips, extending its reach unnaturally."}, {"n": 8, "band": "Volatile", "text": "Its curse marks whoever strikes the final blow, a mummy rot that follows them home."}]}},
 "mummy-lord": {"desc": "Golden funerary wrappings and cracked lapis inlay mark this one as royalty even in ruin, its posture regal despite the rot beneath the linen. It commands its tomb like a throne room, unhurried, certain that time itself answers to it. Every word it rasps carries the weight of a dynasty that expects to be obeyed even now.", "role": "apex", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Demands tribute be laid at its sarcophagus before it will even acknowledge intruders."}, {"n": 2, "band": "Grounded", "text": "Guards a specific relic of its old reign, indifferent to any other treasure in the tomb."}, {"n": 3, "band": "Grounded", "text": "Commands lesser mummies and animated guardians with a single raised, wrapped hand."}, {"n": 4, "band": "Grounded", "text": "Recites its own funerary rites aloud, as if still performing the ceremony centuries later."}, {"n": 5, "band": "Grounded", "text": "Its curse has already spread to a nearby village, and someone there needs it broken."}, {"n": 6, "band": "Textured", "text": "Offers to spare whoever restores its stolen crown, a bargain with real teeth behind it."}, {"n": 7, "band": "Strange", "text": "Sand pours continuously from a crack in its wrappings, filling the chamber ankle-deep."}, {"n": 8, "band": "Mythic", "text": "Its true tomb lies beneath this one, and this mummy lord is only its herald."}]}},
 "ogre-zombie": {"desc": "A brute's frame gone slack and green, stitched crudely at the joints where it clearly came apart before someone forced it back together. It swings with the same mindless force any ogre would, but slower, wetter, leaving trails of black ichor with every lumbering step. The stench alone announces it long before it arrives.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "One arm hangs looser than the other, crudely resewn and prone to tearing free mid-swing."}, {"n": 2, "band": "Grounded", "text": "Still wears a chain collar, some necromancer's leash rusted through and forgotten."}, {"n": 3, "band": "Grounded", "text": "Trails a swarm of flies thick enough to visibly obscure its approach."}, {"n": 4, "band": "Grounded", "text": "Swings its club with enough leftover memory to occasionally overcorrect, missing wide."}, {"n": 5, "band": "Grounded", "text": "Leaks a black ichor that eats through cheap leather and rope on contact."}, {"n": 6, "band": "Textured", "text": "Bellows in a voice half its own, half whatever creature reanimated it."}, {"n": 7, "band": "Strange", "text": "Its stitched wounds occasionally pulse as if something still alive is caught inside them."}, {"n": 8, "band": "Volatile", "text": "Explodes in a burst of foul ichor and bloat-gas the instant it's finally dropped."}]}},
 "poltergeist": {"desc": "Nothing is visible except what it throws — furniture skidding, doors slamming, dust kicked up in a whirlwind of spite. Its laughter, when it comes, is childish and cruel in equal measure, delighted by the fear it causes. It never shows a face because in life it may never have earned one people remembered.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hurls only small objects at first, testing which target flinches before escalating."}, {"n": 2, "band": "Grounded", "text": "Locks doors and windows from the inside, trapping victims before the real mischief starts."}, {"n": 3, "band": "Grounded", "text": "Mimics a child's laughter through the walls, unsettling even before anything moves."}, {"n": 4, "band": "Grounded", "text": "Fixates on a single piece of furniture, defending it with disproportionate fury."}, {"n": 5, "band": "Grounded", "text": "Writes crude words in dust or condensation, taunting whoever reads them."}, {"n": 6, "band": "Textured", "text": "Turns portraits and mirrors to face the wall the instant no one's looking directly at them."}, {"n": 7, "band": "Strange", "text": "Its thrown objects occasionally strike targets it shouldn't be able to see or reach."}, {"n": 8, "band": "Volatile", "text": "Coordinates a full room's furniture at once, a small hurricane confined to four walls."}]}},
 "shadow": {"desc": "It rises from the dark corner of the room like a stain given purpose, featureless but for two points of colder black where eyes belong. It moves along walls and ceilings as easily as floors, sound swallowed wherever it passes. Touching it feels like losing a piece of yourself you didn't know could be taken.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Flattens itself against a wall in perfect stillness, waiting for prey to walk past unaware."}, {"n": 2, "band": "Grounded", "text": "Retreats instantly from any exposed flame or sunbeam, unwilling to risk the light."}, {"n": 3, "band": "Grounded", "text": "Was once a person killed in darkness — a faint, familiar outline still visible in its silhouette."}, {"n": 4, "band": "Grounded", "text": "Drains warmth from a room before revealing itself, the temperature drop the only warning."}, {"n": 5, "band": "Grounded", "text": "Moves in short, silent bursts rather than a continuous glide, appearing to blink between spots."}, {"n": 6, "band": "Textured", "text": "Leaves a faint grey stain on stone it's touched, visible only in torchlight at an angle."}, {"n": 7, "band": "Strange", "text": "Splits briefly into a thinner duplicate when struck hard, both halves equally hungry."}, {"n": 8, "band": "Volatile", "text": "A cluster of three converges the instant one shadow's Strength-drain succeeds."}]}},
 "skeleton": {"desc": "Bare bone rattles into motion, joints clicking with a dry, mechanical rhythm as it raises whatever weapon was buried or bound with it. There's no malice in its hollow sockets, only the blank obedience of something that stopped being a person a long time ago. It fights exactly as ordered, nothing more, nothing less.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Wields a weapon clearly too large for its frame, a scavenged blade from a taller corpse."}, {"n": 2, "band": "Grounded", "text": "Stands at rigid attention until triggered, still holding a guard-post no one remembers assigning."}, {"n": 3, "band": "Grounded", "text": "Missing several ribs and a hand, held together by whatever crude magic first raised it."}, {"n": 4, "band": "Grounded", "text": "Marches in step with others nearby, a drill pattern surviving from its living service."}, {"n": 5, "band": "Grounded", "text": "Wears scraps of rusted armor bearing an insignia no living kingdom claims anymore."}, {"n": 6, "band": "Textured", "text": "Its jaw hangs open in a permanent, silent scream that never quite closes."}, {"n": 7, "band": "Strange", "text": "Reassembles itself from scattered bones nearby if given even a few unwatched seconds."}, {"n": 8, "band": "Volatile", "text": "Shatters on death into shards that animate briefly as small biting fragments."}]}},
 "skeleton-archer": {"desc": "It stands with unnatural stillness, bony fingers already nocked, waiting with the patience only the dead can afford. Its aim doesn't waver with fear or fatigue, drawing and loosing with the same mechanical precision every time. Old fletching, brittle and grey, still somehow flies true.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Holds high ground on instinct, retreating to elevated ledges the instant melee closes in."}, {"n": 2, "band": "Grounded", "text": "Its quiver holds only a handful of arrows, forcing it to loot fallen shafts mid-fight."}, {"n": 3, "band": "Grounded", "text": "Fires in disciplined volleys alongside others, a drill formation from its living regiment."}, {"n": 4, "band": "Grounded", "text": "One eye socket is cracked and canted, throwing its aim consistently a hair off true."}, {"n": 5, "band": "Grounded", "text": "Draws its bowstring with a dry creak audible well before it ever looses a shot."}, {"n": 6, "band": "Textured", "text": "Marks targets with a bone-white chalk arrow scratched into nearby stone before firing."}, {"n": 7, "band": "Strange", "text": "Its arrows curve slightly around obstacles that should have blocked the shot outright."}, {"n": 8, "band": "Volatile", "text": "Fires flaming arrows lit from an unseen brazier, an upgrade none of its kin share."}]}},
 "skeleton-warrior": {"desc": "Broader and better-armored than common bone soldiers, this one carries itself with the discipline of a veteran rather than a conscript. Its strikes are economical, testing an opponent's guard before committing to the killing blow. Whatever officer it once was, the instinct for command never fully rotted away.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Directs lesser skeletons with sharp gestures, a chain of command intact past death."}, {"n": 2, "band": "Grounded", "text": "Fights with textbook precision, parrying rather than trading blows recklessly."}, {"n": 3, "band": "Grounded", "text": "Wears a dented officer's helm still bearing a faded unit crest."}, {"n": 4, "band": "Grounded", "text": "Falls back to defensible terrain the instant a fight turns against its formation."}, {"n": 5, "band": "Grounded", "text": "Carries a shield notched from dozens of old battles, a veteran's worn-in habit."}, {"n": 6, "band": "Textured", "text": "Barks silent, wordless commands that lesser skeletons somehow still obey instantly."}, {"n": 7, "band": "Strange", "text": "Its blade holds an edge no rust has touched in however many decades it's lain buried."}, {"n": 8, "band": "Volatile", "text": "Rallies a broken skeleton formation mid-fight, steadying a rout with sheer presence."}]}},
 "specter": {"desc": "A translucent, roughly humanoid shape drifts free of the floor, trailing cold in a shroud of tattered light. It has no memory of who it was, only the compulsion to hunt warmth and take it. Where it passes, breath fogs and candle flames gutter low, guttering toward nothing.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Passes through walls at odd, testing angles, as if still learning what solid means."}, {"n": 2, "band": "Grounded", "text": "Drains warmth in a widening radius before ever making contact with a target."}, {"n": 3, "band": "Grounded", "text": "Its shroud briefly resolves into the shape of the clothes it died wearing."}, {"n": 4, "band": "Grounded", "text": "Flinches from consecrated ground, circling a chapel's edge without ever crossing it."}, {"n": 5, "band": "Grounded", "text": "Moves in silence except for a faint keening only the wounded seem able to hear."}, {"n": 6, "band": "Textured", "text": "Its passing frosts metal armor and weapons, briefly making them brittle to the touch."}, {"n": 7, "band": "Strange", "text": "Two specters overlap briefly into one denser shape before splitting apart again."}, {"n": 8, "band": "Volatile", "text": "Every point of max HP it drains here manifests as a faint, screaming echo in the walls."}]}},
 "swamp-shadow": {"desc": "This shadow clings low along stagnant water, its edge rippling with the murk rather than solid ground. Marsh-gas bubbles up where it passes, and the cold it carries smells of rot rather than mere absence of light. It hunts patiently, in no hurry, certain the swamp will wear its prey down long before it needs to strike.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Rides just beneath the water's surface, a darker patch drifting against the current."}, {"n": 2, "band": "Grounded", "text": "Surfaces from beneath a half-submerged corpse, using it as cover before striking."}, {"n": 3, "band": "Grounded", "text": "Retreats into reeds and cattails rather than open ground, using the marsh as camouflage."}, {"n": 4, "band": "Grounded", "text": "Trails a faint smell of rot distinct from the swamp's own stagnant reek."}, {"n": 5, "band": "Grounded", "text": "Its edges blur into drifting marsh-gas, nearly invisible in the mist."}, {"n": 6, "band": "Textured", "text": "Leaves patches of water unnaturally still and black where it's passed beneath."}, {"n": 7, "band": "Strange", "text": "Feeds faster near standing water, its Strength-drain sharper the wetter the ground."}, {"n": 8, "band": "Volatile", "text": "A whole bog's worth of shadows rise at once when the swamp itself seems disturbed."}]}},
 "swarm-of-crawling-claws": {"desc": "Dozens of severed hands scrabble together across the floor in a single chittering mass, a carpet of grasping fingers and yellowed nails. Individually pitiful, together they move like a single hungry animal, flowing under doors and up furniture. The sound alone — nails on stone, en masse — is enough to send most people running.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Flows as one mass beneath a door before reforming into a scrabbling wave on the other side."}, {"n": 2, "band": "Grounded", "text": "Climbs a victim's body in a swarm, dozens of small grips overwhelming one at a time."}, {"n": 3, "band": "Grounded", "text": "Scatters into individual claws the instant it takes heavy damage, harder to finish off."}, {"n": 4, "band": "Grounded", "text": "Several claws still bear rings and bracelets, glinting oddly amid the writhing mass."}, {"n": 5, "band": "Grounded", "text": "Moves toward the loudest sound in the room, drawn to noise over sight."}, {"n": 6, "band": "Textured", "text": "Leaves a floor coated in fine dust and shed nail-fragments after passing through."}, {"n": 7, "band": "Strange", "text": "Reforms from two smaller swarms nearby if either is left more than half-alive."}, {"n": 8, "band": "Volatile", "text": "Floods in through every crack in a room at once, an ambush with no clear point of origin."}]}},
 "undead-eye-tyrant": {"desc": "The great orb still hangs suspended in dead air, eyestalks writhing with the memory of malice rather than any living intent. Rot has claimed most of its bulk, but the central eye burns with an antimagic cold that has outlasted the mind that once wielded it. It floats through ruins like a slow-drifting nightmare no one built.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Drifts along the exact patrol path its living self once guarded, rot notwithstanding."}, {"n": 2, "band": "Grounded", "text": "Several eyestalks hang inert and blackened, only a handful still able to fire."}, {"n": 3, "band": "Grounded", "text": "Its central eye flickers erratically, the antimagic field cutting in and out unpredictably."}, {"n": 4, "band": "Grounded", "text": "Commands a small cluster of lesser undead with silent, imperious gestures."}, {"n": 5, "band": "Grounded", "text": "Trails torn tendrils of desiccated flesh that drift like slow banners as it moves."}, {"n": 6, "band": "Textured", "text": "Its rays occasionally misfire backward onto its own trailing eyestalks."}, {"n": 7, "band": "Strange", "text": "Old vault wards flare and fail near it, its antimagic disrupting magic it shouldn't reach."}, {"n": 8, "band": "Volatile", "text": "Its central eye briefly stabilizes to full power for one terrifying round before guttering again."}]}},
 "vampire": {"desc": "Immaculate, cold, and utterly composed, it studies the room the way a collector studies a wine cellar — assessing, unhurried, already certain of the outcome. Its charm is a blade as sharp as its fangs, and both are offered with the same courteous smile. Centuries of patience sit behind eyes that have stopped needing to blink.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Hosts a lavish gathering as cover, feeding selectively from guests who won't be missed."}, {"n": 2, "band": "Grounded", "text": "Keeps a favored thrall close, testing their loyalty with small cruelties before any fight starts."}, {"n": 3, "band": "Grounded", "text": "Refuses to enter a home uninvited, exploiting every technicality of the old law instead."}, {"n": 4, "band": "Grounded", "text": "Speaks fluent, dated court etiquette, a courtesy from a century no one else remembers."}, {"n": 5, "band": "Grounded", "text": "Keeps meticulous account of debts owed and favors given, a ledger centuries deep."}, {"n": 6, "band": "Textured", "text": "Charms the least suspicious member of the party first, turning ally against ally quietly."}, {"n": 7, "band": "Strange", "text": "Its reflection lags a half-second behind its actual movement in any mirror nearby."}, {"n": 8, "band": "Volatile", "text": "Commands a small brood of spawn who arrive mid-fight the instant it's seriously threatened."}]}},
 "vampire-nightbringer": {"desc": "Where common vampires hide in shadow, this one seems to bring the dark with it, torches guttering low as it enters uninvited rooms it was never barred from. Its presence feels like a held breath the whole world takes before the strike. It speaks softly, as if volume were beneath something so certain of its own power.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Extinguishes light sources on entry without visible effort, arriving in near-total dark."}, {"n": 2, "band": "Grounded", "text": "Moves in absolute silence, its footsteps somehow producing no sound at all."}, {"n": 3, "band": "Grounded", "text": "Speaks first before any violence, unnervingly calm and almost gentle in tone."}, {"n": 4, "band": "Grounded", "text": "Leaves a lingering cold in any room it's occupied, long after it departs."}, {"n": 5, "band": "Grounded", "text": "Its shadow moves independently of the light source, pooling wherever it chooses."}, {"n": 6, "band": "Textured", "text": "Feeds without waking its victim, leaving them merely exhausted and unaware."}, {"n": 7, "band": "Strange", "text": "Passes through a barred, warded door as if the ward simply forgot to notice it."}, {"n": 8, "band": "Volatile", "text": "Plunges an entire room into unnatural night the instant combat truly begins."}]}},
 "vampire-spawn": {"desc": "Younger, hungrier, and far less patient than its maker, it moves in sudden bursts of desperate speed. Its manners are a threadbare mimicry of nobility, the performance slipping the moment blood is close. It serves because it must, resentment simmering visibly under every obedient gesture.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Glances toward its master's resting place mid-fight, seeking approval it may never earn."}, {"n": 2, "band": "Grounded", "text": "Feeds recklessly the instant blood is drawn, abandoning tactics for hunger."}, {"n": 3, "band": "Grounded", "text": "Wears stolen finery it doesn't quite know how to carry, still new to its condition."}, {"n": 4, "band": "Grounded", "text": "Flinches visibly at running water, an aversion it hasn't yet learned to mask."}, {"n": 5, "band": "Grounded", "text": "Resents being sent as bait, muttering complaints even mid-combat."}, {"n": 6, "band": "Textured", "text": "Bites without any of its maker's control, risking creating unwanted new spawn."}, {"n": 7, "band": "Strange", "text": "Its charm gaze flickers and fails at the worst moments, still an unmastered skill."}, {"n": 8, "band": "Volatile", "text": "Turns feral entirely once its maker is destroyed nearby, all pretense gone."}]}},
 "vampire-umbral-lord": {"desc": "Shadow doesn't just follow this one, it serves — pooling at its feet, rising to shield its steps, thickening the dark wherever it walks. Its court manners are impeccable and its cruelty absolute, the two never once in conflict. Even other vampires seem to defer, some old hierarchy of night still recognizing rank.", "role": "apex", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Commands a small court of lesser vampires, each deferring visibly the instant it enters."}, {"n": 2, "band": "Grounded", "text": "Wields shadow as a physical extension of its will, forming brief solid shapes to strike with."}, {"n": 3, "band": "Grounded", "text": "Speaks of rival vampire lords by name, hinting at a wider hidden hierarchy of the night."}, {"n": 4, "band": "Grounded", "text": "Its umbral cloak swallows thrown light sources whole, torches guttering out unnaturally."}, {"n": 5, "band": "Grounded", "text": "Tests intruders with a probing conversation before ever considering violence."}, {"n": 6, "band": "Textured", "text": "Its shadow-servants move independently, striking from angles its body never occupies."}, {"n": 7, "band": "Strange", "text": "Vanishes into a cast shadow entirely, reappearing from a wholly different one across the room."}, {"n": 8, "band": "Mythic", "text": "Commands the shadows of everyone present briefly, turning allies' own darkness against them."}]}},
 "warhorse-skeleton": {"desc": "Bare ribs and a bridle of tarnished metal are all that remain of what was once a knight's proud mount. It charges in a straight, relentless line, hoofbeats echoing louder than bone should allow. No rider steadies it anymore, and it doesn't seem to notice the difference.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Still wears a barding marked with a house crest no living family claims anymore."}, {"n": 2, "band": "Grounded", "text": "Charges toward the last place it remembers a rider mounting, drawn by old habit."}, {"n": 3, "band": "Grounded", "text": "Rears without warning, throwing off any attempt to control or calm it."}, {"n": 4, "band": "Grounded", "text": "Trails a snapped lead-rope, evidence someone once tried to stable it uselessly."}, {"n": 5, "band": "Grounded", "text": "Its hoofbeats fall out of sync, one leg fused stiff from an old, unhealed break."}, {"n": 6, "band": "Textured", "text": "Snorts a cloud of fine bone-dust in an old animal reflex that means nothing anymore."}, {"n": 7, "band": "Strange", "text": "Answers a distant, unseen rider's whistle it shouldn't still be able to hear."}, {"n": 8, "band": "Volatile", "text": "Tramples in a straight line through anything, animate or not, standing in its path."}]}},
 "wight": {"desc": "Grey, wind-dried skin stretches over a soldier's frame still carrying the discipline of whatever war made it. It fights with cold economy, more tactician than beast, its claws leaving victims weaker with every touch. Command lingers in its bearing long after the cause it served has rotted to nothing.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Reviews a small formation of lesser undead like a drill sergeant inspecting troops."}, {"n": 2, "band": "Grounded", "text": "Carries a rusted map case, still convinced a campaign it lost is somehow ongoing."}, {"n": 3, "band": "Grounded", "text": "Speaks in clipped orders rather than threats, addressing enemies like insubordinates."}, {"n": 4, "band": "Grounded", "text": "Retreats behind its lesser undead deliberately, using them as a shield without hesitation."}, {"n": 5, "band": "Grounded", "text": "Wears the tattered rank insignia of an officer from a defeated, forgotten army."}, {"n": 6, "band": "Textured", "text": "Prioritizes draining the strongest-looking target first, a calculated tactical choice."}, {"n": 7, "band": "Strange", "text": "Its life-drain touch leaves a faint frost-rime pattern on skin shaped like old unit markings."}, {"n": 8, "band": "Volatile", "text": "Commands a full squad of zombies with silent, precise hand-signals mid-battle."}]}},
 "wight-lord": {"desc": "Broader and more richly armored than common wights, this one carries itself like a general who never accepted the war was lost. Its claws are edged with old steel rather than bare bone, and its commands ripple visibly through every lesser undead nearby. Even in defeat, it seems certain the next battle is the one it wins.", "flavorTable": {"die": "d8", "mode": "hook", "rows": [{"n": 1, "band": "Grounded", "text": "Commands a disciplined honor guard of wights and zombies, deployed with real tactics."}, {"n": 2, "band": "Grounded", "text": "Carries a battle standard of a fallen kingdom, planted defiantly at its command post."}, {"n": 3, "band": "Grounded", "text": "Holds a captured living scout for interrogation, unwilling to kill a useful source yet."}, {"n": 4, "band": "Grounded", "text": "Wears a general's signet that a living noble house would pay well to recover."}, {"n": 5, "band": "Grounded", "text": "Its war-map of the region is centuries out of date, and it hasn't noticed the world changed."}, {"n": 6, "band": "Textured", "text": "Offers surrender terms to the party, utterly convinced of its own continued authority."}, {"n": 7, "band": "Strange", "text": "Its drained victims rise as new soldiers under its banner within the hour, not merely wights."}, {"n": 8, "band": "Volatile", "text": "Rallies every undead within earshot the instant it's struck below half its remaining HP."}]}},
 "will-o-wisp": {"desc": "A cold blue light bobs invisibly at the edge of vision, drifting just far enough ahead to seem like a path rather than a trap. It hums faintly, a sound almost like a voice calling a name, drawing the lost deeper into the marsh. Only when the ground gives way does its true shape — pure malice, nothing more — finally show.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Mimics the specific glow of a lantern or torch, luring travelers who trust the wrong light."}, {"n": 2, "band": "Grounded", "text": "Leads its prey along the exact edge of a bog or sinkhole, letting the terrain do its work."}, {"n": 3, "band": "Grounded", "text": "Vanishes instantly the moment it's directly looked at, reappearing only from the corner of the eye."}, {"n": 4, "band": "Grounded", "text": "Hums a half-remembered lullaby, borrowed from some past victim's final moments."}, {"n": 5, "band": "Grounded", "text": "Flickers erratically to imitate a dying torch, baiting rescuers rather than the lost."}, {"n": 6, "band": "Textured", "text": "Splits its glow briefly into two false lights, doubling the confusion of any pursuit."}, {"n": 7, "band": "Strange", "text": "Its light briefly shows the silhouette of a past victim reaching out from within the glow."}, {"n": 8, "band": "Volatile", "text": "Leads an entire party single-file along a cliff edge, waiting to snuff its light all at once."}]}},
 "wraith": {"desc": "A hooded shape of pure darkness hovers with no visible legs, cold radiating outward in a slow, deliberate pulse. It passes through walls the way water passes through cloth, hunting by some sense that isn't sight. Its touch doesn't just kill — it withers, leaving behind husks that used to be people.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Phases through a wall mid-chase, cutting off a fleeing target rather than following directly."}, {"n": 2, "band": "Grounded", "text": "Hovers motionless in a dark corner for long stretches, patient past any living creature's tolerance."}, {"n": 3, "band": "Grounded", "text": "Its hood conceals nothing at all, only deeper, hungrier dark beneath it."}, {"n": 4, "band": "Grounded", "text": "Drains warmth from an entire room gradually, long before it ever attacks directly."}, {"n": 5, "band": "Grounded", "text": "Moves with an audible, dry whisper that isn't quite words but almost could be."}, {"n": 6, "band": "Textured", "text": "Its life-drain touch leaves victims looking decades older, hollow-cheeked and grey."}, {"n": 7, "band": "Strange", "text": "Casts no shadow of its own, an absence so complete it disturbs even other undead nearby."}, {"n": 8, "band": "Volatile", "text": "Raises a fresh specter from whichever victim its touch has just withered to death."}]}},
 "zombie": {"desc": "It shambles forward with slack, wet limbs, jaw hanging open in a groan that never quite becomes a word. Rot has claimed most of the face, leaving eyes clouded and indifferent to pain, fire, or reason. It doesn't hate the living. It simply doesn't stop.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Still wears the clothes it died in, recognizable enough for someone here to know the name."}, {"n": 2, "band": "Grounded", "text": "Shambles in a straight, unbending line toward the nearest sound, ignoring obstacles entirely."}, {"n": 3, "band": "Grounded", "text": "Keeps twitching and clawing at the ground for several seconds after being dropped."}, {"n": 4, "band": "Grounded", "text": "Bears a wound clearly inflicted after death, evidence someone already tried and failed to stop it."}, {"n": 5, "band": "Grounded", "text": "Trails maggots and flies thick enough to be heard before the zombie itself is seen."}, {"n": 6, "band": "Textured", "text": "Groans in a rough approximation of a name, the last word it ever tried to say."}, {"n": 7, "band": "Strange", "text": "Keeps rising again after a killing blow, sheer stubborn animation refusing to quit."}, {"n": 8, "band": "Volatile", "text": "Its bite festers instantly, a rot that spreads visibly within minutes if untreated."}]}},
 "zombie-plague-carrier": {"desc": "Sores weep openly along grey skin, and every ragged breath carries a visible haze of sickness into the air around it. It moves slower than most of its kind, weighed down by the disease consuming what's left of its body. Anything that survives its bite doesn't stay clean for long.", "flavorTable": {"die": "d8", "mode": "variant", "rows": [{"n": 1, "band": "Grounded", "text": "Leaves a visible trail of infected fluid, marking a path even the blind could track by smell."}, {"n": 2, "band": "Grounded", "text": "Coughs a fine mist of contagion with every groan, sickening anyone standing too close."}, {"n": 3, "band": "Grounded", "text": "Moves sluggishly compared to its kin, weighed down by its own advancing rot."}, {"n": 4, "band": "Grounded", "text": "Was clearly quarantined once — chain links and warning signs litter the ground nearby."}, {"n": 5, "band": "Grounded", "text": "Draws flies and rats in numbers that swarm ahead of its actual arrival."}, {"n": 6, "band": "Textured", "text": "Its wounds visibly worsen the disease's spread the longer the fight drags on."}, {"n": 7, "band": "Strange", "text": "The sickness it carries seems to hasten decay in anything nearby, plant or flesh."}, {"n": 8, "band": "Volatile", "text": "A single scratch here spreads the plague to every other corpse in the room, all rising sick."}]}}
};
